#include <errno.h>

// Define the FrameHeader structure
struct FrameHeader {
    time_t timestamp; // Timestamp of the frame
    uint32_t srcIP;   // Source IP address of the frame
    uint32_t dstIP;   // Destination IP address of the frame
    uint16_t len;     // Length of the frame in bytes
};

// Define the Frame struct
struct Frame {
    struct FrameHeader header;
    char* payload; // Payload of the frame
};

// Declare the internal data structures and variables
static struct Frame** frames = NULL;
static size_t numFrames = 0;
static size_t maxFrames = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the library with a specified number of maximum frames
void frame_lib_init(size_t numMaxFrames) {
    if (frames != NULL || maxFrames > 0) return; // Ensure initialization only once

    maxFrames = numMaxFrames;
    numFrames = 0;

    frames = malloc(sizeof(struct Frame*) * maxFrames);
    memset(frames, 0, sizeof(struct Frame*) * maxFrames);
}

// Cleanup the library and free memory
void frame_lib_cleanup() {
    if (frames != NULL) {
        for (size_t i = 0; i < numFrames; i++) {
            free(frames[i]->payload);
            free(frames[i]);
        }
        free(frames);
        frames = NULL;
        maxFrames = 0;
        numFrames = 0;
    }
}

// Append a new frame to the internal array, resize if necessary
void append_frame(struct Frame* frame) {
    pthread_mutex_lock(&mutex);

    // Check for maximum frame size
    if (frame->header.len > maxFrames) {
        log_error("Frame too large, maximum allowed is %d bytes", maxFrames);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Resize the internal array if necessary
    if (numFrames == maxFrames) {
        size_t newMax = maxFrames * 2;
        struct Frame** newFrames = realloc(frames, sizeof(struct Frame*) * newMax);
        memset(newFrames + maxFrames, 0, sizeof(struct Frame*) * (newMax - maxFrames));
        frames = newFrames;
        maxFrames = newMax;
    }

    // Append the frame to the internal array
    frames[numFrames] = malloc(sizeof(struct Frame));
    memcpy(frames[numFrames], frame, sizeof(struct Frame));
    numFrames++;

    pthread_mutex_unlock(&mutex);
}

// Get a specific frame by index
struct Frame* get_frame(size_t idx) {
    if (idx >= numFrames) return NULL;
    return frames[idx];
}

// Return the current number of frames in the internal array
size_t num_frames() {
    return numFrames;
}

// Resize the internal frame array to a specific size, balancing memory usage with performance
void resize(size_t newSize) {
    pthread_mutex_lock(&mutex);

    // Ensure new size is valid
    if (newSize <= 0 || newSize > maxFrames) {
        log_error("Invalid new size %d", newSize);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Resize the internal array
    struct Frame** newFrames = realloc(frames, sizeof(struct Frame*) * newSize);
    memset(newFrames + numFrames, 0, sizeof(struct Frame*) * (newSize - numFrames));
    frames = newFrames;
    maxFrames = newSize;

    pthread_mutex_unlock(&mutex);
}
```
