```c
// Source file: integers.c
#include "integers.h"

#define MAX_INPUT_SIZE 1024

void initIntegerList(IntegerList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

bool addIntegerToList(IntegerList* list, int32_t data) {
    // Create a new node and allocate memory for it
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return false;
    }

    // Set the data field of the node to the input value
    node->data = data;

    // If there are no existing nodes in the list, set the head and tail pointers to this new node
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        // Otherwise, add the new node to the end of the list
        list->tail->next = node;
        list->tail = node;
    }

    // Increment the count of integers in the list
    list->count++;

    return true;
}

bool removeIntegerFromList(IntegerList* list, int32_t data) {
    // If there are no existing nodes in the list, do nothing
    if (list->head == NULL) {
        return false;
    }

    // Search for the node containing the input value and remove it from the list
    Node* current = list->head;
    while (current != NULL) {
        if (current->data == data) {
            // If we find a matching node, update the list pointers and decrement the count of integers
            Node* temp = current;
            current = current->next;
            free(temp);
            list->count--;
            break;
        } else {
            current = current->next;
        }
    }

    // If we didn't find a matching node, do nothing
    if (current == NULL) {
        return false;
    }

    // Update the list pointers to reflect the change in size
    if (list->head == current) {
        list->head = current->next;
    }
    if (list->tail == current) {
        list->tail = current->prev;
    }

    return true;
}

int32_t getIntegerFromList(const IntegerList* list, size_t index) {
    // If the input index is out of range, return 0
    if (index >= list->count) {
        return 0;
    }

    // Search for the node at the specified index and return its data field
    Node* current = list->head;
    size_t i;
    for (i = 0; i < index; i++) {
        current = current->next;
    }
    return current->data;
}

size_t getIntegerCount(const IntegerList* list) {
    return list->count;
}

void freeIntegerList(IntegerList* list) {
    // Free all nodes in the list
    while (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    list->tail = NULL;
}
```
