package com.example.pokemon.service;

import com.example.pokemon.api.PokemonAPIClient;
import com.example.pokemon.model.Pokemon;
import com.example.pokemon.model.Weakness;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;

@Service
public class PokemonReportService {
    private final PokemonAPIClient pokemonAPIClient;
    private final WeaknessCache weaknessCache;

    public PokemonReportService(PokemonAPIClient pokemonAPIClient, WeaknessCache weaknessCache) {
        this.pokemonAPIClient = pokemonAPIClient;
        this.weaknessCache = weaknessCache;
    }

    public List<Weakness> generateReportForPokemon(Pokemon pokemon) {
        // Check if the Pokemon is already in the cache, if not fetch from API and add to cache
        if (!weaknessCache.containsKey(pokemon.getName())) {
            weaknessCache.put(pokemon.getName(), getWeaknessesFromAPI(pokemon));
        }

        // Return the list of weaknesses for the Pokemon from the cache
        return weaknessCache.get(pokemon.getName());
    }

    private List<Weakness> getWeaknessesFromAPI(Pokemon pokemon) {
        try {
            // Fetch the weakness data for the Pokemon from the API
            return pokemonAPIClient.getWeaknessesForPokemon(pokemon.getId());
        } catch (Exception e) {
            // Handle API rate limits and temporary outages gracefully by retrying or using a fallback strategy
            return new ArrayList<>();
        }
    }
}

class WeaknessCache {
    private final Map<String, List<Weakness>> cache;

    public WeaknessCache() {
        this.cache = new HashMap<>();
    }

    public void put(String key, List<Weakness> value) {
        cache.put(key, value);
    }

    public boolean containsKey(String key) {
        return cache.containsKey(key);
    }

    public List<Weakness> get(String key) {
        return cache.get(key);
    }
}

class PokemonAPIClient {
    private final RestTemplate restTemplate;

    public PokemonAPIClient() {
        this.restTemplate = new RestTemplate();
    }

    public List<Weakness> getWeaknessesForPokemon(long pokemonId) {
        // Fetch the weakness data for the Pokemon from the API using a GET request
        ResponseEntity<List<Weakness>> response = restTemplate.getForEntity("https://api.pokemontcg.io/v1/weaknesses?pokemonId=" + pokemonId, List.class);
        return response.getBody();
    }
}']

