// Dynamic Cryptographic Service Framework

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <sodium/crypto_aead.h>

// Algorithm Collection Structure
struct Algorithm {
  char* name; // Name of the algorithm
  void* (*impl)(void*); // Implementation function pointer
  char* source; // Source of the algorithm (in-memory or external library)
};

// Thread-safe collection of algorithms
static struct Algorithm algos[10] = {
  {"AES-GCM", EVP_aes_128_gcm, "external-library"},
  {"AES-CBC", EVP_aes_128_cbc, "external-library"},
  {"RSA-OAEP", EVP_PKEY_new, "external-library"},
  {"ECDSA-P256", NULL, "in-memory"}
};

// Lazy loading of external libraries
static void* (*loadLibrary)(char*) = NULL;

// Initialization and startup functions
void initFramework() {
  // Load OpenSSL library
  loadLibrary("openssl");
  // Load LibSodium library
  loadLibrary("libsodium");
}

void deinitFramework() {
  // Unload OpenSSL library
  unloadLibrary("openssl");
  // Unload LibSodium library
  unloadLibrary("libsodium");
}

// Load an external library by name
void* loadLibrary(char* libName) {
  if (strcmp(libName, "openssl") == 0) {
    return dlopen("libcrypto.so", RTLD_NOW);
  } else if (strcmp(libName, "libsodium") == 0) {
    return dlopen("libsodium.so", RTLD_NOW);
  } else {
    printf("Unknown library name\n");
  }
}

// Unload an external library by name
void unloadLibrary(char* libName) {
  if (strcmp(libName, "openssl") == 0) {
    dlclose(loadLibrary("openssl"));
  } else if (strcmp(libName, "libsodium") == 0) {
    dlclose(loadLibrary("libsodium"));
  } else {
    printf("Unknown library name\n");
  }
}

// Get a collection of algorithms and their implementations
struct Algorithm* getAlgorithms() {
  return algos;
}

// Get the implementation function pointer for a specific algorithm by name
void* (*getImpl(char* algoName)) {
  // Check if the algorithm exists in the collection
  struct Algorithm* algo = NULL;
  for (int i = 0; i < 10; i++) {
    if (strcmp(algos[i].name, algoName) == 0) {
      algo = &algos[i];
      break;
    }
  }
  // Return the implementation function pointer or NULL if it doesn't exist
  return algo != NULL ? algo->impl : NULL;
}

// Get the source of a specific algorithm by name
char* getSource(char* algoName) {
  struct Algorithm* algo = NULL;
  for (int i = 0; i < 10; i++) {
    if (strcmp(algos[i].name, algoName) == 0) {
      algo = &algos[i];
      break;
    }
  }
  return algo != NULL ? algo->source : "unknown";
}

// Update the collection of algorithms and their implementations
void updateAlgorithms(struct Algorithm* newAlgos, int numAlgo) {
  // Copy the new algorithms into the old ones
  for (int i = 0; i < numAlgo; i++) {
    algos[i] = newAlgos[i];
  }
}

// Add a new algorithm to the collection
void addAlgorithm(struct Algorithm* algo) {
  // Check if there is space in the collection for the new algorithm
  if (numAlgo == 10) {
    printf("Collection is full\n");
    return;
  }
  // Add the new algorithm to the end of the collection
  algos[numAlgo++] = *algo;
}

// Remove an algorithm from the collection by name
void removeAlgorithm(char* algoName) {
  struct Algorithm* algo = NULL;
  for (int i = 0; i < 10; i++) {
    if (strcmp(algos[i].name, algoName) == 0) {
      algo = &algos[i];
      break;
    }
  }
  // Check if the algorithm exists in the collection
  if (algo != NULL) {
    // Shift all algorithms to the left of the removed one
    for (int i = 0; i < numAlgo - 1; i++) {
      algos[i] = algos[i + 1];
    }
    numAlgo--;
  } else {
    printf("Algorithm does not exist\n");
  }
}

// Replace an algorithm in the collection by name with a new one
void replaceAlgorithm(char* oldName, struct Algorithm* newAlgo) {
  struct Algorithm* algo = NULL;
  for (int i = 0; i < 10; i++) {
    if (strcmp(algos[i].name, oldName) == 0) {
      algo = &algos[i];
      break;
    }
  }
  // Check if the algorithm exists in the collection
  if (algo != NULL) {
    *algo = *newAlgo;
  } else {
    printf("Algorithm does not exist\n");
  }
}

// Get the number of algorithms in the collection
int getNumAlgorithms() {
  return numAlgo;
}

// Check if an algorithm is present in the collection by name
bool algorithmExists(char* algoName) {
  struct Algorithm* algo = NULL;
  for (int i = 0; i < 10; i++) {
    if (strcmp(algos[i].name, algoName) == 0) {
      algo = &algos[i];
      break;
    }
  }
  return algo != NULL ? true : false;
}
