  }
};

void processAndLogInsertion(const string& firstString, const string& secondString, const string& externalServiceUrl) {
  DependencyManager depManager;
  auto service = depManager.getService(externalServiceUrl);

  // Load configurations and cache service endpoints
  depManager.loadConfigurations();

  if (firstString.empty() || secondString.empty()) {
    throw invalid_argument("Invalid input: first or second string is empty");
