  // Use efficient search algorithm to find the first occurrence of firstString in itemList
  forward_list<string> itemList;
  auto it = find(itemList.begin(), itemList.end(), firstString);
  if (it == itemList.end()) {
    stringstream ss;
    ss << "First string '" << firstString << "' not found in list";
    service->logMessage("ERROR", ss.str());
    return;
  }

  // Insert secondString immediately after it
  auto newIt = itemList.insert_after(it, secondString);
  if (newIt == itemList.end()) {
