    explicit SandeshClient(boost::asio::io_context& io_context)
        : m_io_context(io_context),
          m_work(m_io_context.get_executor()) {}

    void run() {
        std::cout << "Starting Sandesh client" << std::endl;
        m_work = boost::asio::spawn(m_io_context, [this](boost::asio::yield_context yield) {
            while (true) {
                try {
