                    http::request<http::string_body> req;
                    req.method(http::verb::get);
                    req.target("/api/data");
                    req.version(11);
                    m_socket = tcp::socket(m_io_context);
                    m_resolver.async_resolve(req.url(), yield[ec]);
                    if (ec) {
                        std::cout << "Resolve error: " << ec.message() << std::endl;
                        break;
                    }
                    m_socket.async_connect(m_resolver.endpoint(), yield[ec]);
                    if (ec) {
                        std::cout << "Connect error: " << ec.message() << std::endl;
                        break;
                    }
                    m_socket.async_handshake(ssl::stream_base::client, yield[ec]);
                    if (ec) {
                        std::cout << "Handshake error: " << ec.message() << std::endl;
                        break;
                    }
                    http::write(m_socket, req);
                    http::response<http::string_body> res;
                    http::read(m_socket, res);
                    if (res) {
                        std::cout << "Response status: " << res.result() << std::endl;
                        std::cout << "Response body: " << res.body() << std::endl;
                    } else {
                        std::cout << "No response received" << std::endl;
