    public class ExecuteParameterizedQueryAsync : IDisposable
    {
        private readonly string _connectionString;
        private readonly int _commandTimeout;
        private readonly int _retryCount;
        private readonly int _retryDelay;
        private readonly bool _enableConnectionPooling;
        private readonly bool _enableTransactions;

        public ExecuteParameterizedQueryAsync(string connectionString, int commandTimeout = 30, int retryCount = 5, int retryDelay = 1000, bool enableConnectionPooling = true, bool enableTransactions = false)
        {
            _connectionString = connectionString;
            _commandTimeout = commandTimeout;
            _retryCount = retryCount;
            _retryDelay = retryDelay;
            _enableConnectionPooling = enableConnectionPooling;
            _enableTransactions = enableTransactions;
        }

        public async Task<SqlDataReader> ExecuteAsync(string commandText, List<SqlParameter> parameters)
        {
            // Validate input parameters
            if (string.IsNullOrEmpty(commandText))
                throw new ArgumentException("Command text cannot be null or empty", nameof(commandText));
            if (parameters == null || parameters.Count == 0)
                throw new ArgumentException("Parameter list cannot be null or empty", nameof(parameters));

            // Initialize connection and command objects
            SqlConnection connection = null;
            SqlCommand command = null;

            try
            {
                // Create and open a database connection
                connection = new SqlConnection(_connectionString);
                await connection.OpenAsync();

                // Create a SQL command object with the given command text and parameters
                command = new SqlCommand(commandText, connection)
                {
                    CommandTimeout = _commandTimeout,
                    EnableConnectionPooling = _enableConnectionPooling,
                    EnableTransactions = _enableTransactions
                };

                // Add the parameters to the SQL command object
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }

                // Execute the query and return a data reader
                var dataReader = await command.ExecuteReaderAsync();

                // Return the data reader
                return dataReader;
            }
            catch (Exception ex)
