class PageUpdateRequest {
public:
    PageUpdateRequest(int pageId, int elementId, string htmlContent) :
        pageId_(pageId), elementId_(elementId), htmlContent_(htmlContent) {}

    int getPageId() const { return pageId_; }
    int getElementId() const { return elementId_; }
