function renderFooterScripts(scripts) {
  let html = '';

  for (let script of scripts) {
    if (!script.key || !script.code) {
      // Skip invalid or malformed scripts
      continue;
    }

    const type = script.type || 'javascript';
    const key = script.key;
    const code = script.code;

    if (type === 'svg') {
      html += `<svg class="footer-script" data-key="${key}">${code}</svg>`;
    } else if (type === 'css') {
      html += `<style>${code}</style>`;
    } else {
      // Whitelist allowed domains for external scripts to prevent XSS attacks
      const domain = new URL(script.src).hostname;
      if (!ALLOWED_DOMAINS.includes(domain)) {
        console.warn(`Invalid domain ${domain} in script`);
        continue;
      }

      html += `<script src="${script.src}" data-key="${key}">${code}</script>`;
    }
  }

  return html;
}
```
