  // Regular expression pattern for matching Old Testament book names
  const bookPattern = /^(Old|New)?\s?(Testament|Testameents?)\s?(\d+:\d+)\s?([a-zA-Z]+)/g;

  // Function to validate a single book reference against the canonical list
  function validateBookReference(reference) {
    const book = reference.match(bookPattern)[1].toLowerCase();
    if (book === "old" || book === "new") {
      return true;
    } else {
      throw new Error("Invalid book reference");
    }
  }

  // Function to update the dialog fields with the found references
  function updateDialogFields(references) {
    const dialog = angular.element("#dialog");
    if (dialog.length > 0) {
      const field = dialog.find("input[name='book']").eq(0);
      field.val(references.join(", "));
      return true;
    } else {
      throw new Error("Dialog fields not found");
    }
