    const url = "https://example.com/api/books?q=" + encodeURIComponent(text);
    return $.getJSON(url, {
      headers: { "Content-Type": "application/json" }
    });
  }

  // Function to handle potential network issues and edge cases
  function handleError(error) {
    console.error("Error refreshing dialog fields:", error);
    return false;
  }

  // Main function to refresh the dialog fields with found references
  function refreshDialogFieldsWithReferences(text) {
    const regex = new RegExp(bookPattern, "g");
    const references = [];
    let match;
    while ((match = regex.exec(text))) {
      const reference = match[1].toLowerCase();
      if (validateBookReference(reference)) {
        references.push(reference);
      } else {
        console.warn("Invalid book reference:", reference);
      }
    }
    if (references.length > 0) {
      return updateDialogFields(references);
    } else {
      return false;
    }
  }

  // Handle asynchronous call to fetch book references
  const promise = fetchBookReferences(text).then((data) => {
    const references = data.results.map((result) => result.book);
    return updateDialogFields(references);
  }).catch((error) => {
    console.error("Error fetching book references:", error);
    return false;
  });

  // Return a promise that resolves to the updated dialog fields or false on failure
  return promise;
}
