  // Check if the bundle has been cached previously
  const cacheFilePath = path.join(CACHE_DIR, `${bundleId}.json`);
  if (fs.existsSync(cacheFilePath)) {
    return JSON.parse(fs.readFileSync(cacheFilePath));
