class DOMTreeService {
  private parser: DOMParser;
  private axiosInstance: axios.AxiosInstance;
  private cache: Map<string, ExternalData>;

  constructor(parser: DOMParser, axiosInstance: axios.AxiosInstance) {
    this.parser = parser;
    this.axiosInstance = axiosInstance;
    this.cache = new Map();
  }

  async processDOMTree(rootNode: Element): Promise<Array<{ nodeData: NodeData, externalData: ExternalData }>> {
    const nodesToProcess = [...rootNode.querySelectorAll('[customAttributeValue]')];
    const promises = [];

    for (const node of nodesToProcess) {
      promises.push(this.processNode(node));
    }

    return Promise.all(promises);
  }

  async processNode(node: Element): Promise<{ nodeData: NodeData, externalData: ExternalData }> {
    const customAttributeValue = node.getAttribute('customAttributeValue');
    const nodeData = { id: node.id, customAttributeValue };

    // Check cache for existing data
    if (this.cache.has(nodeData.id)) {
      return { nodeData, externalData: this.cache.get(nodeData.id) };
    }

    // Fetch external data asynchronously and update cache
    const { data, statusCode, error } = await axiosInstance.get(`/api/external-data?id=${nodeData.id}`);
    this.cache.set(nodeData.id, { data, statusCode, error });

    // Handle potential errors and return node data with external data
    if (error) {
      console.log('Error fetching external data', error);
      return { nodeData, externalData: { data: null, statusCode: 500, error } };
    } else {
      return { nodeData, externalData: { data, statusCode, error } };
    }
  }
}
