    let mut cpu_usage = 0f64;
    let mut mem_usage = 0u64;

    // Build the crates
    for crate in config.crates.iter() {
        let mut cmd = Command::new("cargo");
        cmd.arg("build").arg(crate);
        let output = cmd.output()?;
        if !output.status.success() {
            return Err(format!("Failed to build crate: {}", crate).into());
        }
    }

    // Handle potential mismatches or missing dependencies gracefully
    for dependency in config.dependencies.iter() {
        let mut cmd = Command::new("cargo");
        cmd.arg("install").arg(dependency);
        let output = cmd.output()?;
        if !output.status.success() {
            return Err(format!("Failed to install dependency: {}", dependency).into());
        }
    }

