    let mut has_failure = false;
    for crate in config.crates.iter() {
        let mut cmd = Command::new("cargo");
        cmd.arg("build").arg(crate);
        let output = cmd.output()?;
        if !output.status.success() {
            has_failure = true;
            break;
        }
    }
    if has_failure {
        return Err("Build failed".into());
    }

