<?php

// Session Management
use Symfony\Component\HttpFoundation\Session\Session;
use Symfony\Component\Security\Core\Authentication\Token\UsernamePasswordToken;
use Symfony\Component\Security\Http\Event\LoginSuccessEvent;

$session = new Session();
$token = $session->get('oauth_access_token');
if ($token) {
    $user = $this->getUserByOAuthToken($token);
    if ($user) {
        $event = new LoginSuccessEvent($token, 'main', $user);
        $dispatcher->dispatch(LoginSuccessEvent::class, $event);
    } else {
        // invalidate token and logout user
        $session->set('oauth_access_token', null);
        $this->get('security.token_storage')->setToken(null);
    }
}

// Token Storage & Caching
