<?php

namespace App\Modules\PasswordUpdater;

use GuzzleHttp\Client;
use Psr\Log\LoggerInterface;
use Symfony\Component\Cache\Adapter\AbstractAdapter;
use Symfony\Component\Validator\Constraints\Password;
use Symfony\Component\Security\Core\Encoder\UserPasswordEncoderInterface;

class PasswordUpdater
{
    private $client;
    private $encoder;
    private $logger;
    private $cache;
    private $passwordPolicy;

    public function __construct(Client $client, UserPasswordEncoderInterface $encoder, LoggerInterface $logger, AbstractAdapter $cache)
    {
        $this->client = $client;
        $this->encoder = $encoder;
        $this->logger = $logger;
        $this->cache = $cache;
        $this->passwordPolicy = new Password();
    }

    public function updatePassword(User $user, string $newPassword): void
    {
        // Validate the password against the policy
        if (!$this->passwordPolicy->isValid($newPassword)) {
            throw new InvalidArgumentException('The provided password is not valid');
        }

        // Encode the password using the user's salt and encoder
        $encodedPassword = $this->encoder->encodePassword($user, $newPassword);

        // Authenticate with the third-party authentication service using OAuth2
        try {
            $accessToken = $this->client->requestAccessToken($user->getUsername(), $encodedPassword);
        } catch (AuthenticationException $e) {
            $this->logger->warning('Failed to authenticate user', [
                'username' => $user->getUsername(),
                'error' => $e->getMessage(),
            ]);

            throw new AuthenticationException('Failed to authenticate user');
        }

        // Update the password in the database
        $this->cache->delete($user->getId());
        $user->setPassword($encodedPassword);
        $this->logger->info('Updated password for user', [
            'username' => $user->getUsername(),
        ]);
    }
}
