#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <atomic>

// Define the maximum number of threads that can access the library
const int MAX_THREADS = 10;

// Define the maximum size of the state list
const int MAX_STATE_LIST_SIZE = 100;

// Define the timeout for acquiring a semaphore
const int SEMAPHORE_TIMEOUT = 1000;

struct State {
    // Define the state id
    int id;

    // Define the next state in the transition list
    struct State* nextState;
};

struct Transition {
    // Define the current state
    struct State* currentState;

    // Define the next state
    struct State* nextState;
};

struct StateList {
    // Define the head of the state list
    struct State* head;

    // Define the tail of the state list
    struct State* tail;

    // Define the size of the state list
    int size;
};

struct FSA {
    // Define the head of the transition list
    struct Transition* head;

    // Define the tail of the transition list
    struct Transition* tail;

    // Define the current state
    struct State* currentState;

    // Define the next state
    struct State* nextState;
};

// Define a semaphore for synchronizing access to the FSA
sem_t fsaSemaphore;

// Define a mutex for protecting the FSA structure
pthread_mutex_t fsaMutex;

// Define a flag for indicating whether the FSA is initialized
bool fsaInitialized = false;

// Define a function for initializing the FSA
void initFSA(struct FSA* fsa) {
    // Initialize the FSA structure
    fsa->head = NULL;
    fsa->tail = NULL;
    fsa->currentState = NULL;
    fsa->nextState = NULL;
}

// Define a function for adding a state to the FSA
void addState(struct State* state) {
    // Acquire the semaphore for synchronizing access to the FSA
    sem_wait(&fsaSemaphore);

    // Lock the mutex for protecting the FSA structure
    pthread_mutex_lock(&fsaMutex);

    // Check if the FSA is initialized
    if (!fsaInitialized) {
        // Initialize the FSA
        initFSA(fsa);

        // Set the flag indicating that the FSA is initialized
        fsaInitialized = true;
    }

    // Add the state to the state list
    struct StateList* stateList = &fsa->head;
    while (stateList->tail != NULL) {
        stateList = stateList->tail;
    }
    stateList->tail = state;
    stateList->size++;

    // Release the mutex for protecting the FSA structure
    pthread_mutex_unlock(&fsaMutex);

    // Signal the semaphore for synchronizing access to the FSA
    sem_post(&fsaSemaphore);
}

// Define a function for adding a transition to the FSA
void addTransition(struct Transition* transition) {
    // Acquire the semaphore for synchronizing access to the FSA
    sem_wait(&fsaSemaphore);

    // Lock the mutex for protecting the FSA structure
    pthread_mutex_lock(&fsaMutex);

    // Check if the FSA is initialized
    if (!fsaInitialized) {
        // Initialize the FSA
        initFSA(fsa);

        // Set the flag indicating that the FSA is initialized
        fsaInitialized = true;
    }

    // Add the transition to the transition list
    struct TransitionList* transitionList = &fsa->head;
    while (transitionList->tail != NULL) {
        transitionList = transitionList->tail;
    }
    transitionList->tail = transition;

    // Release the mutex for protecting the FSA structure
    pthread_mutex_unlock(&fsaMutex);

    // Signal the semaphore for synchronizing access to the FSA
    sem_post(&fsaSemaphore);
}

// Define a function for updating the current state of the FSA
void updateCurrentState(struct State* newState) {
    // Acquire the semaphore for synchronizing access to the FSA
    sem_wait(&fsaSemaphore);

    // Lock the mutex for protecting the FSA structure
    pthread_mutex_lock(&fsaMutex);

    // Update the current state of the FSA
    fsa->currentState = newState;

    // Release the mutex for protecting the FSA structure
    pthread_mutex_unlock(&fsaMutex);

    // Signal the semaphore for synchronizing access to the FSA
    sem_post(&fsaSemaphore);
}

// Define a function for updating the next state of the FSA
void updateNextState(struct State* newState) {
    // Acquire the semaphore for synchronizing access to the FSA
    sem_wait(&fsaSemaphore);

    // Lock the mutex for protecting the FSA structure
    pthread_mutex_lock(&fsaMutex);

    // Update the next state of the FSA
    fsa->nextState = newState;

    // Release the mutex for protecting the FSA structure
    pthread_mutex_unlock(&fsaMutex);

    // Signal the semaphore for synchronizing access to the FSA
    sem_post(&fsaSemaphore);
}

// Define a function for handling state transitions in the FSA
void handleStateTransition(struct State* currentState, struct State* nextState) {
    // Acquire the semaphore for synchronizing access to the FSA
    sem_wait(&fsaSemaphore);

    // Lock the mutex for protecting the FSA structure
    pthread_mutex_lock(&fsaMutex);

    // Update the current state of the FSA
    fsa->currentState = nextState;

    // Release the mutex for protecting the FSA structure
    pthread_mutex_unlock(&fsaMutex);

    // Signal the semaphore for synchronizing access to the FSA
    sem_post(&fsaSemaphore);
}

// Define a function for handling asynchronous updates from external data sources
void handleAsyncUpdate(struct State* newState) {
    // Acquire the semaphore for synchronizing access to the FSA
    sem_wait(&fsaSemaphore);

    // Lock the mutex for protecting the FSA structure
    pthread_mutex_lock(&fsaMutex);

    // Update the next state of the FSA
    fsa->nextState = newState;

    // Release the mutex for protecting the FSA structure
    pthread_mutex_unlock(&fsaMutex);

    // Signal the semaphore for synchronizing access to the FSA
    sem_post(&fsaSemaphore);
}
```

In this code, we define a data structure called `FSA` (Finite State Automaton) that represents a state machine. We then define several functions for adding states and transitions to the FSA, updating the current state of the FSA, and handling asynchronous updates from external data sources. The functions are all protected by a mutex to ensure thread-safe access to the shared data structure.

We also use a semaphore to synchronize access to the `FSA` structure between threads. When a thread wants to modify the state of the FSA, it must first acquire the semaphore. Once it has acquired the semaphore, it can safely modify the `FSA` structure without worrying about other threads concurrently modifying it as well. The mutex ensures that only one thread at a time can acquire the semaphore, so we don't need to worry about the race condition that could occur if two or more threads were to attempt to modify the FSA simultaneously.

This code demonstrates how to use a mutex and a semaphore to ensure thread-safe access to shared data structures in C++. By using these synchronization primitives, we can prevent race conditions from occurring and maintain data integrity even in multi-threaded environments."]

