```c++
#include <iostream>
#include <map>
#include <chrono>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>
#include <algorithm>
#include <random>

// Define the different types of attacks
enum class AttackType {
    BasicAttack,
    SpecialAttack,
    UltimateAttack
};

// Define a struct to represent an attack
struct Attack {
    // The ID of the character that can perform this attack
    int characterId;

    // The type of attack
    AttackType type;

    // The cooldown period in seconds
    float cooldownPeriod;
};

// Define a struct to represent a character's stats
struct CharacterStats {
    // The ID of the character
    int id;

    // The name of the character
    std::string name;

    // The current health of the character
    float health;

    // The maximum health of the character
    float maxHealth;

    // The attack speed of the character
    float attackSpeed;
};

// Define a struct to represent a game session
struct GameSession {
    // The ID of the game session
    int id;

    // The number of players in the game session
    int numPlayers;

    // A vector of character IDs for each player in the game session
    std::vector<int> playerIds;
};

// Define a class to represent the attack selection function
class AttackSelection {
public:
    // Constructor that takes in the list of available attacks and cooldown periods
    AttackSelection(std::map<AttackType, float> attacks, std::map<int, CharacterStats> characters) :
        m_attacks(attacks),
        m_characters(characters) {}

    // Function to select the next attack for a character
    Attack selectNextAttack(int characterId) {
        // Get the current character's stats
        CharacterStats& character = m_characters[characterId];

        // Find the first available attack that is not on cooldown
        std::vector<AttackType> availableAttacks;
        for (auto it = m_attacks.begin(); it != m_attacks.end(); ++it) {
            if (!isOnCooldown(characterId, it->first)) {
                availableAttacks.push_back(it->first);
            }
        }

        // If there are no available attacks, return an empty attack
        if (availableAttacks.empty()) {
            return Attack{};
        }

        // Select a random attack from the list of available attacks
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, availableAttacks.size() - 1);
        int attackIndex = dis(gen);

        // Return the selected attack
        return Attack{characterId, availableAttacks[attackIndex], m_attacks[availableAttacks[attackIndex]]};
    }

    // Function to update the cooldown period for a given attack type
    void updateCooldownPeriod(AttackType type, float cooldownPeriod) {
        // Update the cooldown period for the specified attack type
        m_attacks[type] = cooldownPeriod;
    }

private:
    // Function to check if an attack is on cooldown for a given character
    bool isOnCooldown(int characterId, AttackType type) {
        // Get the current time in seconds
        auto now = std::chrono::steady_clock::now();
        double secondsElapsed = std::chrono::duration<double>(now - m_lastAttackTime[characterId]).count();

        // Check if the attack is on cooldown
        return secondsElapsed < m_attacks[type];
    }

    // Map of available attacks and their cooldown periods
    std::map<AttackType, float> m_attacks;

    // Map of character IDs to their stats
    std::map<int, CharacterStats> m_characters;

    // Map of character IDs to the last time an attack was performed
    std::map<int, std::chrono::time_point<std::chrono::steady_clock>> m_lastAttackTime;
};
```
