  bool enable_aes_gcm;
};

void CryptoLibraryInit(struct CryptoContext* context) {
  // Initialize AES cipher
  EVP_CIPHER_CTX_init(&context->aes);
  EVP_EncryptInit_ex(&context->aes, EVP_aes_256_cbc(), NULL, NULL, NULL);

  // Initialize Camellia cipher
  EVP_CIPHER_CTX_init(&context->camellia);
  EVP_EncryptInit_ex(&context->camellia, EVP_camellia_256_cbc(), NULL, NULL, NULL);

