  AES_set_encrypt_key(&context->aes_key, 256, NULL);

  // Initialize Camellia key
  CAMELLIA_set_encrypt_key(&context->camellia_key, 256, NULL);
}

void CryptoLibraryFree(struct CryptoContext* context) {
  EVP_CIPHER_CTX_cleanup(&context->aes);
  EVP_CIPHER_CTX_cleanup(&context->camellia);
  EVP_MD_CTX_cleanup(&context->md5);
  EVP_MD_CTX_cleanup(&context->sha1);
  RSA_free(context->rsa);
  HMAC_CTX_cleanup(&context->hmac_sha256);
}

