// Function to encrypt data using AES-GCM and HMAC-SHA256
static void encrypt(unsigned char *data, size_t len, unsigned char *key, unsigned char iv[], unsigned char tag[]) {
  EVP_CIPHER_CTX *ctx = NULL;
  int out_len;

  if (!(ctx = EVP_CIPHER_CTX_new())) {
    ERR_print_errors_fp(stderr);
    exit(1);
  }

  // Set encryption key and IV
  if (EVP_EncryptInit_ex(ctx, ENCRYPTION_ALGORITHM, NULL, key, iv) != 1) {
    ERR_print_errors_fp(stderr);
    exit(1);
