  // Set HMAC-SHA256 for data integrity checks
  if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, NULL) != 1) {
    ERR_print_errors_fp(stderr);
    exit(1);
  }

  // Encrypt data
  if (EVP_EncryptUpdate(ctx, data, &out_len, data, len) != 1) {
    ERR_print_errors_fp(stderr);
    exit(1);
  }

  // Generate HMAC-SHA256 tag
  if (EVP_EncryptFinal_ex(ctx, tag, NULL) != 1) {
    ERR_print_errors_fp(stderr);
    exit(1);
  }

  EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt data using AES-GCM and HMAC-SHA256
