    ERR_print_errors_fp(stderr);
    exit(1);
  }

  // Set HMAC-SHA256 for data integrity checks
  if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, tag) != 1) {
    ERR_print_errors_fp(stderr);
    exit(1);
  }

  // Decrypt data
  if (EVP_DecryptUpdate(ctx, data, &out_len, data, len) != 1) {
