#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <cstdlib>
#include <cassert>

// Third-party libraries
#include "webp/encode.h"
#include "aws-s3/client.h"

using namespace std;

constexpr int MIN_RESOLUTION = 1024;
constexpr int MAX_RESOLUTION = 8192;
constexpr float RESIZING_FACTOR = 0.5f;

// Memory pool for image buffers
struct ImageBuffer {
    unsigned char* data;
    size_t size;
};

vector<ImageBuffer> bufferPool;
mutex bufferPoolMutex;
condition_variable bufferPoolCondVar;

// Load an image file and resize it if necessary
void loadAndResizeImage(const string& filePath, const float resizingFactor) {
    // Check if the input file exists
    ifstream file(filePath, ios::binary);
    if (!file.is_open()) {
        cerr << "Error: Could not open image file '" << filePath << "'" << endl;
        return;
    }

    // Get the image dimensions and resize if necessary
    int width = 0, height = 0;
    file >> width >> height;
    if (width < MIN_RESOLUTION || height < MIN_RESOLUTION) {
        cerr << "Error: Image too small. Resizing to minimum resolution." << endl;
        resizingFactor = MIN_RESOLUTION / max(width, height);
    } else if (width > MAX_RESOLUTION || height > MAX_RESOLUTION) {
        cerr << "Error: Image too large. Resizing to maximum resolution." << endl;
        resizingFactor = MAX_RESOLUTION / max(width, height);
    }

    // Read the image data into a memory buffer
    vector<unsigned char> rawData(file.rdbuf()->pubsetbuf(nullptr, 0));
    file.close();

    // Resize the image if necessary and convert to WebP format
    unsigned char* resizedData = nullptr;
    size_t resizedSize = 0;
    if (resizingFactor != 1) {
        resizedData = webpRescale(rawData.data(), rawData.size(), width * resizingFactor, height * resizingFactor);
        resizedSize = webpGetInfo(resizedData, resizedData + rawData.size(), nullptr, nullptr);
    } else {
        resizedData = rawData.data();
        resizedSize = rawData.size();
    }

    // Upload the resized image to S3
    string s3BucketName;
    string s3ObjectKey;
    if (awsS3Upload(resizedData, resizedSize, &s3BucketName, &s3ObjectKey)) {
        cerr << "Error: Failed to upload image to S3" << endl;
        return;
    }

    // Generate a user-friendly URL for the optimized image
    stringstream url;
    url << "https://" << s3BucketName << ".s3.amazonaws.com/" << s3ObjectKey;

    cout << "Image optimized and uploaded successfully!" << endl;
    cout << "URL: " << url.str() << endl;
}

// Memory pool for image buffers
void initBufferPool(int maxBuffers) {
    bufferPoolMutex.lock();
    if (bufferPool.size() > 0) {
        // Reuse existing buffers if possible
        cout << "Reusing " << bufferPool.size() << " buffers from the pool." << endl;
    } else {
        // Create new buffers if necessary
        for (int i = 0; i < maxBuffers; i++) {
            ImageBuffer buffer = {};
            buffer.data = (unsigned char*)malloc(BUFFER_SIZE);
            buffer.size = BUFFER_SIZE;
            bufferPool.push_back(buffer);
        }
    }
    bufferPoolMutex.unlock();
}

// Memory pool for image buffers
void freeBufferPool() {
    bufferPoolMutex.lock();
    for (auto& buffer : bufferPool) {
        if (buffer.data) {
            free(buffer.data);
        }
    }
    bufferPool.clear();
    bufferPoolMutex.unlock();
}

// Thread function for buffer management
void manageBuffers() {
    while (true) {
        bufferPoolCondVar.wait(lock);
        if (!bufferPool.empty()) {
            // Remove buffers that are no longer needed
            bufferPoolMutex.lock();
            vector<ImageBuffer> freeBuffers;
            for (auto it = bufferPool.begin(); it != bufferPool.end();) {
                if ((*it).data == nullptr || (*it).size == 0) {
                    freeBuffers.push_back(*it);
                    it = bufferPool.erase(it);
                } else {
                    ++it;
                }
            }
            bufferPoolMutex.unlock();

            // Free the removed buffers
            for (auto& buffer : freeBuffers) {
                if (buffer.data) {
                    free(buffer.data);
                }
            }
        }
    }
}

// Thread function for image processing
void processImage(const string& filePath, const float resizingFactor) {
    // Load and resize the image if necessary
    loadAndResizeImage(filePath, resizingFactor);
}

int main() {
    // Initialize the memory pool for image buffers
    initBufferPool(10);

    // Start a thread to manage the image buffers
    thread bufferManager(manageBuffers);

    // Process images in parallel using multiple threads
    vector<thread> imageProcessors;
    for (int i = 0; i < 5; i++) {
        imageProcessors.push_back(thread(processImage, "path/to/image" + to_string(i), 1));
    }

    // Wait for all the threads to finish
    for (auto& processor : imageProcessors) {
        processor.join();
    }

    // Free the memory pool for image buffers
    freeBufferPool();
}
```
This is a simple example that demonstrates how to use a memory pool to manage a large number of image buffers in parallel. The `initBufferPool` function initializes the memory pool by creating a fixed number of image buffers, and the `manageBuffers` function manages the lifetime of these buffers by removing them from the pool when they are no longer needed. The `processImage` function uses the memory pool to allocate and free buffers as needed for each image processing task.

This example demonstrates how to use a memory pool to manage a large number of image buffers in parallel, and also shows how to implement a simple buffer management system using condition variables and mutexes. The `manageBuffers` function uses a while loop with a condition variable to wait for new tasks or notification that buffers are no longer needed, and then removes the corresponding buffers from the pool. This design allows the memory pool to be safely accessed by multiple threads without worrying about race conditions or deadlocks.']

