    public static async Task<string> DeployAsync(string directoryPath, string siteName, string authToken)
    {
        // Validate the directory path against the whitelist of allowed root directories for hosting
        if (!IsWhitelistedRootDirectory(directoryPath))
        {
            return "403 Forbidden: The provided directory path is not whitelisted";
        }

        // Ensure the presence of a web.config file before proceeding
        if (!File.Exists(WebConfigPath))
        {
            return "400 Bad Request: Missing configuration file (web.config)";
        }

        // Authenticate with the external web server management API using the provided token
        var authResponse = await AuthenticateAsync(authToken);
        if (!authResponse.IsAuthenticated)
        {
            Logger.LogError($"Authentication failed for {directoryPath}");
            return "401 Unauthorized: Authentication failure";
        }

        // Integrate with multiple external services for additional configurations, such as database connection settings and caching configurations
        var integrationResponses = await IntegrateWithExternalServicesAsync(directoryPath);
        if (integrationResponses.Any(response => !response.IsSuccessful))
        {
            Logger.LogError($"Integration with external services failed for {directoryPath}");
            return "500 Internal Server Error: Integration failure";
        }

