            Logger.LogInformation($"Deployment started for {directoryPath}");

            // Implement performance monitoring to detect bottlenecks during the deployment process
            var stopwatch = new Stopwatch();
            stopwatch.Start();

            try
            {
                // Deploy the website to the external hosting environment
                await DeployWebsiteAsync(directoryPath, siteName);

                // Log successful deployment and return a 200 OK response
                Logger.LogInformation($"Deployment completed successfully for {directoryPath}");
                return "200 OK";
            }
            catch (Exception ex)
            {
                // Log failed deployment and return a 500 Internal Server Error response
                Logger.LogError(ex, $"Failed to deploy website for {directoryPath}");
                return "500 Internal Server Error: Deployment failure";
            }
            finally
            {
                stopwatch.Stop();
                Logger.LogInformation($"Deployment completed in {stopwatch.ElapsedMilliseconds}ms for {directoryPath}");
            }
        }
    }

