// config.c
#include "config.h"

// Default configuration values
static const char *DEFAULT_API_KEY = "";
static const char *DEFAULT_ENDPOINT_URL = "";
static const uint16_t DEFAULT_PORT = 0;

// Initialize the configuration structure with default values
void init_config(config_t *cfg) {
    cfg->api_key = DEFAULT_API_KEY;
    cfg->endpoint_url = DEFAULT_ENDPOINT_URL;
    cfg->port = DEFAULT_PORT;
    cfg->active = false;
}

// Validate the configuration parameters
bool validate_config(config_t *cfg) {
    // Check for null or empty strings
    if (cfg->api_key == NULL || strlen(cfg->api_key) == 0) {
        printf("Invalid API key: %s\n", cfg->api_key);
        return false;
    }
    if (cfg->endpoint_url == NULL || strlen(cfg->endpoint_url) == 0) {
        printf("Invalid endpoint URL: %s\n", cfg->endpoint_url);
        return false;
    }

    // Check for a valid port number
    if (cfg->port == 0) {
        printf("Invalid port number: %d\n", cfg->port);
        return false;
    }

    // Check for an active connection status
    if (!cfg->active) {
        printf("Connection is not active\n");
        return false;
    }

    return true;
}

// Update the configuration structure with new values
void update_config(config_t *cfg, char *api_key, char *endpoint_url, uint16_t port) {
    // Check for null or empty strings
    if (api_key == NULL || strlen(api_key) == 0) {
        cfg->api_key = DEFAULT_API_KEY;
    } else {
        cfg->api_key = api_key;
    }
    if (endpoint_url == NULL || strlen(endpoint_url) == 0) {
        cfg->endpoint_url = DEFAULT_ENDPOINT_URL;
    } else {
        cfg->endpoint_url = endpoint_url;
    }

    // Check for a valid port number
    if (port != 0 && port < 65536) {
        cfg->port = port;
    } else {
        cfg->port = DEFAULT_PORT;
    }

    // Update the active flag
    cfg->active = true;
}
