using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace SecureDataHandler
{
    public class SecureDataHandler
    {
        private readonly string _filePath;
        private readonly byte[] _encryptionKey;
        private readonly byte[] _initializationVector;
        private readonly Encoding _encoding;

        public SecureDataHandler(string filePath, byte[] encryptionKey, byte[] initializationVector, Encoding encoding)
        {
            _filePath = filePath;
            _encryptionKey = encryptionKey;
            _initializationVector = initializationVector;
            _encoding = encoding;
        }

        public async Task<T> ProcessEncryptedDataAsync<T>(string filePath, byte[] encryptionKey, byte[] initializationVector)
        {
            using (var fs = new FileStream(filePath, FileMode.Open))
            {
                using (var decryptor = AesCbc.Create())
                {
                    var iv = GetInitializationVector(initializationVector);
                    decryptor.Key = encryptionKey;
                    decryptor.IV = iv;

                    var encryptedBytes = new byte[fs.Length];
                    await fs.ReadAsync(encryptedBytes, 0, encryptedBytes.Length).ConfigureAwait(false);

                    using (var ms = new MemoryStream())
                    {
                        using (var cs = new CryptoStream(ms, decryptor.CreateDecryptor(), CryptoStreamMode.Write))
                        {
                            await cs.WriteAsync(encryptedBytes, 0, encryptedBytes.Length).ConfigureAwait(false);
                            await cs.FlushFinalBlockAsync().ConfigureAwait(false);

                            var decryptedBytes = ms.ToArray();
                            return Deserialize<T>(decryptedBytes);
                        }
                    }
                }
            }
        }

        private byte[] GetInitializationVector(byte[] initializationVector)
        {
            if (initializationVector != null && initializationVector.Length == _initializationVector.Length)
            {
                return initializationVector;
            }
            else
            {
                return _initializationVector;
            }
        }

        private T Deserialize<T>(byte[] bytes)
        {
            var serializer = new Serializer(_encoding);
            using (var ms = new MemoryStream(bytes))
            {
                return (T)serializer.Deserialize(ms, typeof(T));
            }
        }
    }
}
```
