            var allObjects = new List<T>();
            using (var fileStream = new FileStream(_filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
            {
                var binaryFormatter = new BinaryFormatter();
                while (fileStream.Position < fileStream.Length)
                {
                    try
                    {
                        var deserializedObject = binaryFormatter.Deserialize(fileStream) as T;
                        if (deserializedObject == null)
                        {
                            throw new InvalidDataException("Invalid data format");
                        }

                        allObjects.Add(deserializedObject);
                    }
                    catch (EndOfStreamException ex)
                    {
                        break;
                    }
                    catch (IOException ex)
                    {
                        // Handle file not found or access denied errors.
                        throw new FileNotFoundException($"File '{_filePath}' not found.", ex);
                    }
                    catch (InvalidDataException ex)
                    {
                        // Handle invalid data format errors.
                        throw new InvalidDataException($"Invalid data format in file '{_filePath}'.", ex);
                    }
                }
            }

            return allObjects;
        }

        public async Task<IEnumerable<T>> DeserializeAllAsync(string[] filePaths, CancellationToken cancellationToken = default)
        {
            var allObjects = new List<T>();
            foreach (var filePath in filePaths)
            {
                using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                {
                    var binaryFormatter = new BinaryFormatter();
                    while (fileStream.Position < fileStream.Length)
                    {
                        try
                        {
                            var deserializedObject = binaryFormatter.Deserialize(fileStream) as T;
                            if (deserializedObject == null)
                            {
                                throw new InvalidDataException("Invalid data format");
                            }

                            allObjects.Add(deserializedObject);
                        }
                        catch (EndOfStreamException ex)
                        {
                            break;
                        }
                        catch (IOException ex)
                        {
                            // Handle file not found or access denied errors.
                            throw new FileNotFoundException($"File '{filePath}' not found.", ex);
                        }
                        catch (InvalidDataException ex)
                        {
                            // Handle invalid data format errors.
                            throw new InvalidDataException($"Invalid data format in file '{filePath}'.", ex);
                        }
                    }
                }
            }

            return allObjects;
        }

        public async Task SerializeAsync(T obj, string filePath = null, CancellationToken cancellationToken = default)
        {
            if (string.IsNullOrEmpty(filePath))
            {
                filePath = _filePath;
            }

            using (var fileStream = new FileStream(filePath, FileMode.Create, FileAccess.Write, FileShare.ReadWrite))
            {
                var binaryFormatter = new BinaryFormatter();
                try
                {
                    binaryFormatter.Serialize(fileStream, obj);
                    _cache[filePath] = obj;
                }
                catch (IOException ex)
                {
                    // Handle file not found or access denied errors.
                    throw new FileNotFoundException($"File '{filePath}' not found.", ex);
                }
            }
        }
    }
}
