['```java
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.Serializable;
import java.net.URL;
import java.util.HashMap;
import java.util.Map;

public class DynamicClassDeserializer {
    private Map<String, Class<?>> cachedClasses = new HashMap<>();
    private URL apiUrl;

    public DynamicClassDeserializer(URL apiUrl) {
        this.apiUrl = apiUrl;
    }

    public <T extends Serializable> T deserialize(byte[] data) throws IOException, ClassNotFoundException {
        String className = getClassName(data);
        Class<?> clazz = cachedClasses.get(className);
        if (clazz == null) {
            clazz = loadClass(className);
            cachedClasses.put(className, clazz);
        }
        return (T) deserializeObject(data, clazz);
    }

    private String getClassName(byte[] data) throws IOException {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bais);
        return (String) ois.readObject();
    }

    private Class<?> loadClass(String className) throws ClassNotFoundException {
        URL classUrl = new URL(apiUrl, "class/" + className);
        return Class.forName(className, true, getClass().getClassLoader());
    }

    private <T extends Serializable> T deserializeObject(byte[] data, Class<T> clazz) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bais);
        return (T) ois.readObject();
    }
}
```
