    fn from(error: reqwest::Error) -> Self {
        ApiError {
            status_code: error.status().unwrap_or(0),
            response_body: "".to_string(),
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
