    let (mut apis, mut storage) = config.apis;

    loop {
        let api_data = &apis[0];
        let storage_client = &storage.db;

        // Fetch data from API
        let response = get(api_data.url.clone(), &api_data.headers).await?;
        if !response.status().is_success() {
