['```rust
use std::path::PathBuf;
use std::sync::{Arc, RwLock};
use std::time::Duration;

const CONFIG_STORAGE_PATH: &str = "config_storage";
const CONFIG_MANAGEMENT_SERVICE_URL: &str = "https://example.com/config-management";
const CONFIG_UPDATE_INTERVAL: Duration = Duration::from_secs(60);

struct ConfigManager {
    config_storage_path: Arc<RwLock<PathBuf>>,
    config_service_client: Client,
}

impl ConfigManager {
    pub fn new() -> Self {
        let mut config_storage_path = PathBuf::from(CONFIG_STORAGE_PATH);
        if !config_storage_path.is_dir() {
            if let Err(e) = std::fs::create_dir(&config_storage_path) {
                log::error!("Failed to create config storage directory: {}", e);
            }
        }

        Self {
            config_storage_path: Arc::new(RwLock::new(config_storage_path)),
            config_service_client: Client::new(),
        }
    }

    pub fn update(&mut self) -> Result<(), String> {
        let config_storage_path = self.config_storage_path.read().unwrap();
        if !config_storage_path.exists() {
            log::info!("Config storage directory does not exist, creating...");
            std::fs::create_dir(&config_storage_path).map_err(|e| format!("Failed to create config storage directory: {}", e))?;
        }

        let mut updated = false;
        loop {
            match self.config_service_client.get_configuration() {
                Ok(response) => {
                    if response.data != *self.config_storage_path.read().unwrap() {
                        updated = true;
                        break;
                    } else {
                        std::thread::sleep(Duration::from_secs(1));
                    }
                },
                Err(e) => {
                    log::error!("Failed to retrieve configuration from service: {}", e);
                    std::thread::sleep(Duration::from_secs(CONFIG_UPDATE_INTERVAL.as_secs()));
                }
            }
        }

        if updated {
            self.config_storage_path.write().unwrap() = response.data;
            log::info!("Updated configuration from service");
        }

        Ok(())
    }
}
```
