    std::mutex mtx_;
    std::condition_variable cv_;

    // Buffer for storing IoT device data
    std::vector<IoTDeviceData> dataBuffer_;

    // Function to add a new IoT device data point to the buffer
    void addNewDataPoint(const IoTDeviceData& data) {
