        printf("Password must contain at least one lowercase letter, one uppercase letter, and one digit.\n");
        return 1;
    }
    // Decrypt the string using AES-256
    unsigned char iv[16];
    RAND_bytes(iv, 16);
    EVP_CIPHER_CTX *ctx = NULL;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, iv);
    int outlen;
    unsigned char *outbuf = (unsigned char *)malloc(strlen(string));
    if (!EVP_DecryptUpdate(ctx, outbuf, &outlen, (unsigned char *)string, strlen(string))) {
        printf("Error decrypting string.\n");
        EVP_CIPHER_CTX_free(ctx);
        return 1;
    }
    // Insert the decrypted string into the database
    sqlite3_stmt *stmt = NULL;
    char sql[256];
    sprintf(sql, "INSERT INTO decrypted_strings VALUES (?, ?)", outlen);
    int rc = sqlite3_prepare_v2(db_conn, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        printf("Error inserting decrypted string into database.\n");
        EVP_CIPHER_CTX_free(ctx);
        return 1;
    }
    sqlite3_bind_blob(stmt, 1, outbuf, outlen, SQLITE_STATIC);
    if (sqlite3_step(stmt) != SQLITE_DONE) {
