#define BUFFER_SIZE 16384

typedef enum {
    ENCRYPTION,
    DECRYPTION
} operation_t;

static int encrypt(const char *input, const char *key, const char *iv) {
    int ret = -1;
    AES_KEY aes_key;
    unsigned char output[BUFFER_SIZE];
    size_t outlen = BUFFER_SIZE;

    // Validate input strings for appropriate character encoding and handle malformed strings gracefully. Implement a fallback mechanism for unsupported encodings.
    if (!validate_encoding(input, key)) {
        printf("Error: Invalid input string encoding\n");
        return -1;
    }

    // Initialize the AES key and IV from the given strings.
    ret = AES_set_encrypt_key(key, strlen(key) * 8, &aes_key);
    if (ret != 0) {
        printf("Error: Invalid key or IV\n");
        return -1;
    }

    // Encrypt the input string using AES in CBC mode with the given IV.
    ret = AES_cbc_encrypt(input, output, outlen, &aes_key, iv, BUFFER_SIZE);
    if (ret != 0) {
        printf("Error: Encryption failed\n");
        return -1;
    }

    // Write the encrypted output to the external data storage system.
    sqlite3 *db = NULL;
    char *errmsg = NULL;
    ret = sqlite3_open("encrypted.db", &db);
    if (ret != 0) {
        printf("Error: Failed to open database\n");
        return -1;
    }
    ret = sqlite3_exec(db, "INSERT INTO encrypted VALUES ('input', ?)", NULL, NULL, NULL);
    if (ret != 0) {
        printf("Error: Failed to execute query\n");
        return -1;
    }

    // Clean up and return success.
    sqlite3_close(db);
    return 0;
}

static int decrypt(const char *input, const char *key) {
    int ret = -1;
    AES_KEY aes_key;
    unsigned char output[BUFFER_SIZE];
    size_t outlen = BUFFER_SIZE;

    // Validate input strings for appropriate character encoding and handle malformed strings gracefully. Implement a fallback mechanism for unsupported encodings.
    if (!validate_encoding(input, key)) {
        printf("Error: Invalid input string encoding\n");
        return -1;
    }

    // Initialize the AES key from the given string.
    ret = AES_set_decrypt_key(key, strlen(key) * 8, &aes_key);
    if (ret != 0) {
        printf("Error: Invalid key or IV\n");
        return -1;
    }

    // Decrypt the input string using AES in CBC mode with the given IV.
    ret = AES_cbc_decrypt(input, output, outlen, &aes_key, iv, BUFFER_SIZE);
    if (ret != 0) {
        printf("Error: Decryption failed\n");
        return -1;
    }

    // Write the decrypted output to the external data storage system.
    sqlite3 *db = NULL;
    char *errmsg = NULL;
    ret = sqlite3_open("decrypted.db", &db);
    if (ret != 0) {
        printf("Error: Failed to open database\n");
        return -1;
    }
    ret = sqlite3_exec(db, "INSERT INTO decrypted VALUES ('input', ?)", NULL, NULL, NULL);
    if (ret != 0) {
        printf("Error: Failed to execute query\n");
        return -1;
    }

    // Clean up and return success.
    sqlite3_close(db);
    return 0;
}

static int validate_encoding(const char *input, const char *key) {
    if (strlen(input) == 0 || strlen(key) == 0) {
        printf("Error: Input string or key cannot be empty\n");
        return -1;
    }
    if (!is_utf8(input)) {
        printf("Warning: Input string is not in UTF-8 encoding. Using fallback mechanism.\n");
    }
    return 0;
}

static int is_utf8(const char *s) {
    const unsigned char *p = (unsigned char *)s;
    while (*p != '\0') {
        if ((*p & 0xc0) == 0x80) {
            return -1;
        }
        p++;
    }
    return 0;
}
```
