    if (total_length > size_limit) {
        log_error("Token length exceeds limit");
        json_object_put(json);
        return false;
    }
    char *output = malloc(total_length + 1); // allocate memory for output string
    strcpy(output, access_token);
    strcat(output, utc_time);

