char* truncateAndWrapString(struct TruncateWrapContext* context) {
    char* result = NULL;
    if (context->sizeLimit == 0) {
        return result;
    }

    // Determine the maximum number of characters that can be displayed based on the font size and style
    int maxChars = context->maxWidth / context->fontSize * 1.25;

