static bool string_truncate(char* str, size_t max_len) {
    if (str == NULL || max_len <= 0) return false;

    // Get the length of the input string
    size_t len = strlen(str);

    // Check if the input string is already within the maximum length
    if (len <= max_len) return true;

    // Truncate the input string to the maximum length
    str[max_len] = '\0';

    return true;
}

// Define the function for wrapping a string with ellipses
static char* string_wrap(char* str, size_t max_len) {
    if (str == NULL || max_len <= 0) return NULL;

    // Get the length of the input string
    size_t len = strlen(str);

    // Check if the input string is already within the maximum length
    if (len <= max_len) return str;

    // Calculate the required size for the wrapped string
    size_t wrapped_size = len + 3;

    // Allocate memory for the wrapped string
    char* wrapped_str = malloc(wrapped_size);
    if (wrapped_str == NULL) return NULL;

    // Copy the input string to the wrapped string
    memcpy(wrapped_str, str, len);

    // Add ellipses to the end of the wrapped string
    wrapped_str[len] = '.';
    wrapped_str[len + 1] = '.';
    wrapped_str[len + 2] = '\0';

    return wrapped_str;
}

// Define the function for formatting a frame header for display
static char* format_frame(FrameHeader* frame, size_t max_len) {
    if (frame == NULL || max_len <= 0) return NULL;

    // Get the length of the input string
    size_t len = strlen(frame->source_ip);

    // Check if the input string is already within the maximum length
    if (len <= max_len) return frame->source_ip;

