class CloudStorage {
private:
    std::unordered_map<std::string, Object> objects;
    std::mutex mutex_;

public:
    void addObject(const std::string& id, int timestamp, double value) {
        std::lock_guard<std::mutex> lock(mutex_);
        objects[id] = { id, timestamp, value };
    }

    Object getObject(const std::string& id) const {
        std::lock_guard<std::mutex> lock(mutex_);
        return objects.at(id);
    }

    void removeObject(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        objects.erase(id);
    }

    std::vector<Object> getAllObjects() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return std::vector<Object>(objects.begin(), objects.end());
    }
};

class Object {
public:
    std::string id;
    int timestamp;
    double value;

    Object() {}

    Object(const std::string& id, int timestamp, double value) : id(id), timestamp(timestamp), value(value) {}
};

void main() {
    CloudStorage storage;
    storage.addObject("obj1", 1234567890, 10.5);
    storage.addObject("obj2", 9876543210, 20.5);
    storage.removeObject("obj1");
    Object obj = storage.getObject("obj2");
    std::vector<Object> allObjects = storage.getAllObjects();
}

