#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>

#define PORT 8080
#define MAX_CLIENTS 20
#define BUFSIZE 1024
#define CACHE_SIZE 1000
#define LOGGING_PATH "logs"
#define CACHE_PATH "cache"

typedef struct client_t {
    int socket;
    char* ip;
} client_t;

typedef struct cache_entry_t {
    char* key;
    char* value;
} cache_entry_t;

// Initialize the server
int init_server(void) {
    // Create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        return 1;
    }

    // Setup the server address
    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    // Bind the socket to the server address
    if (bind(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Bind failed");
        return 1;
    }

    // Listen for incoming connections
    if (listen(sock, MAX_CLIENTS) < 0) {
        perror("Listen failed");
        return 1;
    }

    return sock;
}

// Handle an incoming connection from a client
void handle_client(int sock) {
    // Get the client's IP address and port number
    struct sockaddr_in cli_addr;
    int clilen = sizeof(cli_addr);
    getpeername(sock, (struct sockaddr*)&cli_addr, &clilen);
    char* ip = inet_ntoa(cli_addr.sin_addr);

    // Accept the connection from the client
    int new_sock = accept(sock, NULL, NULL);
    if (new_sock < 0) {
        perror("Accept failed");
        return;
    }

    // Read the request from the client
    char buffer[BUFSIZE];
    int n = read(new_sock, buffer, BUFSIZE - 1);
    if (n < 0) {
        perror("Read failed");
        return;
    }

    // Process the request and generate a response
    char* response = process_request(buffer);
    int send_n = write(new_sock, response, strlen(response));
    if (send_n < 0) {
        perror("Write failed");
        return;
    }

    // Close the connection with the client
    close(new_sock);
}

// Process an incoming request from a client
char* process_request(char* buffer) {
    // Parse the request and extract the key
    char* key = strtok(buffer, " ");
    if (key == NULL) {
        perror("Error parsing request");
        return NULL;
    }

    // Retrieve the value from the cache or database
    char* value = get_value_from_cache(key);
    if (value == NULL) {
        value = retrieve_value_from_database(key);
        if (value == NULL) {
            perror("Error retrieving value");
            return NULL;
        }
    }

    // Return the response to the client
    char* response = generate_response(value);
    return response;
}

// Retrieve a value from the cache
char* get_value_from_cache(char* key) {
    // Check if the key is in the cache
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(key, cache[i].key) == 0) {
            return cache[i].value;
        }
    }

    // If the key is not in the cache, retrieve it from the database
    char* value = retrieve_value_from_database(key);
    if (value == NULL) {
        perror("Error retrieving value");
        return NULL;
    }

    // Add the key-value pair to the cache
    add_to_cache(key, value);

    return value;
}

// Retrieve a value from the database
char* retrieve_value_from_database(char* key) {
    // Send a request to the RESTful service
    char request[BUFSIZE];
    sprintf(request, "GET %s\n", key);
    int send_n = write(sock, request, strlen(request));
    if (send_n < 0) {
        perror("Write failed");
        return NULL;
    }

    // Read the response from the database
    char buffer[BUFSIZE];
    int n = read(sock, buffer, BUFSIZE - 1);
    if (n < 0) {
        perror("Read failed");
        return NULL;
    }

    // Parse the response and extract the value
    char* value = strtok(buffer, " ");
    if (value == NULL) {
        perror("Error parsing response");
        return NULL;
    }

    return value;
}

// Add a key-value pair to the cache
void add_to_cache(char* key, char* value) {
    // Check if the cache is full
    if (cache_size >= CACHE_SIZE) {
        return;
    }

    // Add the key-value pair to the cache
    cache[cache_size].key = malloc(strlen(key) + 1);
    strcpy(cache[cache_size].key, key);
    cache[cache_size].value = malloc(strlen(value) + 1);
    strcpy(cache[cache_size].value, value);
    cache_size++;
}

// Generate a response to the client
char* generate_response(char* value) {
    char* response = malloc(sizeof(char)*BUFSIZE);
    sprintf(response, "Value for key %s is %s\n", key, value);
    return response;
}

// Initialize the cache with the pre-defined values
void init_cache(void) {
    // Load the cache from disk if it exists
    FILE* file = fopen("cache.txt", "r");
    if (file != NULL) {
        while ((fscanf(file, "%s %s\n", key, value)) != EOF) {
            add_to_cache(key, value);
        }
        fclose(file);
    }
}

// Save the cache to disk
void save_cache(void) {
    // Open the cache file for writing
    FILE* file = fopen("cache.txt", "w");
    if (file == NULL) {
        perror("Error opening cache file for writing");
        return;
    }

    // Write each key-value pair to the cache file
    for (int i = 0; i < cache_size; i++) {
        fprintf(file, "%s %s\n", cache[i].key, cache[i].value);
    }

    // Close the cache file
    fclose(file);
}

// Initialize the database connection
void init_database(void) {
    // Connect to the database
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Error creating socket");
        return;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(80);
    inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr);

    if (connect(sock, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        perror("Error connecting to database");
        return;
    }
}

// Close the database connection
void close_database(void) {
    if (sock >= 0) {
        close(sock);
    }
}

// Initialize the cache and database connections
void init_connections(void) {
    init_cache();
    init_database();
}

// Close all open connections
void close_connections(void) {
    save_cache();
    close_database();
}

int main() {
    // Initialize the cache and database connections
    init_connections();

    while (1) {
        handle_request();
    }

    return 0;
}
