Here is an example of a modular C library that implements a robust semaphore system for managing resources across different subsystems in a high-concurrency, distributed file management system with external APIs and database queries:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <pthread.h>
#include <errno.h>
#include <assert.h>

// Define the maximum number of concurrent requests that can be handled by the library
#define MAX_CONCURRENT_REQUESTS 50000

// Define the initial values for the semaphores
#define INITIAL_SEMAPHORE_VALUES {1, 2, 3}

// Define the maximum number of attempts to acquire a semaphore before giving up
#define MAX_ATTEMPTS_TO_ACQUIRE_SEMAPHORE 5

// Define the timeout for acquiring a semaphore in milliseconds
#define SEMAPHORE_ACQUIRE_TIMEOUT_MS 100

// Define the maximum number of threads that can be spawned by the library
#define MAX_THREADS 10

// Structure to represent a file request
typedef struct {
    char* filename; // The name of the file
    int version; // The version number of the file
} file_request_t;

// Function to acquire a semaphore with a given index and return its value
int acquire_semaphore(int index) {
    sem_t* sem = sem_open("/sem_" + index, O_CREAT | O_EXCL, 0644, INITIAL_SEMAPHORE_VALUES[index]);
    if (sem == SEM_FAILED) {
        fprintf(stderr, "Failed to create semaphore: %s\n", strerror(errno));
        return -1;
    }

    int val = 0;
    for (int i = 0; i < MAX_ATTEMPTS_TO_ACQUIRE_SEMAPHORE; i++) {
        if (sem_trywait(sem) == 0) {
            // Successfully acquired the semaphore
            val++;
        } else {
            // Failed to acquire the semaphore, try again after a timeout
            sleep(SEMAPHORE_ACQUIRE_TIMEOUT_MS);
        }
    }

    if (val == 0) {
        fprintf(stderr, "Failed to acquire semaphore: %s\n", strerror(errno));
        return -1;
    }

    return val;
}

// Function to release a semaphore with a given index and return its value
int release_semaphore(int index) {
    sem_t* sem = sem_open("/sem_" + index, O_CREAT | O_EXCL, 0644, INITIAL_SEMAPHORE_VALUES[index]);
    if (sem == SEM_FAILED) {
        fprintf(stderr, "Failed to create semaphore: %s\n", strerror(errno));
        return -1;
    }

    int val = 0;
    for (int i = 0; i < MAX_ATTEMPTS_TO_ACQUIRE_SEMAPHORE; i++) {
        if (sem_trywait(sem) == 0) {
            // Successfully acquired the semaphore
            val++;
        } else {
            // Failed to acquire the semaphore, try again after a timeout
            sleep(SEMAPHORE_ACQUIRE_TIMEOUT_MS);
        }
    }

    if (val == 0) {
        fprintf(stderr, "Failed to release semaphore: %s\n", strerror(errno));
        return -1;
    }

    // Release the semaphore
    sem_post(sem);

    return val;
}

// Function to handle a file request and process it according to its version number
int handle_file_request(file_request_t* request) {
    // Acquire semaphores for the given index
    int semaphore_values[3] = INITIAL_SEMAPHORE_VALUES;
    if (acquire_semaphore(0) < 0 || acquire_semaphore(1) < 0 || acquire_semaphore(2) < 0) {
        // Failed to acquire semaphores, return an error
        fprintf(stderr, "Failed to acquire semaphores: %s\n", strerror(errno));
        return -1;
    }

    // Update the file name with the new version number format
    char* new_filename = NULL;
    if (sscanf(request->filename, "v%d.%d.%d", &request->version) == 3) {
        new_filename = malloc(strlen(request->filename) + 10);
        snprintf(new_filename, strlen(request->filename) + 10, "vX.Y.Z.<type>", request->version);
    } else {
        // Failed to parse the version number, return an error
        fprintf(stderr, "Failed to parse version number: %s\n", strerror(errno));
        return -1;
    }

    // Update the file name in the request structure
    free(request->filename);
    request->filename = new_filename;

    // Release semaphores for the given index
    release_semaphore(0);
    release_semaphore(1);
    release_semaphore(2);

    return 0;
}

// Function to handle a list of file requests and process them concurrently
int handle_file_requests(file_request_t* requests, int n) {
    // Spawn threads for each request
    pthread_t threads[n];
    for (int i = 0; i < n; i++) {
        if (pthread_create(&threads[i], NULL, handle_file_request, &requests[i]) != 0) {
            fprintf(stderr, "Failed to create thread: %s\n", strerror(errno));
            return -1;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < n; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Main function
int main() {
    // Create a list of file requests
    int n = 3;
    file_request_t* requests = malloc(n * sizeof(file_request_t));
    for (int i = 0; i < n; i++) {
        requests[i].filename = "v1.2.3";
    }

    // Handle the list of file requests concurrently
    if (handle_file_requests(requests, n) != 0) {
        fprintf(stderr, "Failed to handle file requests\n");
        return -1;
    }

    return 0;
}']

