namespace RandomEngine {

// Abstract class for RNG algorithms
class RNGAlgorithm {
public:
    virtual ~RNGAlgorithm() = default;
    virtual void seed(uint64_t seed) = 0;
    virtual uint64_t generate() = 0;
};

// Implementation of Mersenne Twister algorithm
class MersenneTwister : public RNGAlgorithm {
public:
    MersenneTwister(uint64_t seed);
    void seed(uint64_t seed) override;
    uint64_t generate() override;
};

// Implementation of PCG algorithm
class PCG : public RNGAlgorithm {
public:
    PCG(uint64_t seed);
    void seed(uint64_t seed) override;
    uint64_t generate() override;
};

// Implementation of Xorshift algorithm
class Xorshift : public RNGAlgorithm {
public:
    Xorshift(uint64_t seed);
    void seed(uint64_t seed) override;
    uint64_t generate() override;
};

// Class for managing instances of different RNG algorithms
class RNGManager {
public:
    // Constructor
    RNGManager();

    // Destructor
    ~RNGManager();

    // Get the current seed value
    uint64_t getSeed() const;

    // Set the seed value
    void setSeed(uint64_t seed);

    // Generate a random number using the specified RNG algorithm
    uint64_t generate(RNGAlgorithm* algorithm) const;

private:
    // Map of RNG algorithms by name
    std::map<std::string, std::unique_ptr<RNGAlgorithm>> algorithms_;
};

// User-friendly interface for generating random numbers
class Random {
public:
    // Constructor
    Random();

    // Destructor
    ~Random();

    // Generate a random number using the default RNG algorithm
    uint64_t generate() const;

    // Set the seed value for the default RNG algorithm
    void setSeed(uint64_t seed);
};

// Implementation of RandomEngine namespace
namespace RandomEngine {
    // Get the current seed value
    uint64_t getSeed() const;

    // Set the seed value
    void setSeed(uint64_t seed);

    // Generate a random number using the specified RNG algorithm
    uint64_t generate(RNGAlgorithm* algorithm) const;
}
```
