using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace DynamicDatabaseService
{
    public class DatabaseService : IDisposable
    {
        private readonly IConfiguration _config;
        private readonly ILogger<DatabaseService> _logger;
        private readonly Dictionary<string, SqlConnection> _connections = new();

        public DatabaseService(IConfiguration config, ILogger<DatabaseService> logger)
        {
            _config = config;
            _logger = logger;
        }

        public async Task ExecuteComplexQueryAsync(string query, object parameters)
        {
            var connectionString = _config["ConnectionStrings:Default"];
            if (connectionString == null)
            {
                throw new Exception("No default connection string specified.");
            }

            var connection = GetOrCreateConnection(connectionString);
            try
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddRange(parameters);
                    var result = await command.ExecuteReaderAsync();
                    // Handle result as needed
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to execute query.");
            }
            finally
            {
                connection.Close();
            }
        }

        private SqlConnection GetOrCreateConnection(string connectionString)
        {
            if (!_connections.TryGetValue(connectionString, out var connection))
            {
                connection = new SqlConnection(connectionString);
                _connections.Add(connectionString, connection);
            }
            return connection;
        }

        public void Dispose()
        {
            foreach (var connection in _connections.Values)
            {
                if (connection.State == ConnectionState.Open)
                {
                    connection.Close();
                }
            }
        }
    }
}
