```typescript
import { EmployeeAPI } from './employee-api';
import { DOMParser } from 'xmldom';
import { throttle } from 'async';

interface NodeData {
  id: string;
  customAttributeValue: string;
}

interface SupervisorInfo {
  name: string;
  city: string;
  address: string;
}

class DOMTreeProcessor {
  private readonly employeeAPI: EmployeeAPI;
  private readonly cache = new Map<string, SupervisorInfo>();

  constructor(employeeAPI: EmployeeAPI) {
    this.employeeAPI = employeeAPI;
  }

  public async processDOMTree(tree: Node): Promise<NodeData[]> {
    const nodeDataList: NodeData[] = [];
    const nodesToProcess: Array<Promise<void>> = [];

    for (const node of tree.querySelectorAll('[custom-attribute]')) {
      const customAttributeValue = node.getAttribute('custom-attribute');
      if (!customAttributeValue) continue;

      // Check cache first
      let supervisorInfo: SupervisorInfo | undefined = this.cache.get(customAttributeValue);

      // Fetch from API if not in cache
      if (!supervisorInfo) {
        nodesToProcess.push(this.fetchSupervisorInfo(customAttributeValue).then((info) => {
          supervisorInfo = info;
          this.cache.set(customAttributeValue, supervisorInfo);
        }));
      }

      nodeDataList.push({
        id: node.id,
        customAttributeValue,
        supervisorName: supervisorInfo ? supervisorInfo.name : '',
        supervisorCity: supervisorInfo ? supervisorInfo.city : '',
        supervisorAddress: supervisorInfo ? supervisorInfo.address : ''
      });
    }

    // Wait for all promises to resolve
    await Promise.all(nodesToProcess);

    return nodeDataList;
  }

  private async fetchSupervisorInfo(customAttributeValue: string): Promise<SupervisorInfo> {
    const employeeId = customAttributeValue.split('-')[0];
    return this.employeeAPI.getEmployeeById(employeeId).then((employee) => {
      return {
        name: employee.name,
        city: employee.city,
        address: employee.address
      };
    });
  }
}
```
