Here is a sample implementation of the modular JavaScript component loading system in Rust that integrates with an external REST API for module retrieval and version updates:
```rust
use async_std::{fs, path};
use reqwest::blocking::get;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::error::Error;
use std::fs::File;
use std::io::Read;
use std::path::PathBuf;
use std::result::Result;
use tokio::task::{self, JoinHandle};

#[derive(Debug, Serialize, Deserialize)]
struct Module {
    name: String,
    version: String,
    path: PathBuf,
}

impl Module {
    fn new(name: &str, version: &str) -> Result<Self, Error> {
        let mut file = File::open(format!("{}.js", name))?;
        let mut content = String::new();
        file.read_to_string(&mut content)?;
        Ok(Module {
            name: name.to_string(),
            version: version.to_string(),
            path: PathBuf::from("."),
        })
    }
}

struct ModuleLoader {
    modules: HashMap<String, String>,
}

impl ModuleLoader {
    fn new() -> Self {
        ModuleLoader {
            modules: HashMap::new(),
        }
    }

    fn load(&mut self, module: &Module) -> Result<(), Error> {
        let url = format!("https://api.example.com/modules/{}/{}.js", module.name, module.version);
        let response = get(url).await?;
        if !response.status().is_success() {
            return Err(Error::new("Failed to load module"));
        }
        self.modules.insert(module.name.clone(), module.version.clone());
        Ok(())
    }
}

struct ModuleManager {
    loader: ModuleLoader,
}

impl ModuleManager {
    fn new() -> Self {
        ModuleManager {
            loader: ModuleLoader::new(),
        }
    }

    async fn load_modules(&mut self) -> Result<(), Error> {
        let mut tasks = vec![];
        for module in self.loader.modules.iter() {
            let name = module.name;
            let version = module.version;
            tasks.push(task::spawn(async move {
                match self.loader.load(&Module::new(name, version).await) {
                    Ok(_) => println!("Loaded module {}", name),
                    Err(e) => eprintln!("Failed to load module {}: {}", name, e),
                }
            }));
        }
        for task in tasks {
            task.await;
        }
        Ok(())
    }
}

fn main() -> Result<(), Error> {
    let mut manager = ModuleManager::new();
    manager.load_modules().await?;
    println!("Loaded {} modules", manager.loader.modules.len());
    Ok(())
}
```
This implementation uses the `async_std` library to perform asynchronous file operations and the `reqwest` library to make HTTP requests to an external API. It also uses the `serde` library for serializing and deserializing JSON data, and the `tokio` library for managing asynchronous tasks.

The `Module` struct represents a module that is loaded by the system, with a name, version, and path. The `ModuleLoader` struct loads modules from an external API, and the `ModuleManager` struct manages the loading of modules.

The `main` function creates a new `ModuleManager` instance and calls its `load_modules` method to load all modules that are configured in the system. It then prints the number of loaded modules to the console.']

