struct ProcessingContext {
    // Map data source names to their respective processing contexts
    data_source_contexts: HashMap<String, DataSourceContext>,

    // Current time in nanoseconds
    current_time: u64,
}

struct DataSourceContext {
    // Name of the data source
    name: String,

    // Number of messages processed so far
    message_count: usize,

    // Time when the last message was received
    last_message_time: u64,
}

fn process_streaming_data(processing_context: &mut ProcessingContext) {
    // Iterate over all data sources
    for (_, data_source_context) in processing_context.data_source_contexts.iter() {
        // Check if there are any new messages to process
        if data_source_context.message_count > 0 {
            // Process the next message from the data source
            let message = // ...; // Retrieve the next message from the data source
            process_message(processing_context, message);
        }
    }

    // Handle backpressure by throttling the processing rate if necessary
    if processing_context.current_time - processing_context.last_message_time < Duration::from_secs(1) {
        std::thread::sleep(Duration::from_millis(50));
    }
}

fn process_message(processing_context: &mut ProcessingContext, message: &Message) {
    // Extract the data source name from the message metadata
    let data_source = message.metadata["data_source"];

    // Retrieve the processing context for the current data source
    let data_source_context = processing_context.data_source_contexts.get(&data_source).unwrap();

    // Increment the message count for the current data source
    data_source_context.message_count += 1;

    // Update the last message time for the current data source
    data_source_context.last_message_time = processing_context.current_time;

