// Unit test suite for password update component
namespace PasswordUpdateComponentTestSuite {
    using System;
    using System.Security.Cryptography;
    using PasswordUpdateComponent;

    public class PasswordUpdateTests {
        // Test case: Validate that the password policy is enforced correctly
        [Fact]
        public void EnforcePasswordPolicy() {
            var password = "password123";
            var result = PasswordUpdate.ValidatePassword(password);
            Assert.False(result.Success, "Invalid password should not be accepted");
            Assert.Equal("Password does not meet the minimum requirements", result.Message);
        }

        // Test case: Validate that the password history is enforced correctly
        [Fact]
        public void EnforcePasswordHistory() {
            var password = "password123";
            var passwordHistory = new List<string>() { "password123", "password456" };
            var result = PasswordUpdate.ValidatePassword(password, passwordHistory);
            Assert.False(result.Success, "Repeated password should not be accepted");
            Assert.Equal("Password has been used in the past", result.Message);
        }

        // Test case: Validate that the authentication service is integrated correctly
        [Fact]
        public void IntegrateAuthenticationService() {
            var accessToken = "access_token";
            var userId = 123;
            var passwordUpdateComponent = new PasswordUpdateComponent();
            var result = passwordUpdateComponent.AuthenticateUser(accessToken, userId);
            Assert.True(result.Success, "Authentication should be successful");
        }
    }
}

// Implementation of the password update component
namespace PasswordUpdateComponent {
    using System;
    using System.Security.Cryptography;
    using System.Threading.Tasks;
    using ThirdPartyAuthenticationService;

    public class PasswordUpdate {
        private readonly IThirdPartyAuthenticationService _authenticationService;
        private readonly IPasswordHasher _passwordHasher;
        private readonly IPasswordHistoryRepository _passwordHistoryRepository;

        public PasswordUpdate(IThirdPartyAuthenticationService authenticationService, IPasswordHasher passwordHasher, IPasswordHistoryRepository passwordHistoryRepository) {
            _authenticationService = authenticationService;
            _passwordHasher = passwordHasher;
            _passwordHistoryRepository = passwordHistoryRepository;
        }

        public async Task<PasswordUpdateResult> UpdatePassword(string accessToken, int userId, string newPassword) {
            // Validate the input parameters
            if (String.IsNullOrEmpty(accessToken)) {
                return PasswordUpdateResult.InvalidAccessToken();
            }

            if (userId <= 0) {
                return PasswordUpdateResult.InvalidUserId();
            }

            if (String.IsNullOrEmpty(newPassword)) {
                return PasswordUpdateResult.InvalidNewPassword();
            }

            // Authenticate the user with the third-party authentication service
            var authenticationResult = await _authenticationService.AuthenticateUserAsync(accessToken);
            if (!authenticationResult.Success) {
                return PasswordUpdateResult.FailedAuthentication();
            }

            // Validate the password policy
            var validationResult = ValidatePassword(newPassword);
            if (!validationResult.Success) {
                return validationResult;
            }

            // Check if the new password has been used in the past
            var passwordHistory = await _passwordHistoryRepository.GetPasswordHistoryAsync(userId);
            if (passwordHistory.Contains(newPassword)) {
                return PasswordUpdateResult.RepeatedPassword();
            }

            // Update the user's password
            var hashedPassword = _passwordHasher.ComputeHash(newPassword);
            await _authenticationService.SetUserPasswordAsync(userId, hashedPassword);

            return PasswordUpdateResult.Success();
        }

        public PasswordUpdateResult ValidatePassword(string password) {
            // Check the minimum length requirement
            if (password.Length < 12) {
                return PasswordUpdateResult.InvalidMinimumLength();
            }

            // Check for at least two uppercase letters, two lowercase letters, two digits, and two special characters
            var hasUppercase = password.Any(c => Char.IsUpper(c));
            var hasLowercase = password.Any(c => Char.IsLower(c));
            var hasDigit = password.Any(c => Char.IsDigit(c));
            var hasSpecialCharacter = password.Any(c => Char.IsPunctuation(c) || Char.IsSymbol(c));
            if (!hasUppercase || !hasLowercase || !hasDigit || !hasSpecialCharacter) {
                return PasswordUpdateResult.InvalidCombination();
            }

            // Check that the password is unique against the user's previous five passwords
            var passwordHistory = _passwordHistoryRepository.GetPasswordHistory(userId);
            if (passwordHistory.Any(p => p == newPassword)) {
                return PasswordUpdateResult.RepeatedPassword();
            }

            return PasswordUpdateResult.Success();
        }
    }
}']

['```
class DynamicJSONFileHandler:
    def __init__(self, file_path):
        self.file_path = file_path
        self.json_data = None
        self.factory_functions = {}

    def read_file(self):
        try:
            with open(self.file_path, 'r') as f:
                lines = [line.strip() for line in f]
                sorted_lines = sorted(lines)
                last_line = sorted_lines[-1]
                sequence_number = int(last_line.split(' ')[-1])
                self.json_data = json.loads(last_line)
        except Exception as e:
            print(f'Error reading file {self.file_path}: {e}')

    def create_new_instance(self, factory_function):
        try:
            instance = factory_function()
            return instance
        except Exception as e:
            print(f'Error creating new instance using factory function {factory_function}: {e}')

    def parse_json(self):
        try:
            json_data = self.json_data
            parsed_data = json.loads(json_data)
            return parsed_data
        except Exception as e:
            print(f'Error parsing JSON data {json_data}: {e}')

    def write_json(self, json_data):
        try:
            with open(self.file_path, 'w') as f:
                json.dump(json_data, f)
        except Exception as e:
            print(f'Error writing JSON data {json_data} to file {self.file_path}: {e}')

    def register_factory_function(self, factory_function):
        try:
            self.factory_functions[factory_function.__name__] = factory_function
        except Exception as e:
            print(f'Error registering factory function {factory_function.__name__}: {e}')

    def create_new_instance_from_json(self, json_data):
        try:
            instance = self.create_new_instance(self.factory_functions[json_data['type']])
            instance.update_from_json(json_data)
            return instance
        except Exception as e:
            print(f'Error creating new instance of type {json_data["type"]} using JSON data {json_data}: {e}')
```
Here is a sample usage of the `DynamicJSONFileHandler` class:
```
# Initialize the file handler with the path to the JSON file
file_handler = DynamicJSONFileHandler('example.json')

# Register a factory function for creating new instances of the "User" class
class User:
    def __init__(self, name):
        self.name = name

    def update_from_json(self, json_data):
        self.name = json_data['name']

file_handler.register_factory_function(User)

# Read the JSON file and parse its contents
file_handler.read_file()
parsed_data = file_handler.parse_json()

# Create a new instance of the "User" class using the parsed data
user = file_handler.create_new_instance_from_json(parsed_data)
print(user.name) # Output: John Doe

# Update the user's name and write the changes to the JSON file
user.name = 'Jane Doe'
file_handler.write_json(user.to_json())
```']

['Here is an example of a modular, scalable, and resilient C library module that manages a finite state automaton (FSA) with dynamic state lists, supporting concurrent access from multiple threads:
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define a struct to represent a state in the FSA
struct State {
    int id;
    char *name;
    struct State *next_state; // next state in the list
};

// Define a struct to represent the FSA
struct FSA {
    struct State *initial_state; // initial state of the FSA
    struct State *final_state; // final state of the FSA
    int num_states; // number of states in the FSA
};

// Define a struct to represent a thread-safe queue for managing state transitions
struct Queue {
    sem_t *semaphore; // semaphore for synchronizing access to the queue
    struct State **buffer; // buffer for storing state transitions
    int size; // size of the queue (number of elements)
    int front; // index of the first element in the queue
    int rear; // index of the last element in the queue
};

// Function to create a new FSA with the given initial and final states
struct FSA *fsa_create(int num_states, struct State *initial_state, struct State *final_state) {
    // Allocate memory for the FSA structure
    struct FSA *fsa = (struct FSA *)malloc(sizeof(struct FSA));
    if (!fsa) {
        return NULL;
    }

    // Initialize the FSA structure
    fsa->initial_state = initial_state;
    fsa->final_state = final_state;
    fsa->num_states = num_states;

    // Create a new thread-safe queue for managing state transitions
    struct Queue *queue = (struct Queue *)malloc(sizeof(struct Queue));
    if (!queue) {
        free(fsa);
        return NULL;
    }
    sem_init(&queue->semaphore, 0, 1); // initialize the semaphore to 1
    queue->buffer = (struct State **)malloc(sizeof(struct State *) * num_states);
    if (!queue->buffer) {
        free(fsa);
        free(queue);
        return NULL;
    }
    queue->size = num_states;
    queue->front = 0;
    queue->rear = 0;

    // Set the queue field of the FSA structure to point to the new queue
    fsa->queue = queue;

    return fsa;
}

// Function to destroy an FSA
void fsa_destroy(struct FSA *fsa) {
    if (!fsa) {
        return;
    }

    // Destroy the thread-safe queue for managing state transitions
    struct Queue *queue = fsa->queue;
    sem_destroy(&queue->semaphore);
    free(queue->buffer);
    free(queue);

    // Free the memory allocated for the FSA structure
    free(fsa);
}

// Function to add a state transition to the FSA
void fsa_add_transition(struct FSA *fsa, struct State *current_state, struct State *next_state) {
    if (!fsa || !current_state || !next_state) {
        return;
    }

    // Acquire the semaphore for synchronizing access to the queue
    sem_wait(&fsa->queue->semaphore);

    // Check if there is space in the queue for the new state transition
    if (fsa->queue->rear >= fsa->queue->size) {
        // If there is no space, resize the buffer to accommodate more elements
        int new_size = fsa->queue->size * 2;
        struct State **new_buffer = (struct State **)realloc(fsa->queue->buffer, sizeof(struct State *) * new_size);
        if (!new_buffer) {
            // If the reallocation fails, release the semaphore and return
            sem_post(&fsa->queue->semaphore);
            return;
        }
        fsa->queue->buffer = new_buffer;
        fsa->queue->size = new_size;
    }

    // Add the state transition to the queue
    fsa->queue->buffer[fsa->queue->rear] = next_state;
    fsa->queue->rear++;

    // Release the semaphore for synchronizing access to the queue
    sem_post(&fsa->queue->semaphore);
}

// Function to retrieve a state transition from the FSA
struct State *fsa_get_transition(struct FSA *fsa, struct State *current_state) {
    if (!fsa || !current_state) {
        return NULL;
    }

    // Acquire the semaphore for synchronizing access to the queue
    sem_wait(&fsa->queue->semaphore);

    // Check if there are any state transitions available in the queue
    if (fsa->queue->front == fsa->queue->rear) {
        // If there are no state transitions, release the semaphore and return NULL
        sem_post(&fsa->queue->semaphore);
        return NULL;
    }

    // Retrieve the next state transition from the queue
    struct State *next_state = fsa->queue->buffer[fsa->queue->front];
    fsa->queue->front++;

    // Release the semaphore for synchronizing access to the queue
    sem_post(&fsa->queue->semaphore);

    return next_state;
}

// Function to update the state of an FSA based on a given input
void fsa_update(struct FSA *fsa, struct Input *input) {
    if (!fsa || !input) {
        return;
    }

    // Acquire the semaphore for synchronizing access to the queue
    sem_wait(&fsa->queue->semaphore);

    // Check if there are any state transitions available in the queue
    if (fsa->queue->front == fsa->queue->rear) {
        // If there are no state transitions, release the semaphore and return NULL
        sem_post(&fsa->queue->semaphore);
        return;
    }

    // Update the state of the FSA based on the given input
    struct State *next_state = fsa_get_transition(fsa, fsa->current_state);
    if (next_state) {
        fsa->current_state = next_state;
    } else {
        // If there are no state transitions available, release the semaphore and return NULL
        sem_post(&fsa->queue->semaphore);
        return;
    }

    // Release the semaphore for synchronizing access to the queue
    sem_post(&fsa->queue->semaphore);
}
```

This code implements an FSA using a thread-safe queue. The `fsa_add_transition` function adds a state transition to the queue, and the `fsa_get_transition` function retrieves the next state transition from the queue. The `fsa_update` function updates the state of the FSA based on a given input.

The queue is implemented using a semaphore to synchronize access to it. This ensures that only one thread can access the queue at a time, which is necessary for the FSA to work correctly in a multithreaded environment.

Note that this code assumes that the `struct Input` and `struct State` types are defined elsewhere in the program. It also assumes that the input provided to the `fsa_update` function is valid, i.e., it represents a legal state transition for the current state of the FSA.']

