['Here is an example of how you might implement the given programming task using C++:
```
#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>

// Define the character class
class Character {
public:
  // Constructor
  Character(const std::string& name, const int id) : name_(name), id_(id) {}

  // Getter for name
  const std::string& getName() const { return name_; }

  // Getter for ID
  const int& getId() const { return id_; }

  // Setter for attack type
  void setAttackType(const std::string& attack) { attack_ = attack; }

  // Getter for attack type
  const std::string& getAttackType() const { return attack_; }

  // Setter for cooldown period
  void setCooldownPeriod(const int cooldown) { cooldown_ = cooldown; }

  // Getter for cooldown period
  const int& getCooldownPeriod() const { return cooldown_; }

private:
  std::string name_;
  int id_;
  std::string attack_;
  int cooldown_;
};

// Define the game server class
class GameServer {
public:
  // Constructor
  GameServer() : state_(GameState::IDLE) {}

  // Start the game server
  void start() {
    std::cout << "Starting game server..." << std::endl;
    while (true) {
      // Check for new connections
      if (new_connections_.empty()) {
        // If no new connections, continue loop
        continue;
      }

      // Accept new connection
      auto connection = std::make_shared<Connection>();
      new_connections_.pop();
      connections_.push(connection);

      // Notify all connected clients of the new connection
      for (auto& client : clients_) {
        client->notifyNewConnection(connection);
      }
    }
  }

  // Add a client to the game server
  void addClient(std::shared_ptr<Client> client) {
    clients_.push(client);
  }

  // Remove a client from the game server
  void removeClient(std::shared_ptr<Client> client) {
    clients_.remove(client);
  }

  // Send data to all connected clients
  void sendDataToAllClients(const std::string& data) {
    for (auto& client : clients_) {
      client->sendData(data);
    }
  }

private:
  enum class GameState { IDLE, IN_PROGRESS };

  // Vector of all connected clients
  std::vector<std::shared_ptr<Client>> clients_;

  // Queue of new connections waiting to be accepted
  std::queue<std::shared_ptr<Connection>> new_connections_;

  // Current game state
  GameState state_;
};

// Define the connection class
class Connection {
public:
  // Constructor
  Connection() : state_(ConnectionState::DISCONNECTED) {}

  // Connect to the game server
  void connect(std::shared_ptr<GameServer> game_server) {
    game_server->addClient(this);
  }

  // Disconnect from the game server
  void disconnect() {
    if (game_server_) {
      game_server_->removeClient(this);
    }
  }

  // Send data to the game server
  void sendData(const std::string& data) {
    if (!game_server_) {
      return;
    }

    game_server_->sendDataToAllClients(data);
  }

private:
  enum class ConnectionState { DISCONNECTED, CONNECTED };

  // Game server instance
  std::shared_ptr<GameServer> game_server_;
};

// Define the client class
class Client {
public:
  // Constructor
  Client() : state_(ClientState::IDLE) {}

  // Connect to the game server
  void connect(std::shared_ptr<GameServer> game_server) {
    game_server->addClient(this);
  }

  // Disconnect from the game server
  void disconnect() {
    if (game_server_) {
      game_server_->removeClient(this);
    }
  }

  // Notify all connected clients of a new connection
  void notifyNewConnection(std::shared_ptr<Connection> connection) {
    sendData("[NEW CONNECTION] " + connection->getName());
  }

  // Send data to the game server
  void sendData(const std::string& data) {
    if (!game_server_) {
      return;
    }

    game_server_->sendDataToAllClients(data);
  }

private:
  enum class ClientState { IDLE, CONNECTED };

  // Game server instance
  std::shared_ptr<GameServer> game_server_;
};

int main() {
  // Create a new game server
  auto game_server = std::make_shared<GameServer>();

  // Start the game server
  std::thread(game_server).detach();

  // Create a new connection
  auto connection = std::make_shared<Connection>();

  // Connect to the game server
  connection->connect(game_server);

  // Create a new client
  auto client = std::make_shared<Client>();

  // Connect to the game server
  client->connect(game_server);

  // Send data to the game server
  connection->sendData("Hello, world!");
}
```
This code defines a `Character` class that represents a character in the game with its unique ID and attack type. It also defines a `GameServer` class that manages all connections to the game and provides methods for sending data between clients and the server. The `Connection` class represents a connection to the game server and contains a pointer to the `GameServer` instance. Finally, the `Client` class represents a client connected to the game server and contains a pointer to the `GameServer` instance.

In this example, the `main()` function creates a new `GameServer` instance and starts it in a separate thread using `std::thread(game_server).detach()`. It then creates a new `Connection` instance and connects it to the game server using the `connect()` method. Finally, it creates a new `Client` instance and connects it to the game server using the `connect()` method.

This is just one way of implementing a multiplayer game in C++. There are many other ways to do it, and the specific implementation will depend on your needs and preferences.']

