// DynamicSecureSequenceGenerator.cs

using System;
using System.Threading.Tasks;
using System.Collections.Concurrent;

namespace SecureSequenceGenerator
{
    public class DynamicSecureSequenceGenerator
    {
        private readonly ExternalEntropyService _entropyService;
        private readonly ConcurrentDictionary<int, double> _sequenceCache;
        private readonly object _lockObject = new object();

        // Constructor to initialize the entropy service and cache
        public DynamicSecureSequenceGenerator(ExternalEntropyService entropyService)
        {
            _entropyService = entropyService;
            _sequenceCache = new ConcurrentDictionary<int, double>();
        }

        // Method to generate a sequence of unique random numbers
        public async Task<double[]> GenerateSequenceAsync(int length)
        {
            // Check if the requested length is cached
            if (_sequenceCache.ContainsKey(length))
            {
                return _sequenceCache[length];
            }

            // Retrieve entropy from the external service
            var entropy = await GetEntropyFromServiceAsync();

            // Generate a sequence of random numbers using the entropy
            var sequence = GenerateSequence(entropy, length);

            // Add the generated sequence to the cache
            _sequenceCache.TryAdd(length, sequence);

            return sequence;
        }

        // Method to retrieve entropy from the external service
        private async Task<double[]> GetEntropyFromServiceAsync()
        {
            try
            {
                var response = await _entropyService.GetEntropyAsync();
                return response.Entropy;
            }
            catch (Exception ex) when (!(ex is SecurityException))
            {
                // Log the exception and retry
                LogRetry("Error retrieving entropy from service", ex);
                return await GetEntropyFromServiceAsync();
            }
        }

        // Method to generate a sequence of random numbers using the entropy
        private double[] GenerateSequence(double[] entropy, int length)
        {
            var sequence = new double[length];
            for (var i = 0; i < length; i++)
            {
                sequence[i] = entropy[(int)(entropy.Length * _random.NextDouble())];
            }
            return sequence;
        }

        // Method to log retries and successful sequence generation
        private void LogRetry(string message, Exception ex)
        {
            var retryCount = 0;
            while (ex is AggregateException && ex.InnerException != null)
            {
                ex = ex.InnerException;
                retryCount++;
            }
            // Log the retry count and successful sequence generation rate
            Console.WriteLine($"{message} - Retry Count: {retryCount} - Success Rate: {_sequenceCache.Count / 100d}%");
        }
    }
}

