public static async Task MigrateDatabaseAsync(string sourceUrl, string targetUrl, string username, string password, List<string> excludedTables = null)
{
    if (!IsWhitelistedUrl(sourceUrl))
    {
        throw new UnauthorizedAccessException("The source URL is not whitelisted.");
    }

    if (!IsWhitelistedUrl(targetUrl))
    {
        throw new UnauthorizedAccessException("The target URL is not whitelisted.");
    }

    using (var sourceConnection = new SqlConnection(sourceUrl)
    {
        await sourceConnection.OpenAsync();
    }

    using (var targetConnection = new SqlConnection(targetUrl)
    {
        await targetConnection.OpenAsync();
    }

    var schemaFilePath = GetSchemaFilePath(sourceUrl);
    if (!File.Exists(schemaFilePath))
    {
        throw new InvalidOperationException("The schema definition file is missing.");
    }

    var schemaDefinition = File.ReadAllText(schemaFilePath);
    await targetConnection.ExecuteNonQueryAsync($"CREATE SCHEMA IF NOT EXISTS `{targetUrl}`");

    foreach (var table in GetTablesFromSchema(schemaDefinition))
    {
        if (!string.IsNullOrEmpty(excludedTables) && excludedTables.Contains(table))
        {
            continue;
        }

        await targetConnection.ExecuteNonQueryAsync($"CREATE TABLE IF NOT EXISTS `{targetUrl}.{table}`");
    }

    var migrationStartTime = DateTimeOffset.UtcNow;
    using (var dataReader = sourceConnection.ExecuteReader("SELECT * FROM [dbo].[TableName]"))
    {
        while (dataReader.Read())
        {
            await targetConnection.ExecuteNonQueryAsync($"INSERT INTO `{targetUrl}.{table}` VALUES ({dataReader["Column1"]}, {dataReader["Column2"]})");
        }
    }

    var migrationEndTime = DateTimeOffset.UtcNow;
    var totalMigrationTime = migrationEndTime - migrationStartTime;
    Log.Information($"Migration completed in {totalMigrationTime} seconds.");

    foreach (var table in GetTablesFromSchema(schemaDefinition))
    {
        if (!string.IsNullOrEmpty(excludedTables) && excludedTables.Contains(table))
        {
            continue;
        }

        await targetConnection.ExecuteNonQueryAsync($"ALTER TABLE `{targetUrl}.{table}` ADD CONSTRAINT [FK_TableName_ReferenceTable] FOREIGN KEY ([Column1]) REFERENCES [dbo].[ReferenceTable]([Column2])");
    }
}
```
