using namespace std;

struct TokenValidationResult {
  bool valid;
  string error_message;
};

class OAuth2TokenValidator {
 public:
  OAuth2TokenValidator(boost::asio::io_context& io_context) : io_context_(io_context) {}

  void validate_token(const std::string& token, const std::set<std::string>& required_fields) {
    boost::json::value json;
    try {
      json = boost::json::parse(token);
    } catch (boost::json::parse_error& e) {
      throw TokenValidationError("Invalid JSON format");
    }

    if (json.is_null()) {
      throw TokenValidationError("Empty token");
    }

    // Validate token type
    if (json["token_type"].as_string() != "Bearer") {
      throw TokenValidationError("Invalid token type");
    }

    // Validate required fields
    for (const auto& field : required_fields) {
      if (!json.is_object()) {
        throw TokenValidationError("Missing required field: " + field);
      }

      const boost::json::value& value = json[field];
      if (value.is_null()) {
        throw TokenValidationError("Missing required field: " + field);
      }
    }

    // Validate expires_in
    int64_t expires_in = json["expires_in"].as_int();
    if (expires_in < 0) {
      throw TokenValidationError("Invalid expiration time");
    }

    // Handle optional refresh_token field
    if (json.is_object() && json["refresh_token"].as_string().empty()) {
      throw TokenValidationError("Missing required field: refresh_token");
    }
  }

 private:
  boost::asio::io_context& io_context_;
};

int main(int argc, char** argv) {
  // Initialize Boost ASIO
  boost::asio::io_context io_context;

  // Create a Sandesh client
  auto sandesh_client = new SandeshClient(io_context);

  // Set up required fields and token validation result map
  std::set<std::string> required_fields{"access_token", "expires_in"};
  std::map<std::string, TokenValidationResult> token_validation_results;

  // Get tokens from external API endpoints concurrently
  boost::asio::post(io_context, [&]() {
    // Send GET requests to external API endpoints and get tokens
    std::vector<std::string> tokens = send_get_requests();

    // Validate each token concurrently
    for (const auto& token : tokens) {
      boost::asio::post(io_context, [token, &required_fields]() {
        try {
          OAuth2TokenValidator validator(io_context);
          validator.validate_token(token, required_fields);
          token_validation_results[token] = TokenValidationResult{true, ""};
        } catch (const TokenValidationError& e) {
          token_validation_results[token] = TokenValidationResult{false, e.what()};
        }
      });
    }
  });

  // Wait for all validation requests to finish
  io_context.run();

  // Print validation results
  for (const auto& result : token_validation_results) {
    std::cout << "Token: " << result.first << ", Valid: " << result.second.valid << ", Error Message: " << result.second.error_message << std::endl;
  }

  return 0;
}
```
