        {
            _logger = logger;
            _config = config;
            _redis = redis;
            _redisOptions = redisOptions;
            _analyticsService = analyticsService;
            _messageQueue = messageQueue;
        }

        public async Task<string> GenerateAuthTokenAsync(string userId)
        {
            var token = Guid.NewGuid().ToString();
            await _redis.StringSetAsync($"auth-token:{userId}", token);
            await _analyticsService.LogEventAsync("Auth Token Generated", new Dictionary<string, object> { { "UserId", userId }, { "Token", token } });
            return token;
        }

        public async Task InvalidateAuthTokenAsync(string userId)
        {
            await _redis.KeyDeleteAsync($"auth-token:{userId}");
            await _analyticsService.LogEventAsync("Auth Token Invalidated", new Dictionary<string, object> { { "UserId", userId } });
        }

        public async Task<string> ValidateAuthTokenAsync(string token)
        {
            var userId = await _redis.StringGetAsync($"auth-token:{token}");
            if (userId != null)
            {
                return userId;
            }
            else
            {
                throw new Exception("Invalid auth token.");
            }
        }

        public async Task<string> GetAuthTokenForUserAsync(string userId)
        {
            var token = await _redis.StringGetAsync($"auth-token:{userId}");
            if (token != null)
            {
                return token;
            }
            else
            {
                try
                {
                    token = await GenerateAuthTokenAsync(userId);
                    return token;
                }
                catch (Exception e)
                {
                    _logger.LogError(e, "Failed to generate auth token.");
                    throw new Exception("Failed to generate auth token.", e);
                }
            }
        }
    }
}
