            getResult(input, input_length);
            break;
        }
    }
}

// Define the functions to handle concurrent connections, using thread-safe operations when necessary
void handleConcurrentConnection(unsigned char* input, unsigned int input_length) {
    // Use a mutex to synchronize access to shared resources during concurrent connections
    if (THREAD_SAFE_OPERATIONS) {
        pthread_mutex_lock(&shared_resource_mutex);
        encrypt(input, input_length, output);
        decrypt(input, input_length, output);
        getKey(input, input_length);
        getResult(input, input_length);
        pthread_mutex_unlock(&shared_resource_mutex);
    } else {
        encrypt(input, input_length, output);
        decrypt(input, input_length, output);
        getKey(input, input_length);
        getResult(input, input_length);
    }
}

