// Define a struct for the FSA data structure
struct fsa {
    char *password;
    char *connection_title;
    void (*callback)(int, void*);
};

// Define a struct for the state list data structure
struct state_list {
    int *states;
    size_t num_states;
    int last_state;
};

// Define a function to construct a dynamic state list for an FSA
struct state_list* fsa_construct_state_list(int *states, size_t num_states, struct fsa *fsa) {
    // Validate that the password is non-empty and not NULL, the connection title is non-empty, and the callback function is not NULL
    if (fsa->password == NULL || strlen(fsa->password) == 0) {
        errno = EINVAL;
        return NULL;
    }
    if (fsa->connection_title == NULL || strlen(fsa->connection_title) == 0) {
        errno = EINVAL;
        return NULL;
    }
    if (fsa->callback == NULL) {
        errno = EINVAL;
        return NULL;
    }

    // Allocate memory for the state list
    struct state_list *state_list = malloc(sizeof(struct state_list));
    if (state_list == NULL) {
        errno = ENOMEM;
        return NULL;
    }

    // Initialize the state list fields
    state_list->states = malloc(num_states * sizeof(int));
    if (state_list->states == NULL) {
        free(state_list);
        errno = ENOMEM;
        return NULL;
    }
    state_list->num_states = num_states;
    state_list->last_state = -1;

    // Copy the states into the state list
    for (size_t i = 0; i < num_states; i++) {
        state_list->states[i] = states[i];
    }

    return state_list;
}

// Define a function to add a new state to an FSA's state list
void fsa_add_state(struct state_list *state_list, int new_state) {
    // Validate that the new state is not already in the state list
    for (size_t i = 0; i < state_list->num_states; i++) {
        if (state_list->states[i] == new_state) {
            return;
        }
    }

    // Allocate memory for the new state and copy it into the state list
    int *new_states = realloc(state_list->states, (state_list->num_states + 1) * sizeof(int));
    if (new_states == NULL) {
        return;
    }
    state_list->states = new_states;
    state_list->states[state_list->num_states] = new_state;
    state_list->num_states++;
}

// Define a function to remove a state from an FSA's state list
void fsa_remove_state(struct state_list *state_list, int old_state) {
    // Find the index of the state to be removed in the state list
    size_t i;
    for (i = 0; i < state_list->num_states; i++) {
        if (state_list->states[i] == old_state) {
            break;
        }
    }

    // If the state is not found, do nothing
    if (i == state_list->num_states) {
        return;
    }

    // Remove the state from the state list by shifting all subsequent states back one index
    for (size_t j = i + 1; j < state_list->num_states; j++) {
        state_list->states[j - 1] = state_list->states[j];
    }
    state_list->num_states--;
}
