import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Logger;

public class TenantManager {
    private static final Logger LOGGER = Logger.getLogger(TenantManager.class.getName());

    // Use a ConcurrentHashMap for storing tenant profiles
    private final ConcurrentHashMap<String, TenantProfile> tenants = new ConcurrentHashMap<>();

    // Use an ExecutorService for handling concurrent requests
    private final ExecutorService executor = Executors.newCachedThreadPool();

    public void createTenant(String tenantId) {
        if (tenants.containsKey(tenantId)) {
            LOGGER.warning("Tenant " + tenantId + " already exists");
            return;
        }
        TenantProfile profile = new TenantProfile();
        // Initialize the tenant profile with default values
        profile.setName("New Tenant");
        profile.setSubscription(null);
        tenants.put(tenantId, profile);
    }

    public void deleteTenant(String tenantId) {
        if (!tenants.containsKey(tenantId)) {
            LOGGER.warning("Tenant " + tenantId + " does not exist");
            return;
        }
        TenantProfile profile = tenants.get(tenantId);
        // Cancel any active subscriptions and remove the tenant from the map
        if (profile.getSubscription() != null) {
            profile.getSubscription().cancel();
        }
        tenants.remove(tenantId);
    }

    public void updateTenant(String tenantId, TenantProfile profile) {
        if (!tenants.containsKey(tenantId)) {
            LOGGER.warning("Tenant " + tenantId + " does not exist");
            return;
        }
        // Update the existing tenant profile with the new values
        tenants.put(tenantId, profile);
    }

    public TenantProfile getTenant(String tenantId) {
        if (!tenants.containsKey(tenantId)) {
            LOGGER.warning("Tenant " + tenantId + " does not exist");
            return null;
        }
        return tenants.get(tenantId);
    }
}

class TenantProfile {
    private String name;
    private Subscription subscription;

    // Getters and setters for name and subscription
}

class Subscription {
    private String plan;
    private Date startDate;
    private Date endDate;

    public void cancel() {
        // Cancel the subscription
    }
}
```
This code defines a `TenantManager` class that manages tenant profiles and provides methods for creating, deleting, updating, and retrieving tenants. The `createTenant` method checks if the tenant already exists and creates a new profile if it doesn't. The `deleteTenant` method cancels any active subscriptions and removes the tenant from the map if it exists. The `updateTenant` method updates an existing tenant profile with new values. The `getTenant` method returns a tenant profile if it exists, or null otherwise.

The `TenantProfile` class represents a single tenant profile, which includes the tenant's name and any active subscription. The `Subscription` class represents an active subscription for a tenant, including the plan, start date, and end date. The `cancel` method cancels the subscription by setting its end date to the current date.

The code uses a ConcurrentHashMap to store tenant profiles in memory. It also uses an ExecutorService to handle concurrent requests for managing tenants and subscriptions.']

