int filename_analysis(filename_t* filename) {
    // Determine the number of digits in the filename
    int num_digits = 0;
    for (int i = 0; i < strlen(filename->name); i++) {
        if (isdigit(filename->name[i])) {
            num_digits++;
        } else {
            break;
        }
    }

    // Determine the file type based on the number of digits
    if (num_digits > 0) {
        filename->extension = 1; // Image
    } else {
        filename->extension = 2; // Audio
    }

    return 0;
}

// Define a function to initialize a new state in the FSA for the given filename
int fsa_init(fsa_t* fsa, filename_t* filename) {
    // Allocate memory for the new state and add it to the FSA's state list
    int state_id = fsa->state_count++;
    fsa->states[state_id] = (fsa_state_t*)malloc(sizeof(fsa_state_t));
    if (!fsa->states[state_id]) {
        // Handle memory allocation failure gracefully by returning NULL
        return NULL;
    }

    // Set the new state's ID and name
    fsa->states[state_id]->id = state_id;
    strcpy(fsa->states[state_id]->name, filename->name);

    // Link the new state to the previous state using a 'next' pointer
    if (fsa->current_state) {
        fsa->states[state_id]->next = fsa->current_state;
        fsa->current_state = fsa->states[state_id];
