#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/wait.h>
#include <pthread.h>

struct profile {
    char *name;
    int age;
};

struct user_list {
    struct profile **profiles;
    size_t num_profiles;
    pthread_mutex_t mutex;
};

void add_profile(struct user_list *user_list, const char *name, int age) {
    // Validate input
    if (name == NULL || age < 0) {
        return;
    }

    // Acquire lock
    pthread_mutex_lock(&user_list->mutex);

    // Allocate memory for new profile
    struct profile *new_profile = malloc(sizeof(struct profile));
    if (new_profile == NULL) {
        perror("Failed to allocate memory for new profile");
        pthread_mutex_unlock(&user_list->mutex);
        return;
    }

    // Set profile fields
    new_profile->name = strdup(name);
    new_profile->age = age;

    // Add profile to list
    user_list->profiles = realloc(user_list->profiles, (user_list->num_profiles + 1) * sizeof(struct profile));
    if (user_list->profiles == NULL) {
        perror("Failed to allocate memory for new profile");
        pthread_mutex_unlock(&user_list->mutex);
        return;
    }
    user_list->profiles[user_list->num_profiles++] = new_profile;

    // Release lock
    pthread_mutex_unlock(&user_list->mutex);
}

void remove_profile(struct user_list *user_list, int index) {
    // Validate input
    if (index < 0 || index >= user_list->num_profiles) {
        return;
    }

    // Acquire lock
    pthread_mutex_lock(&user_list->mutex);

    // Remove profile from list
    struct profile *profile = user_list->profiles[index];
    free(profile->name);
    free(profile);
    memmove(&user_list->profiles[index], &user_list->profiles[index + 1], (user_list->num_profiles - index) * sizeof(struct profile));
    user_list->num_profiles--;

    // Release lock
    pthread_mutex_unlock(&user_list->mutex);
}

void execute_shell_command(const char *command) {
    pid_t pid = fork();
    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("Failed to execute shell command");
        exit(1);
    } else {
        int status;
        waitpid(pid, &status, 0);
    }
}
```
