```java
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import com.google.cloud.storage.Bucket;
import com.google.cloud.storage.StorageOptions;
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.serialization.StringDeserializer;

public class DataIngestionService {
  private static final String BROKER_URL = "kafka://localhost:9092";
  private static final String TOPIC_NAME = "data-ingestion";
  private static final int CONSUMER_POOL_SIZE = 5;
  private static final int PROCESSOR_POOL_SIZE = 10;
  private static final long MAX_BATCH_SIZE = 1000L;
  private static final long MAX_PROCESSING_TIME = TimeUnit.MINUTES.toMillis(5);
  private static final String STORAGE_BUCKET = "my-bucket";
  private static final String STORAGE_PATH = "data/ingestion";

  private KafkaConsumer<String, byte[]> consumer;
  private ScheduledExecutorService executor;
  private Bucket storageBucket;

  public DataIngestionService() {
    // Set up Kafka consumer with the broker URL and topic name
    consumer = new KafkaConsumer<>(getKafkaConfig());
    consumer.subscribe(Collections.singletonList(TOPIC_NAME));

    // Set up storage bucket and path for storing ingested data
    storageBucket = StorageOptions.getDefaultInstance().getService();
    storageBucket.create(STORAGE_BUCKET);
  }

  public void start() {
    executor = Executors.newScheduledThreadPool(CONSUMER_POOL_SIZE + PROCESSOR_POOL_SIZE);

    // Start consuming messages from Kafka in parallel with processing
    executor.scheduleWithFixedDelay(() -> consumer.poll(MAX_BATCH_SIZE), 0, 100, TimeUnit.MILLISECONDS);
    executor.scheduleWithFixedDelay(() -> processMessages(), 0, MAX_PROCESSING_TIME, TimeUnit.MILLISECONDS);

    // Start scheduled tasks for cleaning up data and monitoring the service
    executor.scheduleAtFixedRate(() -> {
      try {
        // Clean up old data in storage bucket
        storageBucket.deleteObjects(STORAGE_PATH, null);
      } catch (IOException e) {
        log.error("Error cleaning up old data in storage bucket", e);
      }
    }, 0, TimeUnit.DAYS.toMillis(7));
    executor.scheduleAtFixedRate(() -> {
      // Monitor the service and handle errors as needed
      try {
        if (consumer.poll(MAX_BATCH_SIZE) > 0) {
          log.info("Received new data");
        } else {
          log.warn("No new data received in last poll");
        }
      } catch (Exception e) {
        log.error("Error polling Kafka", e);
      }
    }, 0, TimeUnit.MINUTES.toMillis(5));
  }

  public void stop() {
    if (executor != null) {
      executor.shutdown();
    }
  }

  private Map<String, Object> getKafkaConfig() {
    // Set up Kafka consumer configuration with the broker URL and other options
    Map<String, Object> config = new HashMap<>();
    config.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, BROKER_URL);
    config.put(ConsumerConfig.GROUP_ID_CONFIG, "my-group");
    config.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "latest");
    return config;
  }

  private void processMessages() {
    // Process messages in parallel with storage write operations
    executor.submit(() -> {
      try {
        while (true) {
          ConsumerRecords<String, byte[]> records = consumer.poll(MAX_BATCH_SIZE);
          for (ConsumerRecord<String, byte[]> record : records) {
            // Process the message and store it in storage bucket
            try {
              storageBucket.create(STORAGE_PATH + "/" + record.key(), new ByteArrayInputStream(record.value()));
            } catch (IOException e) {
              log.error("Error storing data in storage bucket", e);
            }
          }
        }
      } catch (Exception e) {
        log.error("Error processing messages", e);
      }
    });
  }
}
```
Note that this is just a sample code, and you may need to modify it to fit your specific use case. Additionally, the above code assumes that you have already set up Kafka and Cloud Storage services, and have configured them accordingly.

