class Semaphore {
public:
    explicit Semaphore(int initial_value = 0) : value_(initial_value) {}

    // Acquire a permit from the semaphore, blocking until available
    void acquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (value_ <= 0) {
            condition_.wait(lock);
        }
        value_--;
    }

    // Release a permit to the semaphore, making it available for acquisition
    void release() {
        std::unique_lock<std::mutex> lock(mutex_);
        value_++;
        condition_.notify_all();
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;
    int value_;
};
```
