    // Open the file in binary mode
    std::ifstream inputStream(filePath, std::ios::in | std::ios::binary);

    // Check if the file is valid and can be read
    if (!inputStream.is_open()) {
        return nullptr;
    }

    try {
        // Read the state from the ObjectInputStream
        auto state = ReadFromObjectInputStream(inputStream);

        // Close the input stream
        inputStream.close();

        // Return the loaded state
        return state;
    } catch (const std::exception& e) {
        // Clean up any resources that were allocated
        inputStream.close();

        // Throw an exception with a detailed message
        throw std::runtime_error("Failed to load state from file: " + filePath);
    }
}

// Implement the method to read the state from an ObjectInputStream
std::shared_ptr<MoSTState> MoSTState::ReadFromObjectInputStream(std::ifstream& inputStream) {
    // Create a new instance of the class
    auto state = std::make_shared<MoSTState>();

    try {
        // Read the serialized data from the stream
        inputStream.read((char*)state.get(), sizeof(MoSTState));

        // Return the loaded state
        return state;
    } catch (const std::exception& e) {
        // Clean up any resources that were allocated
        state = nullptr;

        // Throw an exception with a detailed message
