    fprintf(stderr, "Error encrypting data\n");
    return -1;
  }

  // Finalize the encryption operation and get the output length
  int outLen = EVP_EncryptFinal(&ctx, dataOut + dataSize, &outLen);

  // Free the EVP_CIPHER_CTX object
  EVP_CIPHER_CTX_cleanup(&ctx);

  return outLen;
}

// Define function to decrypt data using AES-128/192/256 in GCM mode with a custom IV
int decryptData(unsigned char* dataIn, unsigned char* dataOut, int dataSize, const unsigned char* key, int cipherMode) {
