  int mode = CIPHER_MODE_AES_128 + cipherMode;
  int keySize = KEY_SIZE_AES_128 + cipherMode * 2;

  // Initialize the decryption operation using AES-128/192/256 in GCM mode with a custom IV
  if (EVP_DecryptInit(&ctx, EVP_aes_128_gcm(), key, iv) != 1) {
