    return -1;
  }

  // Decrypt the input data using AES-128/192/256 in GCM mode with a custom IV
  if (EVP_DecryptUpdate(&ctx, dataOut, &dataSize, dataIn, dataSize) != 1) {
    fprintf(stderr, "Error decrypting data\n");
    return -1;
  }

  // Finalize the decryption operation and get the output length
  int outLen = EVP_DecryptFinal(&ctx, dataOut + dataSize, &outLen);

  // Free the EVP_CIPHER_CTX object
  EVP_CIPHER_CTX_cleanup(&ctx);

  return outLen;
}
