import os
import threading
from concurrent.futures import ThreadPoolExecutor
import time

class EncryptionService:
    def __init__(self, vault_service):
        self.vault_service = vault_service

    def encrypt(self, password):
        return self.vault_service.encrypt(password)

class FileProcessor:
    def __init__(self, config_file):
        self.config_file = config_file

    def process_file(self, filepath):
        with open(filepath, "r") as f:
            content = f.read()

        replaced_content = self.replace_placeholders(content)

        return replaced_content

    def replace_placeholders(self, content):
        placeholders = [
            placeholder for placeholder in content.split("{{") if placeholder.endswith("}}")
        ]

        for placeholder in placeholders:
            key = placeholder[:-2]

            try:
                value = self.config_file[key]
            except KeyError:
                print(f"Key {key} not found in config file.")
                continue

            content = content.replace(placeholder, value)

        return content

class EncryptionTask:
    def __init__(self, filepath, config_file):
        self.filepath = filepath
        self.config_file = config_file

    def execute(self):
        try:
            with open(self.filepath, "r") as f:
                content = f.read()

            replaced_content = self.replace_placeholders(content)

            with open(self.filepath, "w") as f:
                f.write(replaced_content)
        except Exception as e:
            print(f"Failed to process file {self.filepath}: {e}")

class EncryptionProcessor:
    def __init__(self, config_file):
        self.config_file = config_file

    def process_files(self, filepaths):
        with ThreadPoolExecutor(max_workers=len(filepaths)) as executor:
            tasks = [EncryptionTask(filepath, self.config_file) for filepath in filepaths]

            results = executor.map(tasks)

            return results

    def process_directory(self, directory):
        files = os.listdir(directory)

        with ThreadPoolExecutor(max_workers=len(files)) as executor:
            tasks = [EncryptionTask(os.path.join(directory, file), self.config_file) for file in files]

            results = executor.map(tasks)

            return results

if __name__ == "__main__":
    config_file = {
        "username": "johndoe",
        "password": "secret"
    }

    vault_service = EncryptionService("https://example.com/vault")

    files = ["file1.txt", "file2.txt", "file3.txt"]

    processor = EncryptionProcessor(config_file, vault_service)

    start_time = time.perf_counter()
    results = processor.process_files(files)
    end_time = time.perf_counter()

    print("Processed files:")
    for file, result in zip(files, results):
        if result is None:
            print(f"{file}: Failed to process.")
        else:
            print(f"{file}: Processed successfully.")

    print("\nElapsed time: {end_time - start_time} seconds")
```
