// Compilation Module

use std::collections::HashMap;

pub struct Compiler {
    config: Config,
}

impl Compiler {
    pub fn new(config: &str) -> Self {
        // Parse configuration file and extract target architectures and optimization levels.
        let config = match parse_config(config) {
            Ok(c) => c,
            Err(e) => panic!("Failed to parse configuration: {}", e),
        };

        Compiler { config }
    }

    pub fn compile(&self, source_files: &[String]) -> Result<Vec<u8>, String> {
        // Resolve dependencies and parse source code.
        let deps = resolve_dependencies(source_files)?;
        let src = parse_src(source_files)?;

        // Compile source code into machine code for each target architecture.
        let mut result = HashMap::new();
        for arch in &self.config.architectures {
            let target = Arch::from_str(arch)?;
            let code = compile(&target, &deps, &src)?;
            result.insert(arch.to_string(), code);
        }

        // Optimize machine code for each optimization level.
        for level in &self.config.optimization_levels {
            optimize(&result, *level)?;
        }

        // Return compiled output as a HashMap of architecture -> binary data.
        Ok(result)
    }
}

fn parse_config(config: &str) -> Result<Config, String> {
    // Parse configuration file and extract target architectures and optimization levels.
    let config = Config::from_file(config)?;

    // Validate target architectures and optimization levels.
    for arch in &config.architectures {
        if !Arch::is_valid(arch) {
            return Err(format!("Invalid architecture: {}", arch));
        }
    }
    for level in &config.optimization_levels {
        if !OptLevel::is_valid(*level) {
            return Err(format!("Invalid optimization level: {}", level));
        }
    }

    Ok(config)
}

fn resolve_dependencies(source_files: &[String]) -> Result<HashMap<String, String>, String> {
    // Resolve dependencies for each source file.
    let mut deps = HashMap::new();
    for src in source_files {
        let dep_file = find_dep_file(src)?;
        let deps = parse_deps(&dep_file)?;
        deps.iter().for_each(|(k, v)| {
            deps.insert(k.to_string(), v.to_string());
        });
    }

    Ok(deps)
}

fn parse_src(source_files: &[String]) -> Result<HashMap<String, String>, String> {
    // Parse source code for each source file.
    let mut src = HashMap::new();
    for src in source_files {
        let code = read_file(src)?;
        src.insert(src.to_string(), code);
    }

    Ok(src)
}

fn compile(target: &Arch, deps: &HashMap<String, String>, src: &HashMap<String, String>) -> Result<Vec<u8>, String> {
    // Compile source code into machine code for the specified target architecture.
    let mut result = Vec::new();
    for (file, code) in src {
        let compiled_code = compile_code(target, &deps[file], &code)?;
        result.extend(compiled_code);
    }

    Ok(result)
}

fn optimize(machine_code: &HashMap<String, Vec<u8>>, level: OptLevel) -> Result<(), String> {
    // Optimize machine code for the specified optimization level.
    let mut optimized = HashMap::new();
    for (file, code) in machine_code {
        let opt_code = optimize_code(&code, level)?;
        optimized.insert(file.to_string(), opt_code);
    }

    Ok(())
}

fn find_dep_file(src: &str) -> Result<String, String> {
    // Find the corresponding dependency file for a source file.
    let dep_file = format!("{}.deps", src);
    if File::exists(&dep_file) {
        Ok(dep_file)
    } else {
        Err(format!("Dependency file not found: {}", dep_file))
    }
}

fn parse_deps(file: &str) -> Result<HashMap<String, String>, String> {
    // Parse the dependency file for a source file.
    let deps = HashMap::new();
    Ok(deps)
}

fn read_file(file: &str) -> Result<String, String> {
    // Read the contents of a file as a string.
    let mut file = File::open(file)?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;

    Ok(contents)
}

fn compile_code(target: &Arch, deps: &str, code: &String) -> Result<Vec<u8>, String> {
    // Compile source code into machine code for the specified target architecture.
    let mut result = Vec::new();
    for dep in deps.split(' ') {
        // Resolve dependency.
        if !File::exists(dep) {
            return Err(format!("Dependency not found: {}", dep));
        }
        let code = read_file(dep)?;
        result.extend(compile_code(&target, &code, deps)?);
    }

    Ok(result)
}

fn optimize_code(code: &Vec<u8>, level: OptLevel) -> Result<Vec<u8>, String> {
    // Optimize machine code for the specified optimization level.
    let mut optimized = Vec::new();
    for byte in code {
        if *byte == 0x00 {
            // Remove unnecessary zero-bytes.
            continue;
        }
        optimized.push(*byte);
    }

    Ok(optimized)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_deps() {
        let deps = parse_deps("foo.dep");
        assert_eq!(deps, Ok(HashMap::new()));
    }

    #[test]
    fn test_find_dep_file() {
        let dep_file = find_dep_file("foo.src");
        assert_eq!(dep_file, Ok(String::from("foo.deps")));
    }
}
