class LoadMonitor {
private:
    std::vector<RandomGenerator*> generators; // list of random generator instances
    std::mutex mutex; // synchronize access to generators vector
    uint64_t maxLoad = 10000; // maximum concurrent requests per second
public:
    LoadMonitor(std::vector<RandomGenerator*> generators) {
        this->generators = generators;
    }

    void adjustParameters() {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto generator : generators) {
            if (generator.getLoad() > maxLoad) { // load is above maximum, decrease pool size
                generator.decreasePoolSize();
            } else if (generator.getLoad() < maxLoad / 2) { // load is below half maximum, increase pool size
                generator.increasePoolSize();
            }
        }
    }
};
}

