import json
import time
from concurrent import futures
from requests import get, put, delete
from urllib3.exceptions import HTTPError
from urllib.parse import quote
from os.path import join

# Class to handle the interaction with the media asset manager
class MediaAssetManager():
    def __init__(self):
        self._base_url = "http://localhost:8080/api"
        self._headers = {
            'Content-Type': 'application/json',
        }

    # Function to create a new media asset
    def create(self, media_asset):
        url = f'{self._base_url}/media/create'
        try:
            response = put(url=url, headers=self._headers, json=media_asset)
            if response.status_code == 201:
                return json.loads(response.content)['id']
            else:
                raise Exception(f'Failed to create media asset: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to create media asset: {e}')

    # Function to retrieve a specific media asset
    def get(self, media_id):
        url = f'{self._base_url}/media/{quote(str(media_id))}'
        try:
            response = get(url=url, headers=self._headers)
            if response.status_code == 200:
                return json.loads(response.content)
            else:
                raise Exception(f'Failed to retrieve media asset {media_id}: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to retrieve media asset {media_id}: {e}')

    # Function to update a specific media asset
    def update(self, media_asset):
        url = f'{self._base_url}/media/{quote(str(media_asset["id"]))}'
        try:
            response = put(url=url, headers=self._headers, json=media_asset)
            if response.status_code == 200:
                return True
            else:
                raise Exception(f'Failed to update media asset {media_asset["id"]}: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to update media asset {media_asset["id"]}: {e}')

    # Function to delete a specific media asset
    def delete(self, media_id):
        url = f'{self._base_url}/media/{quote(str(media_id))}'
        try:
            response = delete(url=url, headers=self._headers)
            if response.status_code == 204:
                return True
            else:
                raise Exception(f'Failed to delete media asset {media_id}: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to delete media asset {media_id}: {e}')

    # Function to get all the media assets
    def list(self):
        url = f'{self._base_url}/media'
        try:
            response = get(url=url, headers=self._headers)
            if response.status_code == 200:
                return json.loads(response.content)
            else:
                raise Exception(f'Failed to retrieve media assets list: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to retrieve media assets list: {e}')

# Class to handle the ingestion, transformation, and distribution of multimedia content across diverse storage solutions and delivery platforms
class MediaIngest():
    def __init__(self):
        self._media_asset_manager = MediaAssetManager()
        self._storage_solutions = {
            'AWS S3': {'bucket_name': 'my-bucket', 'access_key': 'my-access-key', 'secret_key': 'my-secret-key'},
            'Azure Blob Storage': {'container_name': 'my-container', 'account_name': 'my-account-name', 'shared_key': 'my-shared-key'}
        }
        self._delivery_platforms = {
            'YouTube': {'api_key': 'my-api-key', 'client_id': 'my-client-id'},
            'Twitch': {'client_id': 'my-client-id', 'client_secret': 'my-client-secret'}
        }

    # Function to ingest a media asset from an external source
    def ingest(self, media_asset):
        url = f'{self._base_url}/media/ingest'
        try:
            response = put(url=url, headers=self._headers, json=media_asset)
            if response.status_code == 201:
                return json.loads(response.content)['id']
            else:
                raise Exception(f'Failed to ingest media asset: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to ingest media asset: {e}')

    # Function to transform a media asset into multiple formats for delivery
    def transform(self, media_id):
        url = f'{self._base_url}/media/{quote(str(media_id))}/transform'
        try:
            response = put(url=url, headers=self._headers)
            if response.status_code == 200:
                return True
            else:
                raise Exception(f'Failed to transform media asset {media_id}: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to transform media asset {media_id}: {e}')

    # Function to distribute a transformed media asset to delivery platforms
    def distribute(self, media_id):
        url = f'{self._base_url}/media/{quote(str(media_id))}/distribute'
        try:
            response = put(url=url, headers=self._headers)
            if response.status_code == 204:
                return True
            else:
                raise Exception(f'Failed to distribute media asset {media_id}: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to distribute media asset {media_id}: {e}')

    # Function to get the status of a distributed media asset
    def status(self, media_id):
        url = f'{self._base_url}/media/{quote(str(media_id))}/status'
        try:
            response = get(url=url, headers=self._headers)
            if response.status_code == 200:
                return json.loads(response.content)
            else:
                raise Exception(f'Failed to retrieve media asset status {media_id}: {response.text}')
        except HTTPError as e:
            raise Exception(f'Failed to retrieve media asset status {media_id}: {e}')
