import logging
from typing import Dict
from http import HTTPStatus
from urllib.parse import quote

import requests
from ratelimit import RateLimit

logger = logging.getLogger(__name__)

# OAuth providers and their API specifications
providers = {
    "google": {"api_url": "https://accounts.google.com/o/oauth2/v2/auth", "client_id": "", "client_secret": ""},
    "facebook": {"api_url": "https://www.facebook.com/dialog/oauth", "client_id": "", "client_secret": ""},
    "github": {"api_url": "https://github.com/login/oauth/authorize", "client_id": "", "client_secret": ""}
}

# Rate limiting configurations
rate_limit = RateLimit(requests, per=60, max_calls=100000)


def login(provider: str, code: str) -> Dict[str, Any]:
    """Authenticates the user with the given OAuth provider using the provided code."""
    # Set up the HTTP request headers and URL parameters for the authentication request
    url = f"{providers[provider]['api_url']}?client_id={providers[provider]['client_id']}&redirect_uri=http://localhost:8080/callback&response_type=code&scope=email%20profile&state=login"
    headers = {"Authorization": f"Basic {quote(f'{providers[provider]['client_id']}:{providers[provider]['client_secret']}')}"}

    # Send the authentication request and handle any errors
    response = requests.post(url, headers=headers, data={"code": code})
    if not response.ok:
        logger.error(f"Failed to authenticate with {provider}: {response.text}")
        return {"status": HTTPStatus.INTERNAL_SERVER_ERROR, "message": "An error occurred while authenticating."}

    # Parse the authentication response and extract the access token
    try:
        response_data = response.json()
        access_token = response_data["access_token"]
    except (KeyError, JSONDecodeError):
        logger.error(f"Invalid response from {provider}: {response.text}")
        return {"status": HTTPStatus.BAD_REQUEST, "message": "An error occurred while authenticating."}

    # Send a second request to the OAuth provider to retrieve user information
    profile_url = f"{providers[provider]['api_url']}?access_token={access_token}&fields=id,email,name"
    response = requests.get(profile_url)

    # Handle any errors while retrieving user information
    if not response.ok:
        logger.error(f"Failed to retrieve user information from {provider}: {response.text}")
        return {"status": HTTPStatus.INTERNAL_SERVER_ERROR, "message": "An error occurred while retrieving user information."}

    # Parse the user information and extract the email address and name
    try:
        response_data = response.json()
        email = response_data["email"]
        name = f"{response_data['name']['first']} {response_data['name']['last']}"
    except (KeyError, JSONDecodeError):
        logger.error(f"Invalid user information from {provider}: {response.text}")
        return {"status": HTTPStatus.BAD_REQUEST, "message": "An error occurred while retrieving user information."}

    # Return the authentication result with the extracted email address and name
    return {"email": email, "name": name, "provider": provider, "access_token": access_token}


def authenticate(code: str) -> Dict[str, Any]:
    """Authenticates the user using the given OAuth code."""
    # Iterate over all OAuth providers and try to authenticate with each one
    for provider in providers.keys():
        result = login(provider, code)

        # If authentication is successful, return the result
        if result["status"] == HTTPStatus.OK:
            logger.info(f"Authenticated user {result['email']} with {provider}")
            return result

    # If no provider was able to authenticate the user, return an error response
    logger.error("Failed to authenticate user with any OAuth provider")
    return {"status": HTTPStatus.UNAUTHORIZED, "message": "An error occurred while authenticating."}
