// API for registering a new microservice
app.post('/register', (req, res) => {
  const serviceId = req.body.id;
  const serviceUrl = req.body.url;
  if (!services[serviceId]) {
    services[serviceId] = { url: serviceUrl };
    res.status(201).send({ message: `Service ${serviceId} registered successfully.` });
  } else {
    res.status(409).send({ message: `Service ${serviceId} already registered.` });
  }
