    // Query node for points within bounding box
    std::vector<double> queryNode(const double min_x, const double min_y, const double min_z,
                                const double max_x, const double max_y, const double max_z) {
        // Check if node exists in octree
        if (m_nodes.find(point_cloud_data[0]) != m_nodes.end()) {
            // Query existing node for points within bounding box
            return queryNode(m_nodes.find(point_cloud_data[0])->second, min_x, min_y, min_z, max_x, max_y, max_z);
        } else {
            // Return empty vector if node doesn't exist in octree
            return std::vector<double>();
        }
    }

    // Update existing node with new data
    void updateNode(std::vector<double>& node, const std::vector<double>& point_cloud_data) {
        // Check if node is full and needs to be split
        if (node.size() == m_max_node_capacity) {
            // Split node into two child nodes and update them with new data
            splitNode(node, point_cloud_data);
        } else {
            // Add new data to node
            addDataToNode(node, point_cloud_data);
        }
    }

    // Query existing node for points within bounding box
    std::vector<double> queryNode(std::vector<double>& node, const double min_x, const double min_y, const double min_z,
                                const double max_x, const double max_y, const double max_z) {
        // Check if node is within bounding box
        if (isNodeWithinBoundingBox(node, min_x, min_y, min_z, max_x, max_y, max_z)) {
            // Return points in node that are within bounding box
            return queryPointsInNode(node, min_x, min_y, min_z, max_x, max_y, max_z);
        } else {
            // Return empty vector if node is not within bounding box
            return std::vector<double>();
        }
    }

    // Check if node is within a given spatial and temporal bounding box
    bool isNodeWithinBoundingBox(const std::vector<double>& node, const double min_x, const double min_y, const double min_z,
                                const double max_x, const double max_y, const double max_z) {
        // Check if node's minimum coordinates are within bounding box
        if (node[0] < min_x || node[1] < min_y || node[2] < min_z) {
            return false;
        }

        // Check if node's maximum coordinates are within bounding box
        if (node[3] > max_x || node[4] > max_y || node[5] > max_z) {
            return false;
        }

        // If all conditions are met, node is within bounding box
        return true;
    }

    // Add new data to a given node
    void addDataToNode(std::vector<double>& node, const std::vector<double>& point_cloud_data) {
        // Add new data to node's point cloud vector
        for (size_t i = 0; i < m_feature_size; ++i) {
            node.push_back(point_cloud_data[i]);
        }
    }

    // Split existing node into two child nodes and update them with new data
    void splitNode(std::vector<double>& node, const std::vector<double>& point_cloud_data) {
        // Create new node with half the size of the parent node
        std::vector<double> new_node = node;
        new_node.resize(m_max_node_capacity / 2);

        // Split node's point cloud vector into two vectors, one for each child node
        std::vector<double> left_child_data = node;
        std::vector<double> right_child_data = node;
        left_child_data.erase(left_child_data.begin() + (m_max_node_capacity / 2), left_child_data.end());
        right_child_data.erase(right_child_data.begin(), right_child_data.begin() + (m_max_node_capacity / 2));

        // Update new node with data from parent node's left child
        updateNode(new_node, left_child_data);

        // Add new node to octree and update its minimum coordinates to reflect its position in the octree
        int new_node_id = m_nodes.size();
        m_nodes[new_node_id] = new_node;
        new_node[0] = node[0] + (m_max_node_capacity / 2) * (m_max_node_capacity / 2);
        new_node[1] = node[1] + (m_max_node_capacity / 2) * (m_max_node_capacity / 2);
        new_node[2] = node[2] + (m_max_node_capacity / 2) * (m_max_node_capacity / 2);
        new_node[3] = new_node[0] + m_max_node_capacity;
        new_node[4] = new_node[1] + m_max_node_capacity;
        new_node[5] = new_node[2] + m_max_node_capacity;

        // Update parent node with data from parent node's right child
        updateNode(node, right_child_data);
    }

    // Return points in a given node that are within a given spatial and temporal bounding box
    std::vector<double> queryPointsInNode(const std::vector<double>& node, const double min_x, const double min_y, const double min_z,
                                const double max_x, const double max_y, const double max_z) {
        // Initialize empty vector to store points within bounding box
        std::vector<double> points_within_box;

        // Iterate over node's point cloud vector and check if each point is within the bounding box
        for (size_t i = 0; i < m_feature_size; ++i) {
            if (isPointWithinBoundingBox(node[i], min_x, min_y, min_z, max_x, max_y, max_z)) {
                // Add point to vector of points within bounding box
                points_within_box.push_back(node[i]);
            }
        }

        return points_within_box;
    }

    // Check if a given point is within a given spatial and temporal bounding box
    bool isPointWithinBoundingBox(const std::vector<double>& point, const double min_x, const double min_y, const double min_z,
                                const double max_x, const double max_y, const double max_z) {
        // Check if point's minimum coordinates are within bounding box
        if (point[0] < min_x || point[1] < min_y || point[2] < min_z) {
            return false;
        }

        // Check if point's maximum coordinates are within bounding box
        if (point[3] > max_x || point[4] > max_y || point[5] > max_z) {
            return false;
        }

        // If all conditions are met, point is within bounding box
        return true;
    }
};
