using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Linq;
using System.Net.Http;
using Newtonsoft.Json.Linq;

namespace DynamicStreamingDataProcessor
{
    public class DataSourceConnection
    {
        private readonly string _name;
        private readonly string _url;
        private readonly HttpClient _client;

        public DataSourceConnection(string name, string url)
        {
            _name = name;
            _url = url;
            _client = new HttpClient();
        }

        public async Task<JObject> GetData()
        {
            try
            {
                var response = await _client.GetAsync(_url);
                return JObject.Parse(await response.Content.ReadAsStringAsync());
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error while fetching data from {_name}: {e}");
                return null;
            }
        }
    }

    public class DataProcessor
    {
        private readonly List<DataSourceConnection> _dataSources;
        private readonly List<Func<JObject, JObject>> _processors;
        private readonly IOutput _output;

        public DataProcessor(IEnumerable<DataSourceConnection> dataSources, IEnumerable<Func<JObject, JObject>> processors, IOutput output)
        {
            _dataSources = new List<DataSourceConnection>(dataSources);
            _processors = new List<Func<JObject, JObject>>(processors);
            _output = output;
        }

        public async Task ProcessData()
        {
            var data = await FetchAndProcessData();
            if (data != null)
            {
                await _output.Write(data);
            }
        }

        private async Task<JObject> FetchAndProcessData()
        {
            JObject data = null;
            foreach (var source in _dataSources)
            {
                var sourceData = await source.GetData();
                if (sourceData != null)
                {
                    data = ProcessData(sourceData);
                }
            }
            return data;
        }

        private JObject ProcessData(JObject data)
        {
            foreach (var processor in _processors)
            {
                data = processor(data);
            }
            return data;
        }
    }

    public interface IOutput
    {
        Task Write(JObject data);
    }

    public class ConsoleOutput : IOutput
    {
        public async Task Write(JObject data)
        {
            Console.WriteLine($"Data received: {data}");
        }
    }
}
