Here is a sample Node.js microservice for managing a configuration file for a legacy enterprise application:
```
const fs = require('fs');
const crypto = require('crypto');
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);
const writeFileAsync = promisify(fs.writeFile);

// Define the configuration file path and name
const configPath = '/path/to/config/file';
const configName = 'configuration.json';

// Define a function to generate a random password
function generatePassword() {
  const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890';
  let password = '';
  for (let i = 0; i < 10; i++) {
    password += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return password;
}

// Define a function to update the configuration file with a generated password
function updateConfigFile(password) {
  const config = {
    // Add any additional configuration options here
    password: password,
  };
  fs.writeFileSync(configPath + configName, JSON.stringify(config));
}

// Define a function to read the configuration file and return the generated password
function getConfig() {
  const config = fs.readFileSync(configPath + configName);
  return JSON.parse(config).password;
}

// Define a function to handle incoming requests with JSON parameters
app.post('/update-config', async (req, res) => {
  try {
    // Generate a random password if one is not provided in the request body
    const password = req.body.password || generatePassword();

    // Update the configuration file with the generated password
    updateConfigFile(password);

    // Return the updated configuration
    res.json({ config: getConfig() });
  } catch (err) {
    console.error(err);
    res.status(500).send('Error updating configuration');
  }
});
```
