    const EVP_CIPHER *decAlgorithm = EVP_aes_128_cbc();

    // Generate a random initialization vector for encryption and decryption
    unsigned char iv[16];
    RAND_bytes(iv, sizeof(iv));

    // Set the key size for the encryption and decryption algorithms
    int encKeySize = EVP_CIPHER_key_length(encAlgorithm);
    int decKeySize = EVP_CIPHER_key_length(decAlgorithm);

    // Generate a random number between two integers for the key size
    int keySize = rand_between(encKeySize, decKeySize);

    // Set the key length for the encryption and decryption algorithms
    EVP_CIPHER_CTX *encCtx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(encCtx, encAlgorithm, NULL, keySize);
    EVP_CIPHER_CTX *decCtx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(decCtx, decAlgorithm, NULL, keySize);

    // Set the initialization vector for the encryption and decryption algorithms
    EVP_CIPHER_CTX_ctrl(encCtx, EVP_CTRL_GCM_SET_IVLEN, sizeof(iv), NULL);
    EVP_EncryptInit_ex(encCtx, encAlgorithm, NULL, keySize, iv, NULL);

    EVP_CIPHER_CTX_ctrl(decCtx, EVP_CTRL_GCM_SET_IVLEN, sizeof(iv), NULL);
    EVP_DecryptInit_ex(decCtx, decAlgorithm, NULL, keySize, iv, NULL);

    // Set the encryption and decryption keys
    unsigned char encKey[keySize];
    unsigned char decKey[keySize];
    RAND_bytes(encKey, keySize);
    RAND_bytes(decKey, keySize);

    EVP_EncryptUpdate(encCtx, NULL, &len, encKey, keySize);
    EVP_DecryptUpdate(decCtx, NULL, &len, decKey, keySize);

    // Set the encryption and decryption data
    unsigned char encData[1024];
    unsigned char decData[1024];
    RAND_bytes(encData, 1024);

    // Encrypt the data using the encryption algorithm
    int len = EVP_EncryptUpdate(encCtx, encData, sizeof(encData), encKey, keySize);

    // Decrypt the data using the decryption algorithm
    len = EVP_DecryptUpdate(decCtx, decData, sizeof(decData), decKey, keySize);

    // Print the encrypted and decrypted data
    printf("Encrypted data: ");
    for (int i = 0; i < len; i++) {
        printf("%d ", encData[i]);
    }
    printf("\n");

    printf("Decrypted data: ");
    for (int i = 0; i < len; i++) {
        printf("%d ", decData[i]);
    }
    printf("\n");

    return 0;
}
