```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <getopt.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <curl/curl.h>

#define BUFFER_SIZE 1024
#define MAX_FILENAME_LEN 256
#define MAX_WORD_COUNT 100000
#define MAX_UNIQUE_WORDS 10000

// Global variables
char* input_files[MAX_FILENAME_LEN];
int num_input_files = 0;
int case_sensitive = 0;
char* output_file = NULL;
int word_count = 0;
int unique_word_count = 0;
char* unique_words[MAX_UNIQUE_WORDS];

// Function to parse command-line arguments
void parse_args(int argc, char* argv[]) {
    int c;
    while ((c = getopt(argc, argv, "i:o:c")) != -1) {
        switch (c) {
            case 'i':
                if (num_input_files >= MAX_FILENAME_LEN) {
                    fprintf(stderr, "Too many input files\n");
                    exit(EXIT_FAILURE);
                }
                strcpy(input_files[num_input_files++], optarg);
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'c':
                case_sensitive = 1;
                break;
            default:
                fprintf(stderr, "Invalid option\n");
                exit(EXIT_FAILURE);
        }
    }
}

// Function to read input files and count words
void count_words() {
    for (int i = 0; i < num_input_files; ++i) {
        FILE* fp = fopen(input_files[i], "r");
        if (!fp) {
            perror("Error opening input file");
            continue;
        }
        char buffer[BUFFER_SIZE];
        while (fgets(buffer, BUFFER_SIZE, fp)) {
            // Remove newline character and trim whitespace from end of line
            int len = strlen(buffer);
            if (buffer[len - 1] == '\n') buffer[len - 1] = '\0';
            char* token;
            for (token = strtok(buffer, " \t\n"); token != NULL; token = strtok(NULL, " \t\n")) {
                if (!case_sensitive) {
                    // Convert token to lowercase
                    for (int j = 0; j < len; ++j) {
                        if ('A' <= token[j] && token[j] <= 'Z') {
                            token[j] += 'a' - 'A';
                        }
                    }
                }
                // Check if word is already in unique_words array
                int found = 0;
                for (int j = 0; j < unique_word_count; ++j) {
                    if (!strcmp(token, unique_words[j])) {
                        found = 1;
                        break;
                    }
                }
                // If not already in array, add it
                if (!found) {
                    strcpy(unique_words[unique_word_count++], token);
                }
            }
        }
        fclose(fp);
    }
}

// Function to print results
void print_results() {
    printf("Word count: %d\n", word_count);
    if (case_sensitive) {
        printf("Unique words: ");
        for (int i = 0; i < unique_word_count; ++i) {
            printf("%s ", unique_words[i]);
        }
        printf("\n");
    } else {
        printf("Unique words (lowercase): ");
        for (int i = 0; i < unique_word_count; ++i) {
            char* token = strdup(unique_words[i]);
            for (int j = 0; j < strlen(token); ++j) {
                if ('A' <= token[j] && token[j] <= 'Z') {
                    token[j] += 'a' - 'A';
                }
            }
            printf("%s ", token);
        }
        printf("\n");
    }
}

int main(int argc, char* argv[]) {
    // Parse command-line arguments
    parse_args(argc, argv);
    // Count words in input files
    count_words();
    // Print results
    print_results();
    return 0;
}
```
This implementation uses a fixed-size buffer to read lines from the input files and split them into tokens using `strtok`. It then maintains a running count of the number of words and unique words, and stores all unique words in an array for later printing. It also provides options for case sensitivity and custom output file names.

The `curl` library is used to retrieve input files from remote APIs, but it is only included in this implementation as an example of how to handle network failures and authentication issues. In a real-world scenario, you would likely use a more robust networking library like `libcurl` or `libnet`.

The trade-offs for this implementation are:

* Memory usage can become an issue with very large input files or high word counts. This is because the entire input file must be read into memory to count words, and a large array is used to store all unique words. To address this issue, you could use a streaming approach instead of reading the entire input file into memory at once.
* The tool assumes that each input file contains only one stream of words. If multiple streams are present in an input file, they will be concatenated together when counting words. This may lead to unexpected results if the streams are not properly separated by newline characters. To address this issue, you could add a separate option for handling multiple streams.
* The tool does not provide any mechanism for error handling or recovery in case of network failures or other issues during input file processing. You could add a retry mechanism with exponential backoff to handle transient errors more robustly.
* The tool assumes that the output file name is specified by the user and is used as-is without any validation or sanitization. You could add checks for validity and sanitize the input before using it in file operations.']

