// Define a function to retrieve the current time from an external time service
time_t getCurrentTime() {
    // Round-robin strategy for selecting the external time service
    static int next_service = 0;

    // Select the next available service and try to retrieve the current time
    for (int i = 0; i < 2; i++) {
        char *service = (next_service + i) % 2 == 0 ? TIME_SERVICE1 : TIME_SERVICE2;
        int sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            syslog(LOG_ERR, "Failed to create a socket");
            continue;
        }

        struct hostent *hostinfo = gethostbyname(service);
        if (!hostinfo) {
            syslog(LOG_ERR, "Failed to resolve hostname");
            close(sockfd);
            continue;
        }

        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(struct sockaddr_in));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(13); // NTP port
        server_addr.sin_addr.s_addr = *((unsigned long*)hostinfo->h_addr);

        if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(struct sockaddr)) < 0) {
            syslog(LOG_ERR, "Failed to connect to the time service");
            close(sockfd);
            continue;
        }

        char buffer[128];
        if (recv(sockfd, buffer, 128, 0) < 0) {
            syslog(LOG_ERR, "Failed to receive data from the time service");
            close(sockfd);
            continue;
        }

        char *time_str = strtok(buffer, "\n");
        if (!time_str) {
            syslog(LOG_ERR, "Failed to parse received data");
            close(sockfd);
            continue;
        }

        long seconds = atol(time_str);
        time_t current_time = seconds;

        close(sockfd);
        return current_time;
    }

    // All attempts to retrieve the current time failed, so return 0
    return 0;
}

