@RestController
public class BillingService {
  @Autowired
  private BillingRepository repository;

  // Handle incoming transaction requests from SaaS platform
  @PostMapping("/transactions")
  public ResponseEntity<String> handleTransaction(@RequestBody TransactionRequest request) {
    // Validate the request and extract relevant information
    String tenantId = request.getTenantId();
    BigDecimal amount = request.getAmount();

    // Check if the transaction is within the allowed limit for the tenant
    if (amount > getRemainingBalance(tenantId)) {
      return ResponseEntity.status(HttpStatus.FORBIDDEN).body("Transaction exceeds allowable amount");
    }

    // Initiate asynchronous payment processing
    CompletableFuture<Void> future = CompletableFuture.runAsync(() -> {
      // Use a distributed caching layer to cache subscription details for improved performance and reduced database load
      Subscription subscription = repository.getSubscription(tenantId);

      // Implement a batch processing engine to handle transaction requests with support for retries and error recovery
      List<Transaction> transactions = new ArrayList<>();
      try {
        transactions.add(new Transaction(tenantId, amount));

        // Use an asynchronous messaging system (e.g., RabbitMQ, Kinesis) to process transactions in parallel
        sendTransactionsToQueue(transactions);

        // Update the subscription details and cache them for improved performance
        repository.updateSubscription(subscription.getId(), new BigDecimal(subscription.getBalance().add(amount)));
      } catch (Exception e) {
        // Handle transaction failures and retry as needed, ensuring no transactions are lost due to transient failures
        if (e instanceof TransactionFailedException) {
          RetryableTransaction tx = new RetryableTransaction(tenantId, amount);

          // Use a backpressure mechanism to prevent the system from being overwhelmed during peak loads
          if (tx.canRetry()) {
            transactionQueue.put(tx);
          } else {
            e.printStackTrace();
          }
        } else {
          throw new RuntimeException("Transaction failed", e);
        }
      }
    });

    // Return a response indicating the transaction is being processed asynchronously
    return ResponseEntity.accepted().body("Transaction processing in progress");
  }

  // Define a distributed caching layer to cache frequently accessed subscription details
  @Cacheable(value = "subscriptionDetails", key = "#tenantId")
