    // Implement a backpressure mechanism to prevent the system from being overwhelmed during peak loads
    if (transactions.size() >= transactionQueue.remainingCapacity()) {
      return;
    }

    for (Transaction tx : transactions) {
      try {
        processTransaction(tx);
      } catch (Exception e) {
        // Handle transaction failures and retry as needed, ensuring no transactions are lost due to transient failures
        if (e instanceof TransactionFailedException) {
          RetryableTransaction tx = new RetryableTransaction(tx.getTenantId(), tx.getAmount());

          // Use a backpressure mechanism to prevent the system from being overwhelmed during peak loads
          if (tx.canRetry()) {
