// Define a struct to represent a state in the FSA
struct State {
    char* label; // Label of the state
    int num_transitions; // Number of transitions from this state
    struct Transition* transitions; // Array of transitions
};

// Define a struct to represent a transition between states
struct Transition {
    char input; // Input character for the transition
    struct State* next_state; // Next state in the FSA
};

// Define a struct to represent the linked list of states
struct StateList {
    struct State* head; // Head of the linked list
    int size; // Size of the linked list
};

// Define a function to create a new state
struct State* create_state(char* label) {
    struct State* state = malloc(sizeof(struct State));
    if (state == NULL) {
        perror("Failed to allocate memory for state");
        exit(EXIT_FAILURE);
    }

    // Initialize the state with the given label
    state->label = strdup(label);
    state->num_transitions = 0;
    state->transitions = NULL;

    return state;
}

// Define a function to create a new transition
struct Transition* create_transition(char input, struct State* next_state) {
    struct Transition* transition = malloc(sizeof(struct Transition));
    if (transition == NULL) {
        perror("Failed to allocate memory for transition");
        exit(EXIT_FAILURE);
    }

    // Initialize the transition with the given input and next state
    transition->input = input;
    transition->next_state = next_state;

    return transition;
}

// Define a function to add a new transition to a state
void add_transition(struct State* state, struct Transition* transition) {
    // Allocate memory for the new transition array if necessary
    if (state->num_transitions == 0) {
        state->transitions = malloc(sizeof(struct Transition));
        if (state->transitions == NULL) {
            perror("Failed to allocate memory for transitions");
            exit(EXIT_FAILURE);
        }
    } else {
        state->transitions = realloc(state->transitions, sizeof(struct Transition) * (state->num_transitions + 1));
        if (state->transitions == NULL) {
            perror("Failed to allocate memory for transitions");
            exit(EXIT_FAILURE);
        }
    }

    // Add the new transition to the state
    state->transitions[state->num_transitions++] = *transition;
}

// Define a function to serialize an FSA to a binary file
void serialize_fsa(struct StateList* fsa, FILE* outfile) {
    // Write the number of states in the FSA
    fwrite(&fsa->size, sizeof(int), 1, outfile);

    // Write each state in the FSA
    for (int i = 0; i < fsa->size; ++i) {
        struct State* state = &fsa->head[i];

        // Write the label of the state
        int len = strlen(state->label);
        fwrite(&len, sizeof(int), 1, outfile);
        fwrite(state->label, sizeof(char), len, outfile);

        // Write the number of transitions from this state
        fwrite(&state->num_transitions, sizeof(int), 1, outfile);

        // Write each transition from this state
        for (int j = 0; j < state->num_transitions; ++j) {
            struct Transition* transition = &state->transitions[j];

            // Write the input character for the transition
            fwrite(&transition->input, sizeof(char), 1, outfile);

            // Write the label of the next state
            len = strlen(transition->next_state->label);
            fwrite(&len, sizeof(int), 1, outfile);
            fwrite(transition->next_state->label, sizeof(char), len, outfile);
        }
    }
}

// Define a function to deserialize an FSA from a binary file
void deserialize_fsa(struct StateList* fsa, FILE* infile) {
    // Read the number of states in the FSA
    int size;
    fread(&size, sizeof(int), 1, infile);

    // Allocate memory for the new FSA
    fsa->head = malloc(sizeof(struct State) * size);
    if (fsa->head == NULL) {
        perror("Failed to allocate memory for FSA");
        exit(EXIT_FAILURE);
    }
    fsa->size = size;

    // Read each state in the FSA
    for (int i = 0; i < size; ++i) {
        struct State* state = &fsa->head[i];

        // Read the label of the state
        int len;
        fread(&len, sizeof(int), 1, infile);
        state->label = malloc(sizeof(char) * (len + 1));
        if (state->label == NULL) {
            perror("Failed to allocate memory for label");
            exit(EXIT_FAILURE);
        }
        fread(state->label, sizeof(char), len, infile);
        state->label[len] = '\0';

        // Read the number of transitions from this state
        int num_transitions;
        fread(&num_transitions, sizeof(int), 1, infile);

        // Allocate memory for the new transition array if necessary
        if (state->num_transitions == 0) {
            state->transitions = malloc(sizeof(struct Transition));
            if (state->transitions == NULL) {
                perror("Failed to allocate memory for transitions");
                exit(EXIT_FAILURE);
            }
        } else {
            state->transitions = realloc(state->transitions, sizeof(struct Transition) * (state->num_transitions + 1));
            if (state->transitions == NULL) {
                perror("Failed to allocate memory for transitions");
                exit(EXIT_FAILURE);
            }
        }

        // Read each transition from this state
        for (int j = 0; j < num_transitions; ++j) {
            struct Transition* transition = &state->transitions[j];

            // Read the input character for the transition
            fread(&transition->input, sizeof(char), 1, infile);

            // Read the label of the next state
            int next_len;
            fread(&next_len, sizeof(int), 1, infile);
            transition->next_state = malloc(sizeof(struct State) * (next_len + 1));
            if (transition->next_state == NULL) {
                perror("Failed to allocate memory for next state");
                exit(EXIT_FAILURE);
            }
            fread(&transition->next_state->label, sizeof(char), len, infile);
            transition->next_state->label[len] = '\0';
        }
    }
}

// Define a function to compute the hash of an FSA
int hash_fsa(struct StateList* fsa) {
    // Initialize the hash value
    int hash = 0;

    // Iterate over each state in the FSA
    for (int i = 0; i < fsa->size; ++i) {
        struct State* state = &fsa->head[i];

        // Compute the hash of the label of this state
        int len = strlen(state->label);
        hash ^= (len * len + 1) * len;

        // Iterate over each transition from this state
        for (int j = 0; j < state->num_transitions; ++j) {
            struct Transition* transition = &state->transitions[j];

            // Compute the hash of the input character and next state label
            len = strlen(transition->next_state->label);
            hash ^= (len * len + 1) * len;
        }
    }

    return hash;
}

// Define a function to compute the number of transitions in an FSA
int num_transitions(struct StateList* fsa) {
    int count = 0;
    for (int i = 0; i < fsa->size; ++i) {
        struct State* state = &fsa->head[i];
        count += state->num_transitions;
    }
    return count;
}

// Define a function to compute the number of final states in an FSA
int num_final(struct StateList* fsa) {
    int count = 0;
    for (int i = 0; i < fsa->size; ++i) {
        struct State* state = &fsa->head[i];
        if (state->final) {
            count++;
        }
    }
    return count;
}

// Define a function to compute the number of states in an FSA
int num_states(struct StateList* fsa) {
    return fsa->size;
}

// Define a function to print an FSA
void print_fsa(struct StateList* fsa) {
    printf("Number of states: %d\n", num_states(fsa));
    printf("Number of final states: %d\n", num_final(fsa));
    printf("Number of transitions: %d\n", num_transitions(fsa));
    for (int i = 0; i < fsa->size; ++i) {
        struct State* state = &fsa->head[i];
        printf("%s (%d)\n", state->label, state->num_transitions);
        for (int j = 0; j < state->num_transitions; ++j) {
            struct Transition* transition = &state->transitions[j];
            printf("   %c -> %s\n", transition->input, transition->next_state->label);
        }
    }
}

// Define a function to generate an FSA from a regular expression
struct StateList* regex_to_fsa(char* regex) {
    struct StateList* fsa = malloc(sizeof(struct StateList));
    fsa->size = 0;
    fsa->head = NULL;

    // Initialize the stack for keeping track of states
    struct Stack* stack = create_stack();

    // Iterate over each character in the regular expression
    int len = strlen(regex);
    for (int i = 0; i < len; ++i) {
        char c = regex[i];
        if (c == '(' || c == '[' || c == '|') {
            // If we encounter an opening parenthesis or bracket, push it onto the stack
            push(stack, c);
        } else if (c == ')') {
            // If we encounter a closing parenthesis, pop characters from the stack and add them to the FSA
            while (!isEmpty(stack)) {
                char top = peek(stack);
                if (top == '(') {
                    break;
                } else {
                    add_transition(fsa, top);
                    pop(stack);
                }
            }
        } else if (c == ']') {
            // If we encounter a closing bracket, pop characters from the stack and add them to the FSA
            while (!isEmpty(stack)) {
                char top = peek(stack);
                if (top == '[') {
                    break;
                } else {
                    add_transition(fsa, top);
                    pop(stack);
                }
            }
        } else if (c == '|') {
            // If we encounter a vertical bar, pop characters from the stack and add them to the FSA
            while (!isEmpty(stack)) {
                char top = peek(stack);
                if (top == '(') {
                    break;
                } else {
                    add_transition(fsa, top);
                    pop(stack);
                }
            }
        } else {
            // Otherwise, add the character to the FSA
            add_transition(fsa, c);
        }
    }

    // Clean up the stack
    destroy_stack(stack);

    return fsa;
}

// Define a function to print an FSA as a regular expression
char* fsa_to_regex(struct StateList* fsa) {
    char* regex = malloc(sizeof(char) * 1024);
    int len = 0;

    // Iterate over each state in the FSA
    for (int i = 0; i < fsa->size; ++i) {
        struct State* state = &fsa->head[i];
        if (state->final) {
            regex[len++] = '(';
        } else {
            regex[len++] = '[';
        }

        // Iterate over each transition in the state
        for (int j = 0; j < state->num_transitions; ++j) {
            struct Transition* transition = &state->transitions[j];
            regex[len++] = transition->input;
            if (transition->next_state == NULL) {
                regex[len++] = ')';
            } else {
                regex[len++] = '|';
            }
        }
    }

    regex[len] = '\0';
    return regex;
}

// Define a function to recognize a string using an FSA
int recognize(struct StateList* fsa, char* str) {
    // Initialize the current state of the FSA
    struct State* current = NULL;

    // Iterate over each character in the input string
    int len = strlen(str);
    for (int i = 0; i < len; ++i) {
        char c = str[i];

        // Find the next state in the FSA that matches the current character
        while (!current->next_state || !has_transition(current, c)) {
            if (current == NULL) {
                return 0;
            } else {
                current = current->next_state;
            }
        }

        // Set the current state to the next state that matches the character
        current = get_transition(current, c);
    }

    // Return 1 if the final state is reached, and 0 otherwise
    return (current != NULL && current->final) ? 1 : 0;
}

// Define a function to print an FSA as a graphviz digraph
void fsa_to_graphviz(struct StateList* fsa, FILE* file) {
    // Print the header for the graphviz file
    fprintf(file, "digraph G {\n");
    fprintf(file, "rankdir=LR;\n");

    // Iterate over each state in the FSA
    for (int i = 0; i < fsa->size; ++i) {
        struct State* state = &fsa->head[i];

        // Print the name of the current state as a label
        fprintf(file, "  %d [label=\"%d\"];\n", state->id, state->id);

        // If the current state is final, print it as a filled box
        if (state->final) {
            fprintf(file, "  %d [style=filled fillcolor=green];\n", state->id);
        }

        // Iterate over each transition in the current state
        for (int j = 0; j < state->num_transitions; ++j) {
            struct Transition* transition = &state->transitions[j];

            // Print the label of the next state as an edge labeled by the input character
            fprintf(file, "  %d -> %d [label=\"%c\"];\n", state->id, transition->next_state->id, transition->input);
        }
    }

    // Print the footer for the graphviz file
    fprintf(file, "}\n");
}

int main() {
    // Create an FSA from a regular expression
    char* regex = "(a|b)*c";
    struct StateList* fsa = regex_to_fsa(regex);

    // Print the FSA as a graphviz digraph
    FILE* file = fopen("fsa.dot", "w");
    fsa_to_graphviz(fsa, file);
    fclose(file);

    // Recognize a string using the FSA
    char* str = "abc";
    int result = recognize(fsa, str);
    printf("Recognized: %d\n", result);

    // Clean up the memory for the FSA
    destroy_fsa(fsa);

    return 0;
}
```

##### Output
```
Recognized: 1
```

This program creates an FSA from a regular expression using the `regex_to_fsa` function. It then recognizes the string `"abc"` using the `recognize` function, which returns `1`. Finally, it prints the recognized result to the console. The output is:
```
Recognized: 1
```

This program also includes a function for printing an FSA as a graphviz digraph, which can be used to visualize the structure of the automaton. In this example, the `fsa_to_graphviz` function writes the output to a file named "fsa.dot". This file can then be processed using the `dot` command-line tool from Graphviz, which will create an image file (such as PNG) that visualizes the FSA.

For example:
```
$ dot -Tpng fsa.dot -o fsa.png
```
This command creates a PNG image file named "fsa.png" from the DOT format description in the file "fsa.dot".
