bool upsertUserProfile(sqlite3 *db, UserProfile *profile) {
    // Prepare the SQL query for inserting/updating a user profile
    char *query = "INSERT INTO users (name, email, password) VALUES (?, ?, ?) ON CONFLICT (email) DO UPDATE SET name = excluded.name, password = excluded.password";

    // Bind the values for the query parameters
    sqlite3_bind_text(query, 1, profile->name);
    sqlite3_bind_text(query, 2, profile->email);
    sqlite3_bind_text(query, 3, profile->password);

    // Execute the query and check for errors
    int result = sqlite3_exec(db, query, NULL, NULL, &error);
    if (result != SQLITE_OK) {
        return false;
    }

    return true;
}

