    if (mq == -1) {
        return false;
    }

    // Encode the user profile data as a JSON object and pack it into an event message
    char *json = encodeUserProfile(profile);
    size_t jsonSize = strlen(json);

    mq_send(mq, json, jsonSize, 0);

    return true;
}

