#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

// Command line arguments structure
struct args {
    char *input_file; // Input file path
    char *output_file; // Output file path
    int count_only; // Flag for counting lines only
};

// Error codes
#define FILE_NOT_FOUND 1
#define INVALID_ARGUMENTS 2
#define IO_ERROR 3
#define THIRD_PARTY_API_ERROR 4

// File types supported by the library
enum file_type {
    TXT,
    CSV,
    JSON,
};

// File information structure
struct file {
    char *path; // Path to the file
    int fd; // File descriptor
    enum file_type type; // Type of the file (txt, csv, json)
    semaphore_t lock; // Lock for concurrent access to the file
};

// Initialize the library with command line arguments
void init(struct args *args) {
    if (args->input_file == NULL || args->output_file == NULL) {
        fprintf(stderr, "Error: Invalid arguments provided\n");
        exit(INVALID_ARGUMENTS);
    }
}

// Count the number of lines in a file
int count_lines(struct file *file) {
    char buffer[1024];
    int line_count = 0;

    while (read(file->fd, buffer, sizeof(buffer)) > 0) {
        for (char *c = buffer; c < buffer + sizeof(buffer); c++) {
            if (*c == '\n') {
                line_count++;
            }
        }
    }

    return line_count;
}

// Process a file and update its extension to a new format
void process_file(struct file *file) {
    char *path = malloc(strlen(file->path) + 10); // 10 is the length of ".vX.Y.Z.<type>"
    sprintf(path, "%s.v%d.%d.%d.%s", file->path, VERSION_MAJOR, VERSION_MINOR, VERSION_PATCH, file->type);

    if (rename(file->path, path) < 0) {
        fprintf(stderr, "Error: Failed to rename the file %s\n", file->path);
        exit(IO_ERROR);
    }

    free(path);
}

// Update a list of files and process them concurrently
void update_files(struct file *files[], int num_files) {
    semaphore_t lock = create_semaphore(1); // Lock for concurrent access to the list of files

    // Create threads for each file
    pthread_t threads[num_files];
    for (int i = 0; i < num_files; i++) {
        struct file *file = files[i];
        pthread_create(&threads[i], NULL, process_file, file);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_semaphore(&lock);
}

// Main function to handle the command line arguments
int main(int argc, char *argv[]) {
    struct args args = {}; // Initialize with empty values
    int opt;
    while ((opt = getopt(argc, argv, "i:o:c")) != -1) {
        switch (opt) {
            case 'i':
                args.input_file = optarg;
                break;
            case 'o':
                args.output_file = optarg;
                break;
            case 'c':
                args.count_only = 1;
                break;
        }
    }

    if (args.input_file == NULL) {
        fprintf(stderr, "Error: Input file not specified\n");
        exit(INVALID_ARGUMENTS);
    }

    init(&args); // Initialize the library with command line arguments

    struct file *files = malloc(sizeof(struct file) * num_files); // Allocate memory for the list of files

    int i = 0;
    while ((opt = getopt(argc, argv, "i:o:c")) != -1) {
        switch (opt) {
            case 'i':
                files[i].path = optarg; // Store the path to the file in the list
                break;
            case 'o':
                args.output_file = optarg;
                break;
            case 'c':
                args.count_only = 1;
                break;
        }
    }

    // Open all files and process them concurrently
    for (int i = 0; i < num_files; i++) {
        struct file *file = &files[i];
        file->fd = open(file->path, O_RDONLY);
        if (file->fd == -1) {
            fprintf(stderr, "Error: Failed to open the file %s\n", file->path);
            exit(IO_ERROR);
        }
    }

    update_files(files, num_files); // Update the list of files and process them concurrently

    return 0;
}
