        }
        hashMapCurrent = hashMapCurrent->next;
    }
    // If the node is not in the hash map, return
    if (hashMapCurrent == NULL) {
        goto exit;
    }
    // Remove the node from the linked list and hash map
    if (prev != NULL) {
        prev->next = current->next;
    } else {
        manager->linkedListHead = current->next;
    }
    free(current->data);
    free(current);
    if (hashMapCurrent->next != NULL) {
        hashMapCurrent->next = current->next;
    } else {
        struct HashMapNode *prev = manager->hashMapHead;
        while (prev->next != current) {
            prev = prev->next;
        }
        prev->next = NULL;
        free(current);
    }
exit:
    // Release the mutex
    pthread_mutex_unlock(&manager->mutex);
}

// Function to retrieve a NFAPI_CRC_INDICATION_PDU structure from the data structure manager
void *retrieveNFAPI_CRC_INDICATION_PDU(struct DataStructureManager *manager, unsigned int rnti) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);
    struct HashMapNode *hashMapCurrent = manager->hashMapHead;
    while (hashMapCurrent != NULL) {
        if (hashMapCurrent->rnti == rnti) {
            break;
        }
        hashMapCurrent = hashMapCurrent->next;
    }
    // If the node is not in the hash map, return NULL
    if (hashMapCurrent == NULL) {
        goto exit;
    }
    struct LinkedListNode *linkedListCurrent = manager->linkedListHead;
    while (linkedListCurrent != NULL) {
        if (linkedListCurrent->data->rnti == rnti) {
