    }
    void *crcIndicationBody = linkedListCurrent->data->crcIndicationBody;
exit:
    // Release the mutex
    pthread_mutex_unlock(&manager->mutex);
    return crcIndicationBody;
}

// Function to free the memory allocated by the data structure manager
void freeDataStructureManager(struct DataStructureManager *manager) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&manager->mutex);
    // Free the linked list and hash map nodes
    struct LinkedListNode *current = manager->linkedListHead;
    while (current != NULL) {
        struct LinkedListNode *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    struct HashMapNode *hashMapCurrent = manager->hashMapHead;
    while (hashMapCurrent != NULL) {
        struct HashMapNode *next = hashMapCurrent->next;
        free(hashMapCurrent);
        hashMapCurrent = next;
