using namespace std;

// Constants for the EDA system
const int MAX_MESSAGES_PER_SECOND = 10000000; // Maximum messages per second
const int MIN_LATENCY_MS = 1; // Minimum latency in milliseconds
const int MAX_THREADS = 8; // Maximum number of threads for processing messages
const int MAX_RESOURCES = 50000000; // Maximum resources for resource pooling

// Structure to represent a message
struct Message {
    string id;
    string content;
};

// Structure to represent a node in the EDA system
struct Node {
    int id;
    vector<Message> messages;
};

// Map to store all nodes in the EDA system
map<int, Node> nodes;

// Mutex for synchronizing access to nodes map
mutex nodeMutex;

// Function to add a new message to a node
void addMessage(int nodeId, Message message) {
    // Acquire lock on nodes map
    unique_lock<mutex> lock(nodeMutex);

    // Check if the node already exists in the system
    auto it = nodes.find(nodeId);
    if (it == nodes.end()) {
        // If the node does not exist, create a new one
        Node newNode;
        newNode.id = nodeId;
        newNode.messages.push_back(message);
        nodes[nodeId] = newNode;
    } else {
        // If the node already exists, add the message to it
        it->second.messages.push_back(message);
    }

    // Release lock on nodes map
    lock.unlock();
}

// Function to get a message from a node
Message getMessage(int nodeId) {
    // Acquire lock on nodes map
    unique_lock<mutex> lock(nodeMutex);

    // Check if the node exists in the system
    auto it = nodes.find(nodeId);
    if (it == nodes.end()) {
        // If the node does not exist, return an empty message
        Message emptyMessage;
        emptyMessage.id = "";
        emptyMessage.content = "";
        return emptyMessage;
    } else {
        // If the node exists, get a random message from it and remove it from the map
        int index = rand() % it->second.messages.size();
        Message message = it->second.messages[index];
        it->second.messages.erase(it->second.messages.begin() + index);
        return message;
    }

    // Release lock on nodes map
    lock.unlock();
}

// Function to update a node's messages
void updateNodeMessages(int nodeId, vector<Message> newMessages) {
    // Acquire lock on nodes map
    unique_lock<mutex> lock(nodeMutex);

    // Check if the node exists in the system
    auto it = nodes.find(nodeId);
    if (it == nodes.end()) {
        // If the node does not exist, create a new one with the new messages
        Node newNode;
        newNode.id = nodeId;
        newNode.messages = newMessages;
        nodes[nodeId] = newNode;
    } else {
        // If the node already exists, update its messages
        it->second.messages = newMessages;
    }

    // Release lock on nodes map
    lock.unlock();
}

// Function to remove a node from the system
void removeNode(int nodeId) {
    // Acquire lock on nodes map
    unique_lock<mutex> lock(nodeMutex);

    // Check if the node exists in the system
    auto it = nodes.find(nodeId);
    if (it == nodes.end()) {
        // If the node does not exist, return
        return;
    } else {
        // If the node exists, remove it from the map
        nodes.erase(it);
    }

    // Release lock on nodes map
    lock.unlock();
}

// Function to get all messages in a node's message queue
vector<Message> getNodeMessages(int nodeId) {
    // Acquire lock on nodes map
    unique_lock<mutex> lock(nodeMutex);

    // Check if the node exists in the system
    auto it = nodes.find(nodeId);
    if (it == nodes.end()) {
        // If the node does not exist, return an empty vector
        vector<Message> emptyVector;
        return emptyVector;
    } else {
        // If the node exists, get all messages in its message queue and return them
        return it->second.messages;
    }

    // Release lock on nodes map
    lock.unlock();
}

