### C++ Code

Here is the C++ code for the DFA:
```c++
#include <iostream>
#include <string>
#include <map>
#include <set>
#include <vector>

using namespace std;

// Function to add a state to the set of used states
void add_state(set<int>& used_states, int new_state) {
    if (used_states.find(new_state) == used_states.end()) {
        used_states.insert(new_state);
    }
}

// Function to add a transition to the map of transitions
void add_transition(map<int, vector<pair<string, string>>>& transitions, int state, string from, string to) {
    if (transitions.find(state) == transitions.end()) {
        transitions[state] = vector<pair<string, string>>();
    }
    transitions[state].push_back({from, to});
}

// Function to generate a transition rule for an epsilon transition
void generate_epsilon_transition(set<int>& used_states, map<int, vector<pair<string, string>>>& transitions, int current_state, int next_state) {
    add_state(used_states, next_state);
    add_transition(transitions, current_state, "EPSILON", to_string(next_state));
}

// Function to generate a transition rule for a non-epsilon transition
void generate_non_epsilon_transition(set<int>& used_states, map<int, vector<pair<string, string>>>& transitions, int current_state, int next_state) {
    add_state(used_states, next_state);
    add_transition(transitions, current_state, "NOTEPSILON", to_string(next_state));
}

// Function to generate a DFA from a regular expression
void generate_dfa(set<int>& used_states, map<int, vector<pair<string, string>>>& transitions, string regex) {
    // Initialize the set of used states and the map of transitions
    used_states = set<int>();
    transitions = map<int, vector<pair<string, string>>>();

    // Generate the DFA from the regular expression
    generate_epsilon_transition(used_states, transitions, 0, 1);
    generate_non_epsilon_transition(used_states, transitions, 0, 2);
    generate_epsilon_transition(used_states, transitions, 1, 3);
    generate_epsilon_transition(used_states, transitions, 2, 4);
    generate_non_epsilon_transition(used_states, transitions, 3, 5);
}

// Function to print the DFA
void print_dfa() {
    for (int i = 0; i < used_states.size(); i++) {
        cout << "State " << i << ": ";
        for (pair<string, string> transition : transitions[i]) {
            if (transition.first == "EPSILON") {
                cout << "ε -> " << transition.second << endl;
            } else {
                cout << transition.first << " -> " << transition.second << endl;
            }
        }
    }
}
```
The code defines two functions, `generate_dfa` and `print_dfa`, to generate the DFA from a regular expression and print it respectively. The `generate_epsilon_transition` function generates an epsilon transition between two states, while the `generate_non_epsilon_transition` function generates a non-epsilon transition.

The code also defines a set of used states and a map of transitions to store the DFA. The `add_state` function adds a new state to the set of used states if it is not already present, while the `add_transition` function adds a new transition to the map of transitions if it is not already present.

To generate a DFA from a regular expression, we call the `generate_dfa` function with the regular expression as an argument. The `generate_epsilon_transition` and `generate_non_epsilon_transition` functions are called recursively to generate the transitions between states.

Finally, we can print the DFA by calling the `print_dfa` function.

### Example

Here is an example of how to use the `generate_dfa` and `print_dfa` functions:
```c++
