void parseAndTransformData(FILE* file, struct DataTransformer* transformer, char* result, size_t result_size) {
    // Check if the input is valid
    if (!file || !transformer || !result || result_size == 0) {
        return;
    }

    // Lock the mutex to prevent concurrent access
    sem_wait(&parseAndTransformMutex);

    // Increment the number of pending requests
