        void* output = (void*)&result[num_records * sizeof(char)];
        transformer->transform_data(input, output);
        int validation_ret = validateData(transformer, output);
        if (validation_ret == 0) {
            num_records++;
        } else {
            handleError(validation_ret, transformer);
        }
    }

    // Free the buffer
    free(buffer);

    return ret;
}

static int validateData(struct DataTransformer* transformer, void* data) {
    if (!transformer || !data) {
        return -1;
    }

    // Call the validation function provided by the user
    return transformer->validate_data(data);
}

static void handleError(int err, struct DataTransformer* transformer) {
    if (!transformer) {
        return;
    }

    // Call the error handling function provided by the user
    transformer->handle_error(err);
}
