import os
import hashlib
from threading import Thread
from concurrent.futures import ProcessPoolExecutor
from timeit import default_timer as timer
from collections import deque
from logging import getLogger, StreamHandler, Formatter, FileHandler

class MD5Hasher:
    def __init__(self, chunk_size=1024*1024, max_file_size=10*1024*1024):
        self.chunk_size = chunk_size
        self.max_file_size = max_file_size

    def compute_hash(self, filepath, block_size=None):
        if not os.path.exists(filepath):
            raise ValueError("File does not exist")
        if os.path.getsize(filepath) > self.max_file_size:
            raise ValueError("File size exceeds maximum allowed")
        with open(filepath, 'rb') as f:
            md5 = hashlib.md5()
            while True:
                chunk = f.read(self.chunk_size)
                if not chunk:
                    break
                md5.update(chunk)
            return md5.hexdigest()

class MD5HasherProcessPoolExecutor(ProcessPoolExecutor):
    def __init__(self, max_workers=None):
        super().__init__(max_workers=max_workers)

    def map(self, func, files, block_size=1024*1024):
        if not isinstance(files, (list, tuple)):
            files = [files]
        futures = []
        for file in files:
            future = self.submit(func, file, block_size)
            futures.append(future)
        return futures

class MD5HasherThreaded(MD5Hasher):
    def __init__(self, chunk_size=1024*1024, max_file_size=10*1024*1024):
        super().__init__(chunk_size, max_file_size)
        self.threads = []

    def compute_hash(self, filepath, block_size=None):
        if not os.path.exists(filepath):
            raise ValueError("File does not exist")
        if os.path.getsize(filepath) > self.max_file_size:
            raise ValueError("File size exceeds maximum allowed")
        with open(filepath, 'rb') as f:
            md5 = hashlib.md5()
            while True:
                chunk = f.read(self.chunk_size)
                if not chunk:
                    break
                md5.update(chunk)
            return md5.hexdigest()

class MD5HasherLogger():
    def __init__(self, log_level=None, filepath=None):
        self.log_level = log_level or 'info'
        self.filepath = filepath

    def log(self, message, level='error'):
        if level not in ['debug', 'info', 'warning', 'error']:
            raise ValueError("Invalid logging level")
        logger = getLogger('MD5Hasher')
        handler = StreamHandler()
        formatter = Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        if self.filepath:
            handler = FileHandler(self.filepath, 'a', encoding='utf-8')
            handler.setFormatter(formatter)
            logger.addHandler(handler)
        getattr(logger, level)(message)

class MD5HasherConfig():
    def __init__(self, chunk_size=1024*1024, max_file_size=10*1024*1024):
        self.chunk_size = chunk_size
        self.max_file_size = max_file_size

    def load_config(self, config_dict):
        if 'chunk_size' in config_dict:
            self.chunk_size = config_dict['chunk_size']
        if 'max_file_size' in config_dict:
            self.max_file_size = config_dict['max_file_size']

class MD5HasherMetrics():
    def __init__(self):
        self.hash_compute_time = deque(maxlen=10)
        self.memory_usage = deque(maxlen=10)

    def update_metrics(self, hash_compute_time, memory_usage):
