// mod.rs

use openssl::symm;
use hyper::Client;
use std::time::Duration;

pub struct CryptoContext {
    cipher_name: String,
    key: Vec<u8>,
    iv: Vec<u8>,
}

impl CryptoContext {
    pub fn new(cipher_name: &str) -> Result<CryptoContext, String> {
        let cipher = symm::Cipher::new(cipher_name)?;
        let key = vec![0u8; 16];
        let iv = vec![0u8; 16];

        Ok(CryptoContext {
            cipher_name: String::from(cipher_name),
            key,
            iv,
        })
    }

    pub fn encrypt(&self, plaintext: &[u8]) -> Result<Vec<u8>, String> {
        let mut cipher = symm::Cipher::new(&self.cipher_name)?;
        cipher.key(self.key.as_slice());
        cipher.iv(self.iv.as_slice());
        let ciphertext = cipher.encrypt(plaintext, None)?;

        Ok(ciphertext)
    }

    pub fn decrypt(&self, ciphertext: &[u8]) -> Result<Vec<u8>, String> {
        let mut cipher = symm::Cipher::new(&self.cipher_name)?;
        cipher.key(self.key.as_slice());
        cipher.iv(self.iv.as_slice());
        let plaintext = cipher.decrypt(ciphertext, None)?;

        Ok(plaintext)
    }
}

pub struct HttpClient {
    client: Client,
}

impl HttpClient {
    pub fn new() -> Result<HttpClient, String> {
        let client = Client::new();

        Ok(HttpClient { client })
    }

    pub fn get(&self, url: &str) -> Result<Vec<u8>, String> {
        let resp = self.client.get(url).send()?;
        let status = resp.status().as_str();
        if !status.starts_with("2") {
            return Err(format!("Invalid response: {}", status));
        }

        let body = resp.text()?;
        Ok(body)
    }
}
