['```cpp
// RandomEngine namespace definition
namespace RandomEngine {
  // Abstract class for RNG algorithms
  class RngAlgorithm {
   public:
    virtual int generate(int min, int max) = 0;
  };

  // Interface for seeding the RNG system
  class SeedingService {
   public:
    virtual void seed(int seed) = 0;
  };

  // Class for Mersenne Twister RNG algorithm
  class MersenneTwister : public RngAlgorithm, public SeedingService {
   private:
    std::mt19937 mt;

   public:
    int generate(int min, int max) override {
      return std::uniform_int_distribution<int>(min, max)(mt);
    }

    void seed(int seed) override {
      mt.seed(seed);
    }
  };

  // Class for PCG RNG algorithm
  class Pcg : public RngAlgorithm, public SeedingService {
   private:
    std::pcg_extras::random<std::mt19937> rng;

   public:
    int generate(int min, int max) override {
      return std::uniform_int_distribution<int>(min, max)(rng());
    }

    void seed(int seed) override {
      rng.seed(seed);
    }
  };

  // Class for Xorshift RNG algorithm
  class Xorshift : public RngAlgorithm, public SeedingService {
   private:
    std::xorshift_engine engine;

   public:
    int generate(int min, int max) override {
      return std::uniform_int_distribution<int>(min, max)(engine);
    }

    void seed(int seed) override {
      engine.seed(seed);
    }
  };
}
