// Define a structure to represent an octree node
struct OctreeNode {
    // Node data members
    int featureSize;                      // Feature size of the node
    int targetLeafCount;                  // Target leaf node count
    int capacity;                         // Maximum number of data points stored in the node
    std::vector<std::unique_ptr<OctreeNode>> childNodes;   // Pointers to child nodes
    std::vector<int> dataPoints;          // Data points stored in this node

    // Constructor initializes a new octree node with default values
    OctreeNode(int featureSize, int targetLeafCount, int capacity) : featureSize(featureSize), targetLeafCount(targetLeafCount), capacity(capacity) {}
};

// Define a class to represent the octree data structure
class Octree {
public:
    // Constructor initializes an empty octree with default values
    Octree(int featureSize, int targetLeafCount, int capacity) : root_(featureSize, targetLeafCount, capacity), leafNodeCount_(0) {}

    // Destructor frees all memory allocated by the octree
    ~Octree() {
        freeMemory();
    }

    // Frees all memory allocated by the octree
    void freeMemory() {
        root_.freeMemory();
    }

    // Inserts a data point into the octree
    void insert(const std::vector<double>& dataPoint) {
        // Check if the node is full and needs to be split
        if (root_.childNodes.size() >= root_.targetLeafCount && !root_.isFull()) {
            splitNode();
        }

        // Recursively insert the data point into the octree
        root_.insert(dataPoint);
    }

    // Retrieves a data point from the octree
    std::vector<double> retrieve(const std::vector<double>& query) {
        return root_.retrieve(query);
    }

private:
    // Split a node if it is full and has not yet reached its target leaf count
    void splitNode() {
        // Calculate the dimension with the largest spread of data points
        int maxDim = 0;
        for (int i = 1; i < root_.featureSize; ++i) {
            if (root_.dataPoints[i].size() > root_.dataPoints[maxDim].size()) {
                maxDim = i;
            }
        }

        // Create a new node for each child dimension and move half of the data points to each child
        int splitPoint = root_.dataPoints[maxDim].size() / 2;
        for (int i = 0; i < root_.featureSize; ++i) {
            if (i != maxDim) {
                root_.childNodes.push_back(std::make_unique<OctreeNode>(root_.featureSize, root_.targetLeafCount, root_.capacity));
                std::move(root_.dataPoints[i].begin() + splitPoint, root_.dataPoints[i].end(), back_inserter(*root_.childNodes.back()));
            }
        }
    }

    // Root node of the octree
    OctreeNode root_;

    // Number of leaf nodes in the octree
    int leafNodeCount_;
};

// Implement a thread-safe logging interface for monitoring performance metrics
class PerformanceMetricsLogger {
public:
    // Constructor initializes the logger with default values
    PerformanceMetricsLogger(int featureSize, int targetLeafCount, int capacity) : root_(featureSize, targetLeafCount, capacity) {}

    // Destructor frees all memory allocated by the octree
    ~PerformanceMetricsLogger() {
        freeMemory();
    }

    // Frees all memory allocated by the octree
    void freeMemory() {
        root_.freeMemory();
    }

    // Inserts a data point into the octree and updates performance metrics
    void insert(const std::vector<double>& dataPoint) {
        root_.insert(dataPoint);

        // Update performance metrics
        leafNodeCount_ = root_.leafNodeCount();
    }

    // Retrieves a data point from the octree and updates performance metrics
    std::vector<double> retrieve(const std::vector<double>& query) {
        auto result = root_.retrieve(query);

        // Update performance metrics
        leafNodeCount_ = root_.leafNodeCount();

        return result;
    }

private:
    // Root node of the octree
    OctreeNode root_;

    // Number of leaf nodes in the octree
    int leafNodeCount_;
};

// Implement a mechanism to handle external dependencies, such as reading initial data from a JSON configuration file and creating directories for persistence
class ExternalDependenciesHandler {
public:
    // Constructor reads the JSON configuration file and sets up external dependencies
    ExternalDependenciesHandler(const std::string& configFilePath) : configFilePath_(configFilePath) {}

    // Destructor cleans up external dependencies
    ~ExternalDependenciesHandler() {
        cleanUp();
    }

    // Clean up external dependencies when the object is destroyed
    void cleanUp() {
        // Remove any directories created by the handler
        std::filesystem::remove_all(configFilePath_);
    }
};
```
