import { Client } from 'node-rest-client';

const client = new Client();
const streamManager = {};

// Initialize the stream manager with the list of available streams
streamManager.initStreams = (streams) => {
  const shards = [];
  for (let i = 0; i < streams.length; i++) {
    shards[i] = [];
  }

  return shards;
};

// Add a new stream to the manager
streamManager.addStream = (stream) => {
  const shardIndex = Math.abs(stream.id % streams.length);
  const shard = shards[shardIndex];

  // Check if the stream is already in the list
  const existingStream = shard.find((s) => s.id === stream.id);

  if (existingStream) {
    return;
  }

  shard.push(stream);
};

// Remove a stream from the manager
streamManager.removeStream = (streamId) => {
  const shardIndex = Math.abs(streamId % streams.length);
  const shard = shards[shardIndex];

  // Check if the stream exists in the list
  const existingStream = shard.find((s) => s.id === streamId);

  if (!existingStream) {
    return;
  }

  shard.splice(existingStream, 1);
};

// Get all streams for a given shard
streamManager.getShardStreams = (shardIndex) => {
  const shard = shards[shardIndex];
  return shard;
};

// Get all streams from the manager
streamManager.getAllStreams = () => {
  return [].concat(...shards);
};

// Add a new stream to the manager and assign it to a shard based on its id
streamManager.addStreamToShard = (stream) => {
  const shardIndex = Math.abs(stream.id % streams.length);
  const shard = shards[shardIndex];

  // Check if the stream is already in the list
  const existingStream = shard.find((s) => s.id === stream.id);

  if (existingStream) {
    return;
  }

  shard.push(stream);
};

// Remove a stream from the manager and release its resources
streamManager.removeStreamFromShard = (streamId) => {
  const shardIndex = Math.abs(streamId % streams.length);
  const shard = shards[shardIndex];

  // Check if the stream exists in the list
  const existingStream = shard.find((s) => s.id === streamId);

  if (!existingStream) {
    return;
  }

  shard.splice(existingStream, 1);
};

// Ingest a new video stream and distribute it to the appropriate shards
streamManager.ingestStream = (stream) => {
  const shardIndex = Math.abs(stream.id % streams.length);
  const shard = shards[shardIndex];

  // Check if the stream is already in the list
  const existingStream = shard.find((s) => s.id === stream.id);

  if (existingStream) {
    return;
  }

  shard.push(stream);
};

// Remove a video stream from the manager and release its resources
streamManager.removeStream = (streamId) => {
  const shardIndex = Math.abs(streamId % streams.length);
  const shard = shards[shardIndex];

  // Check if the stream exists in the list
  const existingStream = shard.find((s) => s.id === streamId);

  if (!existingStream) {
    return;
  }

  shard.splice(existingStream, 1);
};

// Get a list of all video streams for a given user
streamManager.getUserStreams = (userId) => {
  const streams = [];
  shards.forEach((shard) => {
    streams.push(...shard.filter((s) => s.user_id === userId));
  });
  return streams;
};

// Get a list of all video streams for a given category
streamManager.getCategoryStreams = (categoryId) => {
  const streams = [];
  shards.forEach((shard) => {
    streams.push(...shard.filter((s) => s.category_id === categoryId));
  });
  return streams;
};

// Get a list of all video streams for a given tag
streamManager.getTagStreams = (tagId) => {
  const streams = [];
  shards.forEach((shard) => {
    streams.push(...shard.filter((s) => s.tags.includes(tagId)));
  });
  return streams;
};
