        {
            // Decryption and Validation
            var decryptionService = new AsyncDecryptAndValidateMessage();
            var messageStream = new MemoryStream();
            messageStream.WriteAsync("ENCRYPTED_MESSAGE");

            try
            {
                var decryptedMessage = await decryptionService.DecodeAndDecrypt(messageStream);
                Console.WriteLine($"Decrypted message: {decryptedMessage}");
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error decrypting message: {e.Message}");
            }
        }
    }

    public class AsyncDecryptAndValidateMessage
    {
        private readonly byte[] _tripleDesKey;
        private readonly byte[] _iv;

        public AsyncDecryptAndValidateMessage(byte[] tripleDesKey, byte[] iv)
        {
            _tripleDesKey = tripleDesKey;
            _iv = iv;
        }

        public async Task<string> DecodeAndDecrypt(Stream messageStream)
        {
            try
            {
                var decryptedMessage = await DecryptAsync(messageStream);
                return await ValidateMessage(decryptedMessage);
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error decoding or validating message: {e.Message}");
                throw;
            }
        }

        private async Task<string> DecryptAsync(Stream messageStream)
        {
            var buffer = new byte[messageStream.Length];
            await messageStream.ReadAsync(buffer);
            return Encoding.UTF8.GetString(buffer);
        }

        private async Task<string> ValidateMessage(string decryptedMessage)
        {
            // Validate the message against a whitelist of valid messages
            if (decryptedMessage == "VALID_MESSAGE")
                return decryptedMessage;
            else
                throw new Exception("Invalid message");
        }
    }
}
```
