using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace SecureDataProcessor
{
    public class EncryptionProcessor
    {
        private readonly string _encryptionKey;
        private readonly int _concurrencyLimit;
        private readonly int _paddingMode;
        private readonly bool _enableLogging;
        private readonly Dictionary<string, byte[]> _decryptedData = new();

        public EncryptionProcessor(string encryptionKey, int concurrencyLimit, int paddingMode, bool enableLogging)
        {
            _encryptionKey = encryptionKey;
            _concurrencyLimit = concurrencyLimit;
            _paddingMode = paddingMode;
            _enableLogging = enableLogging;
        }

        public async Task<byte[]> DecryptAsync(byte[] encryptedData, string iv)
        {
            if (!_decryptedData.TryGetValue(iv, out byte[] decryptedData))
            {
                decryptedData = await DecryptDataAsync(encryptedData, iv);
                _decryptedData[iv] = decryptedData;
            }

            return decryptedData;
        }

        private async Task<byte[]> DecryptDataAsync(byte[] encryptedData, string iv)
        {
            using var aesAlgorithm = Aes.Create();
            aesAlgorithm.Mode = CipherMode.CBC;
            aesAlgorithm.KeySize = 256;
            aesAlgorithm.BlockSize = 128;
            aesAlgorithm.Padding = _paddingMode == 0 ? PaddingMode.PKCS7 : PaddingMode.Zeros;
            aesAlgorithm.IV = Encoding.ASCII.GetBytes(iv);
            aesAlgorithm.Key = Encoding.ASCII.GetBytes(_encryptionKey);

            using var memoryStream = new MemoryStream();
            using var cryptoStream = new CryptoStream(memoryStream, aesAlgorithm.CreateDecryptor(), CryptoStreamMode.Write);
            await cryptoStream.WriteAsync(encryptedData, 0, encryptedData.Length);
            await cryptoStream.FlushFinalBlockAsync();
            return memoryStream.ToArray();
        }

        public void Dispose()
        {
            _decryptedData.Clear();
        }
    }
}
