Here is a C++ implementation of a modular and highly configurable market data processing library named `marketDataProcessor`:
```c++
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <fstream>
#include <algorithm>
#include <memory>
#include <functional>

// Define the data structures to hold the market data and configurations
struct MarketData {
  std::string symbol;
  double price;
  double volume;
};

struct Config {
  std::string apiUrl;
  int apiPort;
  bool useTls;
  bool useCompression;
  std::string dataEncoding;
  std::string parsingRules;
  std::map<std::string, int> symbolMap;
};

// Define the state of the library
struct State {
  // Map of market symbols to data streams
  std::map<std::string, std::vector<MarketData>> symbolStreams;

  // Set of symbols with active data streams
  std::set<std::string> activeSymbols;

  // Mutex and condition variable for synchronizing access to the state
  std::mutex mutex;
  std::condition_variable cv;

  // Thread pool for parallelizing tasks
  std::vector<std::thread> threadPool;
};

// Define the library class
class MarketDataProcessor {
 public:
  // Constructor to initialize the state
  MarketDataProcessor(const Config& config) : config_(config), state_() {}

  // Function to add a market data stream
  void AddStream(std::string symbol, int apiId) {
    std::lock_guard<std::mutex> lock(state_.mutex);
    if (state_.activeSymbols.find(symbol) != state_.activeSymbols.end()) {
      return;
    }
    auto stream = std::make_shared<MarketDataStream>(apiId, symbol, config_);
    state_.symbolStreams[symbol].push_back(stream);
    state_.threadPool.push_back(std::thread([this, stream]() {
      while (true) {
        std::unique_lock<std::mutex> lock(state_.mutex);
        state_.cv.wait(lock, [this, symbol]() { return state_.activeSymbols.find(symbol) != state_.activeSymbols.end(); });
        if (stream->ReceiveNextMessage()) {
          stream->ProcessMessage();
        } else {
          break;
        }
      }
    }));
  }

  // Function to remove a market data stream
  void RemoveStream(std::string symbol) {
    std::lock_guard<std::mutex> lock(state_.mutex);
    if (state_.activeSymbols.find(symbol) == state_.activeSymbols.end()) {
      return;
    }
    state_.activeSymbols.erase(symbol);
  }

 private:
  // Config structure for the library
  const Config config_;

  // State of the library
  State state_;
};
```
The `MarketDataProcessor` class provides a simple API to add and remove market data streams, as well as functions for handling reconnections and anomaly detection. The internal state is stored in a `State` structure, which is protected by a mutex and condition variable to ensure thread-safe access. The library uses a thread pool to parallelize the processing of messages from multiple streams.

