// OAuthTokenManager.cpp
#include "OAuthTokenManager.h"
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <chrono>
#include <optional>

OAuthTokenManager::OAuthTokenManager(std::string tokenUrl, std::string revocationUrl) : tokenUrl_(tokenUrl), revocationUrl_(revocationUrl) {
  // Initialize the access token to an empty string
  accessToken_ = "";
}

OAuthTokenManager::~OAuthTokenManager() {}

bool OAuthTokenManager::validateToken(const std::string& token) const {
  // Validate the token against the revocation list
  return validateTokenInternal(token);
}

bool OAuthTokenManager::refreshToken(std::string& token) const {
  // Refresh the token by calling the token URL and updating the access token
  return refreshTokenInternal(token);
}

std::optional<std::string> OAuthTokenManager::getAccessToken() const {
  // Return the access token if it is not empty, otherwise return an empty optional
  if (accessToken_ != "") {
    return std::make_optional<std::string>(accessToken_);
  } else {
    return std::nullopt;
  }
}

void OAuthTokenManager::setAccessToken(const std::string& token) {
  // Set the access token to the given value and update the revocation list
  accessToken_ = token;
  updateRevocationList();
}

void OAuthTokenManager::clearAccessToken() {
  // Clear the access token and update the revocation list
  accessToken_ = "";
  updateRevocationList();
}

std::string OAuthTokenManager::getThreadSafeAccessToken() const {
  // Return a thread-safe copy of the access token
  std::lock_guard<std::mutex> lock(accessTokenMutex_);
  return accessToken_;
}

void OAuthTokenManager::setThreadSafeAccessToken(const std::string& token) {
  // Set the access token to the given value and update the revocation list
  std::lock_guard<std::mutex> lock(accessTokenMutex_);
  accessToken_ = token;
  updateRevocationList();
}

bool OAuthTokenManager::validateTokenInternal(const std::string& token) const {
  // Check if the token is present in the revocation list
  std::lock_guard<std::mutex> lock(revocationListMutex_);
  return (std::find(revocationList_.begin(), revocationList_.end(), token) == revocationList_.end());
}

bool OAuthTokenManager::refreshTokenInternal(std::string& token) const {
  // Call the token URL to refresh the token and update the access token
  std::lock_guard<std::mutex> lock(accessTokenMutex_);
  token = "";
  std::vector<std::string> headers;
  headers.push_back("Content-Type: application/x-www-form-urlencoded");
  std::string body = "grant_type=refresh_token&refresh_token=" + token;
  auto response = httpRequest(tokenUrl_, headers, body);
  if (response != nullptr && response->statusCode == 200) {
    std::map<std::string, std::string> jsonResponse = jsonDecode(response->body);
    token = jsonResponse["access_token"];
    updateRevocationList();
    return true;
  } else {
    return false;
  }
}

void OAuthTokenManager::updateRevocationList() const {
  // Update the revocation list by calling the revocation URL and parsing the response as JSON
  std::lock_guard<std::mutex> lock(revocationListMutex_);
  std::vector<std::string> headers;
  headers.push_back("Content-Type: application/json");
  auto response = httpRequest(revocationUrl_, headers, "");
  if (response != nullptr && response->statusCode == 200) {
    std::map<std::string, std::vector<std::string>> jsonResponse = jsonDecodeArray(response->body);
    for (auto& token : jsonResponse["revokedTokens"]) {
      revocationList_.push_back(token);
    }
  } else {
    throw std::runtime_error("Failed to update revocation list");
  }
}
