        if (id < 0 || id >= stateList.size()) {
            throw new IllegalArgumentException("Invalid state ID");
        } else {
            State state = stateList.get(id);
            state.name = name;
            return id;
        }
    }

    public static int removeState(int id) {
        if (id < 0 || id >= stateList.size()) {
            throw new IllegalArgumentException("Invalid state ID");
        } else {
            for (int i = id + 1; i < stateList.size(); i++) {
                State state = stateList.get(i);
                stateList.set(i - 1, state);
            }
            stateList.remove(stateList.size() - 1);
            return id;
        }
    }

    public static void lockStateList() {
        lock.lock();
    }

    public static void unlockStateList() {
        lock.unlock();
    }

    public static State deserialize(byte[] data) {
