// Finite state automaton (FSA)
class FSA {
private:
    struct State {
        int id;
        string name;
    };

    map<int, State> states;
    vector<State*> currentStates;
    mutex stateMutex;
    condition_variable stateCondVar;

public:
    FSA() {}

    void addState(const State& state) {
        unique_lock<mutex> lock(stateMutex);
        states[state.id] = state;
    }

    void removeState(int id) {
        unique_lock<mutex> lock(stateMutex);
        states.erase(id);
    }

    State* getCurrentState() {
        unique_lock<mutex> lock(stateMutex);
        return currentStates[0];
    }

    void setCurrentState(int id) {
        unique_lock<mutex> lock(stateMutex);
        if (states.find(id) != states.end()) {
            currentStates[0] = &states[id];
        }
    }

    void addNextState(const State& state) {
        unique_lock<mutex> lock(stateMutex);
        states[state.id] = state;
        currentStates.push_back(&states[state.id]);
    }

    void removeNextState(int id) {
        unique_lock<mutex> lock(stateMutex);
        for (auto it = currentStates.begin(); it != currentStates.end(); ++it) {
            if ((*it)->id == id) {
                currentStates.erase(it);
                return;
            }
        }
    }

    void updateCurrentState() {
        unique_lock<mutex> lock(stateMutex);
        stateCondVar.notify_all();
    }
};

