using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Newtonsoft.Json;

namespace PasswordManagement {
    public class PasswordManager {
        private readonly IConfiguration _configuration;
        private readonly IPasswordHasher _passwordHasher;

        public PasswordManager(IConfiguration configuration, IPasswordHasher passwordHasher) {
            _configuration = configuration;
            _passwordHasher = passwordHasher;
        }

        public Task<PasswordHash> HashAsync(string password) {
            return _passwordHasher.HashAsync(password);
        }

        public Task<bool> VerifyAsync(string hash, string password) {
            return _passwordHasher.VerifyAsync(hash, password);
        }
    }

    public interface IPasswordHasher {
        Task<PasswordHash> HashAsync(string password);
        Task<bool> VerifyAsync(string hash, string password);
    }

    public class Argon2PasswordHasher : IPasswordHasher {
        private readonly IConfiguration _configuration;

        public Argon2PasswordHasher(IConfiguration configuration) {
            _configuration = configuration;
        }

        public async Task<PasswordHash> HashAsync(string password) {
            var argon2Params = new Argon2Parameters() {
                Iterations = int.Parse(_configuration["Argon2:Iterations"]),
                SaltLength = int.Parse(_configuration["Argon2:SaltLength"])
            };
            var salt = await GetRandomBytesAsync(argon2Params.SaltLength);
            var hash = Argon2.Hash(password, salt, argon2Params);
            return new PasswordHash() { Hash = hash, Salt = salt };
        }

        public async Task<bool> VerifyAsync(string hash, string password) {
            var expectedHash = await HashAsync(password);
            return expectedHash.Equals(hash);
        }

        private static async Task<byte[]> GetRandomBytesAsync(int length) {
            using var cryptoServiceProvider = new RNGCryptoServiceProvider();
            var randomBuffer = new byte[length];
            cryptoServiceProvider.GetBytes(randomBuffer);
            return randomBuffer;
        }
    }

    public class PasswordHash {
        public string Hash { get; set; }
        public byte[] Salt { get; set; }
    }
}
```
