  chrono::system_clock::time_point timestamp;

  // Level of the log entry
  LogLevel level;

  // Message of the log entry
  string message;
};

// Define a map to store logs and their metadata
unordered_map<string, vector<LogEntry>> logs;

// Define mutexes and condition variables for thread safety
mutex logsLock;
condition_variable logsCondVar;
