    // Iterate over each state in the linked list
    while (head != NULL) {
        // Return the current state if it matches the input name
        if (strcmp(head->name, name) == 0) {
            return head;
        }

        // Move to the next state in the linked list
        head = head->next;
    }

    // If no matching state is found, return NULL
    return NULL;
}

// Function to add a transition from one state to another based on an input character
void add_transition(struct State* current_state, char input_char) {
    // Create a new state if the current state does not have any transitions
    if (current_state->num_transitions == 0) {
        current_state->next = malloc(sizeof(struct State));
        current_state->next->name = malloc(2 * sizeof(char));
        current_state->next->name[0] = input_char;
        current_state->next->name[1] = '\0';
        current_state->num_transitions++;
    } else {
        // Iterate over each transition in the current state
        struct Transition* head = current_state->transitions;
        while (head != NULL) {
            if (strcmp(head->name, input_char) == 0) {
                break;
            }

            // Move to the next transition in the linked list
            head = head->next;
        }

        // If no matching transition is found, create a new one
        if (head == NULL) {
            struct Transition* new_transition = malloc(sizeof(struct Transition));
            new_transition->name = malloc(2 * sizeof(char));
            new_transition->name[0] = input_char;
            new_transition->name[1] = '\0';
            head->next = new_transition;
            current_state->num_transitions++;
        }
    }
}

// Function to get the number of states in a linked list
int get_num_states(struct State* head) {
    int num_states = 0;

    // Iterate over each state in the linked list
    while (head != NULL) {
        num_states++;
        head = head->next;
    }

    return num_states;
}

// Function to get an array of transitions from a linked list of states
struct Transition** get_state_transitions(struct State* head) {
    // Initialize an array of transitions with the default size
    struct Transition** transitions = malloc(10 * sizeof(struct Transition));
    int num_transitions = 0;

    // Iterate over each state in the linked list
    while (head != NULL) {
        // Add a transition to the array of transitions
        transitions[num_transitions] = malloc(sizeof(struct Transition));
        transitions[num_transitions]->name = malloc(2 * sizeof(char));
        strcpy(transitions[num_transitions]->name, head->name);
        transitions[num_transitions]->next = NULL;
        num_transitions++;

        // Move to the next state in the linked list
        head = head->next;
    }

    return transitions;
}

// Function to extract a substring from a string
char* substring(char* str, int start, int end) {
    char* substr = malloc((end - start + 1) * sizeof(char));
    for (int i = start; i <= end; i++) {
        substr[i - start] = str[i];
    }

    return substr;
}

// Function to calculate the Hamming distance between two strings
int hamming_distance(char* str1, char* str2) {
    int distance = 0;

    // Iterate over each character in the first string
    for (int i = 0; i < strlen(str1); i++) {
        if (str1[i] != str2[i]) {
            distance++;
        }
    }

    return distance;
}

// Function to extract a substring from a string using regular expressions
char* reg_substring(char* str, char* pattern) {
    regex_t regex;
    if (regcomp(&regex, pattern, REG_EXTENDED)) {
        fprintf(stderr, "Failed to compile regular expression\n");
        return NULL;
    }

    regmatch_t match;
    if (!regexec(&regex, str, 1, &match, 0)) {
        char* substr = malloc((match.rm_eo - match.rm_so + 1) * sizeof(char));
        for (int i = match.rm_so; i <= match.rm_eo; i++) {
            substr[i - match.rm_so] = str[i];
        }

        return substr;
    } else {
        regfree(&regex);
        return NULL;
    }
}
```

The code for the `substring` function is a bit long, but it's mostly straightforward. It takes a string as input and returns a substring of that string between two indices. The function uses pointer arithmetic to extract the characters from the string and allocate memory for the resulting substring.

The `hamming_distance` function calculates the Hamming distance between two strings by iterating over each character in both strings simultaneously and comparing them using the `!=` operator. If a mismatch is found, the function increments a counter to keep track of the number of mismatches. Once all characters have been compared, the function returns the total number of mismatches as the Hamming distance between the two strings.

The `reg_substring` function uses regular expressions to extract a substring from a string. It takes a string and a pattern as input and returns a substring that matches the pattern. The function first compiles the regular expression using the `regcomp` function from the `<regex.h>` library. If compilation fails, it prints an error message to stderr and returns `NULL`. Once compiled, the function searches for a match in the string using the `regexec` function from the same library. If a match is found, it extracts the substring by iterating over each character between the beginning of the match and the end of the match. It then allocates memory for the resulting substring and returns it.

The `substring_test` and `hamming_distance_test` functions are used to test the functionality of the `substring` and `hamming_distance` functions, respectively. The `reg_substring_test` function is a bit more complex because it requires a regular expression pattern as input, which means we need to handle errors in the code if the pattern fails to compile or there is no match for the substring.

