    // Method to encrypt data using DES in ECB mode
    fn encrypt_ecb(&self, data: &[u8]) -> Result<Vec<u8>, ErrorKind> {
        let mut encrypted = Vec::new();

        for chunk in data.chunks(8) {
            let mut block = [0; 8];
            block.copy_from_slice(chunk);

            let (block, _) = cryptography::encrypt_ecb(&self.key, &self.iv, &block);
            encrypted.extend_from_slice(&block);
