// define the caching mechanism
class Cache {
public:
    // constructor
    Cache(int cacheSize) : cacheSize_(cacheSize), currentSize_(0) {}

    // add a resource bundle to the cache
    void addResourceBundle(const string& name, const vector<string>& files) {
        if (currentSize_ >= cacheSize_) {
            return;
        }
        ResourceBundle rb = {name, "", files};
        resources_.push_back(rb);
        currentSize_++;
    }

    // get a resource bundle from the cache
    const ResourceBundle& getResourceBundle(const string& name) {
        for (auto it = resources_.begin(); it != resources_.end(); ++it) {
            if (it->name == name) {
                return *it;
            }
        }
        throw runtime_error("Resource bundle not found");
    }

private:
    // cache size
    int cacheSize_;

    // current size of the cache
    int currentSize_;

    // vector of resource bundles
    vector<ResourceBundle> resources_;
};

// define the memory pool class
class MemoryPool {
public:
    // constructor
    MemoryPool(size_t maxAllocationSize) : maxAllocationSize_(maxAllocationSize), allocationSize_(0) {}

    // allocate a block of memory from the pool
    void* allocateBlock(size_t size) {
        if (allocationSize_ + size > maxAllocationSize_) {
            return nullptr;
        }
        allocationSize_ += size;
        return malloc(size);
    }

    // deallocate a block of memory from the pool
    void deallocateBlock(void* ptr, size_t size) {
        if (ptr == nullptr) {
            return;
        }
        allocationSize_ -= size;
        free(ptr);
    }

private:
    // maximum allocation size for the pool
    size_t maxAllocationSize_;

    // current allocation size of the pool
    size_t allocationSize_;
};

// define the custom memory allocator class
class CustomMemoryAllocator {
public:
    // constructor
    CustomMemoryAllocator(MemoryPool* pool) : pool_(pool) {}

    // allocate a block of memory from the pool
    void* allocateBlock(size_t size) {
        return pool_->allocateBlock(size);
    }

    // deallocate a block of memory from the pool
    void deallocateBlock(void* ptr, size_t size) {
        pool_->deallocateBlock(ptr, size);
