// Function to handle API failures and retries
async function apiRetry(url, params = {}, retries = 0) {
  try {
    const response = await axios.get(url, params);
    return response;
  } catch (err) {
    if (retries > 0) {
      const backoff = Math.min(Math.pow(2, retries - 1) * 1000, 30000);
      console.warn(`API call failed with ${err}, retrying in ${backoff}ms`);
      await new Promise((resolve) => setTimeout(resolve, backoff));
      return apiRetry(url, params, retries - 1);
    } else {
      throw new Error(`API call failed with ${err}`);
    }
  }
