['```python
import logging
import random
from datetime import datetime, timedelta
from typing import List, Dict, Any
from uuid import uuid4

from distributed_task_scheduler.constants import (
    JOB_PRIORITY_HIGHEST,
    JOB_PRIORITY_LOWEST,
    JOB_STATUS_QUEUED,
    JOB_STATUS_RUNNING,
    JOB_STATUS_FAILED,
    JOB_STATUS_COMPLETED,
    JOB_STATUS_CANCELLED,
    JOB_STATUS_PAUSED,
)
from distributed_task_scheduler.utils import (
    get_external_service_status,
    generate_unique_id,
    get_system_load,
    get_cpu_usage,
    get_memory_usage,
)
from distributed_task_scheduler.exceptions import (
    TaskSchedulerException,
    JobNotFoundError,
    InvalidJobStatusError,
    UnsupportedActionError,
)

class DistributedTaskScheduler:
    def __init__(self):
        self.jobs = {}
        self.workers = []
        self.worker_status = {}
        self.priority_queue = []
        self.external_service_status = {}
        self.message_broker = None

    def add_job(self, job: Dict[str, Any]) -> str:
        """Add a new job to the scheduler."""
        job_id = generate_unique_id()
        job["id"] = job_id
        self.jobs[job_id] = job
        return job_id

    def add_worker(self, worker: Dict[str, Any]) -> str:
        """Add a new worker to the scheduler."""
        worker_id = generate_unique_id()
        worker["id"] = worker_id
        self.workers.append(worker)
        return worker_id

    def get_job(self, job_id: str) -> Dict[str, Any]:
        """Get a job by its ID."""
        if job_id not in self.jobs:
            raise JobNotFoundError(f"Job {job_id} not found.")
        return self.jobs[job_id]

    def get_worker(self, worker_id: str) -> Dict[str, Any]:
        """Get a worker by its ID."""
        if worker_id not in self.workers:
            raise JobNotFoundError(f"Worker {worker_id} not found.")
        return self.workers[worker_id]

    def start_job(self, job_id: str) -> None:
        """Start a job."""
        if job_id not in self.jobs:
            raise JobNotFoundError(f"Job {job_id} not found.")
        job = self.jobs[job_id]
        if job["status"] != JOB_STATUS_QUEUED:
            raise InvalidJobStatusError(
                f"Invalid job status for job {job_id}: {job['status']}"
            )
        worker = self._get_available_worker()
        self.priority_queue.append((job["priority"], job_id))
        self.workers[worker]["running_jobs"].append(job_id)
        job["status"] = JOB_STATUS_RUNNING

    def pause_job(self, job_id: str) -> None:
        """Pause a job."""
        if job_id not in self.jobs:
            raise JobNotFoundError(f"Job {job_id} not found.")
        job = self.jobs[job_id]
        if job["status"] != JOB_STATUS_RUNNING:
            raise InvalidJobStatusError(
                f"Invalid job status for job {job_id}: {job['status']}"
            )
        worker = self._get_worker_for_job(job)
        self.workers[worker]["running_jobs"].remove(job_id)
        job["status"] = JOB_STATUS_PAUSED

    def resume_job(self, job_id: str) -> None:
        """Resume a paused job."""
        if job_id not in self.jobs:
            raise JobNotFoundError(f"Job {job_id} not found.")
        job = self.jobs[job_id]
        if job["status"] != JOB_STATUS_PAUSED:
            raise InvalidJobStatusError(
                f"Invalid job status for job {job_id}: {job['status']}"
            )
        worker = self._get_available_worker()
        self.priority_queue.append((job["priority"], job_id))
        self.workers[worker]["running_jobs"].append(job_id)
        job["status"] = JOB_STATUS_RUNNING

    def cancel_job(self, job_id: str) -> None:
        """Cancel a job."""
        if job_id not in self.jobs:
            raise JobNotFoundError(f"Job {job_id} not found.")
        job = self.jobs[job_id]
        if job["status"] != JOB_STATUS_QUEUED and job["status"] != JOB_STATUS_RUNNING:
            raise InvalidJobStatusError(
                f"Invalid job status for job {job_id}: {job['status']}"
            )
        worker = self._get_worker_for_job(job)
        if worker is not None:
            self.workers[worker]["running_jobs"].remove(job_id)
        job["status"] = JOB_STATUS_CANCELLED

    def finish_job(self, job_id: str) -> None:
        """Finish a job."""
        if job_id not in self.jobs:
            raise JobNotFoundError(f"Job {job_id} not found.")
        job = self.jobs[job_id]
        if job["status"] != JOB_STATUS_RUNNING:
            raise InvalidJobStatusError(
                f"Invalid job status for job {job_id}: {job['status']}"
            )
        worker = self._get_worker_for_job(job)
        self.workers[worker]["running_jobs"].remove(job_id)
        job["status"] = JOB_STATUS_FINISHED

    def _get_available_worker(self) -> str:
        """Get an available worker for a new job."""
        workers = [w for w in self.workers if len(self.workers[w]["running_jobs"]) < 2]
        return random.choice(workers)

    def _get_worker_for_job(self, job: Dict[str, Any]) -> str:
        """Get the worker responsible for a job."""
        for w in self.workers:
            if job["id"] in self.workers[w]["running_jobs"]:
                return w
        return None

    def _get_next_priority(self) -> int:
        """Get the next priority to assign to a new job."""
        priorities = [j[0] for j in self.priority_queue]
        if not priorities:
            return 1
        else:
            return max(priorities) + 1

    def _assign_jobs_to_workers(self) -> None:
        """Assign jobs to workers based on their priority and availability."""
        while self.priority_queue:
            priority, job_id = self.priority_queue[0]
            worker = self._get_available_worker()
            self.workers[worker]["running_jobs"].append(job_id)
            del self.priority_queue[0]
        for w in self.workers:
            if not self.workers[w]["running_jobs"]:
                del self.workers[w]

    def _check_worker_health(self) -> None:
        """Check the health of each worker and remove them if they are unresponsive."""
        for w in self.workers:
            if get_worker_status(self.workers[w]) == "unresponsive":
                del self.workers[w]

    def _handle_worker_failure(self, worker_id: str) -> None:
        """Handle a failed worker by reassigning its jobs to other workers."""
        worker = self.workers[worker_id]
        for job_id in worker["running_jobs"]:
            job = self.jobs[job_id]
            if job["status"] == JOB_STATUS_RUNNING:
                new_worker = self._get_available_worker()
                self.workers[new_worker]["running_jobs"].append(job_id)
                del self.workers[worker_id]["running_jobs"][job_id]
            else:
                job["status"] = JOB_STATUS_QUEUED
        del self.workers[worker_id]
```']

