use std::time;
use std::process::Command;
use rustc_driver::catch_with_exit_code;
use early_error;

fn compile_rust_project() -> i32 {
    let start = time::Instant::now();
    let resident_set_size_before = get_resident_set_size();

    let exit_code = catch_with_exit_code(move || {
        let mut cmd = Command::new("rustc");
        cmd.arg("-o").arg("output.bin");
        cmd.arg("source.rs");
        cmd.env("RUSTC_LOG", "--log-level=info");
        cmd.spawn()?.wait()?;
    });

    let resident_set_size_after = get_resident_set_size();
    let elapsed = start.elapsed().as_secs_f64();
    let memory_usage = (resident_set_size_after - resident_set_size_before) as f64 / 1024.0; // convert to KB

    println!("Compilation took {:.3}s, used {}KB of memory", elapsed, memory_usage);

    exit_code
}
```
This function uses the `rustc_driver` crate to install a custom logging hook that captures any errors that occur during compilation and reports them using the `early_error` function. It also measures the time taken for compilation using the `time` module and calculates the resident set size of the process before and after compilation.

The function first creates a new `Command` object for the Rust compiler, passing in the necessary arguments to compile the source code. It then sets up the custom logging hook using the `SyncLazy` module, which allows us to catch any errors that occur during compilation with the `catch_with_exit_code` function.

Once the compilation is complete, we calculate the resident set size of the process after compilation and measure the time taken for compilation using the `time::Instant::now` method. We then print out a message to the console indicating how long the compilation took and how much memory it used.

Finally, we return the exit code of the Rust compiler, excluding any other information such as a preamble or suffix.']

