    task.sourcePath = sourcePath;
    task.targetPath = targetPath;
    task.resizingFactor = resizingFactor;
    task.future = std::async(std::launch::async, uploadImageToS3, sourcePath, targetPath);

    // Add the task to the queue and wait for it to complete
    vector<UploadTask> tasks;
    tasks.push_back(task);
    while (!tasks.empty()) {
        UploadTask& task = tasks.front();
        try {
            task.future.wait();
            if (task.future.valid()) {
                task.future.get();
            }
        } catch (std::exception& e) {
            logError("An error occurred while uploading an image: %s", e.what());
        }
        tasks.erase(tasks.begin());
    }
