    size_t numThreads = std::min(NUM_THREADS, (size_t)sourcePaths.size());
    vector<thread> threads;
    vector<UploadTask> tasks;
    for (size_t i = 0; i < numThreads; i++) {
        string sourcePath = sourcePaths[i];
        string targetPath = targetPaths[i];
        float resizingFactor = resizingFactors[i];
        thread t(processImage, sourcePath, targetPath, resizingFactor);
        threads.push_back(t);
        tasks.push_back({sourcePath, targetPath, resizingFactor});
    }
    for (thread& t : threads) {
        t.join();
    }
}
