using SecureTokenManager;
using SecureTokenManager.Configuration;
using SecureTokenManager.Exceptions;
using SecureTokenManager.Security;
using SecureTokenManager.TokenGeneration;
using SecureTokenManager.TokenValidation;

namespace SecureTokenManager
{
    public class SecureTokenManager : ISecureTokenManager
    {
        private readonly ILogger<SecureTokenManager> _logger;
        private readonly IOptionsMonitor<SecureTokenManagerConfiguration> _config;
        private readonly ISecurityFramework _securityFramework;
        private readonly IDependencyResolver _dependencyResolver;
        private readonly ICache _cache;
        private readonly ITokenGenerationService _tokenGenerationService;
        private readonly ITokenValidationService _tokenValidationService;

        public SecureTokenManager(ILogger<SecureTokenManager> logger, IOptionsMonitor<SecureTokenManagerConfiguration> config, ISecurityFramework securityFramework, IDependencyResolver dependencyResolver, ICache cache)
        {
            _logger = logger;
            _config = config;
            _securityFramework = securityFramework;
            _dependencyResolver = dependencyResolver;
            _cache = cache;
        }

        public async Task<string> GenerateTokenAsync(Guid userId, int maxLength, TimeSpan expirationDuration, SecurityConfiguration securityConfiguration, long validityTimestamp = 0)
        {
            // Rate limiting and quota enforcement
            var tenantConfig = _config.CurrentValue;
            if (tenantConfig.MaximumTokensPerSecond > 0 && !_cache.IsQuotaExceeded(userId))
            {
                await Task.Delay(TimeSpan.FromSeconds(1));
            }
            else
            {
                throw new TokenGenerationException("Reached maximum token generation rate limit.");
            }

            // Generate token
            var generatedToken = _tokenGenerationService.GenerateToken(userId, maxLength, expirationDuration, securityConfiguration, validityTimestamp);

            // Add token to cache
            _cache.Add(generatedToken, userId);

            return generatedToken;
        }

        public async Task<bool> ValidateTokenAsync(string token)
        {
            var isValid = await _tokenValidationService.IsValidAsync(token);

            if (!isValid)
            {
                throw new TokenValidationException("Invalid token.");
            }

            return true;
        }
    }
}
