import { CloudProvider } from './cloud-providers';
import { RetryPolicy } from './retry-policy';
import { UploadProgressTracker } from './upload-progress-tracker';
import { MessageQueue } from './message-queue';

class FileUploaderClient {
  constructor(private cloudProviders: CloudProvider[], private retryPolicy: RetryPolicy) {}

  async startUpload(file: File, provider: CloudProvider): Promise<void> {
    const uploadRequest = this.createUploadRequest(file, provider);

    try {
      await this.sendUploadRequestToCloudProvider(uploadRequest);
    } catch (error) {
      if (this.retryPolicy.shouldRetry(error)) {
        return this.startUpload(file, provider);
      }
      throw error;
    }
  }

  private createUploadRequest(file: File, provider: CloudProvider): UploadRequest {
    const uploadRequest = new UploadRequest();
    uploadRequest.file = file;
    uploadRequest.provider = provider;
    return uploadRequest;
  }

  private async sendUploadRequestToCloudProvider(uploadRequest: UploadRequest): Promise<void> {
    await this.cloudProviders[uploadRequest.provider].uploadFile(uploadRequest.file);
  }
}
