// RetryPolicy class

class RetryPolicy {
  private readonly maxRetries: number;

  constructor(private readonly retryDelay: number, private readonly errorCodesToRetry: number[]) {}

  shouldRetry(error: Error): boolean {
    if (this.retryDelay > 0) {
      setTimeout(() => this.handleError(error), this.retryDelay);
    } else {
      throw error;
    }
  }

  private handleError(error: Error): void {
    const isRetryable = this.isRetryableErrorCode(error);
    if (isRetryable) {
      this.maxRetries--;
      if (this.maxRetries === 0) {
        throw error;
      }
      return this.shouldRetry(error);
    } else {
      throw error;
    }
  }

  private isRetryableErrorCode(error: Error): boolean {
    const errorCode = error.code || 0;
    return this.errorCodesToRetry.includes(errorCode);
  }
}
