// Function to validate the token signature using HMAC-SHA256
int validateSignature(struct TokenData* token) {
    // Generate the signing key from the shared secret
    const EVP_MD* evp = EVP_get_digestbyname("sha256");
    assert(evp != NULL);
    unsigned char* key = (unsigned char*)token->key;
    size_t keyLen = strlen(token->key);
    HMAC_CTX* hmac = HMAC_CTX_new();
    HMAC_Init_ex(hmac, key, keyLen, evp, NULL);

    // Generate the signing string from the token data
    char* signingString = generateSigningString(token);
    unsigned char* signingData = (unsigned char*)signingString;
    size_t signingDataLen = strlen(signingString);

    // Compute the HMAC of the signing string and compare with the token signature
    HMAC_Update(hmac, signingData, signingDataLen);
    unsigned int sigLen = 32;
    unsigned char* sig = (unsigned char*)malloc(sigLen);
    HMAC_Final(hmac, sig, &sigLen);
    HMAC_CTX_free(hmac);

    // Compare the token signature with the computed HMAC
    int result = 0;
    for (int i = 0; i < sigLen; ++i) {
        if (token->signature[i] != sig[i]) {
            result = -1;
            break;
        }
    }
    free(sig);
    free(signingString);
    return result;
}

