    // Concatenate the token ID, type, issuer, and subject
    char* signingString = malloc(strlen(token->id) + strlen(token->type) + strlen(token->issuer) + strlen(token->subject) + 1);
    snprintf(signingString, strlen(token->id) + strlen(token->type) + strlen(token->issuer) + strlen(token->subject) + 1, "%s.%s.%s.%s", token->id, token->type, token->issuer, token->subject);
    return signingString;
