#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <time.h>
#include <pthread.h>

// Define the maximum number of integers to process
#define MAX_INTEGERS 1000000

// Define the range for valid integers
#define MIN_VALUE -1000
#define MAX_VALUE 1000

// Define the logging interval in seconds
#define LOGGING_INTERVAL 10

// Struct to store the integer values and their counts
struct IntegerValues {
    int* values;
    int count;
};

// Function to validate an integer value within a range
int validateInteger(int value) {
    if (value < MIN_VALUE || value > MAX_VALUE) {
        return 0;
    }
    return 1;
}

// Function to read and process integers from standard input
void* readAndProcessIntegers() {
    struct IntegerValues* values = malloc(sizeof(struct IntegerValues));
    values->values = malloc(MAX_INTEGERS * sizeof(int));
    values->count = 0;

    int input;
    while (scanf("%d", &input) == 1) {
        if (!validateInteger(input)) {
            printf("Error: Invalid integer value %d\n", input);
            continue;
        }
        values->values[values->count++] = input;
    }

    return values;
}

// Function to log the maximum integer value and total count of valid integers
void logIntegerValues(struct IntegerValues* values) {
    if (values == NULL) {
        printf("Error: No values to log\n");
        return;
    }
    int maxValue = INT_MIN;
    for (int i = 0; i < values->count; i++) {
        if (values->values[i] > maxValue) {
            maxValue = values->values[i];
        }
    }
    printf("Maximum integer value: %d\n", maxValue);
    printf("Total count of valid integers: %d\n", values->count);
}

// Function to periodically log the integer values and total count to an external API
void* logAndSendIntegerValues() {
    struct IntegerValues* values = NULL;
    while (1) {
        values = readAndProcessIntegers();
        logIntegerValues(values);
        // Send the integer values and total count to an external API here
        free(values->values);
        free(values);
        sleep(LOGGING_INTERVAL);
    }
}

// Main function to read and process integers from standard input, validate, and log
int main() {
    // Create a multi-threaded environment for handling high input rates
    pthread_t thread1;
    pthread_create(&thread1, NULL, readAndProcessIntegers, NULL);
    pthread_t thread2;
    pthread_create(&thread2, NULL, logAndSendIntegerValues, NULL);

    // Join the threads to ensure correct execution order and memory management
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}

// Test cases for the program:
// - Input a single valid integer value (e.g., 5) and verify that it is stored in the array
// - Input multiple valid integer values (e.g., 1 2 3 4 5) and verify that they are stored in the array
// - Input an invalid integer value (-1000) and verify that an error message is printed
// - Test the logging functionality by inputting a single valid integer value, verifying that it is logged to the external API, and then verifying that the maximum integer value and total count of valid integers are correct
// - Test the multi-threaded approach by running multiple instances of the program in parallel and verifying that they do not interfere with each other']

