// Define the function to dynamically generate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
int generate_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **array, int n) {
    // Initialize the array of pointers to NULL
    for (int i = 0; i < n; i++) {
        array[i] = NULL;
    }

    // Allocate memory for each structure and initialize its fields
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            return -1;
        }
        pdu->rx_ue_information_tag = 0;
        pdu->rnti = 0;
        pdu->crc_indication_rel8_tag = 0;
        pdu->crcflag = false;
        array[i] = pdu;
    }

    // Randomly set the fields of each structure
    for (int i = 0; i < n; i++) {
        array[i]->rx_ue_information_tag = rand() % 256;
        array[i]->rnti = rand() % 65536;
        array[i]->crc_indication_rel8_tag = rand() % 65536;
        array[i]->crcflag = (rand() % 2 == 0) ? true : false;
    }

    // Store the populated structures in an SQLite database
    sqlite3 *db;
    char *errmsg;
    int rc;
    rc = sqlite3_open("example.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error: cannot open database: %s\n", sqlite3_errmsg(db));
        return -1;
    }
    for (int i = 0; i < n; i++) {
        char *query = "INSERT INTO nfapi_crc_indication_pdu VALUES(?, ?, ?, ?)";
        sqlite3_stmt *stmt;
        rc = sqlite3_prepare_v2(db, query, -1, &stmt, NULL);
        if (rc != SQLITE_OK) {
            fprintf(stderr, "Error: cannot prepare statement: %s\n", sqlite3_errmsg(db));
            return -1;
        }
        sqlite3_bind_int(stmt, 1, array[i]->rx_ue_information_tag);
        sqlite3_bind_int(stmt, 2, array[i]->rnti);
        sqlite3_bind_int(stmt, 3, array[i]->crc_indication_rel8_tag);
        sqlite3_bind_bool(stmt, 4, array[i]->crcflag);
        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            fprintf(stderr, "Error: cannot step statement: %s\n", sqlite3_errmsg(db));
            return -1;
        }
    }
    rc = sqlite3_finalize(stmt);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error: cannot finalize statement: %s\n", sqlite3_errmsg(db));
        return -1;
    }
    sqlite3_close(db);

    // Free the memory allocated for each structure
    for (int i = 0; i < n; i++) {
        free(array[i]);
    }

    return 0;
}
