using namespace std;

struct LogEntry {
    string filename;
    string message;
    int line_number;
    size_t byte_size;
    map<string, string> metadata;
};

class LogProcessor {
public:
    void process(const string& directory) {
        // Parse the directory and list all log files
        vector<LogEntry> entries;
        for (const auto& file : get_files(directory)) {
            LogEntry entry;
            entry.filename = file;
            parse_file(entry);
            entries.push_back(entry);
        }

        // Sort the log files by filename and line number
        sort(entries.begin(), entries.end(), [](const LogEntry& a, const LogEntry& b) {
            return a.filename < b.filename || (a.filename == b.filename && a.line_number < b.line_number);
        });

        // Group the log files by filename and line number
        map<string, vector<LogEntry>> grouped_entries;
        for (const auto& entry : entries) {
            grouped_entries[entry.filename].push_back(entry);
        }

        // Generate aggregated statistical reports
        for (const auto& file : grouped_entries) {
            generate_report(file.second);
        }
    }

private:
    void parse_file(LogEntry& entry) {
        // Open the log file and read its contents
        ifstream stream(entry.filename);
        string line;
        size_t line_number = 1;
        while (getline(stream, line)) {
            // Parse the log message and extract metadata fields
            parse_message(line, entry.metadata);

            // Increment the line number and byte size
            ++line_number;
            entry.byte_size += line.length();
        }
        stream.close();

        // Save the final line number and byte size
        entry.line_number = line_number;
    }

    void parse_message(const string& message, map<string, string>& metadata) {
        // Extract metadata fields from the log message
        for (const auto& field : get_metadata_fields()) {
            size_t pos = message.find(field);
            if (pos != string::npos) {
                metadata[field] = message.substr(pos + field.length());
            }
        }
    }

    void generate_report(const vector<LogEntry>& entries) {
        // Generate a statistical report for the log files
        map<string, size_t> counts;
        map<string, size_t> byte_sizes;
        for (const auto& entry : entries) {
            ++counts[entry.filename];
            byte_sizes[entry.filename] += entry.byte_size;
        }

        // Print the statistical report
        cout << "Filename: ";
        if (entries.size() > 1) {
            cout << "Multiple (" << entries.size() << ")";
        } else {
            cout << entries[0].filename;
        }
        cout << endl;
        cout << "Line Count: " << entries[0].line_number << endl;
        cout << "Byte Size: " << byte_sizes[entries[0].filename] << endl;
    }

    vector<string> get_metadata_fields() {
        // Return a list of metadata fields to extract from the log messages
        return {"Error Code", "Exception Type"};
    }
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        cout << "Usage: " << argv[0] << " <directory>" << endl;
        return 1;
    }

    // Create a new log processor instance
    LogProcessor processor;

    // Process the specified directory of log files
    processor.process(argv[1]);

    return 0;
}
