ioService_(),
entropyServiceClient_(ioService_, seed_),
thread_(&boost::asio::io_service::run, &ioService_),
isRunning_(true) {
fetchEntropyFromService();
}

SecureRandomSequenceGenerator::~SecureRandomSequenceGenerator() {
if (isInitialized()) {
    isRunning_ = false;
    thread_.join();
}
}

void SecureRandomSequenceGenerator::fetchEntropyFromService() {
entropyServiceClient_.asyncFetchEntropy([this](const boost::system::error_code& error) {
    if (!error) {
        updateSequenceCounters();
        evictCacheEntries();
    } else {
        handleRetry(error);
    }
});
}

