    double value;
};

// Define data structures to store and manage network data
class NetworkData {
private:
    map<int, vector<Message>> nodes; // Map of nodes to their received messages
    mutex nodesMutex; // Mutex for protecting nodes data structure
public:
    void addNode(int nodeId) {
        lock_guard<mutex> lock(nodesMutex);
        nodes[nodeId]; // Create new vector of messages for the node
    }
    void removeNode(int nodeId) {
        lock_guard<mutex> lock(nodesMutex);
        nodes.erase(nodeId); // Remove the node and its received messages
    }
    vector<Message>& getMessagesForNode(int nodeId) {
        lock_guard<mutex> lock(nodesMutex);
        return nodes[nodeId]; // Return the vector of messages for the node
    }
};

