// Define class to handle network health monitor requests
class NetworkHealthMonitorRequestHandler {
private:
    NetworkHealthMonitor monitor; // Instance of the network health monitor class
public:
    void handleRequest(string request) {
        vector<string> tokens = split(request, " "); // Split the request into tokens
        if (tokens[0] == "add_node") { // If the request is to add a new node
            int nodeId = stoi(tokens[1]); // Get the ID of the new node
            monitor.addNode(nodeId); // Add the new node to the network
        } else if (tokens[0] == "remove_node") { // If the request is to remove a node from the network
            int nodeId = stoi(tokens[1]); // Get the ID of the node to be removed
            monitor.removeNode(nodeId); // Remove the node from the network
        } else if (tokens[0] == "update_status") { // If the request is to update the provider status of a node
            int nodeId = stoi(tokens[1]); // Get the ID of the node whose status is being updated
            string status = tokens[2]; // Get the new status of the node
            monitor.updateNodeStatus(nodeId, status); // Update the provider status of the node
        } else if (tokens[0] == "get_status") { // If the request is to get the provider status of a node
            int nodeId = stoi(tokens[1]); // Get the ID of the node whose status is being requested
            string status = monitor.getNodeStatus(nodeId); // Get the current provider status of the node
        } else if (tokens[0] == "update_usage") { // If the request is to update the storage usage of a node
            int nodeId = stoi(tokens[1]); // Get the ID of the node whose usage is being updated
            string usage = tokens[2]; // Get the new storage usage of the node
