use rustc_serialize::json::Json;
use reqwest::Client;

struct ApiService {
    url: String,
    method: String,
    headers: HashMap<String, String>,
}

impl ApiService {
    fn new(url: &str) -> Self {
        ApiService {
            url: url.to_string(),
            method: "GET".to_string(),
            headers: Default::default()
        }
    }

    fn set_method(&mut self, method: &str) -> &mut Self {
        self.method = method.to_string();
        self
    }

    fn add_header(&mut self, key: &str, value: &str) -> &mut Self {
        self.headers.insert(key.to_string(), value.to_string());
        self
    }

    fn send(&self) -> Result<Json, String> {
        let client = Client::new();
        let mut response = client
            .request(self.method.as_str(), &self.url)
            .headers(self.headers.clone())
            .send()?;

        if !response.status().is_success() {
            return Err(format!("Failed to send request: {}", response.text()?));
        }

        let json = response.json();
        Ok(json)
    }
}
