        public EventHandler(EventHubConfiguration configuration)
        {
            _configuration = configuration;
            _eventSources = new IEventSource[configuration.DataSources.Length];
            for (int i = 0; i < _eventSources.Length; i++)
            {
                var dataSource = configuration.DataSources[i];
                var eventSource = dataSource switch
                {
                    "primary" => new PrimaryEventSource(dataSource),
                    "secondary" => new SecondaryEventSource(dataSource),
                    _ => throw new ArgumentException("Unknown data source", nameof(dataSource)),
