#[derive(Clone, Debug, Deserialize)]
pub struct ThemeCache {
    themes: HashMap<String, Arc<RwLock<Theme>>>,
}

impl ThemeCache {
    pub fn new() -> Self {
        Self {
            themes: Default::default(),
        }
    }

    pub async fn get_theme(&self, theme_id: &str) -> Result<Arc<RwLock<Theme>>> {
        let mut lock = self.themes.write().await;
        if let Some(theme) = lock.get(theme_id) {
            return Ok(theme.clone());
        }

        let theme = block_on(fetch_theme(theme_id))?;
        lock.insert(theme_id.to_owned(), Arc::new(RwLock::new(theme)));

        Ok(lock[theme_id].clone())
    }
}

