Here's an example implementation of a modular C++ library for managing a dynamically scalable octree data structure that integrates with an external SQL database for persistent storage:
```c++
#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <unordered_map>
#include <chrono>

using namespace std;

// Forward declaration of the octree node class
class OctreeNode;

// Declaration of the octree class
class Octree {
private:
  // Map to store all the nodes in the octree
  unordered_map<string, shared_ptr<OctreeNode>> nodes_;

  // Vector to store the split thresholds for each dimension
  vector<int> split_thresholds_;

  // The depth of the octree
  int depth_;

  // The size of the octree
  int size_;

  // The maximum number of nodes in the octree
  int max_nodes_;

public:
  // Constructor to initialize the octree
  Octree(int max_nodes, vector<int> split_thresholds) :
    max_nodes_(max_nodes), split_thresholds_(split_thresholds) {}

  // Destructor to free the memory of the nodes in the octree
  ~Octree() {
    for (auto& node : nodes_) {
      delete node.second;
    }
  }

  // Insert a new node into the octree
  void insert(const string& id, const vector<int>& coordinates) {
    if (nodes_.size() >= max_nodes_) {
      return;
    }

    // Calculate the depth of the node based on the split thresholds
    int depth = calculateDepth(coordinates);

    // Create a new node and add it to the octree
    shared_ptr<OctreeNode> node = make_shared<OctreeNode>(id, coordinates, depth);
    nodes_.insert(make_pair(id, node));
  }

  // Search for a node in the octree by its ID
  shared_ptr<OctreeNode> search(const string& id) {
    auto it = nodes_.find(id);
    if (it != nodes_.end()) {
      return it->second;
    } else {
      return nullptr;
    }
  }

  // Remove a node from the octree by its ID
  void remove(const string& id) {
    auto it = nodes_.find(id);
    if (it != nodes_.end()) {
      nodes_.erase(it);
    }
  }

private:
  // Calculate the depth of a node based on its coordinates and split thresholds
  int calculateDepth(const vector<int>& coordinates) const {
    int depth = 0;
    for (int i = 0; i < coordinates.size(); ++i) {
      if (coordinates[i] >= split_thresholds_[i]) {
        ++depth;
      }
    }
    return depth;
  }
};

// Class to represent an octree node
class OctreeNode {
private:
  // The ID of the node
  string id_;

  // The coordinates of the node
  vector<int> coordinates_;

  // The depth of the node in the octree
  int depth_;

public:
  // Constructor to initialize an octree node with its ID and coordinates
  OctreeNode(const string& id, const vector<int>& coordinates, int depth) :
    id_(id), coordinates_(coordinates), depth_(depth) {}

  // Getter for the ID of the node
  const string& getId() const { return id_; }

  // Getter for the coordinates of the node
  const vector<int>& getCoordinates() const { return coordinates_; }

  // Getter for the depth of the node in the octree
  int getDepth() const { return depth_; }
};
```
This implementation includes the following features:

