// Add a NAS message to the hash table
void napi_add_message(NFAPI_CRC_INDICATION_PDU_T* message) {
  // Lock the mutex before modifying the hash table
  pthread_mutex_lock(&nas_messages->mutex);

  // Add the NAS message to the hash table
  add_to_hash_table(nas_messages, message);

  // Unlock the mutex after modifying the hash table
  pthread_mutex_unlock(&nas_messages->mutex);
}

// Remove a NAS message from the hash table
void napi_remove_message(NFAPI_CRC_INDICATION_PDU_T* message) {
  // Lock the mutex before modifying the hash table
  pthread_mutex_lock(&nas_messages->mutex);

  // Remove the NAS message from the hash table
  remove_from_hash_table(nas_messages, message);

  // Unlock the mutex after modifying the hash table
  pthread_mutex_unlock(&nas_messages->mutex);
}

// Get a NAS message from the hash table
NFAPI_CRC_INDICATION_PDU_T* napi_get_message(char* nas_msg_id) {
  // Lock the mutex before accessing the hash table
  pthread_mutex_lock(&nas_messages->mutex);

  // Get the NAS message from the hash table
  NFAPI_CRC_INDICATION_PDU_T* message = get_from_hash_table(nas_messages, nas_msg_id);

  // Unlock the mutex after accessing the hash table
  pthread_mutex_unlock(&nas_messages->mutex);

  return message;
}

// Release resources allocated for a NAS message
void napi_release_message(NFAPI_CRC_INDICATION_PDU_T* message) {
  // Free the NAS message structure and its contents
