const int DEFAULT_QUALITY = 7; // Default quality setting for transcoding
const int MIN_QUALITY = 1; // Minimum quality setting for transcoding
const int MAX_QUALITY = 10; // Maximum quality setting for transcoding
const int QUALITY_STEP = 2; // Quality step for adaptive bitrate transcoding

// Global variables
