int init_video_metadata();
int load_task_queue();
int create_threads();
int start_processing();
int process_video_tasks();
int update_video_metadata();
int delete_video_metadata();
int clear_task_queue();
void log_error(std::string error);

int main() {
    // Initialize video metadata and load task queue from the Kubernetes API
    if (init_video_metadata()) {
        std::cout << "Error initializing video metadata" << std::endl;
        return 1;
    }
    if (load_task_queue()) {
        std::cout << "Error loading task queue" << std::endl;
        return 1;
    }

    // Create worker threads for processing videos
    if (create_threads()) {
        std::cout << "Error creating worker threads" << std::endl;
        return 1;
    }

    // Start processing videos in the task queue
    if (start_processing()) {
        std::cout << "Error starting video processing" << std::endl;
        return 1;
    }

    // Process video tasks until the task queue is empty or an error occurs
    while (process_video_tasks());

    // Update video metadata and clear the task queue
    update_video_metadata();
    delete_video_metadata();
    clear_task_queue();

    return 0;
}

void* process_video(void* arg) {
    std::string video_id = (std::string)arg;
    int error_count = 0;

    // Check if the video ID is valid and has metadata
    if (!video_metadata.contains(video_id)) {
        log_error("Invalid video ID: " + video_id);
        return NULL;
    }

    // Get the video metadata for the current video ID
    std::string video_path = video_metadata[video_id];
    std::string video_quality = video_metadata["quality"];
    int video_size = video_metadata["size"];

    // Check if the video is larger than the maximum size allowed
    if (video_size > MAX_VIDEO_SIZE) {
        log_error("Video ID " + video_id + " is too large (" + std::to_string(video_size) + " bytes)");
        return NULL;
    }

    // Check if the delivery protocol is supported
    if (!std::any_of(DELIVERY_PROTOCOLS.begin(), DELIVERY_PROTOCOLS.end(), [&](const std::string& delivery_protocol) { return delivery_protocol == video_metadata["delivery"]; })) {
        log_error("Delivery protocol " + video_metadata["delivery"] + " is not supported");
        return NULL;
    }

    // Check if the quality setting is valid
    int quality = std::stoi(video_quality);
    if (quality < MIN_QUALITY || quality > MAX_QUALITY) {
        log_error("Invalid quality setting for video ID " + video_id + ": " + video_quality);
        return NULL;
    }

    // Transcode the video based on the quality setting
    std::string transcoded_video_path = "";
    if (quality == DEFAULT_QUALITY) {
        // Use default quality for transcoding
        transcoded_video_path = video_metadata["transcoded"];
    } else if (quality % QUALITY_STEP == 0 && quality > MIN_QUALITY) {
        // Use lower quality for transcoding if the quality step is met
        int new_quality = quality - QUALITY_STEP;
        transcoded_video_path = video_metadata["transcoded_" + std::to_string(new_quality)];
    } else {
        // Use the highest available quality for transcoding
        int new_quality = MAX_QUALITY;
        transcoded_video_path = video_metadata["transcoded_" + std::to_string(new_quality)];
    }

    // Transcode the video based on the transcoded path
    if (transcoded_video_path != "") {
        // Get the output file path for the transcoded video
        std::string output_file = get_output_file_path(transcoded_video_path);

        // Create the transcoding parameters and start the transcoder
        TranscodingParameters params;
        params.input_file = video_path;
        params.output_file = output_file;
        Transcoder transcoder;
        if (transcoder.start(params)) {
            log_error("Error starting transcoder for video ID " + video_id);
            return NULL;
        }

        // Wait for the transcoder to complete and delete the original file
        while (transcoder.isRunning()) {
            sleep(1);
        }
        if (!delete_original_file(video_path)) {
            log_error("Error deleting original file for video ID " + video_id);
            return NULL;
        }
    }

    // Update the video metadata and delete the old transcoded files
    update_video_metadata();
    delete_transcoded_files(video_id, video_size);

    // Return success if no errors occurred during processing
    if (error_count == 0) {
        return NULL;
    } else {
        log_error("Errors encountered while processing video ID " + video_id);
        return NULL;
    }
}

int init_video_metadata() {
    // Initialize the video metadata from the Kubernetes API
    std::string video_metadata = kubernetes.getVideoMetadata();
    if (video_metadata == "") {
        return 1;
    }

    // Parse the video metadata and load it into a map
    std::vector<std::string> lines = split(video_metadata, "\n");
    for (int i = 0; i < lines.size(); i++) {
        std::vector<std::string> fields = split(lines[i], ": ");
        if (fields.size() == 2) {
            video_metadata[fields[0]] = fields[1];
        }
    }

    return 0;
}

int load_task_queue() {
    // Load the task queue from the Kubernetes API
    std::string task_queue = kubernetes.getTaskQueue();
    if (task_queue == "") {
        return 1;
    }

    // Split the task queue into individual video IDs and add them to the queue
    std::vector<std::string> tasks = split(task_queue, "\n");
    for (int i = 0; i < tasks.size(); i++) {
        if (tasks[i] != "") {
            task_queue.push_back(tasks[i]);
        }
    }

    return 0;
}

int create_threads() {
    // Create worker threads for processing videos
    for (int i = 0; i < thread_pool.size(); i++) {
        pthread_create(&thread_pool[i], NULL, process_video, NULL);
    }

    return 0;
}

int start_processing() {
    // Start processing videos in the task queue
    current_task = 0;
    is_processing = true;

    return 0;
}

int process_video_tasks() {
    // Process the next video in the queue if one exists
    if (is_processing && current_task < task_queue.size()) {
        std::string video_id = task_queue[current_task];
        pthread_create(&thread_pool[i], NULL, process_video, (void *)&video_id);
        current_task++;
    }

    return 0;
}

int update_video_metadata() {
    // Update the video metadata in the Kubernetes API with the new transcoded path
    std::string updated_video_metadata = kubernetes.getVideoMetadata();
    if (updated_video_metadata == "") {
        return 1;
    }

    // Parse the updated video metadata and load it into a map
    std::vector<std::string> lines = split(updated_video_metadata, "\n");
    for (int i = 0; i < lines.size(); i++) {
        std::vector<std::string> fields = split(lines[i], ": ");
        if (fields.size() == 2) {
            updated_video_metadata[fields[0]] = fields[1];
        }
    }

    return 0;
}

int delete_transcoded_files(std::string video_id, std::string video_size) {
    // Delete the transcoded files for a specific video and size
    if (video_id == "" || video_size == "") {
        return 1;
    }

    // Get the file path prefix for the transcoded files
    std::string file_path_prefix = get_file_path_prefix(video_id, video_size);
    if (file_path_prefix == "") {
        return 1;
    }

    // Delete the transcoded files that match the file path prefix
    for (int i = 0; i < transcoded_files.size(); i++) {
        std::string file_path = transcoded_files[i];
        if (file_path.find(file_path_prefix) != std::string::npos) {
            delete_file(file_path);
        }
    }

    return 0;
}
