import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FaultTolerantJavaApplication {
    private static final int NUM_THREADS = 10;
    private static final long DEFAULT_TIMEOUT = TimeUnit.SECONDS.toMillis(30);
    private static final int MAX_RETRIES = 5;
    private static final int MIN_BACKOFF = TimeUnit.MILLISECONDS.toSeconds(100);
    private static final int MAX_BACKOFF = TimeUnit.MINUTES.toMillis(5);

    public static void main(String[] args) throws InterruptedException {
        BlockingQueue<Runnable> queue = new ArrayBlockingQueue<>(NUM_THREADS);
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS, r -> {
            Thread thread = new Thread(r);
            thread.setName("TaskProcessor");
            return thread;
        });

        while (true) {
            Runnable task = queue.take();
            if (task != null) {
                executor.execute(task);
            } else {
                break;
            }
        }
    }

    private static class TaskProcessor implements Runnable {
        private final BlockingQueue<Runnable> queue;
        private final int retries;
        private final long timeout;

        public TaskProcessor(BlockingQueue<Runnable> queue, int retries, long timeout) {
            this.queue = queue;
            this.retries = retries;
            this.timeout = timeout;
        }

        @Override
        public void run() {
            while (true) {
                try {
                    Runnable task = queue.poll(DEFAULT_TIMEOUT, TimeUnit.MILLISECONDS);
                    if (task == null) {
                        break;
                    }

                    // process task
                    for (int i = 0; i < retries; i++) {
                        try {
                            task.run();
                            return;
                        } catch (Exception e) {
                            if (i == retries - 1) {
                                // handle error
                            } else {
                                long delay = Math.min(MIN_BACKOFF, MAX_BACKOFF * Math.pow(2, i));
                                TimeUnit.MILLISECONDS.sleep(delay);
                            }
                        }
                    }
                } catch (InterruptedException e) {
                    // handle interrupt
                }
            }
        }
    }
}
