import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.connect.data.Schema;
import org.apache.kafka.connect.data.Struct;
import org.apache.kafka.connect.source.SourceRecord;
import org.apache.kafka.connect.transforms.util.RegexValidators;
import org.apache.kafka.streams.KeyValue;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.Topology;
import org.apache.kafka.streams.kstream.*;
import org.apache.kafka.streams.state.Stores;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FinancialMarketDataProcessor {
  private static final Logger logger = LoggerFactory.getLogger(FinancialMarketDataProcessor.class);

  public void start() throws Exception {
    // Set up Kafka consumer for WebSocket APIs and message queues
    KafkaConsumer<String, String> consumer = new KafkaConsumer<>(new HashMap<>() {{
      put("bootstrap.servers", "localhost:9092");
      put("group.id", "market-data-processor");
      put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
      put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
    }});

    // Set up Kafka producer for PostgreSQL database stream
    KafkaProducer<String, String> producer = new KafkaProducer<>(new HashMap<>() {{
      put("bootstrap.servers", "localhost:9092");
      put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
      put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
    }});

    // Set up Kafka Streams topology for financial market data processing
    StreamsBuilder streamsBuilder = new StreamsBuilder();
    Topology topology = streamsBuilder.newTopology()
      .addSource("market-data", "websocket-api", "message-queue")
      .addProcessor("process-market-data", () -> {
        return new Processor<>() {
          private final KafkaProducer<String, String> producer;

          public Processor(KafkaProducer<String, String> producer) {
            this.producer = producer;
          }

          @Override
          public void init(ProcessorContext context) {}

          @Override
          public void process(ConsumerRecord<String, String> record) {
            // Deserialize market data from JSON string to a Java object
            ObjectMapper mapper = new ObjectMapper();
            try {
              MarketData marketData = mapper.readValue(record.value(), MarketData.class);
              // Validate the market data against a set of predefined rules
              List<String> errors = validateMarketData(marketData);
              if (errors.size() > 0) {
                throw new RuntimeException("Invalid market data: " + String.join(", ", errors));
              }
              // Process the market data and send to PostgreSQL database stream
              producer.send(new ProducerRecord<>("market-data-stream", marketData.getTimestamp(), mapper.writeValueAsString(marketData)));
            } catch (JsonProcessingException e) {
              logger.error("Failed to deserialize market data: {}", record.value());
            } catch (RuntimeException e) {
              logger.error("Invalid market data: {}", record.value(), e);
            }
          }
        };
      }, "process-market-data")
      .addSink("send-to-database", "postgresql-stream");

    // Set up Kafka Streams topology for financial analytics and modeling
    Topology financialAnalyticsTopology = streamsBuilder.newTopology()
      .addSource("market-data-stream")
      .addProcessor("process-analytics", () -> {
        return new Processor<>() {
          @Override
          public void init(ProcessorContext context) {}

          @Override
          public void process(ConsumerRecord<String, String> record) {
            // Deserialize market data from JSON string to a Java object
            ObjectMapper mapper = new ObjectMapper();
            try {
              MarketData marketData = mapper.readValue(record.value(), MarketData.class);
              // Perform advanced analytics and modeling on the market data, such as pattern recognition and predictive modeling
              List<KeyValue<String, String>> results = performAnalyticsAndModeling(marketData);
              // Send the results to a Kafka topic for further processing or storage
              producer.send(new ProducerRecord<>("analytics-results", mapper.writeValueAsString(results)));
            } catch (JsonProcessingException e) {
              logger.error("Failed to deserialize market data: {}", record.value());
            }
          }
        };
      }, "process-analytics")
      .addSink("send-to-database", "postgresql-stream");

    // Start the Kafka Streams instances
    streamsBuilder.build().start();
  }
}
```

In this example, we have defined a `FinancialMarketDataProcessor` class that starts two Kafka Streams instances to process financial market data from WebSocket APIs and message queues, and perform advanced analytics and modeling on the market data before sending the results to a PostgreSQL database stream.

The `start()` method of the `FinancialMarketDataProcessor` class sets up two Kafka consumers for reading from WebSocket APIs and message queues, and one Kafka producer for writing to the PostgreSQL database stream. It also sets up two Kafka Streams topologies for processing financial market data and performing advanced analytics and modeling, respectively.

