using Microsoft.AspNetCore.Identity;

// Configure validation options for user accounts
services.Configure<IdentityOptions>(options =>
{
    // Set minimum password length to 8 characters
    options.Password.RequiredLength = 8;

    // Enable password complexity checks
    options.Password.RequireUppercase = true;
    options.Password.RequireLowercase = true;
    options.Password.RequireDigit = true;
    options.Password.RequireNonAlphanumeric = true;

    // Set maximum length of username to 20 characters
    options.User.AllowedUserNameCharacters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890-_.";
    options.User.MaxLength = 20;
});

// Configure user lockout defaults
services.Configure<IdentityOptions>(options =>
{
    // Set maximum number of failed login attempts before account is locked
    options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(5);
    options.Lockout.MaxFailedAccessAttemptsBeforeLockout = 10;
});
```
