    public class StorageClient
    {
        private readonly IConfiguration _configuration;

        public StorageClient(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public async Task<string> UploadFileAsync(string filePath, string containerName)
        {
            var storageProvider = GetStorageProvider();
            return await storageProvider.UploadFileAsync(filePath, containerName);
        }

        public async Task DownloadFileAsync(string filePath, string containerName)
        {
            var storageProvider = GetStorageProvider();
            await storageProvider.DownloadFileAsync(filePath, containerName);
        }

        public async Task DeleteFileAsync(string filePath, string containerName)
        {
            var storageProvider = GetStorageProvider();
            await storageProvider.DeleteFileAsync(filePath, containerName);
        }

        private ICloudStorageProvider GetStorageProvider()
        {
            var storageProviderType = _configuration["StorageProvider"];
            if (string.IsNullOrEmpty(storageProviderType))
                throw new ArgumentException("Invalid Storage Provider Type");

            var services = new ServiceCollection();
            services.AddTransient<ICloudStorageProvider, S3CloudStorageProvider>();
            services.AddTransient<ICloudStorageProvider, GoogleCloudStorageProvider>();
            services.AddTransient<ICloudStorageProvider, AzureBlobStorageProvider>();

            var serviceProvider = services.BuildServiceProvider();
