#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

// Structure to store TLS configuration and credentials
typedef struct tls_config {
    SSL_CTX* ctx;
    char* ca_file;
    char* cert_file;
    char* key_file;
} tls_config;

// Function to initialize the TLS configuration from a given file
int init_tls_config(const char* filename, tls_config* config) {
    // Load the certificate authority (CA) and server certificate files
    SSL_CTX* ctx = SSL_CTX_new(TLSv1_2_client_method());
    if (!ctx) {
        fprintf(stderr, "Failed to create new SSL context\n");
        return -1;
    }
    config->ctx = ctx;

    // Load the CA and server certificate files
    X509* ca = NULL;
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open %s\n", filename);
        SSL_CTX_free(ctx);
        return -1;
    }
    while ((ca = PEM_read_X509(file, NULL, NULL, NULL))) {
        if (!SSL_CTX_add_client_CA(ctx, ca)) {
            fprintf(stderr, "Failed to add CA certificate\n");
            X509_free(ca);
            SSL_CTX_free(ctx);
            return -1;
        }
    }
    if (!SSL_CTX_use_certificate_file(ctx, filename, SSL_FILETYPE_PEM)) {
        fprintf(stderr, "Failed to load server certificate\n");
        SSL_CTX_free(ctx);
        return -1;
    }
    if (!SSL_CTX_use_PrivateKey_file(ctx, filename, SSL_FILETYPE_PEM)) {
        fprintf(stderr, "Failed to load private key\n");
        SSL_CTX_free(ctx);
        return -1;
    }
    if (!SSL_CTX_check_private_key(ctx)) {
        fprintf(stderr, "Private key does not match the certificate public key\n");
        SSL_CTX_free(ctx);
        return -1;
    }

    // Load any intermediate CA certificates
    char* ca_file = NULL;
    if ((ca_file = getenv("CA_FILE"))) {
        FILE* file = fopen(ca_file, "r");
        if (!file) {
            fprintf(stderr, "Failed to open CA certificate file %s\n", ca_file);
            SSL_CTX_free(ctx);
            return -1;
        }
        while ((ca = PEM_read_X509(file, NULL, NULL, NULL))) {
            if (!SSL_CTX_add_client_CA(ctx, ca)) {
                fprintf(stderr, "Failed to add CA certificate\n");
                X509_free(ca);
                SSL_CTX_free(ctx);
                return -1;
            }
        }
    }

    // Load the client certificate and private key files
    char* cert_file = NULL;
    if ((cert_file = getenv("CERT_FILE"))) {
        SSL_CTX_use_certificate_file(ctx, cert_file, SSL_FILETYPE_PEM);
    }
    char* key_file = NULL;
    if ((key_file = getenv("KEY_FILE"))) {
        SSL_CTX_use_PrivateKey_file(ctx, key_file, SSL_FILETYPE_PEM);
    }

    config->ca_file = ca_file;
    config->cert_file = cert_file;
    config->key_file = key_file;

    return 0;
}

// Function to create a new TLS connection and set up the session ticket cache
SSL* init_tls_connection(const char* hostname, tls_config* config) {
    SSL* ssl = SSL_new(config->ctx);
    if (!ssl) {
        fprintf(stderr, "Failed to create new SSL connection\n");
        return NULL;
    }
    if (SSL_set_fd(ssl, hostname) == 0) {
        fprintf(stderr, "Failed to set SSL file descriptor\n");
        SSL_free(ssl);
        return NULL;
    }

    // Set up the session ticket cache
    SSL_CTX* ctx = SSL_get_SSL_CTX(ssl);
    SSL_CTX_sess_set_new_cb(ctx, [](SSL* ssl, const unsigned char* key) {
        printf("Received new TLS session ticket\n");
        return 1;
    });
    SSL_CTX_sess_set_get_cb(ctx, [](SSL* ssl, const unsigned char* key, int len) {
        printf("Retrieved TLS session ticket\n");
        return 1;
    });
    SSL_CTX_sess_set_remove_cb(ctx, [](SSL* ssl, const unsigned char* key) {
        printf("Removed TLS session ticket\n");
        return 1;
    });

    return ssl;
}

// Function to send a message over the TLS connection and handle errors
int tls_send(SSL* ssl, const void* data, size_t len) {
    if (SSL_write(ssl, data, len) <= 0) {
        fprintf(stderr, "Failed to write data to TLS connection\n");
        return -1;
    }
    return 0;
}

// Function to receive a message over the TLS connection and handle errors
int tls_recv(SSL* ssl, void* data, size_t len) {
    if (SSL_read(ssl, data, len) <= 0) {
        fprintf(stderr, "Failed to read data from TLS connection\n");
        return -1;
    }
    return 0;
}

// Function to close the TLS connection and free resources
void tls_close(SSL* ssl) {
    SSL_free(ssl);
}
```

This code uses the `openssl` library to create a new TLS session and send/receive messages over it. It also sets up the session ticket cache to enable session resumption. The `init_tls_connection` function takes the hostname of the server as an argument and returns a new SSL object, which can be used to send/receive data over the connection. The `tls_send` and `tls_recv` functions handle sending and receiving data over the connection, respectively. Finally, the `tls_close` function frees resources associated with the TLS connection.

Note that this code uses a callback function to set up the session ticket cache, which allows for easy customization of the session ticket behavior. The callback functions are passed as arguments to the `SSL_CTX_sess_set_{new,get,remove}_cb` functions, respectively. In this case, we're simply printing messages when a new session ticket is received or retrieved from the cache, but you could easily modify these functions to perform more complex actions such as storing and reusing session tickets for later use.

You can use this code in conjunction with the `tls_client` example to test out TLS session resumption. Simply replace the hardcoded hostname in the client code with the hostname of the server you're testing against, and run both examples using the same command line arguments (e.g., `-a` for IPv4 and `-b` for IPv6). If everything is working correctly, you should see a message printed when the client receives a new session ticket from the server during the initial connection attempt.']

