// C# Service for Managing User Authentication Tokens
using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using Serilog;
using Serilog.Core;
using Serilog.Events;
using Serilog.Sinks.File;
using StackExchange.Redis;

namespace UserAuthenticationTokenService
{
    public class UserAuthenticator
    {
        private static IConfiguration _configuration;
        private static ILogger _logger;
        private static IDatabase _redisDb;
        private static ConnectionMultiplexer _connection;
        private static string _tokenPrefix = "user_auth_token:";

        public UserAuthenticator(IConfiguration configuration, ILogger<UserAuthenticator> logger)
        {
            _configuration = configuration;
            _logger = logger;

            // Initialize Redis connection and database
            _connection = ConnectionMultiplexer.Connect(_configuration["RedisConnectionString"]);
            _redisDb = _connection.GetDatabase();

            // Set up Serilog logging
            Log.Logger = new LoggerConfiguration()
                .MinimumLevel.Debug()
                .WriteTo.File(new SelfLoggingSink(), rollingInterval: RollingInterval.Day)
                .CreateLogger();
        }

        public async Task<string> GetTokenForUserAsync(int userId)
        {
            try
            {
                // Check if token exists in Redis cache
                string token = await _redisDb.StringGetAsync($"{_tokenPrefix}{userId}");
                if (token != null)
                {
                    return token;
                }

                // Generate new token and add it to the cache
                token = Guid.NewGuid().ToString();
                await _redisDb.StringSetAsync($"{_tokenPrefix}{userId}", token);

                return token;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to get user authentication token for user ID {0}.", userId);
                throw;
            }
        }

        public async Task<string> RefreshTokenAsync(int userId, string token)
        {
            try
            {
                // Check if token exists in Redis cache
                string cachedToken = await _redisDb.StringGetAsync($"{_tokenPrefix}{userId}");
                if (cachedToken == null || cachedToken != token)
                {
                    return null;
                }

                // Generate new token and add it to the cache
                string newToken = Guid.NewGuid().ToString();
                await _redisDb.StringSetAsync($"{_tokenPrefix}{userId}", newToken);

                return newToken;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to refresh user authentication token for user ID {0}.", userId);
                throw;
            }
        }

        public async Task<bool> InvalidateTokenAsync(int userId, string token)
        {
            try
            {
                // Check if token exists in Redis cache
                string cachedToken = await _redisDb.StringGetAsync($"{_tokenPrefix}{userId}");
                if (cachedToken == null || cachedToken != token)
                {
                    return false;
                }

                // Remove token from the cache and return true
                await _redisDb.KeyDeleteAsync($"{_tokenPrefix}{userId}");
                return true;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to invalidate user authentication token for user ID {0}.", userId);
                throw;
            }
        }
    }
}']

