#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>

// Define encryption modes and parameters
const int AES_MODE = EVP_aes_256_cbc();
const int KEY_LEN = 32; // bytes
const int IV_LEN = 16; // bytes
const int TAG_LEN = 16; // bytes

// Define encryption and decryption functions
int encrypt(unsigned char* plaintext, unsigned char* ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;

    // Set up encryption context
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        return -1;
    }

    // Initialize encryption operation
    if (EVP_EncryptInit_ex(ctx, AES_MODE, NULL, NULL, NULL) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -2;
    }

    // Set key and IV
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_KEY, KEY_LEN, plaintext) <= 0 ||
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_IV, IV_LEN, ciphertext) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -3;
    }

    // Encrypt plaintext
    if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, KEY_LEN) <= 0 ||
            EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -4;
    }

    // Get tag
    unsigned char tag[TAG_LEN];
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, TAG_LEN, tag) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -5;
    }

    // Free context and return success
    EVP_CIPHER_CTX_free(ctx);
    memcpy(ciphertext + len, tag, TAG_LEN);
    return len + TAG_LEN;
}

int decrypt(unsigned char* ciphertext, unsigned char* plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;

    // Set up encryption context
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        return -1;
    }

    // Initialize decryption operation
    if (EVP_DecryptInit_ex(ctx, AES_MODE, NULL, NULL, NULL) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -2;
    }

    // Set key and IV
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_KEY, KEY_LEN, ciphertext) <= 0 ||
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_IV, IV_LEN, ciphertext) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -3;
    }

    // Decrypt ciphertext
    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, KEY_LEN + TAG_LEN) <= 0 ||
            EVP_DecryptFinal_ex(ctx, plaintext + len, &len) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -4;
    }

    // Free context and return success
    EVP_CIPHER_CTX_free(ctx);
    return len;
}
```
