#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Memory pool structure for efficient memory management
struct mempool {
  size_t poolsize;    // Size of the pool in bytes
  void *poolptr;      // Pointer to the pool
  pthread_mutex_t lock; // Lock for protecting access to the pool
};

// Record structure for storing data
struct record {
  long offset;  // Offset for retrieving data from an external source
  int key;     // Key used for sorting and searching
  int value;   // Value associated with the key
};

// Function to allocate memory for records
void* alloc_record(size_t size) {
  void *ptr = NULL;

  // Allocate memory from the custom memory pool
  struct mempool *mempool = get_memory_pool();
  pthread_mutex_lock(&mempool->lock);
  ptr = malloc(size);
  if (ptr == NULL) {
    // Log error message and return NULL on failure
    fprintf(stderr, "Error: failed to allocate memory for records\n");
    pthread_mutex_unlock(&mempool->lock);
    return NULL;
  }

  // Update the pool size and pointer
  mempool->poolsize += size;
  mempool->poolptr = ptr;

  // Unlock the lock and return the allocated memory
  pthread_mutex_unlock(&mempool->lock);
  return ptr;
}

// Function to deallocate memory for records
void dealloc_record(void *ptr) {
  struct mempool *mempool = get_memory_pool();
  pthread_mutex_lock(&mempool->lock);

  // Check if the pointer is within the pool range
  if (ptr >= mempool->poolptr && ptr < mempool->poolptr + mempool->poolsize) {
    // Update the pool size and pointer
    mempool->poolsize -= (char *)ptr - (char *)mempool->poolptr;
    mempool->poolptr = ptr;
  } else {
    // Log error message and return if the pointer is outside of the pool range
    fprintf(stderr, "Error: failed to deallocate memory for records\n");
  }

  // Unlock the lock and free the memory
  pthread_mutex_unlock(&mempool->lock);
  free(ptr);
}

// Function to initialize the record array
void init_record_array(struct record **arr, size_t n) {
  for (size_t i = 0; i < n; i++) {
    // Allocate memory for each record using the custom allocator
    struct record *ptr = alloc_record(sizeof(struct record));
    if (ptr == NULL) {
      // Log error message and return if allocation fails
      fprintf(stderr, "Error: failed to allocate memory for records\n");
      return;
    }

    // Initialize the key and value for each record
    ptr->key = rand() % 10 + 1;
    ptr->value = rand();

    // Add the pointer to the array
    arr[i] = ptr;
  }
}

// Function to sort the record array using insertion sort
void sort_record_array(struct record **arr, size_t n) {
  for (size_t i = 1; i < n; i++) {
    // Insert the current element into the sorted portion of the array
    struct record *current = arr[i];
    size_t j = i - 1;
    while (j >= 0 && arr[j]->key > current->key) {
      arr[j + 1] = arr[j];
