Record* get_records(int n, int min, int max) {
    // check if n is within range and if min and max are valid
    if (n <= 0 || n > MAX_RECORDS || min < MIN_KEY || max > MAX_KEY) {
        return NULL;
    }

    // allocate memory for n records, using a thread-local cache or memory pool if available
    Record* records = (Record*)malloc(sizeof(Record) * n);
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for %d records\n", n);
