        records[i].offset = i;
        records[i].key = rand() % (max - min + 1) + min;
    }

    return records;
}

// function to sort the retrieved records based on their keys using insertion sort or a more complex algorithm
void sort_records(Record* records, int n) {
    // check if there are any records to be sorted
    if (!records || n <= 0) {
        return;
    }

    // use insertion sort for small datasets and quicksort/mergesort for larger ones
    if (n < 15) {
        insertion_sort(records, n);
    } else {
        quicksort(records, 0, n - 1);
    }
}

// function to free the memory allocated by get_records() and sort_records()
void free_records(Record* records) {
    // check if there are any records to be freed
    if (!records) {
        return;
    }

    free(records);
}

// function to perform insertion sort on the given range of records
void insertion_sort(Record* records, int n) {
    // check if there are any records to be sorted
    if (!records || n <= 0) {
        return;
    }

    for (int i = 1; i < n; ++i) {
        Record temp = records[i];
        int j = i - 1;
        while (j >= 0 && temp.key < records[j].key) {
            records[j + 1] = records[j];
            --j;
        }
        records[j + 1] = temp;
    }
}

// function to perform quicksort on the given range of records
void quicksort(Record* records, int lo, int hi) {
    // check if there are any records to be sorted
    if (!records || lo >= hi) {
        return;
    }

    int i = lo, j = hi;
    Record pivot = records[(lo + hi) / 2];
    while (i <= j) {
        while (records[i].key < pivot.key) {
            ++i;
        }
        while (pivot.key < records[j].key) {
            --j;
        }
        if (i <= j) {
            Record temp = records[i];
            records[i] = records[j];
            records[j] = temp;
            ++i;
            --j;
        }
    }
    quicksort(records, lo, j);
    quicksort(records, i, hi);
}
