public:
    // Constructor to initialize the cache with a capacity of 1000 entries
    Cache(int capacity) : _capacity(capacity), _size(0) {}

    // Insert a new entry into the cache if it does not exist already
    void insert(const std::string& key, const UserProfile& profile) {
        // Check if the cache is full
        if (_size == _capacity) {
            // Evict the least recently used entry if necessary
            evict();
        }

        // Insert the new entry into the cache
        _cache[key] = profile;
        _size++;
