        if (_cache.find(key) != _cache.end()) {
            return _cache[key];
        } else {
            return {};
        }
    }

private:
    // Evict the least recently used entry from the cache
    void evict() {
        std::chrono::time_point<std::chrono::system_clock> oldest;
        std::string oldestKey = "";

        for (const auto& [key, profile] : _cache) {
            // Get the timestamp of the current entry
            std::chrono::time_point<std::chrono::system_clock> timestamp = profile.timestamp;

            if (!oldest || oldest > timestamp) {
                oldest = timestamp;
                oldestKey = key;
            }
