    pthread_mutex_unlock(&mutex);

    // Handle potential memory allocation failures and robustly manage memory usage
    for (int i = 0; i < n; i++) {
        if (records[i] == NULL) {
            printf("Memory allocation failed\n");
            return NULL;
        }
    }

    // Monitor memory usage to prevent excessive consumption during peak loads
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    if (usage.ru_maxrss > 1024 * 1024) {
        printf("Memory usage is high\n");
    }

    // Free memory and return NULL in case of error
    free(records);
    free(retries);
    free(cache->records);
    free(cache);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);
    return NULL;
}

// Quicksort implementation with insertion sort for small subarrays
void quicksort(struct Record** records, int n) {
    if (n <= 1) { // base case: array of size 0 or 1
        return;
    }
    struct Record* pivot = records[n / 2]; // select pivot as middle element
    int left = 0, right = n - 1;
    while (left < right) {
        if (records[left]->key > pivot->key) {
            swap(records, left, right);
        }
        while (left < right && records[right]->key >= pivot->key) {
            right--;
        }
        // insertion sort for small subarrays
        if (right - left < 10) {
            int i = left + 1, j = right;
            while (i <= j) {
                if (records[i]->key < pivot->key) {
                    swap(records, i, left);
                    left++;
                } else if (records[j]->key > pivot->key) {
                    swap(records, j, right);
                    right--;
                }
                i++;
                j--;
            }
        }
    }
    quicksort(records, left - 1); // recursive call on left subarray
    quicksort(records + (left + 1), n - (left + 1)); // recursive call on right subarray
}

// swap function for sorting arrays
void swap(struct Record** records, int i, int j) {
    struct Record* temp = records[i];
    records[i] = records[j];
    records[j] = temp;
}
