int init_crypt(crypto_params_t *params, crypto_context_t *ctx) {
    int ret = 0;

    if (params->mode == ECB || params->mode == EDE || params->mode == EDE3) {
        // Set the encryption mode and key size
        ctx->block_size = AES_BLOCK_SIZE;
        switch (params->mode) {
            case ECB:
                ctx->cipher_ctx = EVP_CIPHER_CTX_new();
                ret = EVP_EncryptInit(ctx->cipher_ctx, EVP_aes_128_ecb(), params->key, NULL);
                break;
            case EDE:
                ctx->cipher_ctx = EVP_CIPHER_CTX_new();
                ret = EVP_EncryptInit(ctx->cipher_ctx, EVP_aes_128_ede(), params->key, NULL);
                break;
            case EDE3:
                ctx->cipher_ctx = EVP_CIPHER_CTX_new();
                ret = EVP_EncryptInit(ctx->cipher_ctx, EVP_aes_128_ede3(), params->key, NULL);
                break;
        }
    } else if (params->mode == CFB) {
        // Set the encryption mode and key size
        ctx->block_size = AES_BLOCK_SIZE;
        switch (params->mode) {
            case CFB:
                ctx->cipher_ctx = EVP_CIPHER_CTX_new();
                ret = EVP_EncryptInit(ctx->cipher_ctx, EVP_aes_128_cfb(), params->key, NULL);
                break;
        }
    } else {
        // Unsupported encryption mode
        return -1;
    }

    return ret;
}

// Encrypt the given data with the specified parameters
int encrypt(crypto_params_t *params, crypto_context_t *ctx, unsigned char *data, int data_len) {
    int ret = 0;

    // Initialize the cryptographic context if necessary
    if (ctx->cipher_ctx == NULL) {
        ret = init_crypt(params, ctx);
        if (ret != 0) {
            return ret;
        }
    }

    // Encrypt the data
    unsigned char *encrypted_data = NULL;
    encrypted_data = malloc(ctx->block_size * ((data_len + ctx->block_size - 1) / ctx->block_size));
    if (encrypted_data == NULL) {
        return -2;
    }
    int enc_len = data_len;
    ret = EVP_EncryptUpdate(ctx->cipher_ctx, encrypted_data, &enc_len, data, data_len);
    if (ret != 1) {
        free(encrypted_data);
        return -3;
    }

    // Output the encrypted data
    printf("Encrypted data: ");
    for (int i = 0; i < enc_len; i++) {
        printf("%02x", encrypted_data[i]);
    }
    printf("\n");

    free(encrypted_data);
    return ret;
}

// Decrypt the given data with the specified parameters
int decrypt(crypto_params_t *params, crypto_context_t *ctx, unsigned char *data, int data_len) {
    int ret = 0;

    // Initialize the cryptographic context if necessary
    if (ctx->cipher_ctx == NULL) {
        ret = init_crypt(params, ctx);
        if (ret != 0) {
            return ret;
        }
    }

    // Decrypt the data
    unsigned char *decrypted_data = NULL;
    decrypted_data = malloc(ctx->block_size * ((data_len + ctx->block_size - 1) / ctx->block_size));
    if (decrypted_data == NULL) {
        return -2;
    }
    int enc_len = data_len;
    ret = EVP_DecryptUpdate(ctx->cipher_ctx, decrypted_data, &enc_len, data, data_len);
    if (ret != 1) {
        free(decrypted_data);
        return -3;
    }

    // Output the decrypted data
