    for (int i = 0; i < enc_len; i++) {
        printf("%02x", decrypted_data[i]);
    }
    printf("\n");

    free(decrypted_data);
    return ret;
}

// Free the cryptographic context
void free_crypt(crypto_context_t *ctx) {
    if (ctx->cipher_ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
    }
}
