class CryptographyManager {
private:
    map<string, pair<AES, RSA*>> m_keys; // Map of keys (key name -> AES and RSA)
    vector<string> m_keyNames; // Vector of key names
    string m_kmsAddress; // Address of the KMS server
    bool m_enableKeyRotation; // Flag for enabling key rotation
    int m_rotationInterval; // Key rotation interval in days

public:
    CryptographyManager(const string& kmsAddress, const bool enableKeyRotation = false) :
        m_kmsAddress(kmsAddress), m_enableKeyRotation(enableKeyRotation) {}

    ~CryptographyManager() {
        for (auto& key : m_keys) {
            delete key.second.second;
        }
    }

    // Function to add a new key
    void addKey(const string& name, const int bits = MAX_KEY_SIZE) {
        if (name.empty()) {
            throw invalid_argument("Empty key name");
        } else if (bits < 128 || bits > MAX_KEY_SIZE) {
            throw invalid_argument("Invalid key size");
        }

        AES aes(bits);
        RSA* rsa = new RSA(bits, AES::MAX_KEYLENGTH);

        m_keys[name] = make_pair(aes, rsa);
        m_keyNames.push_back(name);
    }

    // Function to remove a key
    void removeKey(const string& name) {
        if (m_keys.find(name) == m_keys.end()) {
            throw invalid_argument("Invalid key name");
        } else {
            delete m_keys[name].second;
            m_keys.erase(name);
            m_keyNames.erase(remove(m_keyNames.begin(), m_keyNames.end(), name), m_keyNames.end());
        }
    }

    // Function to get a key by name
    pair<AES, RSA*> getKey(const string& name) {
        if (m_keys.find(name) == m_keys.end()) {
            throw invalid_argument("Invalid key name");
        } else {
            return m_keys[name];
        }
    }

    // Function to get all key names
    vector<string> getKeyNames() {
        return m_keyNames;
    }

    // Function to enable/disable key rotation
    void setKeyRotation(const bool enableKeyRotation) {
        m_enableKeyRotation = enableKeyRotation;
    }

    // Function to get the current key rotation status
    bool getKeyRotation() {
        return m_enableKeyRotation;
    }

    // Function to set the key rotation interval in days
    void setRotationInterval(const int rotationInterval) {
        m_rotationInterval = rotationInterval;
    }

    // Function to get the current key rotation interval in days
    int getRotationInterval() {
        return m_rotationInterval;
    }

    // Function to encrypt data using a given key and encryption mode
    string encrypt(const string& key, const string& data, const EncryptionMode mode = ECB) {
        if (m_keys.find(key) == m_keys.end()) {
            throw invalid_argument("Invalid key name");
        } else if (!validateData(data)) {
            throw invalid_argument("Invalid data format");
        }

        AES aes = m_keys[key].first;
        RSA* rsa = m_keys[key].second;

        // Generate a random initialization vector (IV) for CBC and CFB modes
        string iv;
        if (mode == CBC || mode == CFB) {
            iv = generateRandomString(BLOCK_SIZE);
        }

        // Encrypt the data using AES-GCM
        string ciphertext;
        if (mode == GCM) {
            ciphertext = aes.EncryptGCM(data, iv, rsa->publicKey(), "");
        } else {
            ciphertext = aes.EncryptCBC(data, iv, rsa->publicKey());
        }

        // Return the encrypted data and IV (for CBC and CFB modes)
        return mode == GCM ? ciphertext : iv + ciphertext;
    }

    // Function to decrypt data using a given key and encryption mode
    string decrypt(const string& key, const string& data, const EncryptionMode mode = ECB) {
        if (m_keys.find(key) == m_keys.end()) {
            throw invalid_argument("Invalid key name");
        } else if (!validateData(data)) {
            throw invalid_argument("Invalid data format");
        }

        AES aes = m_keys[key].first;
        RSA* rsa = m_keys[key].second;

        // Extract the IV (for CBC and CFB modes)
        string iv;
        if (mode == CBC || mode == CFB) {
            iv = data.substr(0, BLOCK_SIZE);
        }

        // Decrypt the ciphertext using AES-GCM
        string plaintext;
        if (mode == GCM) {
            plaintext = aes.DecryptGCM(data, iv, rsa->privateKey());
        } else {
            plaintext = aes.DecryptCBC(data, iv, rsa->privateKey());
        }

        // Return the decrypted data
        return plaintext;
    }

    // Function to validate the data format
    bool validateData(const string& data) {
        if (data.empty()) {
            return false;
        } else if (!isValidBase64(data)) {
            return false;
        }

        // Check if the data is a multiple of BLOCK_SIZE for CBC and CFB modes
        if ((mode == CBC || mode == CFB) && (data.length() % BLOCK_SIZE != 0)) {
            return false;
        }

        return true;
    }
};
