    // Initialize the logging service and threat detection system
    init_logging_service();
    init_threat_detection_system();

    // Create a socket for listening to incoming connections
    int listen_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_socket == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Bind the socket to a specific address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(PORT);
    if (bind(listen_socket, (struct sockaddr *)&server_address, sizeof(server_address)) == -1) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(listen_socket, 3) == -1) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    // Create threads for handling connections and packets
    pthread_t thread[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&thread[i], NULL, handle_connection, NULL) != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for the threads to finish
    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_join(thread[i], NULL) != 0) {
            perror("pthread_join");
            exit(EXIT_FAILURE);
        }
    }

    // Close the socket and release resources
    close(listen_socket);

    return EXIT_SUCCESS;
}

void *handle_connection(void *args) {
    // Accept an incoming connection
    int client_socket = accept(listen_socket, NULL, NULL);
    if (client_socket == -1) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    // Handle the connection and packet processing concurrently
    while (true) {
        pthread_mutex_lock(&mutex);
        if (num_connections >= NUM_THREADS) {
            sem_wait(&semaphore);
        }
        connections[num_connections++] = client_socket;
        pthread_mutex_unlock(&mutex);

        // Read a packet from the socket
        ssize_t length = recv(client_socket, packets[num_connections].buffer, BUFFER_SIZE, 0);
        if (length == -1) {
            perror("recv");
            exit(EXIT_FAILURE);
        }

        // Handle the packet in a separate thread
        pthread_t packet_thread;
        if (pthread_create(&packet_thread, NULL, handle_packet, &packets[num_connections]) != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }

        // Wait for the packet thread to finish
        if (pthread_join(packet_thread, NULL) != 0) {
            perror("pthread_join");
            exit(EXIT_FAILURE);
        }
    }
}

void handle_packet(packet_t *packet) {
