    mutex partitionMutex;
    condition_variable partitionCondVar;
    bool isPartitioning = false;
    int numPartitions = 10;
    size_t maxSize = 1024 * 1024 * 512; // 512 MB

public:
    PartitionedLinkedList(int numPartitions, size_t maxSize) {
        this->numPartitions = numPartitions;
        this->maxSize = maxSize;
    }

    void addItem(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
        // Lock the partition mutex to avoid concurrent access
        lock_guard<mutex> lock(partitionMutex);

        // Check if the item already exists in any partition
        for (auto& partition : partitions) {
            auto it = partition.second.find(RX_UE_INFORMATION_TAG, RNTI);
            if (it != partition.second.end()) {
                // Update the existing item
                *it = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG};
                return;
            }
        }

        // Add a new item to a random partition
        auto& partition = partitions[rand() % numPartitions];
        partition.push_back({RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG});

        // Check the size of each partition and repartition if necessary
        for (auto& partition : partitions) {
            if (partition.second.size() > maxSize / numPartitions) {
                isPartitioning = true;
                break;
            }
        }
    }

    void removeItem(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
        // Lock the partition mutex to avoid concurrent access
        lock_guard<mutex> lock(partitionMutex);

        for (auto& partition : partitions) {
            auto it = partition.second.find(RX_UE_INFORMATION_TAG, RNTI);
            if (it != partition.second.end()) {
                // Remove the item from the partition
                partition.second.erase(it);
                return;
            }
        }
    }

    void getItem(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
        // Lock the partition mutex to avoid concurrent access
        lock_guard<mutex> lock(partitionMutex);

        for (auto& partition : partitions) {
            auto it = partition.second.find(RX_UE_INFORMATION_TAG, RNTI);
            if (it != partition.second.end()) {
                // Return the item from the partition
                return *it;
            }
        }
    }

    void repartition() {
        // Lock the partition mutex to avoid concurrent access
        lock_guard<mutex> lock(partitionMutex);

        if (!isPartitioning) {
            // No need to repartition, return
            return;
        }

        // Repartition the items between partitions
        for (auto& partition : partitions) {
            auto it = partition.second.begin();
            while (it != partition.second.end()) {
                if ((*it).RX_UE_INFORMATION_TAG == 0 || (*it).RNTI == 0 || (*it).CRC_INDICATION_REL8_TAG == 0) {
                    // Remove invalid items from the partition
                    it = partition.second.erase(it);
                } else {
                    // Add the item to a random partition
                    auto& newPartition = partitions[rand() % numPartitions];
                    newPartition.push_back(*it);
                    it++;
                }
            }
        }

        isPartitioning = false;
    }
};
