    size_t pool_capacity;
    PacketHeader* pool;
} PriorityQueueItem;

void initializeMemoryPool(MemoryPool* pool) {
    pool->memory_used = 0;
    pool->memory_free = MAX_POOL_SIZE;
    pool->pool_size = 0;
    pool->pool_capacity = PRIORITY_QUEUE_CAPACITY;
    pool->pool = malloc(pool->pool_capacity * sizeof(PacketHeader));
    assert(pool->pool != NULL);
}

void freeMemoryPool(MemoryPool* pool) {
    free(pool->pool);
}

int allocateMemory(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    int ret = 0;
    if (size <= pool->memory_free) {
        pool->memory_used += size;
        pool->memory_free -= size;
        ret = 1;
    }
    pthread_mutex_unlock(&pool->lock);
    return ret;
}

int freeMemory(MemoryPool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    int ret = 0;
    if (size <= pool->memory_used) {
        pool->memory_used -= size;
        pool->memory_free += size;
        ret = 1;
    }
    pthread_mutex_unlock(&pool->lock);
    return ret;
}

void* allocatePacketHeader(MemoryPool* pool) {
    void* header = NULL;
    if (allocateMemory(pool, sizeof(PacketHeader))) {
        header = malloc(sizeof(PacketHeader));
        assert(header != NULL);
        memset(header, 0, sizeof(PacketHeader));
    } else {
        pthread_mutex_lock(&pool->lock);
        if (pool->pool_size < pool->pool_capacity) {
            header = &pool->pool[pool->pool_size];
            memset(header, 0, sizeof(PacketHeader));
            pool->pool_size++;
        }
        pthread_mutex_unlock(&pool->lock);
    }
    return header;
}

void freePacketHeader(MemoryPool* pool, PacketHeader* header) {
    if (header != NULL) {
        memset(header, 0, sizeof(PacketHeader));
        freeMemory(pool, sizeof(PacketHeader));
    }
}

int allocatePacketHeaders(MemoryPool* pool, size_t num_headers) {
    int ret = 0;
    for (size_t i = 0; i < num_headers; i++) {
        if (!allocateMemory(pool, sizeof(PacketHeader))) {
            break;
        }
        ret++;
    }
    return ret;
}

int freePacketHeaders(MemoryPool* pool, size_t num_headers) {
    int ret = 0;
    for (size_t i = 0; i < num_headers; i++) {
        if (!freeMemory(pool, sizeof(PacketHeader))) {
            break;
        }
        ret++;
    }
    return ret;
}

void initializeLoggingService(LoggingService* service) {
    pthread_mutex_init(&service->lock, NULL);
    service->sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    assert(service->sockfd >= 0);
}

void freeLoggingService(LoggingService* service) {
    close(service->sockfd);
    pthread_mutex_destroy(&service->lock);
}

void initializeThreatDetectionService(ThreatDetectionService* service) {
    pthread_mutex_init(&service->lock, NULL);
    service->sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    assert(service->sockfd >= 0);
}

void freeThreatDetectionService(ThreatDetectionService* service) {
    close(service->sockfd);
    pthread_mutex_destroy(&service->lock);
}

void initializeCachingService(CachingService* service) {
    pthread_mutex_init(&service->lock, NULL);
    service->sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    assert(service->sockfd >= 0);
}

void freeCachingService(CachingService* service) {
    close(service->sockfd);
    pthread_mutex_destroy(&service->lock);
}

int handlePacket(MemoryPool* pool, LoggingService* logging_service, ThreatDetectionService* threat_detection_service, CachingService* caching_service, PacketHeader* header) {
    int ret = 0;
    if (header != NULL) {
        // Handle packet header here.
        freePacketHeader(pool, header);
        ret++;
    } else {
        pthread_mutex_lock(&logging_service->lock);
        sendto(logging_service->sockfd, &(struct sockaddr_in){ .sin_family = AF_INET }, sizeof(struct sockaddr_in), MSG_CONFIRM, (const struct sockaddr*)&(struct sockaddr_in){ .sin_family = AF_INET }, sizeof(struct sockaddr_in));
        pthread_mutex_unlock(&logging_service->lock);
    }
    return ret;
}

int handleQueueItem(MemoryPool* pool, LoggingService* logging_service, ThreatDetectionService* threat_detection_service, CachingService* caching_service, QueueItem* item) {
    int ret = 0;
    if (item != NULL) {
        // Handle queue item here.
        freePacketHeader(pool, &item->header);
        ret++;
