        return EXIT_FAILURE;
    }

    // Create a socket for receiving packets
    sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_TCP);
    if (sockfd < 0) {
        handle_error("socket() failed", errno);
        return EXIT_FAILURE;
    }

    // Set up the packet buffer and metadata structures
    buffer_size = MIN_BUFFER_SIZE;
    metadata_size = CACHE_SIZE * sizeof(struct packet_metadata);
    buffer = malloc(buffer_size * sizeof(char));
    metadata = malloc(metadata_size * sizeof(struct packet_metadata));
    if (buffer == NULL || metadata == NULL) {
        handle_error("malloc() failed", errno);
        return EXIT_FAILURE;
    }

    // Initialize the semaphore for managing concurrent access to the buffer and metadata structures
    if ((semaphore = sem_open("packet_processing", O_CREAT, 0644, MAX_CONCURRENCY)) == SEM_FAILED) {
        handle_error("sem_open() failed", errno);
        return EXIT_FAILURE;
    }

    // Start the connection handler thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, handle_connection, NULL) != 0) {
        handle_error("pthread_create() failed", errno);
        return EXIT_FAILURE;
    }

    // Wait for the connection handler to terminate
    pthread_join(thread, NULL);

    // Close the socket and free resources
    close(sockfd);
    free(buffer);
    free(metadata);
    sem_close(semaphore);

    return EXIT_SUCCESS;
}

void* handle_connection(void* arg) {
    int status = 0;
    struct sockaddr_in client_address;
    socklen_t address_length = sizeof(client_address);
    char* buffer = NULL;
    size_t length = 0;

    while (1) {
        // Receive a packet from the socket
        status = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr*) &client_address, &address_length);
        if (status < 0) {
            handle_error("recvfrom() failed", errno);
            continue;
        }

        // Handle the packet
        handle_packet(buffer, status);
    }
}

void handle_packet(char* buffer, size_t length) {
