    memcpy(&protocol_type, buffer + PACKET_HEADER_LENGTH + sizeof(uint32_t), sizeof(char));
    memcpy(&source_port, buffer + PACKET_HEADER_LENGTH + 1 + sizeof(uint32_t), sizeof(uint16_t));
    memcpy(&destination_port, buffer + PACKET_HEADER_LENGTH + 3 + sizeof(uint32_t), sizeof(uint16_t));
    memcpy(&payload_size, buffer + PACKET_HEADER_LENGTH + 5 + sizeof(uint32_t), sizeof(uint32_t));

    // Add the metadata to the cache
    pthread_mutex_lock(&lock);
    metadata[metadata_index] = (struct packet_metadata) { sequence_number, protocol_type, source_port, destination_port, payload_size };
    if (++metadata_index >= CACHE_SIZE) {
        // TODO: Implement LRU cache replacement policy
        handle_error("LRU cache replacement policy not implemented", 0);
    }
    pthread_mutex_unlock(&lock);
}

void handle_error(const char* error_message, int error_code) {
    LOG_ERROR("%s: %d", error_message, error_code);
}
