        (*array)[i].rnti = rand() % 1000000;
        crcflag = (rand() % 2) ? 1 : 0;
        (*array)[i].crc_indication_rel8_tag = (crcflag << 7) | ((rand() % 128) & 0x7F);
    }

    // Monitor the number of milliseconds taken for each operation
    clock_gettime(CLOCK_REALTIME, &start_time);
    // Populate the CRC flag for each element in the array
    for (i = 0; i < num_elements; i++) {
        (*array)[i].crcflag = crcflag;
    }
    clock_gettime(CLOCK_REALTIME, &end_time);
    duration = (long)((end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000000);
