    // Allocate memory for the new sensor reading if necessary
    if (sensor_data == NULL) {
        num_sensors = 1;   // Initially allocate space for one sensor reading
        sensor_data = malloc(sizeof(struct SensorReading) * num_sensors);
        if (sensor_data == NULL) {
