        if (sensor_data == NULL) {
            printf("Error: failed to reallocate memory for the shared queue\n");
            return;
        }
    }

    // Add the new sensor reading to the end of the shared queue
    struct SensorReading *new_reading = &sensor_data[num_sensors++];
    new_reading->id = id;
    new_reading->timestamp = timestamp;
    new_reading->type = type;
