                    handle_error(num_retries);
                    break;
                } else {
                    // Handle the error and retry the export after a backoff period
                    handle_error(num_retries++);
                    sleep((unsigned int)backoff_time);   // Exponential backoff strategy
                    backoff_time *= 2;   // Increase the backoff time for the next retry
                }
