    cache->data = malloc(max_size * sizeof(struct NFAPI_CRC_INDICATION_PDU));
    cache->size = 0;
    cache->max_size = max_size;
    cache->ttl = time(NULL);
    return cache;
}

// Function to add a new entry to the cache
void cache_add(struct Cache* cache, struct NFAPI_CRC_INDICATION_PDU* data) {
    // Check if the cache is full
    if (cache->size >= cache->max_size) {
        // If so, remove the oldest entry
        cache_remove(cache, 0);
    }
    // Add the new entry to the end of the cache
    cache->data[cache->size++] = *data;
}

// Function to remove an entry from the cache
void cache_remove(struct Cache* cache, size_t index) {
    // Check if the index is valid
    if (index < cache->size) {
        // If so, shift all entries down
        for (int i = index; i < cache->size - 1; i++) {
            cache->data[i] = cache->data[i + 1];
        }
        // Decrement the size of the cache
        cache->size--;
    }
}

// Function to update the TTL for all entries in the cache
void cache_ttl_update(struct Cache* cache) {
