#define SENSOR_READINGS_KEY "sensor_readings"

void storeSensorReadings(struct SensorQueue* queue) {
    // Iterate over the queue and store each reading in Redis
    while (queue->head != queue->tail) {
        struct SensorReading* reading = sensorQueuePop(queue);
        redisSet(SENSOR_READINGS_KEY, reading->id, reading->data, sizeof(reading->data));
    }
}

void retrieveSensorReadings(struct SensorQueue* queue) {
    // Iterate over the queue and retrieve each reading from Redis
    while (queue->head != queue->tail) {
        struct SensorReading* reading = sensorQueuePop(queue);
        redisGet(SENSOR_READINGS_KEY, reading->id, &reading->data, sizeof(reading->data));
    }
}
