#define MAX_NUM_STRUCTS 1000 // Maximum number of structures to allocate at once
#define MIN_MEMORY_ALLOCATION_SIZE 512 // Minimum memory allocation size in bytes
#define LOGGING_VERBOSITY 3 // Logging verbosity level (0-3)

// Structures and typedefs
typedef struct {
    char *rnti; // UE RNTI
} UEInformation;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crcIndicationPdu;
    UEInformation ueInfo;
} CrcIndicationStructure;

// Function prototypes
int createAndPopulateNFApiIndications(int numStructs, UEInformation *ueInfos, int serializeToDisk);
void logCrcIndicationCreation(int successCount, int failureCount, char *errorMessage);
void logCrcIndicationDeserialization(char *filename, int successCount, int failureCount, char *errorMessage);

// Function implementation
int createAndPopulateNFApiIndications(int numStructs, UEInformation *ueInfos, int serializeToDisk) {
    // Initialize variables and structures
    CrcIndicationStructure *crcIndicationStructures = NULL;
    int structureCount = 0;
    int failureCount = 0;
    sqlite3 *db = NULL;

    // Validate input parameters
    if (numStructs <= 0 || ueInfos == NULL) {
        return -1;
    }

    // Open database connection
    if (sqlite3_open("nfapi_database.db", &db) != SQLITE_OK) {
        sqlite3_close(db);
        return -2;
    }

    // Create and populate NFAPI CRC indication structures
    for (int i = 0; i < numStructs; i++) {
        // Allocate memory for the structure
        crcIndicationStructures = realloc(crcIndicationStructures, (structureCount + 1) * sizeof(CrcIndicationStructure));
        if (crcIndicationStructures == NULL) {
            logCrcIndicationCreation(-1, ++failureCount, "Memory allocation failure");
            break;
        }

        // Populate the structure with UE information and CRC indication data
        crcIndicationStructures[structureCount].ueInfo = ueInfos[i];
        sqlite3_stmt *stmt = NULL;
        if (sqlite3_prepare_v2(db, "SELECT crcIndicationData FROM UE WHERE rnti = ?", -1, &stmt, NULL) != SQLITE_OK) {
            logCrcIndicationCreation(-1, ++failureCount, "SQLite prepare statement failure");
            break;
        }
        sqlite3_bind_text(stmt, 1, ueInfos[i].rnti, -1, SQLITE_STATIC);
        if (sqlite3_step(stmt) != SQLITE_ROW) {
            logCrcIndicationCreation(-1, ++failureCount, "SQLite step failure");
            break;
        }
        crcIndicationStructures[structureCount].crcIndicationPdu = *(NFAPI_CRC_INDICATION_PDU_T *)sqlite3_column_blob(stmt, 0);

        // Increment structure count and log creation success
        ++structureCount;
        logCrcIndicationCreation(1, 0, NULL);
    }

    // Close database connection
    sqlite3_close(db);

    // Serialize structures to disk if requested
    if (serializeToDisk) {
        char *filename = "nfapi_crc_indications.bin";
        FILE *file = fopen(filename, "wb");
        if (file == NULL) {
            logCrcIndicationDeserialization(filename, -1, ++failureCount, "File open failure");
        } else {
            // Write structure count and serialized structures to file
            fwrite(&structureCount, sizeof(int), 1, file);
            for (int i = 0; i < structureCount; i++) {
                fwrite(&crcIndicationStructures[i], sizeof(CrcIndicationStructure), 1, file);
            }
            // Close file and log serialization success
            fclose(file);
            logCrcIndicationDeserialization(filename, structureCount, 0, NULL);
        }
    }

    return structureCount;
}

// Log creation/deserialization of NFAPI CRC indication structures
void logCrcIndicationCreation(int successCount, int failureCount, char *errorMessage) {
    if (successCount > 0 || failureCount > 0) {
        printf("NFAPI CRC indication structure creation: %d successful, %d failed\n", successCount, failureCount);
        if (errorMessage != NULL) {
            printf("%s\n", errorMessage);
        }
    }
}

void logCrcIndicationDeserialization(char *filename, int successCount, int failureCount, char *errorMessage) {
    if (successCount > 0 || failureCount > 0) {
        printf("NFAPI CRC indication structure deserialization from %s: %d successful, %d failed\n", filename, successCount, failureCount);
        if (errorMessage != NULL) {
            printf("%s\n", errorMessage);
        }
    }
}
