      arr[i].crc_indication_rel8.CRCFlag = crcflag;

      // Calculate the MD5 hash of a provided string input
      const char *input = "Hello, world!";
      md5(arr[i].md5_hash, (unsigned char *)input);
    }
  } else {
    printf("Invalid RNTI value: %u\n", rnti);
  }
}

// Implement robust error handling to manage invalid RNTI inputs and network failures from the external data source
int validate_rnti(unsigned short rnti) {
