typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set to 1 or 0
} NFAPI_CRC_INDICATION_PDU_T;

// Define the hash map for storing RNTI values
typedef struct {
    uint32_t key;
    int value; // Indicates if RNTI is unique (1) or not (0)
} RNTI_HASHMAP_ENTRY;

// Function to insert a new NFAPI_CRC_INDICATION_PDU_T structure into the list
void insertNFAPICrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Create a hash map entry for the RNTI value
    RNTI_HASHMAP_ENTRY newEntry;
    newEntry.key = pdu->RNTI;
    newEntry.value = 1;

    // Check if the RNTI value already exists in the hash map
    int found = 0;
    for (int i = 0; i < hashMapSize; i++) {
        if (hashMap[i].key == pdu->RNTI) {
            // If the RNTI value is found, update the entry to indicate it's not unique
            hashMap[i].value = 0;
            found = 1;
            break;
        }
    }

    // If the RNTI value doesn't exist in the hash map, add a new entry
    if (!found) {
        hashMapSize++;
        hashMap[hashMapSize - 1] = newEntry;
    }

    // Insert the NFAPI_CRC_INDICATION_PDU_T structure into the list
    pdu->next = NULL;
    if (lastNFAPICrcIndicationPdu != NULL) {
        lastNFAPICrcIndicationPdu->next = pdu;
    } else {
        firstNFAPICrcIndicationPdu = pdu;
    }
    lastNFAPICrcIndicationPdu = pdu;
}

// Function to handle the CRC indication message from an RU
void handleCrcIndication(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Insert the NFAPI_CRC_INDICATION_PDU_T structure into the list
    insertNFAPICrcIndicationPdu((NFAPI_CRC_INDICATION_PDU_T*)pdu);
}

// Function to maintain the hash map and check for RNTI conflicts
void maintainHashMap() {
    // Iterate through the hash map entries and remove any duplicate RNTIs
    int count = 0;
    for (int i = 0; i < hashMapSize; i++) {
        if (hashMap[i].value == 0) {
            // If a duplicate RNTI is found, delete the entry from the hash map
            hashMapSize--;
            count++;
        }
    }
}

// Function to handle the incoming data stream from multiple RUs
void processIncomingDataStream() {
    // Create a buffer for storing the incoming data
    uint8_t* buffer = malloc(BUFFER_SIZE);

    // Read the incoming data from each RU
    while (1) {
        int bytesRead = read(RU_SOCKET, buffer, BUFFER_SIZE);
        if (bytesRead < 0) {
            perror("Error reading from socket");
            break;
        } else if (bytesRead == 0) {
            // If no data is available to read, wait for a short time before checking again
            usleep(100);
            continue;
        }

        // Parse the incoming data and handle each CRC indication message
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)buffer;
        while (pdu != NULL) {
            handleCrcIndication(pdu);
            pdu = pdu->next;
        }
    }

    // Free the buffer memory
    free(buffer);
}

// Main function for the CRC indication message processor
int main() {
    // Initialize the hash map and set the first and last NFAPI_CRC_INDICATION_PDU_T structures to NULL
    int hashMapSize = 0;
    RNTI_HASHMAP_ENTRY* hashMap = malloc(sizeof(RNTI_HASHMAP_ENTRY) * INITIAL_HASHMAP_SIZE);
    memset(hashMap, 0, sizeof(RNTI_HASHMAP_ENTRY) * INITIAL_HASHMAP_SIZE);
    NFAPI_CRC_INDICATION_PDU_T* firstNFAPICrcIndicationPdu = NULL;
    NFAPI_CRC_INDICATION_PDU_T* lastNFAPICrcIndicationPdu = NULL;

    // Create a thread for handling the incoming data stream from multiple RUs
    pthread_t thread1;
    if (pthread_create(&thread1, NULL, processIncomingDataStream, NULL) != 0) {
        perror("Error creating thread");
    }

    // Loop indefinitely to maintain the hash map and check for RNTI conflicts
    while (1) {
        maintainHashMap();
        sleep(1);
    }

    return 0;
}
