// Structure for holding NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    int RNTI;
    char buffer[BUFSIZ];
} CRCIndicationPdu;

// Structure for holding the linked list of CRCIndicationPdus
typedef struct CRCIndicationListNode {
    CRCIndicationPdu data;
    struct CRCIndicationListNode* next;
} CRCIndicationListNode;

// Global variable to hold the head of the linked list
CRCIndicationListNode* head = NULL;

// Function to create a new node in the linked list
CRCIndicationListNode* createNewNode(int RNTI, char* buffer) {
    CRCIndicationListNode* newNode = malloc(sizeof(CRCIndicationListNode));
    if (newNode == NULL) {
        perror("malloc");
        exit(1);
    }
    memset(&newNode->data, 0, sizeof(CRCIndicationPdu));
    newNode->data.RNTI = RNTI;
    strncpy(newNode->data.buffer, buffer, BUFSIZ);
    return newNode;
}

// Function to add a node to the linked list
void addToLinkedList(int RNTI, char* buffer) {
    CRCIndicationListNode* newNode = createNewNode(RNTI, buffer);
    if (head == NULL) {
        head = newNode;
        return;
    }
    CRCIndicationListNode* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = newNode;
}

// Function to remove a node from the linked list
void removeFromLinkedList(int RNTI) {
    if (head == NULL) {
        return;
    }
    CRCIndicationListNode* current = head;
    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    CRCIndicationListNode* previous = current->prev;
    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
}

// Function to search for a node in the linked list by RNTI value
CRCIndicationListNode* findByRNTI(int RNTI) {
    if (head == NULL) {
        return NULL;
    }
    CRCIndicationListNode* current = head;
    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }
    return current;
}

// Function to update a node in the linked list by RNTI value
void updateInLinkedList(int RNTI, char* buffer) {
    CRCIndicationListNode* node = findByRNTI(RNTI);
    if (node == NULL) {
        return;
    }
    strncpy(node->data.buffer, buffer, BUFSIZ);
}

// Function to handle a CRC indication PDU from the network
void handleCRCIndicationPdu(int RNTI, char* buffer) {
    // Check if the node already exists in the linked list
    CRCIndicationListNode* node = findByRNTI(RNTI);
    if (node == NULL) {
        // If the node does not exist, create a new one and add it to the linked list
        addToLinkedList(RNTI, buffer);
    } else {
        // If the node already exists, update its value in the linked list
        updateInLinkedList(RNTI, buffer);
    }
}

// Function to handle a CRC indication PDU from a Radio Unit (RU)
