    // Handle the CRC indication PDU based on its RNTI value
    handleCRCIndicationPdu(RNTI, buffer);
}

// Function to handle a partial packet reception request from the network
void handlePartialPacketReceptionRequest(int RNTI) {
    // Retrieve the node associated with the given RNTI value in the linked list
    CRCIndicationListNode* node = findByRNTI(RNTI);
    if (node == NULL) {
        return;
    }
    // Send a retransmission request to the Radio Unit (RU) associated with the given RNTI value
    sendRetransmissionRequestToRU(node->data.buffer, node->data.RNTI);
}

// Function to handle a retransmission request from a Radio Unit (RU)
void handleRetransmissionRequestFromRU(int RNTI, char* buffer) {
    // Handle the retransmission request based on its RNTI value
    handlePartialPacketReceptionRequest(RNTI);
}

// Function to handle a network partition or failure scenario
void handleNetworkPartitionOrFailure() {
    // Remove all nodes from the linked list and reset the head pointer
    CRCIndicationListNode* current = head;
    while (current != NULL) {
        CRCIndicationListNode* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
}

// Function to handle a transient failure scenario
void handleTransientFailure() {
    // Retry sending the data in the linked list to the Radio Unit (RU) associated with each node
    CRCIndicationListNode* current = head;
    while (current != NULL) {
        sendDataToRU(current->data.buffer, current->data.RNTI);
        current = current->next;
    }
}

// Function to handle a periodic data synchronization scenario
void handlePeriodicDataSynchronization() {
    // Retrieve the node associated with each RNTI value in the linked list and send its data to the Radio Unit (RU)
    CRCIndicationListNode* current = head;
    while (current != NULL) {
        sendDataToRU(current->data.buffer, current->data.RNTI);
        current = current->next;
