    new_node->next = NULL;
    new_node->prev = NULL;

    // If the hash map is empty, insert the new node as both the head and tail of the list
    if (hashmap->head == NULL) {
        hashmap->head = new_node;
        hashmap->tail = new_node;
    } else {
        // Otherwise, insert the new node after the current tail of the list
        hashmap->tail->next = new_node;
        new_node->prev = hashmap->tail;
        hashmap->tail = new_node;
    }

    // Unlock the mutex to allow other threads to access the hash map and linked list
    pthread_mutex_unlock(&lock);

    return 0;
}

// Function to remove a NFAPI_CRC_INDICATION_PDU_T structure from the doubly linked list
int remove_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Lock the mutex to ensure thread safety when modifying the hash map and linked list
    pthread_mutex_lock(&lock);

    // If the hash map is empty, return an error
    if (hashmap->head == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Search for the given PDU in the doubly linked list and remove it if found
    crc_indication_list_t* current = hashmap->head;
    while (current != NULL) {
        if (current->pdu == pdu) {
            // If the node is the head, set the new head as its next node and free the memory of the removed node
            if (current == hashmap->head) {
                hashmap->head = current->next;
                free(current);
                current = NULL;
            } else {
                // Otherwise, remove the node by updating its previous node's next pointer to skip over it
                current->prev->next = current->next;
                free(current);
                current = NULL;
            }
        }
        current = current->next;
    }

    // If the tail is removed, set the new tail as its previous node and update the hash map's tail pointer
    if (hashmap->tail == pdu) {
        crc_indication_list_t* new_tail = hashmap->head;
        while (new_tail->next != NULL) {
            new_tail = new_tail->next;
        }
        hashmap->tail = new_tail;
    }

    // Unlock the mutex to allow other threads to access the hash map and linked list
    pthread_mutex_unlock(&lock);

    return 0;
}

// Function to retrieve a NFAPI_CRC_INDICATION_PDU_T structure from the doubly linked list by RNTI value
NFAPI_CRC_INDICATION_PDU_T* get_crc_indication_pdu(int rnti) {
    // Lock the mutex to ensure thread safety when accessing the hash map and linked list
    pthread_mutex_lock(&lock);

    // Search for the given RNTI in the doubly linked list and return its corresponding PDU if found
    crc_indication_list_t* current = hashmap->head;
    while (current != NULL) {
        if (current->pdu->RX_UE_INFORMATION.RNTI == rnti) {
            pthread_mutex_unlock(&lock);
            return current->pdu;
        }
        current = current->next;
    }

    // If the RNTI is not found, return NULL
    pthread_mutex_unlock(&lock);
    return NULL;
}

// Function to retrieve a CRCFLAG value from the doubly linked list by RNTI value
int get_crc_flag(int rnti) {
    // Lock the mutex to ensure thread safety when accessing the hash map and linked list
    pthread_mutex_lock(&lock);

    // Search for the given RNTI in the doubly linked list and return its corresponding CRCFLAG value if found
    crc_indication_list_t* current = hashmap->head;
    while (current != NULL) {
        if (current->pdu->RX_UE_INFORMATION.RNTI == rnti) {
            pthread_mutex_unlock(&lock);
            return current->pdu->CRC_INDICATION.CRCFLAG;
        }
        current = current->next;
    }

    // If the RNTI is not found, return -1
    pthread_mutex_unlock(&lock);
    return -1;
}

// Function to update a CRCFLAG value in the doubly linked list by RNTI value
int set_crc_flag(int rnti, int crcflag) {
    // Lock the mutex to ensure thread safety when accessing the hash map and linked list
    pthread_mutex_lock(&lock);

    // Search for the given RNTI in the doubly linked list and update its corresponding CRCFLAG value if found
    crc_indication_list_t* current = hashmap->head;
    while (current != NULL) {
        if (current->pdu->RX_UE_INFORMATION.RNTI == rnti) {
            current->pdu->CRC_INDICATION.CRCFLAG = crcflag;
            pthread_mutex_unlock(&lock);
            return 0;
        }
        current = current->next;
    }

    // If the RNTI is not found, return an error
    pthread_mutex_unlock(&lock);
    return -1;
}

// Main function to handle CRIC messages
int main(void) {
    // Initialize the hash map and linked list
    hashmap = malloc(sizeof(struct cric_indication_hashmap));
    hashmap->head = NULL;
    hashmap->tail = NULL;

    // Loop indefinitely to handle CRIC messages
    while (1) {
        // Receive a CRIC message from the network
        struct cric_indication* cri = receive_cric();

        // Check if the received PDU is already stored in the hash map and linked list
        int rnti = cri->RX_UE_INFORMATION.RNTI;
        NFAPI_CRC_INDICATION_PDU* pdu = get_crc_indication(rnti);
        if (pdu == NULL) {
            // If the PDU is not found, create a new node and store it in the hash map and linked list
            pdu = malloc(sizeof(struct cric_indication));
            memcpy(pdu, cri, sizeof(struct cric_indication));
            insert_crc_indication(pdu);
        } else {
            // If the PDU is already stored, update its CRCFLAG value and remove the old node from the hash map and linked list
            set_crc_flag(rnti, cri->CRC_INDICATION.CRCFLAG);
            remove_crc_indication(pdu);
        }
    }
}
