// NetworkDataProcessor.h

#pragma once

#include <vector>
#include <string>
#include <memory>
#include <unordered_map>

class NetworkDataProcessor {
public:
    // Constructor and destructor
    NetworkDataProcessor(const std::vector<std::string>& regions);
    ~NetworkDataProcessor();

    // Add a new region to the processor
    void addRegion(const std::string& region);

    // Remove a region from the processor
    void removeRegion(const std::string& region);

    // Process network data for all regions
    void processNetworkData(const std::vector<std::string>& logs);

private:
    // Regions managed by this processor
    std::unordered_map<std::string, std::unique_ptr<Region>> _regions;
};

// Region.h

#pragma once

#include <string>
#include <vector>
#include <memory>
#include <mutex>
#include <condition_variable>

class NetworkDataProcessor;

class Region {
public:
    // Constructor and destructor
    Region(const std::string& name, NetworkDataProcessor* processor);
    ~Region();

    // Add a new log to the region's queue
    void addLog(const std::string& log);

    // Process all logs in the region's queue
    void processLogs();

private:
    // Name of the region
    std::string _name;

    // NetworkDataProcessor that owns this region
    NetworkDataProcessor* _processor;

    // Queue of logs to be processed
    std::vector<std::string> _logs;

    // Mutex and condition variable for synchronizing access to the queue
    std::mutex _queueMutex;
    std::condition_variable _queueCV;
};

// NetworkDataProcessor.cpp

#include "NetworkDataProcessor.h"
#include "Region.h"

NetworkDataProcessor::NetworkDataProcessor(const std::vector<std::string>& regions) {
    for (const auto& region : regions) {
        addRegion(region);
    }
}

NetworkDataProcessor::~NetworkDataProcessor() {
    // Remove all regions from the processor
    for (auto it = _regions.begin(); it != _regions.end(); ++it) {
        delete it->second;
    }
}

void NetworkDataProcessor::addRegion(const std::string& region) {
    auto it = _regions.find(region);
    if (it == _regions.end()) {
        // Create a new Region object and insert it into the map
        it = _regions.insert({region, std::make_unique<Region>(region, this)}).first;
    }
}

void NetworkDataProcessor::removeRegion(const std::string& region) {
    auto it = _regions.find(region);
    if (it != _regions.end()) {
        // Delete the Region object and remove it from the map
        delete it->second;
        _regions.erase(it);
    }
}

void NetworkDataProcessor::processNetworkData(const std::vector<std::string>& logs) {
    for (auto& region : _regions) {
        // Add each log to the region's queue
        region.second->addLog(logs);
    }
}

// Region.cpp

#include "Region.h"
#include "NetworkDataProcessor.h"

Region::Region(const std::string& name, NetworkDataProcessor* processor) : _name(name), _processor(processor) {}

Region::~Region() {
    // Remove this region from the NetworkDataProcessor's map
    _processor->_regions.erase(_name);
}

void Region::addLog(const std::string& log) {
    // Add the log to the queue, and notify any waiting threads
    {
        std::lock_guard<std::mutex> lock(_queueMutex);
        _logs.push_back(log);
    }
    _queueCV.notify_all();
}

void Region::processLogs() {
    // Process all logs in the queue, and notify any waiting threads when finished
    while (true) {
        std::vector<std::string> logs;
        {
            std::unique_lock<std::mutex> lock(_queueMutex);
            _queueCV.wait(lock, [this] { return !_logs.empty(); });
            logs = std::move(_logs);
        }
        for (auto& log : logs) {
            // Process each log individually
            processLog(log);
        }
    }
}
