// Data structure to represent a single received radio frame
typedef struct LTE_PHY_RX_FRAME_PDU_T {
    uint16_t rnti; // Receiver Network Temporary Identifier
    uint8_t *data; // Pointer to the frame data
    size_t data_len; // Length of the frame data
} LTE_PHY_RX_FRAME_PDU_T;

// Hash table to store received radio frames based on RNTI
typedef struct {
    uint16_t *rnti; // Array of RNTIs
    size_t rnti_len; // Length of the RNTI array
    LTE_PHY_RX_FRAME_PDU_T **frames; // Hash table to store received frames
} frame_hash_table_t;

// Function to insert a new radio frame into the hash table
int insert_frame(frame_hash_table_t *ht, LTE_PHY_RX_FRAME_PDU_T *frame) {
    // Check if the RNTI already exists in the hash table
    uint16_t *rnti = ht->rnti;
    for (size_t i = 0; i < ht->rnti_len; i++) {
        if (*(rnti + i) == frame->rnti) {
            // RNTI already exists, update the corresponding frame
            ht->frames[i] = frame;
            return 1;
        }
    }

    // RNTI does not exist, insert a new entry into the hash table
    ht->rnti_len++;
    ht->rnti = realloc(ht->rnti, sizeof(uint16_t) * ht->rnti_len);
    ht->frames = realloc(ht->frames, sizeof(LTE_PHY_RX_FRAME_PDU_T *) * ht->rnti_len);
    *(ht->rnti + ht->rnti_len - 1) = frame->rnti;
    ht->frames[ht->rnti_len - 1] = frame;

    return 0;
}

// Function to delete a radio frame from the hash table
int delete_frame(frame_hash_table_t *ht, uint16_t rnti) {
    // Check if the RNTI exists in the hash table
    for (size_t i = 0; i < ht->rnti_len; i++) {
        if (*(ht->rnti + i) == rnti) {
            // Found the corresponding RNTI, delete the frame
            free(ht->frames[i]);
            ht->frames[i] = NULL;
            return 1;
        }
    }

    // RNTI not found, do nothing
    return 0;
}

// Function to lookup a radio frame in the hash table
LTE_PHY_RX_FRAME_PDU_T *lookup_frame(frame_hash_table_t *ht, uint16_t rnti) {
    // Check if the RNTI exists in the hash table
    for (size_t i = 0; i < ht->rnti_len; i++) {
        if (*(ht->rnti + i) == rnti) {
            return ht->frames[i];
        }
    }

    // RNTI not found, return NULL
    return NULL;
}

// Function to purge old or redundant frames from the hash table
int purge_frames(frame_hash_table_t *ht) {
    for (size_t i = 0; i < ht->rnti_len; i++) {
        if (ht->frames[i] == NULL) {
            // Found a redundant frame, delete it from the hash table
            free(ht->rnti + i);
            ht->rnti_len--;
            return 1;
        } else if (ht->frames[i]->data_len == 0) {
            // Found an old frame, delete it from the hash table
            free(ht->frames[i]);
            ht->frames[i] = NULL;
            return 1;
        }
    }

    // No redundant or old frames found, do nothing
    return 0;
}

// Function to perform automatic insertion and periodic purging of old or redundant frames
void auto_insert_purge(frame_hash_table_t *ht) {
    while (1) {
        // Perform automatic insertion of new frames
        semaphore_wait(new_frame_sem);
        LTE_PHY_RX_FRAME_PDU_T *frame = (LTE_PHY_RX_FRAME_PDU_T *)malloc(sizeof(LTE_PHY_RX_FRAME_PDU_T));
        // Fill in the frame data and insert it into the hash table
        ht->insert_frame(ht, frame);
        // Unlock the semaphore to signal that new frames have been inserted
        semaphore_post(new_frame_sem);

        // Perform periodic purging of old or redundant frames
        purge_frames(ht);
    }
}

// Function to perform automatic deletion of a frame from the hash table
void auto_delete_frame(frame_hash_table_t *ht, uint16_t rnti) {
    // Perform automatic deletion of the corresponding frame from the hash table
    ht->delete_frame(ht, rnti);
}
```

In this example, we have defined a `frame_hash_table` structure that contains an array of RNTIs and an array of pointers to the corresponding frames. We have also defined several functions for inserting, deleting, looking up, and purging old or redundant frames from the hash table. The `auto_insert_purge` function performs automatic insertion of new frames and periodic purging of old or redundant frames using a semaphore to signal when new frames are available for insertion. The `auto_delete_frame` function performs automatic deletion of a frame from the hash table based on its RNTI.

Note that this is just one example of how you can use a hash table to manage your frames, and you may need to modify it to fit your specific requirements. Additionally, you will need to define the `new_frame_sem` semaphore in order for the `auto_insert_purge` function to work properly."]

