#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>
#include <atomic>
#include <condition_variable>

// Define the cache data structure
struct CacheEntry {
  std::string key;
  std::string value;
  int expirationTime;
};

// Define the cache manager class
class CacheManager {
 public:
  CacheManager() {}

  // Add a new entry to the cache
  void add(const std::string& key, const std::string& value, int expirationTime) {
