// Custom memory pool for data points
class DataPointPool {
public:
    // Allocate a new data point object from the pool
    std::unique_ptr<DataPoint> allocate() {
        if (available_.empty()) {
            return std::make_unique<DataPoint>();
        } else {
            auto& available = available_.front();
            available_.pop_front();
            return std::move(available);
        }
    }

    // Return a data point object to the pool
    void deallocate(std::unique_ptr<DataPoint>&& dataPoint) {
        available_.emplace_back(std::move(dataPoint));
    }

private:
    std::list<std::unique_ptr<DataPoint>> available_;
};

// Data point class
class DataPoint {
public:
    // Constructor
    DataPoint() = default;

    // Setters for timestamp, value, and metadata
    void setTimestamp(const std::chrono::system_clock::time_point& timestamp) {
        timestamp_ = timestamp;
    }

    void setValue(double value) {
        value_ = value;
    }

    void setMetadata(const std::string& metadata) {
        metadata_ = metadata;
    }

    // Getters for timestamp, value, and metadata
    const std::chrono::system_clock::time_point& getTimestamp() const {
        return timestamp_;
    }

    double getValue() const {
        return value_;
    }

    const std::string& getMetadata() const {
        return metadata_;
    }

private:
    // Timestamp for the data point
    std::chrono::system_clock::time_point timestamp_;

    // Numerical value of the data point
    double value_;

    // Metadata tag for the data point
    std::string metadata_;
};

// Time series manager class
class TimeSeriesManager {
public:
    // Constructor
    TimeSeriesManager() : dataPointPool_(std::make_unique<DataPointPool>()) {}

    // Add a new data point to the time series
    void addDataPoint(const std::chrono::system_clock::time_point& timestamp, double value, const std::string& metadata) {
        auto dataPoint = dataPointPool_->allocate();
        dataPoint->setTimestamp(timestamp);
        dataPoint->setValue(value);
        dataPoint->setMetadata(metadata);
        dataPoints_.emplace_back(std::move(dataPoint));
    }

    // Get the latest data point in the time series
    std::unique_ptr<DataPoint> getLatestDataPoint() {
        if (dataPoints_.empty()) {
            return nullptr;
        } else {
            return dataPoints_.back().release();
        }
    }

    // Get all data points in the time series between two timestamps
    std::vector<std::unique_ptr<DataPoint>> getDataPoints(const std::chrono::system_clock::time_point& start, const std::chrono::system_clock::time_point& end) {
        std::vector<std::unique_ptr<DataPoint>> result;
        for (auto it = dataPoints_.begin(); it != dataPoints_.end() && (*it)->getTimestamp() <= end; ++it) {
            if ((*it)->getTimestamp() >= start) {
                result.emplace_back((*it).release());
            }
        }
        return result;
    }

private:
    // Data point pool for efficient memory allocation and deallocation
    std::unique_ptr<DataPointPool> dataPointPool_;

    // Vector of all data points in the time series
    std::vector<std::unique_ptr<DataPoint>> dataPoints_;
};
