    ECB, CBC, GCM, CFB
} CipherMode;

typedef struct {
    unsigned char key[32];
    int key_len;
} EncryptionKey;

typedef struct {
    unsigned char iv[16];
    int iv_len;
} InitializationVector;

typedef struct {
    unsigned char* data;
    int len;
} DataBuffer;

int encrypt(CipherMode mode, EncryptionKey key, InitializationVector iv, DataBuffer data) {
    // Initialize the cipher context and set the key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int rc = 0;

    switch (mode) {
        case ECB:
            rc = EVP_EncryptInit(ctx, EVP_aes_128_ecb(), key.key, iv.iv);
            break;
        case CBC:
            rc = EVP_EncryptInit(ctx, EVP_aes_128_cbc(), key.key, iv.iv);
            break;
        case GCM:
            rc = EVP_EncryptInit(ctx, EVP_aes_128_gcm(), key.key, iv.iv);
            break;
        case CFB:
            rc = EVP_EncryptInit(ctx, EVP_aes_128_cfb(), key.key, iv.iv);
            break;
    }

    if (rc == 0) {
        printf("Error initializing the cipher context\n");
        return -1;
    }

    // Encrypt the data
    int len = EVP_EncryptUpdate(ctx, NULL, &len, data.data, data.len);
    unsigned char* enc_data = (unsigned char*)malloc(len * sizeof(char));
    rc = EVP_EncryptUpdate(ctx, enc_data, &len, data.data, data.len);

    if (rc == 0) {
        printf("Error encrypting the data\n");
        return -1;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    free(enc_data);

    return len;
}

int decrypt(CipherMode mode, EncryptionKey key, InitializationVector iv, DataBuffer data) {
    // Initialize the cipher context and set the key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int rc = 0;

    switch (mode) {
        case ECB:
            rc = EVP_DecryptInit(ctx, EVP_aes_128_ecb(), key.key, iv.iv);
            break;
        case CBC:
            rc = EVP_DecryptInit(ctx, EVP_aes_128_cbc(), key.key, iv.iv);
            break;
        case GCM:
            rc = EVP_DecryptInit(ctx, EVP_aes_128_gcm(), key.key, iv.iv);
            break;
        case CFB:
            rc = EVP_DecryptInit(ctx, EVP_aes_128_cfb(), key.key, iv.iv);
            break;
    }

    if (rc == 0) {
        printf("Error initializing the cipher context\n");
        return -1;
    }

    // Decrypt the data
    int len = EVP_DecryptUpdate(ctx, NULL, &len, data.data, data.len);
    unsigned char* dec_data = (unsigned char*)malloc(len * sizeof(char));
    rc = EVP_DecryptUpdate(ctx, dec_data, &len, data.data, data.len);

    if (rc == 0) {
        printf("Error decrypting the data\n");
        return -1;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    free(dec_data);

    return len;
}

