    // Encrypt the data using the specified mode
    int enc_len = encrypt(ECB, key, iv, data);
    unsigned char* enc_data = (unsigned char*)malloc(enc_len * sizeof(char));
    encrypt(ECB, key, iv, data, enc_data);

    // Decrypt the encrypted data using the specified mode
    int dec_len = decrypt(ECB, key, iv, data);
    unsigned char* dec_data = (unsigned char*)malloc(dec_len * sizeof(char));
    decrypt(ECB, key, iv, data, dec_data);

    // Clean up
    free(enc_data);
    free(dec_data);

    return 0;
}
