#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Header structure to store serialized headers
typedef struct {
    char* name;
    char* value;
} header_t;

// Linked list node for storing headers
typedef struct {
    header_t header;
    struct node* next;
} node_t;

// Global variables
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety
node_t* headers = NULL; // Headers list
size_t num_headers = 0; // Number of headers in the list

// Adds a new header to the end of the list, allocating memory as needed
void add_header(const char* name, const char* value) {
    pthread_mutex_lock(&mutex);
    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) { // Memory allocation failed
        fprintf(stderr, "Error: Failed to allocate memory for header\n");
        exit(EXIT_FAILURE);
    }
    new_node->header.name = strdup(name);
    new_node->header.value = strdup(value);
    new_node->next = NULL;
    if (headers) { // Headers list is not empty
        node_t* current_node = headers;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }
        current_node->next = new_node;
    } else { // Headers list is empty
        headers = new_node;
    }
    num_headers++;
    pthread_mutex_unlock(&mutex);
}

// Updates an existing header by name, or adds a new one if it doesn't exist
void update_header(const char* name, const char* value) {
    pthread_mutex_lock(&mutex);
    node_t* current_node = headers;
    while (current_node != NULL && strcmp(name, current_node->header.name) != 0) {
        current_node = current_node->next;
    }
    if (current_node == NULL) { // Header doesn't exist
        add_header(name, value);
    } else { // Update existing header
        free(current_node->header.value);
        current_node->header.value = strdup(value);
    }
    pthread_mutex_unlock(&mutex);
}

// Removes a header by name, if it exists
void remove_header(const char* name) {
    pthread_mutex_lock(&mutex);
    node_t* current_node = headers;
    while (current_node != NULL && strcmp(name, current_node->header.name) != 0) {
        current_node = current_node->next;
    }
    if (current_node == NULL) { // Header doesn't exist
        pthread_mutex_unlock(&mutex);
        return;
    }
    node_t* previous_node = current_node;
    while (current_node->next != NULL && strcmp(name, current_node->next->header.name) == 0) {
        previous_node = current_node;
        current_node = current_node->next;
    }
    if (previous_node == headers) { // Header is the first in the list
        headers = current_node->next;
    } else {
        previous_node->next = current_node->next;
    }
    free(current_node->header.name);
    free(current_node->header.value);
    free(current_node);
    num_headers--;
    pthread_mutex_unlock(&mutex);
}

// Iterates over all headers, calling the given function for each one
void iterate_headers(void (*callback)(const char* name, const char* value)) {
    pthread_mutex_lock(&mutex);
    node_t* current_node = headers;
    while (current_node != NULL) {
        callback(current_node->header.name, current_node->header.value);
        current_node = current_node->next;
    }
    pthread_mutex_unlock(&mutex);
}

// Exports headers to JSON format, allocating memory as needed
char* export_headers_json() {
    pthread_mutex_lock(&mutex);
    char* json = malloc(sizeof(char) * 20); // Initial buffer size
    if (!json) {
        fprintf(stderr, "Error: Failed to allocate memory for JSON\n");
        exit(EXIT_FAILURE);
    }
    size_t json_size = 1; // Current length of the JSON string
    json[0] = '{';
    node_t* current_node = headers;
    while (current_node != NULL) {
        char* name = strdup(current_node->header.name);
        char* value = strdup(current_node->header.value);
        size_t name_size = strlen(name);
        size_t value_size = strlen(value);
        json_size += name_size + value_size;
        // Add header to JSON string
        char* new_json = realloc(json, sizeof(char) * (json_size + 1));
        if (!new_json) {
            fprintf(stderr, "Error: Failed to allocate memory for JSON\n");
            exit(EXIT_FAILURE);
        }
        json = new_json;
        char* json_cursor = json + strlen(json);
        *json_cursor++ = '"';
        memcpy(json_cursor, name, name_size);
        json_cursor += name_size;
        *json_cursor++ = ':';
        *json_cursor++ = '"';
        memcpy(json_cursor, value, value_size);
        json_cursor += value_size;
        *json_cursor++ = '"';
        if (current_node->next != NULL) {
            *json_cursor++ = ',';
            json_size++;
        }
        free(name);
        free(value);
        current_node = current_node->next;
    }
    *json_cursor++ = '}';
    json[json_size] = '\0'; // Terminate the JSON string
    pthread_mutex_unlock(&mutex);
    return json;
}

// Exports headers to text format, allocating memory as needed
char* export_headers_text() {
    pthread_mutex_lock(&mutex);
    char* text = malloc(sizeof(char) * 20); // Initial buffer size
    if (!text) {
        fprintf(stderr, "Error: Failed to allocate memory for text\n");
        exit(EXIT_FAILURE);
    }
    size_t text_size = 1; // Current length of the text string
    node_t* current_node = headers;
    while (current_node != NULL) {
        char* name = strdup(current_node->header.name);
        char* value = strdup(current_node->header.value);
        size_t name_size = strlen(name);
        size_t value_size = strlen(value);
        text_size += name_size + value_size;
        // Add header to text string
        char* new_text = realloc(text, sizeof(char) * (text_size + 1));
        if (!new_text) {
            fprintf(stderr, "Error: Failed to allocate memory for text\n");
            exit(EXIT_FAILURE);
        }
        text = new_text;
        char* text_cursor = text + strlen(text);
        memcpy(text_cursor, name, name_size);
        text_cursor += name_size;
        *text_cursor++ = ':';
        *text_cursor++ = ' ';
        memcpy(text_cursor, value, value_size);
        text_cursor += value_size;
        if (current_node->next != NULL) {
            *text_cursor++ = '\n';
            text_size++;
        }
        free(name);
        free(value);
        current_node = current_node->next;
    }
    text[text_size] = '\0'; // Terminate the text string
    pthread_mutex_unlock(&mutex);
    return text;
}
```

This code uses a linked list to store the headers. The `add_header`, `update_header`, and `remove_header` functions all use the same basic approach: they acquire a lock on the mutex, traverse the linked list until they find the appropriate header, modify its value if necessary, and then release the lock.

The `iterate_headers` function is similar, but it doesn't modify any values. It simply calls the given callback function for each header in the linked list, passing both the name and value of the header as arguments to the callback function. This allows the caller to perform some operation on each header, such as printing its contents or storing them in a database.

The `export_headers_json` and `export_headers_text` functions are more complex because they need to construct a JSON string or text string from all of the headers in the linked list. They use a recursive approach: they call themselves recursively on each header until they have built up a complete JSON or text string. This allows them to traverse the entire linked list and generate a single string that contains all of the headers.

The `export_headers_json` function first allocates some memory for the JSON string, then it adds the opening brace character to the string. It then iterates over each header in the linked list, adding its name and value to the string using `realloc`. If there are any remaining headers after this one, it adds a comma and a newline character before recursively calling itself on those headers. Finally, it adds the closing brace character and terminates the string with a null character.

The `export_headers_text` function works similarly, but instead of using JSON syntax to represent the headers, it uses simple text formatting. It first allocates some memory for the text string, then it iterates over each header in the linked list, adding its name and value to the string using `realloc`. If there are any remaining headers after this one, it adds a newline character before recursively calling itself on those headers. Finally, it terminates the string with a null character.

Overall, these functions demonstrate how to use a mutex to synchronize access to a shared resource (in this case, a linked list) and how to use recursive function calls to build up a large string from smaller pieces.']

