    // Check if the algorithm is supported
    if (!is_supported_algorithm(algorithm)) {
        return -1;
    }

    // Encrypt the data using the chosen algorithm
    int status = 0;
    switch (algorithm[0]) {
        case 'A':
            status = aes256_encrypt(plaintext, plaintext_len, &ciphertext);
            break;
