            status = rsaoaep_decrypt(ciphertext, ciphertext_len, &plaintext);
            break;
        case 'E':
            status = ed25519_decrypt(ciphertext, ciphertext_len, &plaintext);
            break;
    }

    // Check for errors in the decryption process
    if (status != 0) {
        return -2;
    }

    // Return the decrypted data
    return plaintext;
}

// Function to check if an algorithm is supported by the library
int is_supported_algorithm(unsigned char *algorithm) {
    // Check if the algorithm is in the list of supported algorithms
    if (algorithm[0] == 'A' || algorithm[0] == 'C' || algorithm[0] == 'R' || algorithm[0] == 'E') {
        return 1;
    } else {
        return -1;
    }
}

// Function to get data from an external data source
