    // Calculate the hash of the data using SHA-256
    unsigned char hash[32];
    SHA256(data, data_len, hash);

    // Check if the hash matches the expected value
    if (memcmp(hash, "expected_value", 16) == 0) {
        return 1;
    } else {
        return -1;
    }
}
