#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#define NFAPI_CRC_INDICATION_PDU_T 1

typedef struct {
    uint32_t crc;
} nfapi_crc_indication_pdu_t;

typedef struct {
    nfapi_crc_indication_pdu_t *data;
    size_t capacity;
    size_t count;
    bool is_initialized;
} nfapi_crc_list_t;

void nfapi_crc_list_init(nfapi_crc_list_t *list) {
    list->data = NULL;
    list->capacity = 0;
    list->count = 0;
    list->is_initialized = false;
}

void nfapi_crc_list_free(nfapi_crc_list_t *list) {
    if (list->data != NULL) {
        free(list->data);
        list->data = NULL;
    }
    list->capacity = 0;
    list->count = 0;
}

void nfapi_crc_list_add(nfapi_crc_list_t *list, const uint32_t crc) {
    if (!list->is_initialized) {
        list->data = (nfapi_crc_indication_pdu_t *)malloc(sizeof(nfapi_crc_indication_pdu_t));
        list->capacity = 1;
        list->count = 0;
    } else if (list->count == list->capacity) {
        list->data = (nfapi_crc_indication_pdu_t *)realloc(list->data, (list->capacity + 1) * sizeof(nfapi_crc_indication_pdu_t));
        list->capacity++;
    }
    list->data[list->count].crc = crc;
    list->count++;
}

void nfapi_crc_list_remove(nfapi_crc_list_t *list, size_t index) {
    if (index >= list->count) return;
    for (size_t i = index; i < list->count - 1; i++) {
        list->data[i] = list->data[i + 1];
    }
    list->count--;
}

void nfapi_crc_list_clear(nfapi_crc_list_t *list) {
    if (list->data != NULL) {
        free(list->data);
        list->data = NULL;
    }
    list->capacity = 0;
    list->count = 0;
}

size_t nfapi_crc_list_get_count(nfapi_crc_list_t *list) {
    return list->count;
}

bool nfapi_crc_list_contains(nfapi_crc_list_t *list, uint32_t crc) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->data[i].crc == crc) {
            return true;
        }
    }
    return false;
}

void nfapi_crc_list_foreach(nfapi_crc_list_t *list, void (*visit)(uint32_t)) {
    for (size_t i = 0; i < list->count; i++) {
        visit(list->data[i].crc);
    }
}

void nfapi_crc_list_serialize(nfapi_crc_list_t *list, uint8_t *buf) {
    for (size_t i = 0; i < list->count; i++) {
        buf[i] = list->data[i].crc;
    }
}

void nfapi_crc_list_deserialize(nfapi_crc_list_t *list, uint8_t *buf) {
    for (size_t i = 0; i < list->count; i++) {
        list->data[i].crc = buf[i];
    }
}
