    // Add some algorithm instances to the collection
    collection.add("AES", &aes_implementation, true);  // In-memory implementation of AES
    collection.add("RSA", &rsa_implementation, false); // External library-based implementation of RSA

    // Remove an algorithm instance from the collection
    collection.remove("RSA");

    // Get an algorithm instance by name
    CryptoAlgorithmInstance instance = collection.get("AES");
    std::cout << "Algorithm " << instance.name << " has implementation at " << instance.implementation << std::endl;

