// Resource Retrieval

@GET
@Path("/user/{userId}")
public User getUser(@PathParam("userId") String userId) {
    // Check cache for user details
    User cachedUser = cache.get(userId);
    if (cachedUser != null) {
        return cachedUser;
    }

    // Fetch user details from user management API
    try {
        User user = apiClient.getUserDetails(userId).execute().body();
        cache.put(userId, user);
        return user;
    } catch (IOException e) {
        logger.warn("Failed to retrieve user details: {}", e);
        throw new WebApplicationException(e, Status.SERVICE_UNAVAILABLE);
    }
}

@GET
@Path("/user/{userId}/paymentHistory")
public List<Payment> getUserPayments(@PathParam("userId") String userId) {
    // Check cache for payment history
    List<Payment> cachedPayments = cache.get(userId);
    if (cachedPayments != null) {
        return cachedPayments;
    }

    // Fetch payment history from payment processing API
    try {
        PaymentHistory paymentHistory = apiClient.getPaymentHistory(userId).execute().body();
        List<Payment> payments = new ArrayList<>();
        for (PaymentDetail detail : paymentHistory.getDetails()) {
            payments.add(new Payment(detail));
        }
        cache.put(userId, payments);
        return payments;
    } catch (IOException e) {
        logger.warn("Failed to retrieve payment history: {}", e);
        throw new WebApplicationException(e, Status.SERVICE_UNAVAILABLE);
    }
}
