public Response deleteUser(@PathParam("userId") String userId) {
    // Check for soft deletes and fallback mechanism to recover profiles if necessary
    User deletedUser = getUser(userId);
    if (deletedUser.isDeleted()) {
        return Response.status(Status.GONE).entity("Profile has been deleted").build();
    }

    // Cascading actions for archiving payment records and notifying stakeholders
    try {
        apiClient.archivePaymentRecords(userId);
        notifyStakeholders(userId, "Profile has been deleted");
        return Response.ok().build();
    } catch (IOException e) {
        logger.warn("Failed to delete user profile: {}", e);
        throw new WebApplicationException(e, Status.SERVICE_UNAVAILABLE);
    }
}
