// Modular JavaScript function for rendering footer scripts dynamically
function renderFooterScripts(scripts) {
  // Initialize an array to store the HTML elements for the scripts
  const scriptElements = [];

  // Iterate over the scripts array and create a new element for each script object
  scripts.forEach((script) => {
    // Validate the script against a predefined whitelist of allowed domains
    if (!validateScriptDomain(script)) {
      console.warn(`Invalid script domain: ${script.domain}`);
      return;
    }

    // Create a new HTML element for the script
    const scriptElement = document.createElement('script');
    scriptElement.setAttribute('src', script.url);
    scriptElement.setAttribute('type', script.type);

    if (script.async) {
      scriptElement.setAttribute('async', 'true');
    }

    if (script.domain) {
      scriptElement.setAttribute('crossorigin', 'anonymous');
    }

    // Add the CSP directives to the element
    for (let i = 0; i < script.cspDirective.length; i++) {
      const directive = script.cspDirective[i];
      scriptElement.setAttribute('integrity', directive.hash);
      scriptElement.setAttribute('nonce', directive.nonce);
    }

    // Add the element to the array of script elements
    scriptElements.push(scriptElement);
  });

  // Dynamically insert the script elements into the footer
  const footer = document.querySelector('footer');
  scriptElements.forEach((element) => {
    footer.appendChild(element);
  });
}

