    unsigned char buffer[16];
    RAND_bytes(buffer, sizeof(buffer));
    key->key = (unsigned char *)malloc(sizeof(unsigned char) * 16);
    memcpy(key->key, buffer, sizeof(buffer));
    key->length = 16;
    return OK;
}

