    while (!key_retrieval_failed) {
        sleep(1);
    }

    // Handle the key retrieval failure
    handle_key_retrieval_failure();

    return 0;
}

// Initializes the service
void init() {
    // Initialize the key rotation thread
    pthread_mutex_init(&key_lock, NULL);

    // Load the keys from the KMS
    load_keys();

    // Start the key rotation thread
    pthread_t key_rotation_thread;
    if (pthread_create(&key_rotation_thread, NULL, rotate_keys, (void*)&force) != 0) {
        printf("Failed to create key rotation thread\n");
        return -1;
    }
}

// Rotates the keys
void rotate_keys(bool force) {
    // Lock the key lock
    pthread_mutex_lock(&key_lock);

    // Check if the key rotation is enabled
    if (!key_rotation_enabled || force) {
        // Enable the key rotation
        key_rotation_enabled = true;

        // Update the last key rotation time
        last_key_rotation_time = time(NULL);

        // Print a message indicating that the keys have been rotated
        printf("Keys rotated\n");
    }

    // Unlock the key lock
    pthread_mutex_unlock(&key_lock);
}

// Generates a CRC indication PDU
int generate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Lock the key lock
    pthread_mutex_lock(&key_lock);

    // Check if the current key index is valid
    if (current_key_index < 0) {
        // Unlock the key lock
        pthread_mutex_unlock(&key_lock);

        // Return an error
        return -1;
    }

    // Encrypt the data
    int encrypt_result = encrypt_data(pdu->data, pdu->data_size, keys[current_key_index], key_sizes[current_key_index], iv, sizeof(iv));
    if (encrypt_result != 0) {
        // Unlock the key lock
        pthread_mutex_unlock(&key_lock);

        // Return an error
        return -1;
    }

    // Set the CRC indication PDU fields
    pdu->crc_indication_rel8.CR_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    pdu->crc_indication_rel8.data = ciphertext;
    pdu->crc_indication_rel8.data_size = ciphertext_size;

    // Unlock the key lock
    pthread_mutex_unlock(&key_lock);

    return 0;
}

// Encrypts data using the current key
int encrypt_data(unsigned char* data, size_t data_size, unsigned char* key, size_t key_size, unsigned char* iv, size_t iv_size) {
    // Check if the key and IV are valid
    if (key == NULL || iv == NULL) {
        return -1;
    }

    // Encrypt the data using AES-CBC
    int encrypt_result = aes_cbc_encrypt(data, data_size, key, key_size, iv, iv_size);
    if (encrypt_result != 0) {
        return -1;
    }

    return 0;
}

// Decrypts data using the current key
int decrypt_data(unsigned char* ciphertext, size_t ciphertext_size, unsigned char* key, size_t key_size, unsigned char* iv, size_t iv_size) {
    // Check if the key and IV are valid
    if (key == NULL || iv == NULL) {
        return -1;
    }

    // Decrypt the data using AES-CBC
    int decrypt_result = aes_cbc_decrypt(ciphertext, ciphertext_size, key, key_size, iv, iv_size);
    if (decrypt_result != 0) {
        return -1;
    }

    return 0;
}

// Handles a key retrieval failure
void handle_key_retrieval_failure() {
    // Print a message indicating that the key retrieval failed
    printf("Key retrieval failed\n");

    // Set the key rotation flag to false
    key_rotation_enabled = false;
}
