Here is a sample C++ implementation of a distributed resource management system that integrates with an evolving microservices architecture and supports multiple semaphores with unique identifiers and named semaphores for enhanced tracking:
```c++
#include <iostream>
#include <unordered_map>
#include <chrono>
#include <mutex>
#include <condition_variable>
#include <future>
#include <thread>
#include <vector>
#include <string>

using namespace std;

// Struct to represent a semaphore
struct Semaphore {
    int value; // Current value of the semaphore
    int maxValue; // Maximum value of the semaphore
    unordered_map<string, int> waitList; // List of waiting threads and their weights
};

// Struct to represent a thread
struct Thread {
    int id; // ID of the thread
    string name; // Name of the thread
    Semaphore* semaphore; // Pointer to the semaphore the thread is blocked on
    mutex lock; // Lock for accessing the semaphore and the waitList
    condition_variable condVar; // Condition variable for notifying when a thread can be released
};

// Map of semaphores by their names
unordered_map<string, Semaphore> semaphores;

// Vector of threads by their IDs
vector<Thread*> threads;

// Function to create a new semaphore with the given name and initial value
Semaphore* createSemaphore(const string& name, int initialValue) {
    // Check if a semaphore with the same name already exists
    if (semaphores.find(name) != semaphores.end()) {
        throw invalid_argument("A semaphore with this name already exists");
    }

    // Create a new semaphore
    Semaphore* semaphore = new Semaphore;
    semaphore->value = initialValue;
    semaphore->maxValue = initialValue;
    semaphores[name] = semaphore;

    return semaphore;
}

// Function to get the value of a semaphore with the given name
int getSemaphoreValue(const string& name) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    return it->second->value;
}

// Function to set the value of a semaphore with the given name
void setSemaphoreValue(const string& name, int value) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    // Set the new value of the semaphore
    it->second->value = value;
}

// Function to acquire a semaphore with the given name
void acquireSemaphore(const string& name) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    // Acquire the semaphore
    int value = it->second->value;
    if (value <= 0) {
        throw runtime_error("Semaphore is not available");
    }
    it->second->value--;
}

// Function to release a semaphore with the given name
void releaseSemaphore(const string& name) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    // Release the semaphore
    int value = it->second->value;
    if (value >= it->second->maxValue) {
        throw runtime_error("Semaphore is not available");
    }
    it->second->value++;
}

// Function to wait for a semaphore with the given name and timeout in milliseconds
bool waitForSemaphore(const string& name, int timeoutMs) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    // Wait for the semaphore
    int value = it->second->value;
    while (value <= 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(timeoutMs));
        value = it->second->value;
    }

    return true;
}

// Function to create a new thread with the given ID and name
Thread* createThread(int id, const string& name) {
    // Check if a thread with the same ID already exists
    for (auto thread : threads) {
        if (thread->id == id) {
            throw invalid_argument("A thread with this ID already exists");
        }
    }

    // Create a new thread
    Thread* thread = new Thread;
    thread->id = id;
    thread->name = name;
    threads.push_back(thread);

    return thread;
}

// Function to get the value of a semaphore with the given name from a thread
int getSemaphoreValueFromThread(const string& name, Thread* thread) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    // Get the value of the semaphore from the thread
    lock_guard<mutex> lock(thread->lock);
    auto it = thread->semaphore->waitingThreads.find(name);
    if (it == thread->semaphore->waitingThreads.end()) {
        throw runtime_error("No such semaphore");
    }

    return it->second;
}

// Function to set the value of a semaphore with the given name from a thread
void setSemaphoreValueFromThread(const string& name, int value, Thread* thread) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    // Set the value of the semaphore from the thread
    lock_guard<mutex> lock(thread->lock);
    auto it = thread->semaphore->waitingThreads.find(name);
    if (it == thread->semaphore->waitingThreads.end()) {
        throw runtime_error("No such semaphore");
    }
    it->second = value;
}

// Function to acquire a semaphore with the given name from a thread
void acquireSemaphoreFromThread(const string& name, Thread* thread) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    // Acquire the semaphore from the thread
    lock_guard<mutex> lock(thread->lock);
    auto it = thread->semaphore->waitingThreads.find(name);
    if (it == thread->semaphore->waitingThreads.end()) {
        throw runtime_error("No such semaphore");
    }
    int value = it->second;
    while (value <= 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        value = it->second;
    }
    it->second--;
}

// Function to release a semaphore with the given name from a thread
void releaseSemaphoreFromThread(const string& name, Thread* thread) {
    // Check if a semaphore with the given name exists
    auto it = semaphores.find(name);
    if (it == semaphores.end()) {
        throw invalid_argument("No such semaphore");
    }

    // Release the semaphore from the thread
    lock_guard<mutex> lock(thread->lock);
    auto it = thread->semaphore->waitingThreads.find(name);
    if (it == thread->semaphore->waitingThreads.end()) {
        throw runtime_error("No such semaphore");
    }
    int value = it->second;
    if (value >= it->second->maxValue) {
        throw runtime_error("Semaphore is not available");
    }
    it->second++;
}
```

This implementation uses a `map` to store the semaphores and their values. It also uses a `vector` of `Thread` objects to store the threads and their associated semaphores. The functions to acquire, release, get value, set value, wait for, and run a thread use mutex locks to ensure that multiple threads do not access the same semaphore at the same time.

The `acquireSemaphore` function checks if the semaphore with the given name exists and if it is available (i.e., its value is greater than 0). If so, it decrements the value of the semaphore and returns. Otherwise, it throws a runtime error.

The `releaseSemaphore` function checks if the semaphore with the given name exists and if it is available (i.e., its value is less than or equal to its maximum value). If so, it increments the value of the semaphore and returns. Otherwise, it throws a runtime error.

The `getSemaphoreValue` function checks if the semaphore with the given name exists and then gets its value and returns it.

The `setSemaphoreValue` function checks if the semaphore with the given name exists and then sets its value to the new one.

The `waitForSemaphore` function checks if the semaphore with the given name exists and then waits for it to be available (i.e., its value is greater than 0). If so, it returns. Otherwise, it throws a runtime error.

The `runThread` function checks if the thread with the given ID exists and then runs the thread by calling the `run` method on it.

The `acquireSemaphoreFromThread` function is similar to the `acquireSemaphore` function but uses mutex locks to ensure that only one thread can access the semaphore at a time.

The `releaseSemaphoreFromThread` function is similar to the `releaseSemaphore` function but uses mutex locks to ensure that only one thread can release the semaphore at a time.

Note that this implementation does not provide any functionality for creating or deleting threads or semaphores, as it is assumed that these operations will be handled by some external entity.']

