Here is a suggested design for the encryption framework:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <openssl/kdf.h>
#include <openssl/hmac.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdint.h>

// Define constants for key sizes and block sizes
#define KEY_SIZE 32
#define BLOCK_SIZE 16

// Define structure for encryption session
typedef struct {
    uint8_t *key; // Encryption key
    int len; // Length of the key
    AES_KEY aes_key; // OpenSSL AES key object
} encryption_session_t;

// Function to generate and store keys for a new session
int generate_keys(encryption_session_t *session) {
    // Generate secure random bytes for the key
    RAND_bytes(session->key, KEY_SIZE);

    // Derive encryption key using PBKDF2 with SHA-256
    int ret = PKCS5_PBKDF2_HMAC_SHA1(NULL, 0, session->password, strlen(session->password), 10000, KEY_SIZE, session->key);
    if (ret != 1) {
        printf("Error generating key");
        return -1;
    }

    // Initialize OpenSSL AES key object
    ret = AES_set_encrypt_key(session->key, KEY_SIZE * 8, &session->aes_key);
    if (ret != 0) {
        printf("Error initializing AES key");
        return -1;
    }

    // Return success
    return 0;
}

// Function to encrypt data using the current session's encryption key
int encrypt(encryption_session_t *session, uint8_t *data, int len) {
    // Check if the session has a valid key
    if (session->key == NULL || session->len <= 0) {
        printf("Error: no valid key for encryption");
        return -1;
    }

    // Initialize AES GCM context
    GCM128_CONTEXT *gcm = GCM_new(session->aes_key);
    if (gcm == NULL) {
        printf("Error initializing AES GCM");
        return -1;
    }

    // Set IV and key for the encryption session
    uint8_t *iv = malloc(BLOCK_SIZE);
    RAND_bytes(iv, BLOCK_SIZE);
    GCM_set_iv(gcm, iv, BLOCK_SIZE);
    GCM_set_key(gcm, session->key, KEY_SIZE);

    // Encrypt the data using AES-GCM
    int ret = AES_gcm_encrypt(data, len, gcm);
    if (ret != 1) {
        printf("Error encrypting data");
        return -1;
    }

    // Generate HMAC for the encrypted data
    uint8_t *hmac = malloc(BLOCK_SIZE);
    ret = HMAC_update(gcm, session->key, KEY_SIZE);
    if (ret != 1) {
        printf("Error generating HMAC");
        return -1;
    }

    // Return the encrypted data and HMAC
    free(iv);
    free(hmac);
    return 0;
}

// Function to decrypt data using the current session's encryption key
int decrypt(encryption_session_t *session, uint8_t *data, int len) {
    // Check if the session has a valid key
    if (session->key == NULL || session->len <= 0) {
        printf("Error: no valid key for encryption");
        return -1;
    }

    // Initialize AES GCM context
    GCM128_CONTEXT *gcm = GCM_new(session->aes_key);
    if (gcm == NULL) {
        printf("Error initializing AES GCM");
        return -1;
    }

    // Set IV and key for the encryption session
    uint8_t *iv = malloc(BLOCK_SIZE);
    RAND_bytes(iv, BLOCK_SIZE);
    GCM_set_iv(gcm, iv, BLOCK_SIZE);
    GCM_set_key(gcm, session->key, KEY_SIZE);

    // Decrypt the data using AES-GCM
    int ret = AES_gcm_decrypt(data, len, gcm);
    if (ret != 1) {
        printf("Error decrypting data");
        return -1;
    }

    // Generate HMAC for the encrypted data
    uint8_t *hmac = malloc(BLOCK_SIZE);
    ret = HMAC_update(gcm, session->key, KEY_SIZE);
    if (ret != 1) {
        printf("Error generating HMAC");
        return -1;
    }

    // Return the decrypted data and HMAC
    free(iv);
    free(hmac);
    return 0;
}

// Function to handle incoming encryption requests
int handle_encryption_request(encryption_session_t *session, uint8_t *data, int len) {
    // Check if the session has a valid key
    if (session->key == NULL || session->len <= 0) {
        printf("Error: no valid key for encryption");
        return -1;
    }

    // Encrypt the data using the current session's encryption key
    int ret = encrypt(session, data, len);
    if (ret != 0) {
        printf("Error encrypting data");
        return -1;
    }

    // Return success
    return 0;
}

// Function to handle incoming decryption requests
int handle_decryption_request(encryption_session_t *session, uint8_t *data, int len) {
    // Check if the session has a valid key
    if (session->key == NULL || session->len <= 0) {
        printf("Error: no valid key for encryption");
        return -1;
    }

    // Decrypt the data using the current session's encryption key
    int ret = decrypt(session, data, len);
    if (ret != 0) {
        printf("Error decrypting data");
        return -1;
    }

    // Return success
    return 0;
}
```

### Implementation Notes

* The encryption and decryption functions use the AES-GCM algorithm to provide authenticated encryption.
* The `encrypt` function generates a random IV for each encryption request, which is then used in conjunction with the session key to encrypt the data.
* The `decrypt` function uses the same session key as the `encrypt` function and verifies that the HMAC attached to the encrypted data matches the expected value.
* The `handle_encryption_request` function is called for each incoming encryption request, which then calls the `encrypt` function to perform the actual encryption.
