### Sample Implementation:
```scss
#include <iostream>
#include <cmath>
#include <ctime>
#include <climits>
using namespace std;

// Struct to represent a state in the FSA
struct State {
    int id;
    string name;
    bool isFinal;
};

// Struct to represent an edge between two states in the FSA
struct Edge {
    State* fromState;
    State* toState;
    char label;
};

// Class to manage a finite state automaton with dynamic state lists
class FSA {
public:
    // Constructor
    FSA();

    // Destructor
    ~FSA();

    // Add a new state to the FSA
    void addState(int id, string name, bool isFinal) {
        states[id] = new State{id, name, isFinal};
    }

    // Remove a state from the FSA
    void removeState(int id) {
        states.erase(id);
    }

    // Get a state by its ID
    State* getStateById(int id) {
        return states[id];
    }

    // Add an edge between two states in the FSA
    void addEdge(int fromId, int toId, char label) {
        edges[fromId].push_back(new Edge{states[fromId], states[toId], label});
    }

    // Remove an edge between two states in the FSA
    void removeEdge(int fromId, int toId) {
        for (auto it = edges[fromId].begin(); it != edges[fromId].end(); ++it) {
            if ((*it)->toState->id == toId) {
                delete *it;
                edges[fromId].erase(it);
                break;
            }
        }
    }

    // Get all edges starting at a given state
    vector<Edge*> getEdgesFromState(int id) {
        return edges[id];
    }

    // Get all edges ending at a given state
    vector<Edge*> getEdgesToState(int id) {
        vector<Edge*> result;
        for (auto it = edges.begin(); it != edges.end(); ++it) {
            if ((*it)->second->toState->id == id) {
                result.push_back((*it)->first);
            }
        }
        return result;
    }

    // Update the FSA with new data from an external source
    void update() {
        // TODO: Implement logic to update the FSA's states and edges based on external data sources.
    }

    // Print the FSA's current state
    void printCurrentState() {
        for (auto it = states.begin(); it != states.end(); ++it) {
            cout << (*it)->id << " : " << (*it)->name << endl;
        }
    }

private:
    // Map of states by ID
    map<int, State*> states;

    // Map of edges by starting state
    map<int, vector<Edge*>> edges;
};
```
