#include <curl/curl.h>
#include <json-c/json.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CACHE_AGE 600 // 10 minutes

struct cache {
    char *hostname;
    char *ip;
};

static int is_valid_auth(const char *username, const char *password) {
    return strcmp(username, "admin") == 0 && strcmp(password, "password") == 0;
}

static struct cache *get_cached_ip(char *hostname) {
    struct cache *cache = NULL;
    for (int i = 0; i < MAX_CACHE_AGE; i++) {
        if (strcmp(hostname, cache->hostname) == 0) {
            return &cache->ip;
        }
    }
    return NULL;
}

static struct cache *set_cached_ip(char *hostname, char *ip) {
    struct cache *cache = malloc(sizeof(struct cache));
    cache->hostname = hostname;
    cache->ip = ip;
    return cache;
}

static void delete_cached_ip(struct cache *cache) {
    free(cache);
}

static int execute_command(char *command, char *username, char *password) {
    if (!is_valid_auth(username, password)) {
        return -1;
    }

    CURL *curl;
    CURLcode res;
    struct cache *cache = get_cached_ip(hostname);
    if (cache != NULL) {
        curl_easy_setopt(curl, CURLOPT_DNS_CACHE_TIMEOUT, MAX_CACHE_AGE);
        curl_easy_setopt(curl, CURLOPT_RESOLVE, cache->ip);
    } else {
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            return -1;
        }
    }

    // Set the command to be executed on the remote server
    curl_easy_setopt(curl, CURLOPT_URL, "https://example.com/command");
    curl_easy_setopt(curl, CURLOPT_USERNAME, username);
    curl_easy_setopt(curl, CURLOPT_PASSWORD, password);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, command);

    // Set the response handler for streaming the results back to the client
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, stdout);

    // Perform the command execution and handle any errors
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        return -1;
    }

    delete_cached_ip(cache);
    return 0;
}

static size_t write_callback(char *ptr, size_t size, size_t nmemb, void *userdata) {
    // Write the response from the remote server to stdout
    fwrite(ptr, size, nmemb, userdata);
    return size * nmemb;
}
