public class VersionNumberProcessor
{
    // Static members to store file extension mappings and the latest version number
    private static readonly Dictionary<string, string> _fileExtensionMappings = new Dictionary<string, string>();
    private static int _latestVersionNumber = 0;

    // Interface for processing a list of filenames with embedded version numbers
    public static List<string> ProcessFilenames(List<string> filenames)
    {
        var processedFilenames = new List<string>();

        foreach (var filename in filenames)
        {
            // Extract the version number using sscanf() and update the file name to a new format 'vX.Y.Z.<type>'
            var versionNumber = sscanf(filename, "%d", _latestVersionNumber);
            processedFilenames.Add($"v{versionNumber}.{_latestVersionNumber}.{_fileExtensionMappings[GetFileType(filename)]}");
        }

        return processedFilenames;
    }

    // Helper function to get the file type from a filename
    private static string GetFileType(string filename)
    {
        var extension = Path.GetExtension(filename);

        if (!_fileExtensionMappings.ContainsKey(extension))
        {
            throw new Exception($"Unsupported file type: {extension}");
        }

        return _fileExtensionMappings[extension];
    }
}
