    public class RandomValueGenerator
    {
        private readonly Dictionary<string, int> _distributions = new Dictionary<string, int>();
        private readonly object _lock = new object();

        public RandomValueGenerator()
        {
            // Initialize the distribution dictionary with uniform and normal distributions
            _distributions["uniform"] = 0;
            _distributions["normal"] = 1;
        }

        public async Task<int> GenerateAsync(string distribution, int maxValue)
        {
            var random = new Random();
            var value = random.Next(maxValue);

