// Define structure to store sensor reading data
typedef struct SensorReading {
    int id;          // Unique identifier for the sensor
    long timestamp;  // Timestamp of the reading (epoch time)
    char *sensor_type;   // Type of sensor (e.g., temperature, humidity, pressure, wind speed)
    float measurements[4];  // Array to store measurement values for each sensor type
    int quality_flags[4];  // Array to store quality flags for each measurement value
} SensorReading;

// Function to load a resource bundle from a file path and return the number of items in the bundle
int load_resource_bundle(const char *filepath) {
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Allocate memory for the bundle and its items
    SensorReading *bundle = malloc(sizeof(SensorReading) * 256);
    if (bundle == NULL) {
        perror("Error allocating memory");
        return -1;
    }

    // Load resource bundle from file
    for (int i = 0; i < 256; i++) {
        SensorReading reading = {0};
        fscanf(fp, "%d %ld %s", &reading.id, &reading.timestamp, reading.sensor_type);
        for (int j = 0; j < 4; j++) {
            fscanf(fp, "%f %d", &reading.measurements[j], &reading.quality_flags[j]);
        }
        bundle[i] = reading;
    }

    // Close file stream
    fclose(fp);

    return 256;  // Return the number of items in the bundle
}
