# Define constants for the API endpoints and data formats
SENSOR_DATA_ENDPOINT = "https://example.com/sensors"
RAW_DATA_FORMAT = "json"
PROCESSED_DATA_FORMAT = "csv"

# Define a class to manage the sensor data processing pipeline
class SensorDataProcessor:
    def __init__(self):
        self.queue = Queue()
        self.processed_data = []
        self.sensor_types = {}
        self.log = logging.getLogger(__name__)

    # Define a function to process the sensor data stream
    def process(self, sensor_data: List[Dict]):
        for data in sensor_data:
            if "type" not in data:
                self.log.warning("Sensor data missing type field")
                continue

            # Add the data to the queue
            self.queue.put(data)

    # Define a function to handle errors during processing
    def error_handler(self, exception):
        self.log.error(f"Error processing sensor data: {exception}")

    # Define a function to process the data in the queue
    def process_queue(self):
        while True:
            try:
                data = self.queue.get()

                if data["type"] not in self.sensor_types:
                    self.log.info("New sensor type detected")
                    self.sensor_types[data["type"]] = 1
                else:
                    self.sensor_types[data["type"]] += 1

                # Process the data and add it to the processed data list
                self.processed_data.append(self.process_data(data))

            except Exception as e:
                self.error_handler(e)

            finally:
                self.queue.task_done()

    # Define a function to process the data and return it in the desired format
    def process_data(self, data: Dict):
        # Convert the raw data to the processed data format
        processed_data = {
            "type": data["type"],
            "value": data["value"]
        }

        return processed_data

    # Define a function to export the processed data to an external service
    def export(self):
        while True:
            try:
                if not self.processed_data:
                    time.sleep(1)
                    continue

                # Export the processed data to an external service
                requests.post(SENSOR_DATA_ENDPOINT, json=self.processed_data)

            except Exception as e:
                self.error_handler(e)

            finally:
                self.processed_data = []

