#include <stdbool.h>

// Define a structure to represent an NFAPI_CRC_INDICATION_PDU_T
struct NFAPI_CRC_INDICATION_PDU_T {
    int id;
    char* message;
};

// Define a priority enum for event severity
enum Priority {
    CRITICAL,
    HIGH,
    MEDIUM,
    LOW,
};

// Define a structure to represent a log entry
struct LogEntry {
    int id;
    char* message;
    enum Priority priority;
};

// Define a queue for storing log entries
struct Queue {
    struct LogEntry** array;
    size_t capacity;
    size_t count;
};

// Initialize a queue with a given capacity
void initQueue(struct Queue* q, size_t capacity) {
    q->array = malloc(sizeof(struct LogEntry*) * capacity);
    if (q->array == NULL) {
        printf("Error: failed to allocate memory for log queue\n");
        exit(-1);
    }
    q->capacity = capacity;
    q->count = 0;
}

// Add an entry to the end of the queue, return false if the queue is full
bool addEntry(struct Queue* q, struct LogEntry* entry) {
    if (q->count == q->capacity) {
        printf("Error: log queue is full\n");
        return false;
    }
    q->array[q->count] = entry;
    q->count++;
    return true;
}

// Remove an entry from the beginning of the queue, return NULL if the queue is empty
struct LogEntry* removeEntry(struct Queue* q) {
    if (q->count == 0) {
        return NULL;
    }
    struct LogEntry* entry = q->array[0];
    memmove(q->array, q->array + 1, sizeof(struct LogEntry*) * (q->capacity - 1));
    q->count--;
    return entry;
}

// Clear all entries in the queue
void clearQueue(struct Queue* q) {
    for (size_t i = 0; i < q->count; i++) {
        free(q->array[i]);
    }
    q->count = 0;
}

// Define a structure to represent the logging service
struct LoggingService {
    struct Queue* queue;
    pthread_mutex_t lock;
};

// Initialize a logging service with a given capacity for the log queue
void initLoggingService(struct LoggingService* s, size_t capacity) {
    s->queue = malloc(sizeof(struct Queue));
    if (s->queue == NULL) {
        printf("Error: failed to allocate memory for logging service\n");
        exit(-1);
    }
    initQueue(s->queue, capacity);
    pthread_mutex_init(&s->lock, NULL);
}

// Add a log entry to the queue, return false if the queue is full
bool addLogEntry(struct LoggingService* s, struct LogEntry* entry) {
    bool success = false;
    pthread_mutex_lock(&s->lock);
    success = addEntry(s->queue, entry);
    pthread_mutex_unlock(&s->lock);
    return success;
}

// Remove a log entry from the queue, return NULL if the queue is empty
struct LogEntry* removeLogEntry(struct LoggingService* s) {
    struct LogEntry* entry = NULL;
    pthread_mutex_lock(&s->lock);
    entry = removeEntry(s->queue);
    pthread_mutex_unlock(&s->lock);
    return entry;
}

// Clear all log entries in the queue
void clearLogEntries(struct LoggingService* s) {
    pthread_mutex_lock(&s->lock);
    clearQueue(s->queue);
    pthread_mutex_unlock(&s->lock);
}

// Define a structure to represent the logging notification channel
struct LogNotificationChannel {
    struct LoggingService* service;
    bool isActive;
};

// Initialize a logging notification channel with a given logging service
void initLogNotificationChannel(struct LogNotificationChannel* c, struct LoggingService* s) {
    c->service = s;
    c->isActive = true;
}

// Activate or deactivate the notification channel based on the given state
void setLogNotificationChannelState(struct LogNotificationChannel* c, bool isActive) {
    c->isActive = isActive;
}

// Define a structure to represent the logging system
struct LoggingSystem {
    struct LoggingService** services;
    size_t numServices;
};

// Initialize a logging system with a given number of logging services
void initLoggingSystem(struct LoggingSystem* s, size_t numServices) {
    s->services = malloc(sizeof(struct LoggingService*) * numServices);
    if (s->services == NULL) {
        printf("Error: failed to allocate memory for logging system\n");
        exit(-1);
    }
    s->numServices = numServices;
}

// Add a logging service to the system, return false if the system is full
bool addLoggingService(struct LoggingSystem* s, struct LoggingService* service) {
    if (s->numServices == 0) {
        printf("Error: logging system is full\n");
        return false;
    }
    s->services[s->numServices - 1] = service;
    s->numServices--;
    return true;
}

// Remove a logging service from the system, return NULL if the system is empty
struct LoggingService* removeLoggingService(struct LoggingSystem* s) {
    struct LoggingService* service = NULL;
    if (s->numServices == 0) {
        return NULL;
    }
    service = s->services[s->numServices - 1];
    memmove(s->services + 1, s->services, sizeof(struct LoggingService*) * (s->numServices - 1));
    s->numServices++;
    return service;
}

// Clear all logging services in the system
void clearLoggingSystem(struct LoggingSystem* s) {
    for (size_t i = 0; i < s->numServices; i++) {
        free(s->services[i]);
    }
    s->numServices = 0;
}

// Define a structure to represent the logging manager
struct LoggingManager {
    struct LoggingSystem* system;
    struct LogNotificationChannel** channels;
    size_t numChannels;
};

// Initialize a logging manager with a given number of logging services and notification channels
void initLoggingManager(struct LoggingManager* m, size_t numServices, size_t numChannels) {
    m->system = malloc(sizeof(struct LoggingSystem));
    if (m->system == NULL) {
        printf("Error: failed to allocate memory for logging manager\n");
        exit(-1);
    }
    initLoggingSystem(m->system, numServices);
    m->channels = malloc(sizeof(struct LogNotificationChannel*) * numChannels);
    if (m->channels == NULL) {
        printf("Error: failed to allocate memory for logging manager\n");
        exit(-1);
    }
    for (size_t i = 0; i < numChannels; i++) {
        m->channels[i] = malloc(sizeof(struct LogNotificationChannel));
        if (m->channels[i] == NULL) {
            printf("Error: failed to allocate memory for logging manager\n");
            exit(-1);
        }
        initLogNotificationChannel(m->channels[i], m->system);
    }
    m->numChannels = numChannels;
}

// Add a logging service to the system, return false if the system is full
bool addLoggingServiceToManager(struct LoggingManager* m, struct LoggingService* service) {
    bool success = false;
    pthread_mutex_lock(&m->system->lock);
    success = addLoggingService(m->system, service);
    pthread_mutex_unlock(&m->system->lock);
    return success;
}

// Remove a logging service from the system, return NULL if the system is empty
struct LoggingService* removeLoggingServiceFromManager(struct LoggingManager* m) {
    struct LoggingService* service = NULL;
    pthread_mutex_lock(&m->system->lock);
    service = removeLoggingService(m->system);
    pthread_mutex_unlock(&m->system->lock);
    return service;
}

// Set the state of a logging notification channel, return false if the channel does not exist
bool setLogNotificationChannelStateInManager(struct LoggingManager* m, struct LogNotificationChannel* channel, bool isActive) {
    bool success = false;
    pthread_mutex_lock(&m->system->lock);
    for (size_t i = 0; i < m->numChannels; i++) {
        if (channel == m->channels[i]) {
            setLogNotificationChannelState(m->channels[i], isActive);
            success = true;
            break;
        }
    }
    pthread_mutex_unlock(&m->system->lock);
    return success;
}

// Log a message to all logging services in the system, return false if the system is empty
bool logMessageToManager(struct LoggingManager* m, struct LogEntry* entry) {
    bool success = false;
    pthread_mutex_lock(&m->system->lock);
    for (size_t i = 0; i < m->numServices; i++) {
        addLogEntry(m->services[i], entry);
    }
    pthread_mutex_unlock(&m->system->lock);
    return success;
}

// Clear all logging services and notification channels in the system
void clearLoggingManager(struct LoggingManager* m) {
    pthread_mutex_lock(&m->system->lock);
    for (size_t i = 0; i < m->numChannels; i++) {
        free(m->channels[i]);
    }
    clearLoggingSystem(m->system);
    pthread_mutex_unlock(&m->system->lock);
}

int main() {
    struct LoggingManager m;
    initLoggingManager(&m, 2, 3);

    // Add logging services and notification channels
    struct LoggingService* s1 = malloc(sizeof(struct LoggingService));
    struct LogNotificationChannel* c1 = malloc(sizeof(struct LogNotificationChannel));
    addLoggingServiceToManager(&m, s1);
    addLogNotificationChannel(&m, c1);

    // Set the state of a logging notification channel
    setLogNotificationChannelStateInManager(&m, c1, true);

    // Log a message to all logging services and notification channels
    struct LogEntry* e = malloc(sizeof(struct LogEntry));
    logMessageToManager(&m, e);

    // Remove a logging service and notification channel
    removeLoggingServiceFromManager(&m);
    free(c1);

    // Clear all logging services and notification channels
    clearLoggingManager(&m);
    return 0;
}']

