    script.src = url;
    script.async = true;

    // Add event listeners for loading, error, and readystatechange events
    this.eventListeners[url] = {
      onload: () => {
        // Remove the script element from the DOM once it has loaded
        script.remove();
        this.scriptCache[url] = true;
        this.cachedScripts.push(url);
        return Promise.resolve();
      },
      onerror: (e) => {
        // Remove the script element from the DOM if it encounters an error
        script.remove();
        delete this.loadingScripts[url];
        return Promise.reject(e);
      },
      onreadystatechange: () => {
        if (script.readyState === "complete") {
          // Remove the script element from the DOM once it has loaded
          script.remove();
          this.scriptCache[url] = true;
          this.cachedScripts.push(url);
          return Promise.resolve();
        }
      },
    };

    script.addEventListener("load", this.eventListeners[url].onload);
    script.addEventListener("error", this.eventListeners[url].onerror);
    script.addEventListener("readystatechange", this.eventListeners[url].onreadystatechange);

    // Add the script element to the DOM and mark it as loading
    document.body.appendChild(script);
    this.loadingScripts[url] = true;

    return new Promise((resolve, reject) => {
      this.eventListeners[url].onload = resolve;
      this.eventListeners[url].onerror = reject;
    });
  }

  unloadScript(url) {
    // Check if the script is already loaded and cached
    if (!this.scriptCache[url]) {
      return Promise.resolve();
    }

    // Remove the script element from the DOM and clear its event listeners
    const script = document.querySelector(`script[src="${url}"]`);
    script.removeEventListener("load", this.eventListeners[url].onload);
    script.removeEventListener("error", this.eventListeners[url].onerror);
    script.removeEventListener("readystatechange", this.eventListeners[url].onreadystatechange);
    delete this.loadingScripts[url];

    // Remove the script element from the cache and return a promise
    delete this.scriptCache[url];
    return Promise.resolve();
  }

  executeScript(url) {
    // Check if the script is already loaded and cached
    if (!this.scriptCache[url]) {
      return Promise.reject(`Script ${url} not found in cache`);
    }

    // Execute the script function from the cache
    const script = this.scriptCache[url];
    return Promise.resolve(script());
  }

  clearCache() {
    // Clear the script cache and remove all event listeners
    this.scriptCache = {};
    this.cachedScripts = [];
    Object.keys(this.eventListeners).forEach((url) => {
      const script = document.querySelector(`script[src="${url}"]`);
      script.removeEventListener("load", this.eventListeners[url].onload);
      script.removeEventListener("error", this.eventListeners[url].onerror);
      script.removeEventListener("readystatechange", this.eventListeners[url].onreadystatechange);
    });
    this.eventListeners = {};
  }
}

// Export the DynamicScriptLoader class
export default DynamicScriptLoader;
