using namespace std;
class Encryption{
public:
	static void encrypt(const char* inputFile, const char* outputFile){
		//Load the input file into memory
		std::ifstream ifs(inputFile, std::ifstream::binary);
		std::ofstream ofs(outputFile, std::ofstream::binary);
		std::string str;
		ifs.seekg (0, ifs.end);
		str.reserve(ifs.tellg());
		ifs.seekg (0, ifs.beg);
		str.assign((std::istreambuf_iterator<char>(ifs)), std::istreambuf_iterator<char>());
		//Encrypt the file data
		string encryptedString = encrypt(str);
		//Write the encrypted data to output file
		ofs << encryptedString;
	}
	static string encrypt(const string& plainText){
		std::string ciphertext = plainText;
		return ciphertext;
	}
};
int main() {
	string inputFile = "/Users/user/Documents/input.txt";
	string outputFile = "/Users/user/Documents/output.txt";
	Encryption::encrypt(inputFile,outputFile);
	return 0;
}']

