// Define a structure to hold network performance metrics
struct NetworkMetrics {
    int crc_errors;
    int packet_loss;
};

// Define a function to append the current date and time to a string,
// respecting a maximum size limit and ensuring case sensitivity.
void appendDateTime(char* buffer, size_t buflen, time_t now) {
    struct tm* tm = localtime(&now);
    strftime(buffer, buflen, "%F %T", tm);
