    struct timespec timestamp = clock_gettime(CLOCK_REALTIME);
    char *formatted_datetime = formatDatetime(timestamp, config->date_format);
    token->access_token = realloc(token->access_token, strlen(token->access_token) + formatted_datetime.length() + 1);
    strcat(token->access_token, formatted_datetime);
  }

  // Log successful authentication with details
  char *success = "Valid access token";
  logger->log(success);
}

// Return true if UUID string is valid, false otherwise
bool isValidUUID(const char *uuid) {
  uuid_t parsed;
  return uuid_parse(uuid, &parsed) == 0 && uuid_is_valid(&parsed) != 0;
}

// Format current UTC date-time using specified format string and return as a new string
char *formatDatetime(struct timespec timestamp, const char *format) {
  time_t t = (time_t)timestamp.tv_sec;
  struct tm* tm = gmtime(&t);
  size_t len = strftime(NULL, 0, format, tm);
  char* buffer = malloc(len + 1);
  strftime(buffer, len + 1, format, tm);
  return buffer;
}
```
Note that this is just a sample implementation and may need to be modified based on specific requirements. Additionally, the function assumes that the external authentication services are already configured and available.']

