['package rust_llvm;

use std::path::Path;
use std::process::Command;

pub struct Compiler {
    llvm: String,
    cwd: String,
}

impl Compiler {
    pub fn new() -> Self {
        Self {
            llvm: "llvm".to_string(),
            cwd: Path::new(".").to_path_buf().into_os_string().to_str().unwrap().to_string(),
        }
    }

    pub fn set_llvm(&mut self, llvm: &str) {
        self.llvm = llvm.to_string();
    }

    pub fn compile(&self, file: &Path) -> Result<String, String> {
        let mut cmd = Command::new(self.llvm);
        cmd.arg("-f").arg(file);
        let output = cmd.output().unwrap();
        if !output.status.success() {
            return Err(String::from_utf8(output.stderr).unwrap());
        }
        Ok(String::from_utf8(output.stdout).unwrap())
    }
}
