Here's an example implementation of a modular C++ logging framework that meets the given requirements:
```c++
#include <string>
#include <map>
#include <chrono>
#include <future>
#include <mutex>
#include <condition_variable>
#include <json/json.h>

// Log level enumeration
enum class LogLevel {
    ERROR,
    WARNING,
    INFO,
    DEBUG
};

// Configuration structure for the logging framework
struct Config {
    // JSON configuration object
    Json::Value configJson;

    // Map of log levels to their corresponding severity levels
    std::map<LogLevel, int> logLevels;

    // Logging level for this instance
    LogLevel logLevel = LogLevel::INFO;
};

// Log message structure
struct LogMessage {
    // Timestamp in milliseconds since epoch
    std::chrono::milliseconds timestamp;

    // Log level of the message
    LogLevel level;

    // Message text
    std::string message;
};

// Logging framework class
class Logger {
public:
    // Constructor
    Logger(const Config& config) : config_(config), logLevels_(config.logLevels) {}

    // Method to log a message at the specified level
    void log(LogLevel level, const std::string& message) {
        if (level >= logLevels_.at(config_.logLevel)) {
            LogMessage msg = {std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()), level, message};
            messages_.push_back(msg);
        }
    }

    // Method to flush the log buffer and export logged messages to a remote service
    void exportMessages() {
