class Program
{
    static void Main(string[] args)
    {
        // Get the current process ID
        int pid = Process.GetCurrentProcess().Id;

        // Install a logging hook to capture the exit code of the subprocess
        using (var loggingHook = new LoggingHook(pid))
        {
            // Compile the Rust code with the custom logging hook installed
            int exitCode = CompileRustCode(loggingHook);

            // Print the exit code and log the time taken for compilation
            Console.WriteLine($"Exit code: {exitCode}");
            Console.WriteLine($"Compilation time: {loggingHook.GetTimeTaken()} seconds");
        }
    }

    private static int CompileRustCode(LoggingHook loggingHook)
    {
        // Install an ice hook to catch any errors that occur during compilation
        using (var iceHook = new IceHook())
        {
            // Run the Rust compiler with a custom logging hook installed
            int exitCode = rustc_driver::catch_with_exit_code(loggingHook.GetExitCode);

            // If an error occurred during compilation, report it and return a non-zero exit code
            if (iceHook.HasError())
            {
                Console.WriteLine($"Error during Rust compilation: {iceHook.GetError()}");
                return -1;
            }

            // Return the exit code of the subprocess
            return exitCode;
        }
    }
}

class LoggingHook : IDisposable
{
    private int _pid;
    private long _startTime;
    private long _endTime;

    public LoggingHook(int pid)
    {
        _pid = pid;
        _startTime = DateTime.UtcNow.Ticks;
    }

    public void Dispose()
    {
        _endTime = DateTime.UtcNow.Ticks;
    }

    public int GetExitCode()
    {
        // Get the exit code of the subprocess
        return Process.GetProcessById(_pid).ExitCode;
    }

    public TimeSpan GetTimeTaken()
    {
        // Calculate the time taken for compilation
        return new TimeSpan(_endTime - _startTime);
    }
}
