Here is a proposed C function that loads a resource bundle from a file and returns the number of items in the bundle:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int load_resource_bundle(const char *filepath) {
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        return -1;
    }

    // Allocate memory for the bundle and its items
    int num_items = 0;
    char **bundle = malloc(sizeof(char *) * num_items);
    if (bundle == NULL) {
        fclose(fp);
        return -1;
    }

    // Read the file line by line and add each item to the bundle
    while (!feof(fp)) {
        char *line = malloc(256);
        if (fgets(line, 256, fp) != NULL) {
            num_items++;
            bundle[num_items - 1] = line;
        } else {
            free(bundle);
            return -1;
        }
    }

    // Close the file and return the number of items in the bundle
    fclose(fp);
    return num_items;
}
```
This function takes a path to the resource file as input and returns the number of items in the bundle. It allocates memory for the bundle and its items using dynamic memory allocation, and includes error checking and handling to ensure robust operation.']

