void read_binary_file(const char *filename, char **buffer, size_t *size) {
    FILE *fp;
    if ((fp = fopen(filename, "rb")) == NULL) {
        perror("fopen");
        exit(1);
    }
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);
    *buffer = malloc((file_size + 1) * sizeof(char));
    if (*buffer == NULL) {
        perror("malloc");
        exit(1);
    }
    fread(*buffer, file_size, 1, fp);
    (*buffer)[file_size] = '\0';
    *size = file_size;
}

