using namespace std;

const int MAX_AUDIO_STREAMS = 32;
const int MAX_CONCURRENT_REQUESTS = 50;
const int MAX_TIMEOUT_SECONDS = 10;
const int MAX_RATE_LIMIT_ERRORS = 10;
const int MIN_DELAY_BETWEEN_RETRIES = 1000; // ms
const int MAX_DELAY_BETWEEN_RETRIES = 60000; // ms

struct AudioStream {
    string id;
    string format;
    int bitrate;
    int samplingRate;
};

struct TranscodingRequest {
    string audioId;
    string outputFormat;
    int outputBitrate;
    int outputSamplingRate;
};

struct TranscodingResult {
    bool success;
    string errorMessage;
    string transcodedAudio;
};

class AudioPipeline {
private:
    mutex audioStreamsMutex;
    vector<AudioStream> audioStreams;
    queue<TranscodingRequest> transcodingQueue;
    map<string, bool> streamStatuses; // key: streamId, value: true/false (active/inactive)
    map<string, TranscodingResult> transcodingResults; // key: audioId, value: transcoding result
    condition_variable queueNotEmptyCondVar;
    bool isShuttingDown = false;

public:
    AudioPipeline() {
        this->audioStreamsMutex.lock();
        this->audioStreams = vector<AudioStream>();
        this->transcodingQueue = queue<TranscodingRequest>();
        this->streamStatuses = map<string, bool>();
        this->transcodingResults = map<string, TranscodingResult>();
        this->queueNotEmptyCondVar.notify_all();
    }

    void addAudioStream(string id, string format, int bitrate, int samplingRate) {
        lock_guard<mutex> lg(this->audioStreamsMutex);
        this->audioStreams.push_back({id, format, bitrate, samplingRate});
    }

    void removeAudioStream(string id) {
        lock_guard<mutex> lg(this->audioStreamsMutex);
        for (int i = 0; i < this->audioStreams.size(); i++) {
            if (this->audioStreams[i].id == id) {
                this->audioStreams.erase(this->audioStreams.begin() + i);
                break;
            }
        }
    }

    void handleTranscodingRequest(TranscodingRequest request) {
        string audioId = request.audioId;
        int outputBitrate = request.outputBitrate;
        int outputSamplingRate = request.outputSamplingRate;
        string outputFormat = request.outputFormat;

        lock_guard<mutex> lg(this->audioStreamsMutex);
        if (this->streamStatuses[audioId] == false) {
            // Stream is inactive, skip transcoding
            return;
        }

        TranscodingResult result;
        result.success = false;
        result.errorMessage = "Stream not found";

        for (int i = 0; i < this->audioStreams.size(); i++) {
            if (this->audioStreams[i].id == audioId) {
                // Found the stream, start transcoding
                result.success = true;
                result.transcodedAudio = "Transcoded audio";
                break;
            }
        }

        this->transcodingResults[audioId] = result;
    }

    void handleAuthenticationFailure(string streamId) {
        lock_guard<mutex> lg(this->audioStreamsMutex);
        this->streamStatuses[streamId] = false;
    }

    void handleAuthenticationSuccess(string streamId) {
        lock_guard<mutex> lg(this->audioStreamsMutex);
        this->streamStatuses[streamId] = true;
    }

    void handleTranscodingResult(string audioId, TranscodingResult result) {
        lock_guard<mutex> lg(this->audioStreamsMutex);
        this->transcodingResults[audioId] = result;
    }

    void shutdown() {
        this->isShuttingDown = true;
        this->queueNotEmptyCondVar.notify_all();
    }
};

class TranscodingServiceClient {
private:
    AudioPipeline* audioPipeline;
    string serviceUrl;
    mutex clientMutex;
    condition_variable queueNotEmptyCondVar;
    bool isShuttingDown = false;

public:
    TranscodingServiceClient(AudioPipeline* audioPipeline, string serviceUrl) {
        this->audioPipeline = audioPipeline;
        this->serviceUrl = serviceUrl;
        this->clientMutex.lock();
        this->queueNotEmptyCondVar.notify_all();
    }

    void handleTranscodingRequest(TranscodingRequest request) {
        string audioId = request.audioId;
        int outputBitrate = request.outputBitrate;
        int outputSamplingRate = request.outputSamplingRate;
        string outputFormat = request.outputFormat;

        lock_guard<mutex> lg(this->clientMutex);
        if (isShuttingDown) {
            return;
        }

        // Send transcoding request to service
        this->audioPipeline->handleTranscodingRequest(request);
    }

    void handleAuthenticationFailure(string streamId) {
        lock_guard<mutex> lg(this->clientMutex);
        if (isShuttingDown) {
            return;
        }
        this->audioPipeline->handleAuthenticationFailure(streamId);
    }

    void handleAuthenticationSuccess(string streamId) {
        lock_guard<mutex> lg(this->clientMutex);
        if (isShuttingDown) {
            return;
        }
        this->audioPipeline->handleAuthenticationSuccess(streamId);
    }

    void handleTranscodingResult(string audioId, TranscodingResult result) {
        lock_guard<mutex> lg(this->clientMutex);
        if (isShuttingDown) {
            return;
        }
        this->audioPipeline->handleTranscodingResult(audioId, result);
    }

    void shutdown() {
        lock_guard<mutex> lg(this->clientMutex);
        isShuttingDown = true;
        queueNotEmptyCondVar.notify_all();
    }
};

void handleTranscodingRequests() {
    TranscodingServiceClient* client = new TranscodingServiceClient("http://transcoding-service:5000", audioPipeline);
    while (true) {
        lock_guard<mutex> lg(audioPipeline->audioStreamsMutex);
        if (audioPipeline->streamStatuses.empty()) {
            // Queue is empty, wait for notifications
            audioPipeline->queueNotEmptyCondVar.wait(lg);
            continue;
        }

        string streamId = audioPipeline->streamStatuses.begin()->first;
        bool isActive = audioPipeline->streamStatuses[streamId];
        if (isActive) {
            // Send transcoding request to service
            TranscodingRequest request = {"id", "outputFormat", "outputBitrate", "outputSamplingRate"};
            client->handleTranscodingRequest(request);
        } else {
            // Stream is inactive, skip transcoding
            continue;
        }
    }
}

int main() {
    AudioPipeline* audioPipeline = new AudioPipeline();

    // Add audio streams to pipeline
    audioPipeline->addAudioStream("id1", "format1", 128, 44100);
    audioPipeline->addAudioStream("id2", "format2", 64, 44100);

    // Start handling transcoding requests
    thread handleTranscodingThread(handleTranscodingRequests);
    handleTranscodingThread.detach();

    // Start processing authentication events
    thread processAuthEventsThread(processAuthEvents);
    processAuthEventsThread.detach();

    // Wait for shutdown signal
    while (true) {
        if (audioPipeline->isShuttingDown) {
            break;
        }
    }

    // Shut down the pipeline and clean up resources
    audioPipeline->shutdown();
}']

