            return validateRNTIData(rntiMap);
        } catch (std::exception& e) {
            std::cout << "Error: failed to validate RNTI data. Reason: " << e.what() << std::endl;
            if (numRetries == 0) {
                throw std::runtime_error("Error: exceeded maximum number of retries.");
            }
            // Exponential backoff with configurable timeout settings
            baseTimeout *= 2;
            std::this_thread::sleep_for(std::chrono::milliseconds(baseTimeout));
        }
    }
}

