['package com.example.logging;

import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class LoggingService {
    private static final int DEFAULT_BATCH_SIZE = 1000;
    private static final long DEFAULT_BATCH_INTERVAL = TimeUnit.SECONDS.toMillis(1);
    private static final long DEFAULT_MAX_LATENCY = TimeUnit.SECONDS.toMillis(10);
    private static final int DEFAULT_MAX_THREADS = 5;

    private LogParser logParser;
    private LogAggregator logAggregator;
    private ScheduledExecutorService executorService;

    public LoggingService() {
        this.logParser = new LogParser();
        this.logAggregator = new LogAggregator();
        this.executorService = Executors.newScheduledThreadPool(DEFAULT_MAX_THREADS);
    }

    public void start() {
        executorService.scheduleAtFixedRate(() -> {
            int batchSize = getBatchSize();
            long batchInterval = getBatchInterval();
            long maxLatency = getMaxLatency();

            // Process logs in parallel using a thread pool with maximum of 5 threads
            executorService.invokeAll(processLogsInParallel(batchSize, batchInterval, maxLatency));

            // Aggregate logs
            logAggregator.aggregateLogs();
        }, 0, batchInterval, TimeUnit.MILLISECONDS);
    }

    public void stop() {
        executorService.shutdown();
    }

    private List<Callable<Void>> processLogsInParallel(int batchSize, long batchInterval, long maxLatency) {
        List<Callable<Void>> tasks = new ArrayList<>();
        for (int i = 0; i < batchSize; i++) {
            final int taskId = i;
            tasks.add(() -> {
                // Process log with thread-safe access to shared resources
                processLog(taskId, maxLatency);
                return null;
            });
        }
        return tasks;
    }

    private void processLog(int taskId, long maxLatency) {
        try {
            LogRecord log = getNextLog();
            if (log != null) {
                // Parse log and categorize using external API
                String category = logParser.parse(log);
                // Handle API downtime or slow responses with retry strategy
                int retries = 0;
                while (retries < 5) {
                    try {
                        // Store parsed log in cache for query performance
                        storeParsedLogInCache(log);
                        break;
                    } catch (Exception e) {
                        retries++;
                        if (retries == 5) {
                            throw new RuntimeException("Failed to parse log after retrying", e);
                        }
                    }
                }
                // Aggregate log using external API
                logAggregator.aggregateLog(category, log);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (ExecutionException e) {
            throw new RuntimeException("Failed to process log", e);
        }
    }

    private int getBatchSize() {
        return DEFAULT_BATCH_SIZE;
    }

    private long getBatchInterval() {
        return DEFAULT_BATCH_INTERVAL;
    }

    private long getMaxLatency() {
        return DEFAULT_MAX_LATENCY;
    }

    private LogRecord getNextLog() throws InterruptedException, ExecutionException {
        // Implement your own logic to retrieve next log from external data source
        return null;
    }

    private void storeParsedLogInCache(LogRecord log) {
        // Implement your own logic to store parsed log in cache for query performance
    }
}']

