// Data structure for storing the Union-Find data structure
class UnionFind {
    // Map to store the parent nodes and their respective ranks
    Map<Integer, Integer> parents = new HashMap<>();
    // Map to store the number of children for each node
    Map<Integer, Integer> childCounts = new HashMap<>();

    // Function to find the root node of a given node
    int find(int x) {
        if (parents.get(x) == null) return x;
        return find(parents.get(x));
    }

    // Function to union two nodes in the Union-Find data structure
    void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) return;

        // Combine the child counts of the two nodes
        childCounts.put(rootX, childCounts.getOrDefault(rootX, 0) + childCounts.getOrDefault(rootY, 0));

        // Set the parent of the smaller node to the larger node
        if (childCounts.get(rootX) > childCounts.get(rootY)) {
            parents.put(rootY, rootX);
        } else {
            parents.put(rootX, rootY);
        }
    }
}

// Data structure for storing the integer datasets
