        data.put(value, 1);
    }
}

// Data structure for storing the binary datasets
class BinaryDataset {
    // Map to store the binary values in the dataset
    Map<Integer, Boolean> data = new HashMap<>();

    // Function to add a binary value to the dataset
    void add(boolean value) {
        data.put(value ? 1 : 0, true);
    }
}

// Data structure for storing the statistics of the datasets
