    // Function to compute the patterns in a binary dataset
    void calculate(boolean[] data) {
        // Calculate the patterns in the dataset
        for (int i = 0; i < data.length - 1; i++) {
            if (data[i] && !data[i + 1]) {
                patterns.put(data, i);
            }
        }
    }
}

