        // Print the statistical metrics of the datasets
        System.out.println("Integer Dataset: Mean=" + stats.means.get(intDataset.data) + ", Median=" + stats.medians.get(intDataset.data) + ", Mode=" + stats.modes.get(intDataset.data));
        System.out.println("Binary Dataset: Mean=" + stats.means.get(binDataset.data) + ", Median=" + stats.medians.get(binDataset.data) + ", Mode=" + stats.modes.get(binDataset.data));

        // Calculate the pattern recognition tasks of the datasets
