Here is an example implementation of a highly available, scalable Node.js microservice that processes large volumes of streaming data from IoT devices:
```javascript
const http = require('http');
const https = require('https');
const mqtt = require('mqtt');
const zlib = require('zlib');
const { promisify } = require('util');
const { Logger, LogLevel } = require('logger-js');

// Set up logging and monitoring
const logger = new Logger(LogLevel.DEBUG);
const monitoringClient = ...; // Initialize a monitoring client here

// Set up MQTT connection options
const mqttOptions = {
  host: 'localhost',
  port: 1883,
  keepalive: 60,
  reconnectPeriod: 5000,
};

// Set up HTTPS client for cloud integration
const httpsClient = new https.Agent({});

// Set up MQTT client for IoT device communication
const mqttClient = mqtt.connect(mqttOptions);

// Set up data processing pipeline
const processor = async (data) => {
  // Perform data aggregation and compression here
  const compressedData = zlib.gzipSync(JSON.stringify(data));

  // Send compressed data to the cloud API for processing
  await httpsClient.request({
    method: 'POST',
    hostname: 'example.com',
    path: '/api/process-data',
    body: compressedData,
  });
};

// Set up error handling and retry logic
const handleError = (error) => {
  // Log the error and send a status update to the monitoring client
  logger.error(error);
  monitoringClient.updateStatus('ERROR');

  // Retry the failed request after a certain delay
  setTimeout(() => processor(data), 5000);
};

// Set up connection handling and reconnection logic
mqttClient.on('connect', () => {
  logger.info(`Connected to MQTT broker`);

  // Subscribe to the IoT device topic
  mqttClient.subscribe('iot-device/data');
});

mqttClient.on('close', () => {
  logger.warn(`MQTT connection closed unexpectedly`);

  // Reconnect to the MQTT broker after a certain delay
  setTimeout(() => mqttClient.reconnect(), 5000);
});

mqttClient.on('error', (error) => {
  logger.error(error);
  monitoringClient.updateStatus('ERROR');

  // Retry the failed request after a certain delay
  setTimeout(() => processor(data), 5000);
});

// Set up data processing loop
setInterval(() => {
  // Read data from the MQTT client
  const data = mqttClient.read();

  // Process the data and update the monitoring client
  processor(data)
    .then(() => monitoringClient.updateStatus('OK'))
    .catch((error) => handleError(error));
}, 5000);
```
