['```java
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class SignatureManager {
  // Map of hash values and their corresponding signature timestamps
  private static final Map<String, Long> signatureMap = new ConcurrentHashMap<>();

  // Maximum number of signatures to store in the database
  private static final int MAX_SIGNATURES = 10;

  // API URL for the third-party document verification service
  private static final String VERIFICATION_API_URL = "https://verification.example.com";

  public static boolean verifySignature(String hashValue, long signatureTimestamp) {
    // Check if the signature is in the database
    Long dbSignatureTimestamp = signatureMap.get(hashValue);
    if (dbSignatureTimestamp == null) {
      return false;
    }

    // Check if the signature timestamp is within the rolling window of the last ten signatures
    long timeSinceLastSignature = System.currentTimeMillis() - dbSignatureTimestamp;
    if (timeSinceLastSignature > 10 * 60 * 1000) {
      return false;
    }

    // Validate the signature against the third-party document verification service
    boolean valid = verifyAgainstThirdPartyService(hashValue);
    if (valid) {
      // Update the database with the new signature
      updateSignatureDatabase(hashValue, signatureTimestamp);
    }

    return valid;
  }

  private static void updateSignatureDatabase(String hashValue, long signatureTimestamp) {
    // Add the new signature to the database
    signatureMap.put(hashValue, signatureTimestamp);

    // Remove any signatures that are too old
    long currentTime = System.currentTimeMillis();
    List<String> removeSignatures = new ArrayList<>();
    for (Map.Entry<String, Long> entry : signatureMap.entrySet()) {
      if (currentTime - entry.getValue() > MAX_SIGNATURES * 60 * 1000) {
        removeSignatures.add(entry.getKey());
      }
    }
    signatureMap.keySet().removeAll(removeSignatures);
  }

  private static boolean verifyAgainstThirdPartyService(String hashValue) {
    // Send a request to the third-party document verification service
    String url = VERIFICATION_API_URL + "/verify?hash=" + hashValue;
    try {
      URL object = new URL(url);
      HttpURLConnection connection = (HttpURLConnection) object.openConnection();
      int responseCode = connection.getResponseCode();
      if (responseCode == 200) {
        return true;
      } else {
        return false;
      }
    } catch (MalformedURLException e) {
      e.printStackTrace();
    } catch (IOException e) {
      e.printStackTrace();
    }
    return false;
  }
}
```
