// DynamicOctree class declaration
class DynamicOctree {
private:
    // Node struct for representing a spatial octree node
    struct Node {
        float x; // x-coordinate of the node's center
        float y; // y-coordinate of the node's center
        float z; // z-coordinate of the node's center
        int level; // level (depth) of the node in the octree
        int capacity; // maximum number of points stored in this node
        vector<int> point_ids; // ids of the points stored in this node
    };

    // Octree struct for representing the entire spatial octree
    struct Octree {
        int level; // depth of the octree
        int capacity; // maximum number of points stored in the tree
        vector<Node> nodes; // array of all nodes in the octree
    };

    // Function to create a new node at the given coordinates and level
    Node createNode(float x, float y, float z, int level);

    // Function to split an existing node into four smaller nodes
    void splitNode(Node& node, int level);

    // Function to merge two or more nodes into a single node
    void mergeNodes(vector<int>& node_ids, int level);

    // Function to insert a point into the octree
    void insertPoint(const Point& point, const Node& node);

    // Function to remove a point from the octree
    void removePoint(const Point& point, const Node& node);

    // Function to find all points within a given radius of a query point
    vector<int> searchRadius(const Point& query_point, float radius);

    // Function to find all points within a given bounding box
    vector<int> searchBox(const BoundingBox& bbox);

    // Function to find the closest point to a query point
    int searchClosest(const Point& query_point);

    // Function to update the octree after a point has been inserted or removed
    void updateOctree(int node_id, const Node& node);

    // Function to filter transactions based on criteria such as age, recent frequency, and weighted sums
    vector<Transaction> filterTransactions(vector<Transaction>& transactions);

    // Function to handle asynchronous operations for loading and saving data
    void asyncLoadData();

    // Function to optimize geospatial query operations
    void optimizeQuery();

    // Function to implement an adaptive resolution mechanism
    void adaptiveResolution(float density, float threshold);

    // Function to integrate machine learning models that analyze point cloud data within the octree structure
    void integrateMLModels();
};

// Implementation of the Node struct
struct DynamicOctree::Node {
    float x;
    float y;
    float z;
    int level;
    int capacity;
    vector<int> point_ids;
};

// Implementation of the Octree struct
struct DynamicOctree::Octree {
    int level;
    int capacity;
    vector<Node> nodes;
};

// Function to create a new node at the given coordinates and level
DynamicOctree::Node DynamicOctree::createNode(float x, float y, float z, int level) {
    Node node;
    node.x = x;
    node.y = y;
    node.z = z;
    node.level = level;
    node.capacity = 16 * (2 << level); // initial capacity is 16 points per node
    node.point_ids = vector<int>();
    return node;
}

// Function to split an existing node into four smaller nodes
void DynamicOctree::splitNode(Node& node, int level) {
    // Check if the node needs to be split
    if (node.capacity > 16 * (2 << level)) {
        // Split the node into four smaller nodes
        Node n1 = createNode(node.x - 0.5f, node.y - 0.5f, node.z - 0.5f, level + 1);
        Node n2 = createNode(node.x - 0.5f, node.y + 0.5f, node.z - 0.5f, level + 1);
        Node n3 = createNode(node.x - 0.5f, node.y - 0.5f, node.z + 0.5f, level + 1);
        Node n4 = createNode(node.x - 0.5f, node.y + 0.5f, node.z + 0.5f, level + 1);
        vector<int> node_ids = {n1.id, n2.id, n3.id, n4.id};
        mergeNodes(node_ids, level + 1); // recursively merge the smaller nodes
    }
}

// Function to merge two or more nodes into a single node
void DynamicOctree::mergeNodes(vector<int>& node_ids, int level) {
    // Check if the nodes need to be merged
    if (node_ids.size() > 1 && node_ids[0].capacity <= 16 * (2 << level)) {
        Node node = createNode(node.x - 0.5f, node.y - 0.5f, node.z - 0.5f, level + 1);
        // Add the point ids from all the nodes to the new node
        for (int i = 0; i < node_ids.size(); i++) {
            Node& n = getNode(node_ids[i]);
            node.point_ids.insert(node.point_ids.end(), n.point_ids.begin(), n.point_ids.end());
        }
        // Remove the merged nodes from the octree
        for (int i = 0; i < node_ids.size(); i++) {
            removeNode(node_ids[i]);
        }
    }
}

// Function to insert a point into the octree
void DynamicOctree::insertPoint(const Point& point, const Node& node) {
    // Check if the point is outside of the node's bounding box
    if (point.x < node.x - 0.5f || point.x > node.x + 0.5f || point.y < node.y - 0.5f || point.y > node.y + 0.5f || point.z < node.z - 0.5f || point.z > node.z + 0.5f) {
        return; // if it is, exit the function without making any changes to the octree
    }
    // Check if the node needs to be split
    if (node.capacity > 16 * (2 << level)) {
        splitNode(node); // recursively split the node into smaller nodes
    }
    // Add the point to the node's point ids list
    Node& n = getNode(node);
    n.point_ids.push_back(point.id);
}

// Function to remove a node from the octree
void DynamicOctree::removeNode(int id) {
    // Check if the node is in the octree
    if (getNode(id) == nullptr) {
        return; // if it is not, exit the function without making any changes to the octree
    }
    // Remove the node from the octree
    removeNode(getNode(id));
}

