#include <algorithm>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <future>
#include <cassert>

using namespace std;

struct DeviceConnection {
    string udi;
    vector<string> communicationChannels;
    bool connected = false;
};

struct NetworkStatusUpdateRequest {
    string udi;
    string status;
};

class DeviceManager {
public:
    void addDevice(const string& udi, const vector<string>& communicationChannels) {
        devices[udi] = DeviceConnection{udi, communicationChannels, false};
    }

    bool isConnected(const string& udi) {
        return devices.find(udi) != devices.end() && devices[udi].connected;
    }

    void connectDevice(const string& udi) {
        if (devices.find(udi) == devices.end()) {
            throw runtime_error("Device not found");
        }

        auto& device = devices[udi];
        device.connected = true;

        // Send network status update request
        NetworkStatusUpdateRequest request{udi, "connected"};
        networkStatusUpdates.push(request);
    }

    void disconnectDevice(const string& udi) {
        if (devices.find(udi) == devices.end()) {
            throw runtime_error("Device not found");
        }

        auto& device = devices[udi];
        device.connected = false;

        // Send network status update request
        NetworkStatusUpdateRequest request{udi, "disconnected"};
        networkStatusUpdates.push(request);
    }

private:
    map<string, DeviceConnection> devices;
    queue<NetworkStatusUpdateRequest> networkStatusUpdates;
};

class NetworkStatusUpdateManager {
public:
    void start() {
        thread = new thread(&NetworkStatusUpdateManager::run, this);
    }

    void stop() {
        thread->join();
        delete thread;
    }

private:
    void run() {
        while (true) {
            auto request = networkStatusUpdates.pop();
            // Send network status update to messaging broker or database
            cout << "Network status update: UDI=" << request.udi << ", status=" << request.status << endl;
        }
    }

private:
    queue<NetworkStatusUpdateRequest> networkStatusUpdates;
    thread* thread;
};

int main() {
    DeviceManager deviceManager;
    NetworkStatusUpdateManager networkStatusUpdateManager;

    // Add devices to the manager
    deviceManager.addDevice("udi1", {"TCP"});
    deviceManager.addDevice("udi2", {"UDP", "WebSocket"});
    deviceManager.connectDevice("udi1");
    deviceManager.connectDevice("udi2");
    deviceManager.disconnectDevice("udi1");

    // Start the network status update manager
    networkStatusUpdateManager.start();

    // Run the application until terminated by user input
    cout << "Press enter to terminate" << endl;
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    // Stop the network status update manager
    networkStatusUpdateManager.stop();
}
