#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>
#include <ctime>
#include <algorithm>
#include <memory>

// Define the commands that can be executed by the system
struct Command {
  std::string name;
  std::vector<std::string> args;
};

// Define a worker node that executes commands asynchronously
class WorkerNode {
 public:
  // Constructor
  WorkerNode(int id) : _id(id), _is_active(true) {}

  // Destructor
  ~WorkerNode() = default;

  // Function to execute a command asynchronously
  void executeCommand(const Command& cmd, const std::shared_ptr<std::promise<int>>& promise) {
    _is_active = true;

    // Create a new thread for the command execution
    auto thr = std::thread([this, &cmd, &promise]() {
      int ret_code = -1;
      try {
        // Execute the command
        ret_code = system(cmd.name + " " + cmd.args[0] + " " + cmd.args[1]);
      } catch (const std::exception& e) {
        std::cerr << "Error executing command: " << e.what() << std::endl;
      }

      // Set the promise value to the return code of the command execution
      if (ret_code == -1) {
        promise->set_value(-1);
      } else {
        promise->set_value(ret_code);
      }
    });

    thr.detach();
  }

 private:
  int _id;          // ID of the worker node
  bool _is_active;  // Flag indicating whether the worker node is active or not
};

// Define a load balancer that distributes commands across multiple worker nodes
class LoadBalancer {
 public:
  // Constructor
  LoadBalancer(const std::vector<std::shared_ptr<WorkerNode>>& workers) : _workers(workers) {}

  // Destructor
  ~LoadBalancer() = default;

  // Function to distribute a command across the worker nodes
  void distributeCommand(const Command& cmd) {
    // Create a promise object for the command execution
    auto promise = std::make_shared<std::promise<int>>();

    // Distribute the command across the worker nodes in a round-robin fashion
    for (auto& worker : _workers) {
      if (!worker->isActive()) {
        continue;
      }
      worker->executeCommand(cmd, promise);
    }

    // Wait for all worker nodes to complete the command execution
    auto futures = std::vector<std::shared_ptr<std::future<int>>>();
    for (auto& worker : _workers) {
      futures.push_back(promise->get_future());
    }

    // Check if any worker nodes failed to complete the command execution
    bool is_success = true;
    for (auto& future : futures) {
      auto ret_code = future->get();
      if (ret_code == -1) {
        is_success = false;
        break;
      }
    }

    // Return the success status of the command execution
    return is_success;
  }

 private:
  std::vector<std::shared_ptr<WorkerNode>> _workers;  // Vector of worker nodes
};

// Define a command queue that stores commands to be executed
class CommandQueue {
 public:
  // Constructor
  CommandQueue() = default;

  // Destructor
  ~CommandQueue() = default;

  // Function to add a new command to the queue
  void push(const Command& cmd) {
    std::lock_guard<std::mutex> lock(_mutex);
    _commands.push_back(cmd);
  }

  // Function to get the next command from the queue
  Command pop() {
    std::lock_guard<std::mutex> lock(_mutex);
    auto cmd = _commands.front();
    _commands.pop_front();
    return cmd;
  }

 private:
  std::mutex _mutex;   // Mutex to protect the queue
  std::deque<Command> _commands;  // Queue of commands
};

// Define a command executor that executes commands in parallel
class CommandExecutor {
 public:
  // Constructor
  CommandExecutor(const std::vector<std::shared_ptr<WorkerNode>>& workers) : _workers(workers), _is_active(true) {}

  // Destructor
  ~CommandExecutor() = default;

  // Function to execute a command in parallel across multiple worker nodes
  void executeCommand(const Command& cmd) {
    // Create a promise object for the command execution
    auto promise = std::make_shared<std::promise<int>>();

    // Distribute the command across the worker nodes
    _load_balancer->distributeCommand(cmd);

    // Wait for all worker nodes to complete the command execution
    auto futures = std::vector<std::shared_ptr<std::future<int>>>();
    for (auto& worker : _workers) {
      futures.push_back(promise->get_future());
    }

    // Check if any worker nodes failed to complete the command execution
    bool is_success = true;
    for (auto& future : futures) {
      auto ret_code = future->get();
      if (ret_code == -1) {
        is_success = false;
        break;
      }
    }

    // Return the success status of the command execution
    return is_success;
  }

 private:
  std::vector<std::shared_ptr<WorkerNode>> _workers;     // Vector of worker nodes
  bool _is_active;                                       // Flag indicating whether the command executor is active or not
  std::shared_ptr<LoadBalancer> _load_balancer;         // Load balancer for distributing commands across worker nodes
};

// Define a command logger that stores logs of executed commands
class CommandLogger {
 public:
  // Constructor
  CommandLogger() = default;

  // Destructor
  ~CommandLogger() = default;

  // Function to log a command execution
  void log(const Command& cmd, int ret_code) {
    std::lock_guard<std::mutex> lock(_mutex);
    _logs.push_back({cmd, ret_code});
