static int analytics_update_interval = ANALYTICS_UPDATE_INTERVAL;
static float analytics_threshold_percentage = ANALYTICS_THRESHOLD_PERCENTAGE;
static int analytics_backoff_factor = ANALYTICS_BACKOFF_FACTOR;

// Define functions for process management
static void start_process(int index) {
  pid_t pid = fork();
  if (pid == 0) { // child process
    processes[index].start_time = time(NULL);
    processes[index].timeout = PROCESS_TIMEOUT;
    close(process_sem->fd);
    pthread_mutex_unlock(&task_mutex);
    execlp("bash", "bash", "-c", tasks[index].command, NULL);
  } else if (pid < 0) { // error
    perror("Error forking process");
    exit(1);
  } else { // parent process
    processes[index].pid = pid;
    pthread_mutex_unlock(&task_mutex);
  }
}

static void end_process(int index) {
  processes[index].end_time = time(NULL);
  processes[index].exit_status = WEXITSTATUS(waitpid(processes[index].pid, NULL, 0));
  pthread_mutex_unlock(&task_mutex);
}

static void process_timeout(int index) {
  if (time(NULL) - processes[index].start_time > processes[index].timeout) {
    kill(processes[index].pid, SIGKILL);
    end_process(index);
  } else {
    pthread_mutex_unlock(&task_mutex);
  }
}

static void handle_signal(int signal) {
  if (signal == SIGCHLD) {
    waitpid(-1, NULL, WNOHANG | WCONTINUED);
  } else if (signal == SIGTERM) {
    pthread_mutex_lock(&task_mutex);
    for (int i = 0; i < process_count; i++) {
      kill(processes[i].pid, SIGKILL);
      end_process(i);
    }
    pthread_mutex_unlock(&task_mutex);
  } else {
    printf("Invalid signal received.\n");
  }
}

static void monitoring_thread() {
  int i = 0;
  while (1) {
    sem_wait(process_sem);
    pthread_mutex_lock(&task_mutex);
    if (i < process_count && processes[i].end_time != -1) {
      end_process(i);
    }
    i++;
  }
}

static void analytics_thread() {
  while (1) {
    sleep(ANALYTICS_UPDATE_INTERVAL);
    monitoring_count = 0;
    for (int i = 0; i < process_count; i++) {
      if (processes[i].end_time != -1) {
        monitoring_count++;
      }
    }
  }
}

// Define functions for rate limiting
static void token_refill() {
  tokens_available = token_bucket_size;
}

static int is_token_available() {
  if (tokens_available >= token_block_size) {
    return 1;
  } else {
    return 0;
  }
}

static void take_token() {
  tokens_available--;
}

// Define functions for task management
static void queue_task(char* command) {
  pthread_mutex_lock(&task_mutex);
  tasks[task_count].command = command;
  tasks[task_count].start_time = time(NULL);
  start_process(task_count);
  task_count++;
}

static void dequeue_task() {
  pthread_mutex_lock(&task_mutex);
  tasks[0].end_time = time(NULL);
  end_process(0);
  for (int i = 1; i < task_count; i++) {
    tasks[i - 1] = tasks[i];
  }
  task_count--;
}

// Main function
int main() {
  process_sem = sem_open("/process_sem", O_CREAT, 0644, 1);
  pthread_mutexattr_t attr;
  pthread_mutexattr_init(&attr);
  pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
  task_mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
  pthread_mutex_init(task_mutex, &attr);

  signal(SIGCHLD, handle_signal);
  signal(SIGTERM, handle_signal);

  int fd[2];
  pipe(fd);
  pthread_t monitoring_thread_id;
  pthread_create(&monitoring_thread_id, NULL, monitoring_thread, NULL);

  pthread_t analytics_thread_id;
  pthread_create(&analytics_thread_id, NULL, analytics_thread, NULL);

  while (1) {
    char* command = read(fd[0], buffer, BUFFER_SIZE);
    if (command != NULL && strlen(command) > 0) {
      if (is_token_available()) {
        take_token();
        queue_task(command);
      } else {
        perror("Token unavailable.");
      }
    }
  }
}
