// Define the data structures for managing the data pipeline
class DataPipeline {
public:
    DataPipeline();
    ~DataPipeline();

    // Add a new IoT device to the pipeline
    void addDevice(const std::string& id, const std::string& type);

    // Remove an IoT device from the pipeline
    void removeDevice(const std::string& id);

    // Get the current list of IoT devices in the pipeline
    std::vector<IoTDevice> getDevices();

    // Add a new data sink to the pipeline
    void addDataSink(const std::string& name, const std::string& type, std::function<void(const std::string&)> callback);

    // Remove a data sink from the pipeline
    void removeDataSink(const std::string& name);

    // Get the current list of data sinks in the pipeline
    std::vector<DataSink> getDataSinks();

    // Start the data pipeline
    void start();

    // Stop the data pipeline
    void stop();

private:
    // Map of IoT devices to their telemetry data
    std::unordered_map<std::string, std::vector<std::pair<int, std::string>>> devices_;

    // Vector of data sinks and their callback functions
    std::vector<DataSink> data_sinks_;

    // Mutex for protecting the data pipeline state
    std::mutex mutex_;

    // Condition variable to signal when new telemetry data is available
    std::condition_variable cv_;

    // Thread pool for managing the data pipeline
    std::vector<std::thread> threads_;
};

// Implement the DataPipeline class
DataPipeline::DataPipeline() {
    // Initialize the thread pool with a fixed number of threads
    int num_threads = 8;
    for (int i = 0; i < num_threads; ++i) {
        threads_.emplace_back(std::thread([this] { this->run(); }));
    }
}

DataPipeline::~DataPipeline() {
    // Stop the thread pool and join all threads
    stop();
    for (auto& t : threads_) {
        t.join();
    }
}

void DataPipeline::addDevice(const std::string& id, const std::string& type) {
    // Add a new IoT device to the pipeline
    std::lock_guard<std::mutex> lock(mutex_);
    devices_.emplace(id, std::vector<std::pair<int, std::string>>{});
}

void DataPipeline::removeDevice(const std::string& id) {
    // Remove an IoT device from the pipeline
    std::lock_guard<std::mutex> lock(mutex_);
    devices_.erase(id);
}

std::vector<IoTDevice> DataPipeline::getDevices() {
    // Get the current list of IoT devices in the pipeline
    std::lock_guard<std::mutex> lock(mutex_);
    return std::vector<IoTDevice>(devices_.begin(), devices_.end());
}

void DataPipeline::addDataSink(const std::string& name, const std::string& type, std::function<void(const std::string&)> callback) {
    // Add a new data sink to the pipeline
    std::lock_guard<std::mutex> lock(mutex_);
    data_sinks_.emplace_back(name, type, callback);
}

void DataPipeline::removeDataSink(const std::string& name) {
    // Remove a data sink from the pipeline
    std::lock_guard<std::mutex> lock(mutex_);
    for (auto it = data_sinks_.begin(); it != data_sinks_.end(); ++it) {
        if (it->name == name) {
            data_sinks_.erase(it);
            break;
        }
    }
}

std::vector<DataSink> DataPipeline::getDataSinks() {
    // Get the current list of data sinks in the pipeline
    std::lock_guard<std::mutex> lock(mutex_);
    return std::vector<DataSink>(data_sinks_.begin(), data_sinks_.end());
}

void DataPipeline::start() {
    // Start the data pipeline
    running_ = true;
    cv_.notify_all();
}

void DataPipeline::stop() {
    // Stop the data pipeline
    running_ = false;
}

// Run function for each thread in the thread pool
void DataPipeline::run() {
    while (running_) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock);
        if (!running_) break;

        // Process new telemetry data for each device
        for (auto& dev : devices_) {
            for (auto& telemetry : dev.second) {
                // Send the telemetry data to each data sink
                for (auto& sink : data_sinks_) {
                    if (sink.type == "raw") {
                        sink.callback(telemetry.first, telemetry.second);
                    } else if (sink.type == "aggregated") {
                        // Aggregate the telemetry data for this device and send it to the sink
                        std::string agg_data = aggregateTelemetry(dev.first, telemetry.second);
                        sink.callback(agg_data);
                    }
                }
            }
        }
    }
}

// Aggregate the telemetry data for a specific device
std::string DataPipeline::aggregateTelemetry(const std::string& device, const std::string& data) {
    // Implement the aggregation logic here
    return "aggregated data";
}
