import json
from collections import deque

class DistributedGraphDatabaseService:
    def __init__(self, config_file):
        self.config = {}
        with open(config_file) as f:
            self.config = json.load(f)

        # Initialize graph database structure
        self.vertices = set()
        self.edges = set()

    def add_vertex(self, vertex):
        if not isinstance(vertex, dict):
            raise ValueError("Vertex must be a dictionary")

        # Validate vertex schema against config file
        try:
            schema = self.config["schema"]["vertex"]
            for field in schema:
                if field not in vertex or vertex[field] is None:
                    raise ValueError(f"Vertex missing required field '{field}'")
                elif not isinstance(vertex[field], schema[field]):
                    raise ValueError(f"Vertex field '{field}' must be of type {schema[field]}")
        except KeyError as e:
            raise ValueError("Invalid vertex schema") from e

        # Add vertex to set and return success
        self.vertices.add(vertex)
        return True

    def add_edge(self, edge):
        if not isinstance(edge, dict):
            raise ValueError("Edge must be a dictionary")

        # Validate edge schema against config file
        try:
            schema = self.config["schema"]["edge"]
            for field in schema:
                if field not in edge or edge[field] is None:
                    raise ValueError(f"Edge missing required field '{field}'")
                elif not isinstance(edge[field], schema[field]):
                    raise ValueError(f"Edge field '{field}' must be of type {schema[field]}")
        except KeyError as e:
            raise ValueError("Invalid edge schema") from e

        # Add edge to set and return success
        self.edges.add(edge)
        return True

    def remove_vertex(self, vertex):
        if not isinstance(vertex, dict):
            raise ValueError("Vertex must be a dictionary")

        # Remove vertex from set and return success
        try:
            self.vertices.remove(vertex)
            return True
        except KeyError:
            return False

    def remove_edge(self, edge):
        if not isinstance(edge, dict):
            raise ValueError("Edge must be a dictionary")

        # Remove edge from set and return success
        try:
            self.edges.remove(edge)
            return True
        except KeyError:
            return False

    def query_vertices(self, filters=[]):
        # Apply filtering if provided
        if filters:
            for filter in filters:
                vertices = [vertex for vertex in self.vertices if all([filter(vertex[field]) for field in filter])]
                self.vertices = set(vertices)

        return list(self.vertices)

    def query_edges(self, filters=[]):
        # Apply filtering if provided
        if filters:
            for filter in filters:
                edges = [edge for edge in self.edges if all([filter(edge[field]) for field in filter])]
                self.edges = set(edges)

        return list(self.edges)
