#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <syslog.h>

// Define log levels
#define LOG_EMERG 0
#define LOG_ALERT 1
#define LOG_CRIT 2
#define LOG_ERR 3
#define LOG_WARNING 4
#define LOG_NOTICE 5
#define LOG_INFO 6
#define LOG_DEBUG 7

// Define log message format
struct LogMessage {
    char subsystem[10]; // Subsystem name (e.g., "webserver")
    time_t timestamp;   // Timestamp of the log message
    int level;          // Log level (e.g., LOG_INFO)
    char message[1024]; // Formatted error message
};

// Define log queue data structure
typedef struct {
    int size;        // Size of the queue (number of messages stored)
    int capacity;   // Capacity of the queue (maximum number of messages)
    int front;       // Index of the first element in the queue
    int rear;        // Index of the last element in the queue
    struct LogMessage *messages; // Array of log messages
} LogQueue;

// Define a thread-safe logging function
void Log(const char *subsystem, const char *format, ...) {
    va_list args;
    char message[1024];
    size_t msg_len;

    // Validate input parameters
    if (subsystem == NULL || format == NULL) {
        return;
    }

    // Format the log message using snprintf
    va_start(args, format);
    msg_len = vsnprintf(message, sizeof(message), format, args);
    va_end(args);

    // Truncate the message if it exceeds the maximum length
    if (msg_len > 1024) {
        message[1023] = '\0';
    }

    // Add the log message to the queue
    LogQueue *queue = GetLogQueue(subsystem);
    if (queue != NULL) {
        struct LogMessage msg;
        strcpy(msg.subsystem, subsystem);
        msg.timestamp = time(NULL);
        msg.level = LOG_INFO;
        strcpy(msg.message, message);
        EnqueueLogMessage(queue, &msg);
    }
}

// Implement a thread-safe log queue for storing log messages
LogQueue *GetLogQueue(const char *subsystem) {
    // Initialize the queue if necessary
    static LogQueue queue;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    if (queue.messages == NULL) {
        queue.size = 0;
        queue.capacity = 1024;
        queue.front = 0;
        queue.rear = -1;
        queue.messages = malloc(sizeof(struct LogMessage) * queue.capacity);
    }

    // Acquire the mutex lock to access the queue safely
    pthread_mutex_lock(&mutex);

    // Search for an existing log queue with the given subsystem name
    int i;
    for (i = 0; i < queue.size; ++i) {
        if (strcmp(queue.messages[i].subsystem, subsystem) == 0) {
            break;
        }
    }

    // Create a new log queue if none was found
    if (i >= queue.size) {
        struct LogMessage msg;
        strcpy(msg.subsystem, subsystem);
        msg.timestamp = time(NULL);
        msg.level = LOG_INFO;
        EnqueueLogMessage(&queue, &msg);
    }

    // Release the mutex lock and return the log queue
    pthread_mutex_unlock(&mutex);
    return &queue;
}

// Enqueue a new log message in the log queue
void EnqueueLogMessage(LogQueue *queue, struct LogMessage *msg) {
    // Validate input parameters
    if (queue == NULL || msg == NULL) {
        return;
    }

    // Acquire the mutex lock to access the queue safely
    pthread_mutex_lock(&queue->mutex);

    // Increase the size of the queue if necessary
    if (queue->rear >= queue->capacity - 1) {
        queue->capacity *= 2;
        queue->messages = realloc(queue->messages, sizeof(struct LogMessage) * queue->capacity);
    }

    // Add the log message to the rear of the queue
    strcpy(queue->messages[++queue->rear].subsystem, msg->subsystem);
    queue->messages[queue->rear].timestamp = msg->timestamp;
    queue->messages[queue->rear].level = msg->level;
    strcpy(queue->messages[queue->rear].message, msg->message);

    // Increase the size of the queue if necessary
    if (queue->front > 0 && queue->size >= queue->capacity / 4) {
        memmove(queue->messages, &queue->messages[queue->front], sizeof(struct LogMessage) * queue->rear);
        queue->front = 0;
        queue->rear -= queue->front;
    }

    // Release the mutex lock and update the size of the queue
    pthread_mutex_unlock(&queue->mutex);
    ++queue->size;
}

// Dequeue a log message from the log queue
struct LogMessage *DequeueLogMessage(LogQueue *queue) {
    // Validate input parameters
    if (queue == NULL || queue->messages == NULL) {
        return NULL;
    }

    // Acquire the mutex lock to access the queue safely
    pthread_mutex_lock(&queue->mutex);

    // Decrease the size of the queue if necessary
    if (queue->size > 0 && queue->front == queue->rear) {
        --queue->size;
        memmove(queue->messages, &queue->messages[queue->front + 1], sizeof(struct LogMessage) * queue->rear);
        ++queue->front;
    }

    // Return the log message from the front of the queue
    struct LogMessage *msg = &queue->messages[queue->front];
    ++queue->front;

    // Release the mutex lock and update the size of the queue
    pthread_mutex_unlock(&queue->mutex);
    --queue->size;
    return msg;
}

// Implement a thread-safe log queue for storing log messages
LogQueue *GetLogQueue(const char *subsystem) {
    // Initialize the queue if necessary
    static LogQueue queue;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    if (queue.messages == NULL) {
