    // Increase the size of the queue if necessary
    if (queue->front > 0 && queue->size >= queue->capacity / 4) {
        memmove(queue->messages, &queue->messages[queue->front], sizeof(struct LogMessage) * queue->rear);
        queue->front = 0;
        queue->rear -= queue->front;
    }

    // Release the mutex lock and update the size of the queue
    pthread_mutex_unlock(&queue->mutex);
    ++queue->size;
}

// Dequeue a log message from the log queue
struct LogMessage *DequeueLogMessage(LogQueue *queue) {
    // Validate input parameters
    if (queue == NULL || queue->messages == NULL) {
        return NULL;
    }

    // Acquire the mutex lock to access the queue safely
    pthread_mutex_lock(&queue->mutex);

    // Decrease the size of the queue if necessary
    if (queue->size > 0 && queue->front == queue->rear) {
        --queue->size;
        memmove(queue->messages, &queue->messages[queue->front + 1], sizeof(struct LogMessage) * queue->rear);
        ++queue->front;
    }

    // Return the log message from the front of the queue
    struct LogMessage *msg = &queue->messages[queue->front];
    ++queue->front;

    // Release the mutex lock and update the size of the queue
    pthread_mutex_unlock(&queue->mutex);
    --queue->size;
    return msg;
}
```

This implementation uses a `LogQueue` structure to store the messages in a thread-safe manner. The `LogQueue` structure contains a mutex, an array of `LogMessage` structures, and some additional fields to keep track of the current size and capacity of the queue.

The `GetLogQueue()` function is used to get a reference to the log queue for a specific subsystem. If a log queue has not already been created for the subsystem, it is created and initialized with an initial capacity of 1024 messages. The mutex is then locked before returning the reference to the log queue.

The `EnqueueLogMessage()` function is used to add a new message to the log queue. It first locks the mutex for the log queue, checks if there is space in the array for the new message, and if not, it reallocates the array with a new size that is twice the current size. Then it adds the new message to the end of the array and increments the size of the queue. Finally, it unlocks the mutex.

The `DequeueLogMessage()` function is used to remove a message from the log queue. It first locks the mutex for the log queue, checks if there are any messages in the queue, and if not, it returns `NULL`. If there are messages in the queue, it returns the front of the queue (i.e., the oldest message) and increments the front index. Finally, it unlocks the mutex.

The `LogQueue` structure is defined as follows:
```
typedef struct LogQueue {
    pthread_mutex_t mutex;
    int size;
    int capacity;
    LogMessage *messages;
} LogQueue;
```
The `LogMessage` structure is defined as follows:
```
typedef struct LogMessage {
    char *subsystem;
    time_t timestamp;
    LogLevel level;
    char *message;
} LogMessage;
```
This implementation uses a single mutex to protect the log queue, which means that multiple threads can access the log queue simultaneously without worrying about race conditions. However, this approach may not be suitable for very high-traffic systems or systems with very large numbers of messages. In such cases, it may be necessary to use multiple queues and a separate mutex for each queue to reduce contention on the mutex.']

