struct NetworkStatusUpdateRequest {
    std::string udi;
    bool isConnected;
};

class OAuthTokenValidator {
public:
    // Constructor
    OAuthTokenValidator() : deviceInfoMap(), oauthTokenResponses(), networkStatusUpdateRequests(), retryIntervals(), failureCounts(), successCounts(), totalFailedRetries(), totalSuccessfulRetries() {}

    // Destructor
    ~OAuthTokenValidator() {
        deviceInfoMap.clear();
        oauthTokenResponses.clear();
        networkStatusUpdateRequests.clear();
        retryIntervals.clear();
        failureCounts.clear();
        successCounts.clear();
        totalFailedRetries = 0;
        totalSuccessfulRetries = 0;
    }

    // Function to add a device to the map
    void addDevice(const std::string& udi) {
        // Check if the UDI is already present in the map
        if (deviceInfoMap.find(udi) == deviceInfoMap.end()) {
            DeviceInfo newDevice;
            newDevice.udi = udi;
            newDevice.connectionStatus.push_back(0);  // Add a default value of 0 for connection status
            deviceInfoMap[udi] = newDevice;
        }
    }

    // Function to remove a device from the map
    void removeDevice(const std::string& udi) {
        // Check if the UDI is present in the map
        if (deviceInfoMap.find(udi) != deviceInfoMap.end()) {
            deviceInfoMap.erase(udi);
        }
    }

    // Function to get a device's connection status from the map
    int getConnectionStatus(const std::string& udi) {
        // Check if the UDI is present in the map
        if (deviceInfoMap.find(udi) != deviceInfoMap.end()) {
            return deviceInfoMap[udi].connectionStatus.back();  // Return the current connection status for the UDI
        } else {
            return -1;  // Return an error value if the UDI is not present in the map
        }
    }

    // Function to set a device's connection status in the map
    void setConnectionStatus(const std::string& udi, int newStatus) {
        // Check if the UDI is present in the map
        if (deviceInfoMap.find(udi) != deviceInfoMap.end()) {
            deviceInfoMap[udi].connectionStatus.push_back(newStatus);  // Add the new connection status to the vector
        }
    }

    // Function to validate an OAuth token response
    void validateOAuthTokenResponse(const OAuthTokenResponse& oauthTokenResponse) {
        int statusCode = oauthTokenResponse.statusCode;
        std::string accessToken = oauthTokenResponse.accessToken;
        long expiresIn = oauthTokenResponse.expiresIn;

        // Check if the status code is valid and the access token is not empty
        if (statusCode == 200 && !accessToken.empty()) {
            std::cout << "OAuth token validation succeeded for device: " << accessToken << std::endl;
        } else {
            std::cout << "OAuth token validation failed for device: " << accessToken << std::endl;
        }
    }

    // Function to generate a network status update request
    void generateNetworkStatusUpdateRequest(const std::string& udi, bool isConnected) {
        NetworkStatusUpdateRequest newRequest;
        newRequest.udi = udi;
        newRequest.isConnected = isConnected;
        networkStatusUpdateRequests.push_back(newRequest);
    }

    // Function to process the network status update request
    void processNetworkStatusUpdateRequest(const NetworkStatusUpdateRequest& request) {
        std::string udi = request.udi;
        bool isConnected = request.isConnected;

        if (deviceInfoMap.find(udi) != deviceInfoMap.end()) {
            // Check if the UDI is present in the map and set the connection status accordingly
            if (isConnected) {
                deviceInfoMap[udi].connectionStatus.push_back(1);  // Set the connection status to 1 for connected devices
            } else {
                deviceInfoMap[udi].connectionStatus.push_back(0);  // Set the connection status to 0 for disconnected devices
            }
        } else {
            std::cout << "Failed to update network status for device: " << udi << std::endl;
        }
    }

    // Function to retrieve the device information map
    std::map<std::string, DeviceInfo>& getDeviceInfoMap() {
        return deviceInfoMap;
    }

    // Function to retrieve the OAuth token responses vector
    std::vector<OAuthTokenResponse>& getOAuthTokenResponses() {
        return oauthTokenResponses;
    }

    // Function to retrieve the network status update requests vector
    std::vector<NetworkStatusUpdateRequest>& getNetworkStatusUpdateRequests() {
        return networkStatusUpdateRequests;
    }

private:
    // Map to store device information
    std::map<std::string, DeviceInfo> deviceInfoMap;

    // Vector to store OAuth token responses
    std::vector<OAuthTokenResponse> oauthTokenResponses;

    // Vector to store network status update requests
    std::vector<NetworkStatusUpdateRequest> networkStatusUpdateRequests;
};

int main() {
    Device device;

    // Add a few devices to the map
    device.addDevice("device1");
    device.addDevice("device2");
    device.addDevice("device3");

    // Set the connection status for one of the devices
